//! `Workbook` — typed-overlay root for an OOXML spreadsheet
//! package (B1 iter-wb-2).
//!
//! Layered on top of `pkg/store.zig` (PartStore) and the
//! per-part typed parsers in `pkg/typed_parts/`. This iter is
//! read-only — `Workbook.open` + sheet lookup + per-sheet
//! cells / merges / hyperlinks / validations / conditional
//! formats / freeze. Mutation lands in iter-wb-4.
//!
//! Composition shape:
//!
//!     Workbook
//!     ├── store: PartStore           (owns arena for raw part bytes)
//!     ├── workbook: WorkbookXml      (typed view of xl/workbook.xml)
//!     ├── worksheets: []?Worksheet   (lazy slot per sheet, parsed on first access)
//!     ├── sst:    ?SstXml            (lazy)
//!     ├── styles: ?StylesXml         (lazy)
//!     └── arena_ws: ArenaAllocator   (per-Worksheet allocations)
//!
//! Each typed view (`WorkbookXml`, `SheetXml`, `SstXml`,
//! `StylesXml`) carries its own internal arena per the
//! `pkg/typed_parts/*.zig` contract. `Workbook.deinit` walks
//! all of them and reclaims.
//!
//! See `docs/plans/archive/workbook-overlay.md` for the full plan.

const std = @import("std");
const Allocator = std.mem.Allocator;
const assert = std.debug.assert;

/// §9.1 M10q's fill probe. Zero-cost unless a tally is installed.
pub const fill_probe = @import("fill.zig");
const store_mod = @import("store.zig");
/// M5b2: §5.7.3 step 4's prepare/swap transaction. The import points
/// back at this file — `recalc_txn` builds a candidate *for* a
/// `Workbook` — but only through function bodies on both sides, so
/// neither type's layout depends on the other.
const recalc_txn = @import("recalc_txn.zig");
/// M5d2: §5.7's pipeline and §5.7.9's file transaction. The two entry
/// points below are thin forwarders — the pipeline lives in its own file
/// because it composes six layers and because its tests need a root of
/// their own to run under.
const recalc_run = @import("recalc_run.zig");
const typed_parts = @import("typed_parts/root.zig");
const zlsx = @import("zlsx");
const drawing_emit = @import("drawing_emit.zig");
const embedding_part = @import("embedding_part.zig");
const recovery_record = @import("recovery_record.zig");
const sheet_edit = @import("sheet_edit.zig");
const coords = @import("zlsx_refs");
const drawing_edit = @import("drawing_edit.zig");
const vml_edit = @import("vml_edit.zig");
const table_edit = @import("table_edit.zig");
/// S6: the pivot graph, read-only (`Workbook.pivotTables`).
const pivots_mod = @import("pivots.zig");
const sst_plan_mod = @import("zlsx_sst_plan");
const styles_plan_mod = @import("zlsx_styles_plan");
const workbook_xml_plan_mod = @import("zlsx_workbook_xml_plan");
// B3 iter-wr-6: canonical XML-escape helpers + sheet-plan registry
// types live on `pkg/sheet_plan.zig`. Workbook routes its <Override>,
// `<sheet name="…">`, `<si>`, and rich-run emit through the same
// byte-stable producers `xlsx.Writer` uses.
const sheet_plan = @import("zlsx_sheet_plan");

// B3 iter-wr-7: fresh-archive emit substrate. Lifts the entire archive
// orchestration ([Content_Types].xml + rels + workbook.xml + per-sheet
// sheet/rels/comments/vml + sst + styles + ZIP CD/EOCD) into a std-only
// module shared with `xlsx.Writer.save`. Workbook calls into this when
// `saveFreshEmit` is invoked; existing delta-on-bytes `Workbook.save`
// continues to ignore it.
const fresh_emit = @import("zlsx_fresh_emit");

/// The formula engine, as ONE module (M4b1).
///
/// This import is the single point where `pkg/` and `src/formula/`
/// meet, and it points one way: the engine never imports the package
/// layer. It is also deliberately one module rather than four — a file
/// compiled into two modules is two distinct types, so naming `env`,
/// `value` and `decode` separately would build an `EvalEnv` the
/// evaluator could not accept.
///
/// Bound to `engine` rather than `formula`: this file has a dozen
/// parameters called `formula` (data-validation and conditional-format
/// bodies), and a shadowed import is a compile error at every one.
const engine = @import("zlsx_formula");

/// B3 iter-wr-7: deflate adapter for the fresh-emit substrate. Routes
/// to `xlsx.deflateCompress` (the canonical deflate impl). Wrapping
/// is needed because `pkg/fresh_emit.zig` and `pkg/zip.zig` are
/// std-only (cycle-avoidance) and accept a `DeflateFn` callback.
// M5d1's cancellation / deadline / 64 KiB-chunk seam (§5.5). Named
// import so `pkg/control.zig` belongs to exactly one module tree.
const control = @import("zlsx_control");

fn freshEmitDeflate(
    alloc: Allocator,
    input: []const u8,
    out: *std.ArrayListUnmanaged(u8),
    poller: control.Poller,
) anyerror!void {
    return zlsx.deflateCompressControlled(alloc, input, out, poller);
}

const PartStore = store_mod.PartStore;

const workbook_xml_mod = typed_parts.workbook_xml;
const sheet_xml_mod = typed_parts.sheet_xml;
const sst_xml_mod = typed_parts.sst_xml;
const styles_xml_mod = typed_parts.styles_xml;
const doc_props_mod = typed_parts.doc_props_xml;

/// Re-exported SST extension-plan substrate (B3 iter-wr-1). Definition
/// moved to `pkg/sst_plan.zig` so `xlsx.Writer` can import the same
/// types without the cycle that would form via `zlsx → writer.zig →
/// pkg/workbook.zig → zlsx`.
pub const DocProps = doc_props_mod.DocProps;
pub const DocPropsMask = doc_props_mod.Mask;

pub const RichRun = sst_plan_mod.RichRun;
pub const RichEntry = sst_plan_mod.RichEntry;
pub const SstExtensionPlan = sst_plan_mod.SstExtensionPlan;

// B3 iter-wr-2: shared `StylesPlan` substrate. Workbook gains
// `addStyle` / `addDxf` / `internNumFmt` thin pass-throughs that
// delegate to a `StylesPlan`. Type re-exports keep the
// `pkg.Workbook.addStyle(.{ ... })` call shape ergonomic.
pub const StylesPlan = styles_plan_mod.StylesPlan;
pub const Style = styles_plan_mod.Style;
pub const Dxf = styles_plan_mod.Dxf;
pub const BorderSide = styles_plan_mod.BorderSide;
pub const BorderStyle = styles_plan_mod.BorderStyle;
pub const PatternType = styles_plan_mod.PatternType;
pub const HAlign = styles_plan_mod.HAlign;

/// Re-exported workbook.xml fresh-emit plan substrate (B3 iter-wr-3).
/// Same cycle-avoidance argument as `SstExtensionPlan`: definition
/// lives in `pkg/workbook_xml_plan.zig` so `xlsx.Writer` can stage
/// defined names through the same shape.
pub const WorkbookXmlPlan = workbook_xml_plan_mod.WorkbookXmlPlan;
pub const WorkbookDefinedName = workbook_xml_plan_mod.DefinedName;
pub const DefinedNameOptions = workbook_xml_plan_mod.DefinedNameOptions;

pub const Error = error{
    /// Style validation failed — empty font name, non-positive font
    /// size, or empty number format string. Surfaces from
    /// `Workbook.addStyle` / `Workbook.internNumFmt`.
    InvalidStyle,
    MissingWorkbookPart,
    MissingSheetPart,
    MissingRelationship,
    /// Workbook lacks `xl/_rels/workbook.xml.rels` — required to
    /// register a freshly-created `xl/sharedStrings.xml` part. Surfaces
    /// only when an SST extension is requested against a workbook that
    /// has no rels file at all (extremely malformed input).
    MissingWorkbookRels,
    SheetIndexOutOfRange,
    SheetNotFound,
    SstIndexOutOfRange,
    SstEntryIsRich,
    /// Existing `xl/_rels/workbook.xml.rels` is missing the closing
    /// `</Relationships>` tag — refused rather than producing an
    /// unparseable relationships file when extending the SST.
    MalformedWorkbookRels,
    InvalidCellRef,
    NoSheetData,
    UnsupportedCellValue,
    /// `Workbook.renameSheet` rejected `new_name`: empty, exceeds the
    /// length cap, or contains a forbidden character (`: \ / ? * [ ]`),
    /// or is the case-insensitive reserved name "history".
    InvalidSheetName,
    /// `Workbook.renameSheet` rejected `new_name`: an existing sheet
    /// (other than `sheet_idx` itself) already uses that name (case-
    /// insensitive ASCII compare; see method docstring for the
    /// Unicode-fold caveat).
    SheetNameInUse,
    /// Internal invariant: the existing sheet name in `WorkbookXml`
    /// exceeds 128 bytes. OOXML-conformant inputs cannot trip this —
    /// surfaces only on hand-crafted / corrupted workbook.xml.
    InternalSheetNameTooLong,
    /// `Workbook.renameSheet` could not locate the target `<sheet>`
    /// element in the source `xl/workbook.xml` bytes. Surfaces only
    /// if the file mutated under us between parse and patch.
    SheetElementNotFound,
    /// `Workbook.fromBook(book, io, path)` opened `path` but the resulting
    /// sheet count disagreed with `book.sheets.len`. Typically a path-
    /// drift bug in the caller (wrong path passed, file renamed,
    /// etc.). v1 of `fromBook` is a re-open + sanity-check shim;
    /// future iters may share bytes via PartStore-from-bytes.
    SheetCountMismatch,
    /// `Workbook.deleteSheet` refused to remove the sole remaining
    /// sheet. OOXML / Excel require ≥1 sheet per workbook; opening a
    /// zero-sheet `.xlsx` is a hard error in every consumer we know
    /// about. The check is at the API boundary, not in the on-wire
    /// patch helpers, so callers get a typed error before any state
    /// mutation occurs.
    LastSheetUndeletable,
    /// `Workbook.deleteSheet` could not locate the target
    /// `<Relationship Id="rId…">` element in
    /// `xl/_rels/workbook.xml.rels`. Surfaces only when
    /// `WorkbookXml.sheets[idx].r_id` references an Id that doesn't
    /// exist on the wire (corrupted rels file).
    RelationshipElementNotFound,
    /// `Workbook.deleteSheet` could not locate the target
    /// `<Override PartName="/xl/worksheets/sheetN.xml" .../>` element
    /// in `[Content_Types].xml`. Soft: deleteSheet proceeds without
    /// the override removal in this case (some tooling omits per-sheet
    /// Overrides), but the typed error is exposed for future use.
    ContentTypesOverrideNotFound,
    /// The sheet carries a `<drawing>` element that can't be chased
    /// to a drawing part: the element has no `r:id`, the sheet rels
    /// file is missing or has no matching Id, or the target part
    /// isn't in the archive.
    DrawingRelationshipNotFound,
    /// The sheet's existing drawing resolved to a part `addImage`
    /// can't extend: no closing `</xdr:wsDr>` to splice an anchor
    /// into (a legacy VML part, a chartSpace root, a non-`xdr`
    /// prefix), a root whose `xmlns:xdr` is neither the Transitional
    /// nor the Strict spreadsheetDrawing URI, or a part outside the
    /// `xl/drawings/<basename>` layout that the emitted `../media/`
    /// image target assumes.
    UnsupportedDrawingPart,
    /// Existing `xl/drawings/_rels/drawingN.xml.rels` lacks the
    /// closing `</Relationships>` tag — refused rather than producing
    /// an unparseable rels part.
    MalformedDrawingRels,
    /// An id-allocation scan (media part numbers, `rId`s, `cNvPr`
    /// ids) found the u32 id space exhausted — some existing entry
    /// already uses maxInt(u32). Crafted input; refused typed before
    /// any mutation rather than emitting a duplicate id.
    IdSpaceExhausted,
    /// Image bytes' magic header didn't match the declared `mime`.
    MimeMagicMismatch,
    /// Image anchor had a 0 row or 0 col (OOXML is 1-based).
    InvalidAnchor,
    /// `Workbook.addImageRange` got a range whose bottom-right cell
    /// sat above or left of its top-left cell.
    InvertedAnchorRange,
    /// An image's declared MIME matched its magic, but the header that
    /// follows is truncated or carries an unusable pixel size, so its
    /// native extent can't be read.
    UndecodableImageHeader,
    /// A `one_cell` anchor carried a 0 or over-large extent.
    InvalidExtent,
    /// Empty image buffer.
    EmptyImage,
    /// `xl/worksheets/_rels/sheetN.xml.rels` exists but lacks the
    /// closing `</Relationships>` tag — refused rather than producing
    /// an unparseable rels part.
    MalformedSheetRels,
    /// Sheet XML is missing its closing `</worksheet>` tag — refused
    /// rather than producing an unparseable sheet part.
    MalformedSheetXml,
    /// `Worksheet.setCell` refused because the sheet already has
    /// `appended_rows` staged — the iter-er-3 contract makes setCell
    /// and appendRows mutually exclusive on a single Worksheet.
    SheetHasUnsavedAppends,
    /// `Worksheet.appendRows` refused because the sheet already has
    /// `setCell`/`deleteCell` deltas staged — symmetric mutual-
    /// exclusion guard. Lifting this gate is post-iter-er-2e (when
    /// the substring fast-path can merge with delta regen).
    SheetHasUnsavedMutations,
    /// `Worksheet.appendRows` row width exceeds Excel's 16_384-column
    /// cap (`xlsx.max_col_1based`).
    ColumnIndexOutOfRange,
    /// `Worksheet.appendRows` `.integer` value can't round-trip
    /// exactly through f64 (i.e. `!fitsExactlyInF64(n)`). Excel
    /// stores integers as f64 internally; values above 2^53 lose
    /// precision silently.
    IntegerExceedsExcelPrecision,
    /// `Worksheet.emitWithAppendsUsingPlan` refused because the
    /// spliced rows would push past Excel's 1,048,576-row cap
    /// (`xlsx.max_row`). Caller should split the append into
    /// multiple sheets — there is no in-place recovery.
    RowIndexOutOfRange,
    /// `Workbook.insertRow` refused because shifting an existing
    /// row would push it past Excel's 1,048,576-row cap. Surfaced
    /// from `pkg/sheet_edit.zig`.
    RowEditExceedsMaxRow,
    /// `Workbook.insertColumn` refused because shifting an
    /// existing column would push it past Excel's XFD-column cap.
    ColEditExceedsMaxCol,
    /// `Workbook.{insertRow, deleteRow, insertColumn, deleteColumn}`
    /// refused because the sheet carries a `<pane>` with
    /// `state="split"` (or missing `state`, which OOXML defaults to
    /// "split"). Pixel-coordinate splits can't be meaningfully
    /// shifted by row/col edits; only `state="frozen"` /
    /// `state="frozenSplit"` panes are rewritten. Surfaces from
    /// `pkg/sheet_edit.zig`.
    SplitPaneNotSupported,
    /// `Workbook.{insertRow, deleteRow, insertColumn, deleteColumn}`
    /// found a `<pane>` element whose `xSplit`, `ySplit`, or
    /// `topLeftCell` attribute couldn't be parsed (non-integer
    /// split, malformed A1 ref). Refused rather than silently
    /// dropping the pane element. Surfaces from `pkg/sheet_edit.zig`.
    MalformedPaneSplit,
    /// dr-1: `Workbook.{insertRow, deleteRow, insertColumn, deleteColumn}`
    /// failed while rewriting the sheet's xdr drawing part because
    /// the part's structure didn't match the expected
    /// `<xdr:from>`/`<xdr:to>` shape. Refused rather than emit a
    /// silently-corrupted drawing. Surfaces from
    /// `pkg/drawing_edit.zig`.
    MalformedDrawingXml,
    /// dr-1: `Workbook.{insertRow, insertColumn}` would shift an
    /// `<xdr:col>` or `<xdr:row>` value past `std.math.maxInt(u32)`.
    /// Practically unreachable. Surfaces from `pkg/drawing_edit.zig`.
    DrawingCoordinateOverflow,
    /// dr-2: `Workbook.{insertRow, deleteRow, insertColumn, deleteColumn}`
    /// failed while rewriting the sheet's legacy VML drawing
    /// part because the part's structure didn't match the
    /// expected `<x:Anchor>` 8-int payload shape OR an
    /// `<x:Row>`/`<x:Column>` value couldn't be parsed. Refused
    /// rather than emit a silently-corrupted VML drawing.
    /// Surfaces from `pkg/vml_edit.zig`.
    MalformedVmlDrawing,
    /// dr-2: `Workbook.{insertRow, insertColumn}` would shift a
    /// VML anchor coordinate past `std.math.maxInt(u32)`.
    /// Practically unreachable. Surfaces from `pkg/vml_edit.zig`.
    VmlCoordinateOverflow,
    /// dr-2 / REL-705: `Workbook.{insertRow, deleteRow, insertColumn,
    /// deleteColumn}` failed while rewriting the sheet's
    /// `xl/commentsN.xml` part because a `<comment ref>` couldn't
    /// be parsed as a single A1 cell. Refused rather than emit a
    /// silently-corrupted comments part. Surfaces from
    /// `pkg/vml_edit.zig::applyEditToCommentsXml`.
    MalformedCommentsXml,
    /// `Workbook.{insertRow, deleteRow, insertColumn, deleteColumn}`
    /// failed while rewriting an `xl/tables/tableN.xml` part because
    /// the part's `<table ref>` couldn't be parsed. Refused rather
    /// than emit a silently-corrupted table part. Surfaces from
    /// `pkg/table_edit.zig`.
    MalformedTableXml,
    /// `Workbook.{insertRow, insertColumn}` would shift a table
    /// range corner past Excel's row/column cap. Practically
    /// unreachable. Surfaces from `pkg/table_edit.zig`.
    TableCoordinateOverflow,
    /// `Workbook.{deleteRow, deleteColumn}` would shrink a structured
    /// table to zero columns or zero rows. The Editor pre-flight
    /// converts this into the user-facing `RowEditUnsafeForSheet` /
    /// `ColEditUnsafeForSheet`, so this variant only surfaces when a
    /// caller bypasses Editor. Surfaces from `pkg/table_edit.zig`.
    TableCollapseUnsafe,
    /// A row/col edit targets a sheet a pivot table reads from. The
    /// pivot's `<location ref>` and cache field ranges live in a
    /// cross-part graph zlsx has no rewriter for, so the edit refuses
    /// rather than leaving those coordinates pointing at the pre-shift
    /// grid. The Editor pre-flight remaps this to
    /// `RowEditUnsafeForSheet` / `ColEditUnsafeForSheet`. Surfaces
    /// from `Workbook.preflightPivotEditsForSheet`.
    PivotEditUnsafe,
    /// A structural edit found an `<extLst>` `<xm:f>` formula carrier
    /// it cannot rewrite wholly — no `</xm:f>`, or markup inside the
    /// body — on some sheet of the workbook. `<xm:f>` (sparkline data
    /// ranges and date axes, `x14:` conditional-format and validation
    /// formulas) is routed through the formula rewriter under every
    /// row / col / sheet edit (S2 lift, `rewriteAllExtensionFormulas`);
    /// the contract is all-or-nothing, so `preflightExtensionFormulas`
    /// refuses the whole edit BEFORE its first mutation rather than
    /// leave one carrier stale. The Editor remaps this to
    /// `RowEditUnsafeForSheet` / `ColEditUnsafeForSheet`.
    MalformedExtensionXml,
    /// `Workbook.deleteRow` would remove a structured table's header
    /// row (top of `<table ref>` when `headerRowCount >= 1`, the
    /// default). Like `TableCollapseUnsafe`, the Editor pre-flight
    /// remaps this to `RowEditUnsafeForSheet`. Surfaces from
    /// `pkg/table_edit.zig`.
    TableHeaderRowDeleteUnsafe,
    /// `Workbook.renameTableColumn`: no table in the workbook
    /// carries the given `displayName` (fold rule).
    TableNotFound,
    /// `Workbook.renameTableColumn`: the named table has no column
    /// matching the old name (fold rule). Surfaces from
    /// `pkg/table_edit.zig`.
    TableColumnNotFound,
    /// `Workbook.renameTableColumn`: another column in the same
    /// table already carries the new name (fold rule — ECMA-376
    /// §18.5.1.78 uniqueness). Surfaces from `pkg/table_edit.zig`.
    TableColumnNameInUse,
    /// `Workbook.renameTableColumn` rejected the new name: empty,
    /// or a control byte XML cannot carry. Surfaces from
    /// `pkg/table_edit.zig`.
    InvalidTableColumnName,
    /// `Workbook.addSheet` refused because the workbook already
    /// holds the type-system maximum (`std.math.maxInt(u32)`)
    /// number of sheets. Excel imposes no documented sheet count
    /// limit (memory-bounded) but the typed-overlay's u32
    /// indexing does.
    TooManySheets,
    /// `Worksheet.emitWithAppendsUsingPlan` was given a string cell
    /// whose payload was not registered in the SST extension plan.
    /// Surfaces only on a `Workbook.save` bookkeeping bug — the plan
    /// builder walks every sheet's `appended_rows` and `deltas`, so
    /// reaching this error means a string was added between plan-
    /// build and emit.
    SharedStringNotInPlan,
    /// Embedding index relationships resolved to a vec/hash target
    /// that is not present in the package. Surfaces from
    /// `Workbook.embeddings()` (emb-2).
    MissingEmbeddingPart,
    /// `Workbook.setEmbeddings` input failed semantic validation —
    /// vector / hash count diverges from the declared range, or
    /// `inputs.len == 0`. Surfaces from `setEmbeddings` (emb-3).
    InvalidEmbeddingInput,
    /// `Workbook.setEmbeddings` produced a part that would exceed
    /// PartStore's 512 MiB read-side decompression cap. The writer
    /// refuses to emit a workbook it cannot subsequently re-read.
    /// Mitigations: pick a more aggressive quantization (int8 vs
    /// f32), split into multiple smaller coverages, or accept the
    /// future-streaming-API workaround when it lands (v1.1).
    EmbeddingExceedsArchiveLimit,
    WriteFailed,

    // ─── §10's plane-2 taxonomy (M5b2) ───────────────────────────
    //
    // §10 names this error set as plane 2's home. The whole vocabulary
    // lands here at once rather than four names now and ten with M5d2:
    // the transaction already carries an evaluation's refusal census
    // through to the caller, so any of the fourteen can already surface,
    // and a partial set would force a mapping that reports a cycle as
    // malformed input. The spellings are §10's own.
    /// Unregistered call.
    FormulaUnsupportedFunction,
    /// Unsupported semantics — external ref, R1C1, LAMBDA/LET, ambiguous
    /// dialect, relative defined name, table formula without a cell
    /// `<f>`. Mark-eligible (§5.7.7).
    FormulaUnsupportedConstruct,
    /// `fullPrecision="0"`. Always refuses; never mark-eligible.
    FormulaPrecisionAsDisplayed,
    /// Malformed or unsafe input. Never mark-eligible.
    FormulaMalformedInput,
    /// Input outside a pinned locale grammar.
    FormulaLocaleSensitiveInput,
    /// Data-table formulas.
    FormulaDataTableUnsupported,
    /// Signature parts present at model build — mutation would
    /// invalidate them.
    FormulaSignedWorkbook,
    /// A coverage overlapping the run's staged replacements.
    FormulaStaleEmbeddings,
    /// Site-dependent evaluation with no anchor.
    FormulaAnchorRequired,
    /// A cycle with iteration off.
    FormulaCycle,
    /// §5.6e's fixpoint exhausted.
    FormulaDynamicRefUnstable,
    /// Outside the approved mutation set.
    FormulaSpillPersistUnsupported,
    /// A top-level multi-area result (v1).
    FormulaResultNotRepresentable,
    /// Any §9 limit, including §5.7.4's counted retention.
    FormulaLimitExceeded,
    /// S6: a pivot part reached through the relationship graph cannot
    /// be read (`Workbook.pivotTables`). The typed read refuses whole
    /// rather than listing the pivots it could parse.
    MalformedPivotXml,
} || workbook_xml_mod.Error || sheet_xml_mod.ParseError || sst_xml_mod.Error || styles_xml_mod.Error || store_mod.Error ||
    workbook_xml_plan_mod.Error ||
    embedding_part.Error ||
    zlsx.formula_rewriter.Error ||
    std.Io.File.Writer.Error || std.Io.File.OpenError || std.Io.Dir.RenameError || std.Io.Dir.StatFileError ||
    // pkg/atomic_file.zig's temp-name probe loop, reachable through
    // PartStore.save on the write path.
    error{TempNameExhausted};

/// Mutation primitive (B1 iter-wb-4). Strings emit as `inlineStr`
/// — cell-local text, no SST extension required. `shared_string`
/// values flow through `xl/sharedStrings.xml` (m4): the workbook's
/// SST is extended (or created) on save and the cell emits as
/// `<c t="s"><v>idx</v></c>`. Formulas emit as `<f>…</f>` with no
/// cached `<v>`, so Excel recalculates on open.
///
/// `string`, `shared_string`, and `formula` slices borrow for
/// `setCell`'s call only. The delta map duplicates bytes into the
/// Workbook allocator before returning, so the caller can free /
/// reuse the buffer as soon as `setCell` returns.
pub const CellValue = union(enum) {
    blank: void,
    number: f64,
    boolean: bool,
    string: []const u8,
    /// Plain text routed through the workbook's shared-string table.
    /// On save, the SST is extended (or created) with the unique new
    /// strings and the cell emits as `t="s"` + numeric `<v>` index.
    /// De-dup is by exact-byte equality against existing SST plain
    /// entries (post-decode) and against other `.shared_string`
    /// deltas in the same save. Rich-text entries are NOT considered
    /// for de-dup (rare in writes).
    shared_string: []const u8,
    /// Formula text (e.g. "SUM(A1:A10)" — no leading `=`). Emitted
    /// as `<f>…</f>` without a cached value; Excel recalculates the
    /// result on open. Caching computed results is a future iter
    /// (depends on D1 evaluator).
    formula: []const u8,
    /// Fully remove the cell from `<sheetData>`. Distinct from
    /// `.blank` (which emits an empty `<c r="REF"/>` — cell present,
    /// no value): a `.deleted` delta elides the cell entirely from
    /// the regenerated sheet XML, so post-save `cellByRef(ref)`
    /// returns `null`. Staging a `.deleted` delta against a ref that
    /// isn't present in the source sheet is a no-op (delta carries
    /// nothing to elide).
    deleted: void,
};

/// 1-based (row, col) — matches OOXML A1 conventions.
pub const CellRef = struct {
    row: u32,
    col: u32,

    pub fn eql(a: CellRef, b: CellRef) bool {
        return a.row == b.row and a.col == b.col;
    }
};

/// Parse an A1-style ref ("A1", "AA10") into a numeric CellRef.
/// Letters are case-insensitive. Returns `error.InvalidCellRef` for
/// any malformed input (no letters, no digits, leading-zero row,
/// out-of-range col [> Excel's 16384 limit] / row [> 1048576]).
pub fn parseA1Ref(ref: []const u8) Error!CellRef {
    // M0 adapter over `zlsx_refs`. Policy preserved exactly: this is a
    // user-facing entry point, so letters are case-insensitive and a
    // leading-zero row is rejected.
    const cell = coords.parseCell(ref, .{
        .case = .insensitive,
        .leading_zero_row = .reject,
    }) catch return error.InvalidCellRef;
    // Note the base difference from `zlsx.CellRef`, which this module
    // does NOT share: here both fields are 1-based.
    return .{ .row = cell.row.oneBased(), .col = cell.col.oneBased() };
}

/// Format a CellRef as A1 ("A1", "AA10") into `buf`. Returns the
/// written slice. `buf.len >= 16` is sufficient for any in-range ref.
pub fn formatA1Ref(buf: []u8, ref: CellRef) []u8 {
    assert(ref.row >= 1 and ref.row <= coords.max_row);
    assert(ref.col >= 1 and ref.col <= coords.max_col_1based);
    assert(buf.len >= coords.format_buf_len);

    // The asserts above are exactly the constructors' preconditions, so
    // the error branches are unreachable by construction.
    const cell: coords.Cell = .{
        .col = coords.Col.fromOneBased(ref.col) catch unreachable,
        .row = coords.Row.fromOneBased(ref.row) catch unreachable,
    };
    return coords.formatCell(buf, cell);
}

/// Composite read-only view of a cell's resolved style. Each field
/// borrows from the workbook's `StylesXml` arena and is valid for as
/// long as the parent `Workbook` lives.
///
/// v1 simplification: when an `apply_*` flag on the underlying CellXf
/// is false, the corresponding field surfaces as `null`. OOXML's full
/// semantics inherit from `cellStyleXfs[xf.xfId]` in that case; we
/// defer that walk until callers explicitly request it.
///
/// `number_format_code` is `null` when `num_fmt_id` falls in the
/// built-in range (0..163, ECMA-376 §18.8.30) — those codes are
/// implicit and not stored in `<numFmts>`. Callers that need a
/// rendered string for a built-in id must map it themselves.
pub const ResolvedStyle = struct {
    font: ?styles_xml_mod.Font,
    fill: ?styles_xml_mod.Fill,
    border: ?styles_xml_mod.Border,
    alignment: ?styles_xml_mod.Alignment,
    number_format_code: ?[]const u8,
};

/// Resolved number-format descriptor for a cell-style index. Returned
/// by `Workbook.numberFormatFor`. `is_builtin == true` ⇒ `code` points
/// at a static literal from the OOXML built-in table (IDs 0..163 per
/// ECMA-376 §18.8.30); `false` ⇒ `code` borrows from the StylesXml
/// arena (alive while the producing `Workbook` is alive).
pub const NumberFormatInfo = struct {
    fmt_id: u32,
    code: []const u8,
    is_builtin: bool,
};

/// Map an OOXML built-in `numFmtId` to its format code per
/// ECMA-376 §18.8.30 Table. Covers the well-known subset (0-22, 37-49)
/// which is ~95% of real workbooks; locale-specific entries (27-36,
/// 50-58, 81) and anything ≥164 are treated as custom and fall through
/// to the `<numFmt>` table in `xl/styles.xml`.
///
/// Skipped IDs (deliberate): 5-8 (currency variants — locale-driven,
/// not portable as static strings), 23-36 (locale/CJK formats with no
/// stable pan-Excel rendering), 41-44 (currency with locale conditions),
/// 50-58 (locale Asian / hijri / Thai / etc.), 81. Real workbooks
/// touching these embed an explicit custom `<numFmt>` anyway, which our
/// custom-table fallback already handles.
fn builtinNumFmtCode(id: u32) ?[]const u8 {
    return switch (id) {
        0 => "General",
        1 => "0",
        2 => "0.00",
        3 => "#,##0",
        4 => "#,##0.00",
        9 => "0%",
        10 => "0.00%",
        11 => "0.00E+00",
        12 => "# ?/?",
        13 => "# ??/??",
        14 => "m/d/yyyy",
        15 => "d-mmm-yy",
        16 => "d-mmm",
        17 => "mmm-yy",
        18 => "h:mm AM/PM",
        19 => "h:mm:ss AM/PM",
        20 => "h:mm",
        21 => "h:mm:ss",
        22 => "m/d/yyyy h:mm",
        37 => "#,##0 ;(#,##0)",
        38 => "#,##0 ;[Red](#,##0)",
        39 => "#,##0.00;(#,##0.00)",
        40 => "#,##0.00;[Red](#,##0.00)",
        45 => "mm:ss",
        46 => "[h]:mm:ss",
        47 => "mmss.0",
        48 => "##0.0E+0",
        49 => "@",
        else => null,
    };
}

// ---------------------------------------------------------------
// Embedding view (emb-2 — read-only access to xl/zlsxEmbeddings/*)
// ---------------------------------------------------------------

/// One parsed coverage block resolved against the workbook's
/// PartStore: the manifest entry plus the typed header+body views
/// of its vec.bin and hashes.bin sub-parts. All slices borrow from
/// the parent `Workbook`'s `PartStore` and remain valid until
/// `Workbook.deinit`.
pub const EmbeddingCoverageView = struct {
    coverage: embedding_part.Coverage,
    vec: embedding_part.ParsedVecPart,
    hashes: embedding_part.ParsedHashPart,
};

/// Lazy workbook-level view of zlsx embedding parts. The index
/// borrows XML string slices from `index.xml`; each binary part
/// view borrows directly from the `PartStore`-materialized bytes.
pub const EmbeddingView = struct {
    index: embedding_part.Index,
    coverages: []const EmbeddingCoverageView,

    /// Look up a coverage by its `<coverage id="...">` attribute.
    /// Returns `null` if no coverage with that id exists.
    pub fn coverageById(
        self: EmbeddingView,
        id: []const u8,
    ) ?*const EmbeddingCoverageView {
        assert(id.len > 0);
        for (self.coverages) |*coverage| {
            if (std.mem.eql(u8, coverage.coverage.id, id)) return coverage;
        }
        return null;
    }
};

/// One covered slot's standing against current cell content.
///
/// The four cases are the design's Recompute contract verbatim
/// (`docs/plans/embeddings-in-xlsx.md` §Tombstone contract). Named
/// states rather than a bool because "stale" and "no longer embeddable"
/// call for different actions: the first is a re-embed the caller may
/// or may not want, the second is a redaction `--prune` performs.
pub const SlotState = enum {
    /// Stored hash matches the current cell. Nothing to do.
    fresh,
    /// Content moved on, or a tombstoned row became embeddable again.
    /// The vector no longer describes the cell; re-embed to fix. NOT
    /// redacted — there is still content here, so this is drift, not an
    /// orphan.
    stale,
    /// Was embedded, is no longer embeddable — the row was deleted or
    /// blanked in a plain-Excel edit. This is the redaction case: the
    /// vector outlived the text it came from.
    stale_needs_tombstone,
    /// Tombstone that is still correct — nothing embeddable there.
    valid_empty,
};

/// One row that has something worth embedding.
pub const EmbeddableRow = struct {
    row: u32,
    /// Borrows from the shared-string table or the sheet XML.
    text: []const u8,
    /// The canonical content hash to store alongside the vector.
    ///
    /// Computed here rather than by the caller on purpose: it has to
    /// match what `pruneEmbeddings` derives from the same cell, and a
    /// caller holding only `text` cannot know whether the cell was a
    /// string or a number — which changes the canonical form and so
    /// the hash. Getting that wrong would make every freshly-written
    /// row read back as drifted.
    hash: u64,
};

/// What `pruneEmbeddings` did, and what it deliberately left alone.
pub const PruneReport = struct {
    /// Slots turned into tombstones this call.
    redacted: usize = 0,
    /// Content drifted but is still embeddable — left as-is. Surfaced
    /// rather than silently redacted: deleting a vector because its
    /// text was *edited* would lose data the caller never asked to
    /// lose.
    stale: usize = 0,
    fresh: usize = 0,
    valid_empty: usize = 0,

    pub fn total(self: PruneReport) usize {
        return self.redacted + self.stale + self.fresh + self.valid_empty;
    }
};

/// Where `setEmbeddings` places the ER recovery record.
///
/// The default carriers (a hidden `<definedName>` and
/// `docProps/custom.xml`) are invisible to the user but are erased by
/// Apple Numbers. The cell carrier is the only one Numbers preserves,
/// and it is visible under Sheet ▸ Unhide.
///
/// That is not a gap to engineer away. Numbers rebuilds the file from
/// its own document model, so precisely what that model represents
/// survives — and anything invisible to the user is outside it.
/// **Invisibility and Numbers-durability are mutually exclusive by
/// construction**, so this is a choice the caller makes, not one the
/// library can make for them. Default = invisible.
pub const RecoveryOptions = struct {
    /// Also write the record into a hidden sheet, so it survives a
    /// Numbers export. Costs a sheet the user can reveal.
    recovery_in_cells: bool = false,
};

/// What `Workbook.embeddings()` found.
///
/// A tagged union rather than `?EmbeddingView` on purpose. The whole
/// point of the ER recovery record is that a workbook which lost its
/// vectors **says so** — if the accessor collapsed `.stripped` into a
/// bare `null`, the default caller experience would still be silent,
/// which is the outcome the durability contract rejects.
///
/// See `docs/plans/embeddings-in-xlsx.md` §Durability contract.
pub const EmbeddingState = union(enum) {
    /// `xl/zlsxEmbeddings/index.xml` present and parsed.
    present: EmbeddingView,
    /// The index is gone but a recovery record survived: some
    /// consumer stripped the vectors. Carries what they were, so the
    /// caller can re-embed deliberately with the original model and
    /// ranges instead of guessing.
    stripped: recovery_record.RecoveryRecord,
    /// No index and no record — this workbook never had embeddings,
    /// or passed through a consumer that strips even the record.
    /// Not an error.
    absent,

    /// The view when present, else null. For callers that genuinely
    /// only want the vectors and have already decided how to treat a
    /// strip — the name says the state is being discarded.
    pub fn viewOrNull(self: EmbeddingState) ?EmbeddingView {
        return switch (self) {
            .present => |v| v,
            else => null,
        };
    }
};

fn resolveEmbeddingRelTarget(
    rels: []const embedding_part.IndexRelationship,
    rid: []const u8,
) ?[]const u8 {
    if (rid.len == 0) return null;
    for (rels) |r| {
        if (std.mem.eql(u8, r.id, rid)) return r.target;
    }
    return null;
}

/// Tombstone slot `slot` in place: `u64::MAX` in hashes.bin, zeroes
/// over the vec.bin record.
///
/// Both parts keep their length and their headers — `count` is
/// unchanged, because the format is dense and slot `i` must keep
/// meaning row `first_row + i`.
///
/// The vector bytes are zeroed rather than merely unreferenced: the
/// point of a redaction is that the numbers describing deleted text
/// stop existing on disk, not that a flag says to ignore them.
fn redactSlot(
    vec: []u8,
    hashes: []u8,
    slot: u32,
    dim: u32,
    dtype: embedding_part.Dtype,
) Error!void {
    const rec_len = dtype.recordBytes(dim);
    const vec_start = embedding_part.VEC_HEADER_BYTES + @as(usize, slot) * rec_len;
    if (vec_start + rec_len > vec.len) return error.InvalidEmbeddingInput;
    @memset(vec[vec_start .. vec_start + rec_len], 0);

    const hash_start = embedding_part.HASH_HEADER_BYTES + @as(usize, slot) * @sizeOf(u64);
    if (hash_start + @sizeOf(u64) > hashes.len) return error.InvalidEmbeddingInput;
    std.mem.writeInt(
        u64,
        hashes[hash_start..][0..8],
        embedding_part.TOMBSTONE_HASH,
        .little,
    );
}

/// Whether a relationship type names a pivot part.
///
/// Matched on the trailing segment rather than the full URI: the
/// transitional (`.../officeDocument/2006/relationships/pivotTable`)
/// and strict (`.../officeDocument/2006/relationships/pivotTable` under
/// a different host in some producers) spellings share the leaf, and a
/// producer using a namespace zlsx has not seen must still be refused
/// rather than silently edited. Over-matching here costs a refusal;
/// under-matching costs a corrupted workbook.
fn isPivotRelType(rel_type: []const u8) bool {
    const leaf = if (std.mem.lastIndexOfScalar(u8, rel_type, '/')) |i|
        rel_type[i + 1 ..]
    else
        rel_type;
    return std.ascii.eqlIgnoreCase(leaf, "pivotTable") or
        std.ascii.eqlIgnoreCase(leaf, "pivotCacheDefinition") or
        std.ascii.eqlIgnoreCase(leaf, "pivotCacheRecords");
}

/// `<coverage id>` charset + length rules per the spec: required,
/// 1..63 chars, `[A-Za-z0-9_-]` only. Mirrors the parser-side rule
/// from `embedding_part.zig`'s `parseIndex`.
fn isValidEmbeddingCoverageId(id: []const u8) bool {
    if (id.len == 0 or id.len > 63) return false;
    for (id) |c| {
        const ok = (c >= 'A' and c <= 'Z') or
            (c >= 'a' and c <= 'z') or
            (c >= '0' and c <= '9') or
            c == '_' or c == '-';
        if (!ok) return false;
    }
    return true;
}

/// `upsertEmbeddingPart` adds the named part if absent, or replaces
/// its bytes if present. emb-3b: a second `setEmbeddings` call on
/// the same workbook must succeed rather than surface
/// `PartAlreadyExists`, so every part that setEmbeddings writes goes
/// through this helper. `replacePart` reuses the existing
/// `[Content_Types].xml` Override entry that the original addPart
/// installed; `addPart` declares one fresh.
fn upsertEmbeddingPart(
    store: *store_mod.PartStore,
    name: []const u8,
    content_type: []const u8,
    bytes: []const u8,
) !void {
    if ((try store.part(name)) != null) {
        try store.replacePart(name, bytes);
    } else {
        try store.addPart(name, content_type, bytes);
    }
}

/// One coverage's input to `Workbook.setEmbeddings`. The caller
/// supplies pre-quantized vectors AND pre-computed hashes (xxh3-64
/// of the canonical row content per the spec). Vector / hash
/// computation against live cells is the caller's responsibility
/// in v1 — typical flow is read cell text → embed via external
/// API → compute hash via `embedding_part.xxh3Canonical`.
pub const EmbeddingCoverageInput = struct {
    id: []const u8,
    worksheet_target: []const u8,
    range: []const u8,
    column: []const u8,
    include_formulas: bool = false,
    /// Pre-quantized vec.bin body bytes — already in the on-disk
    /// layout for `dtype` (length = count * dtype.recordBytes(dim)).
    /// For f32, this is `count * dim * 4` little-endian f32 bytes.
    /// For int8 sym, this is `count * (4 + dim)` bytes (per-row
    /// f32 scale + i8[dim]). Use `embedding_part.quantizeF32ToI8Sym`
    /// upstream to produce the bytes.
    vec_body: []const u8,
    /// Per-row xxh3-64 hashes (length = count). Use
    /// `TOMBSTONE_HASH` for sparse / formula-excluded rows.
    hashes: []const u64,
};

/// In-memory cap mirroring PartStore's read-side decompression
/// ceiling. `setEmbeddings` refuses to emit any part exceeding this
/// size so zlsx never writes a workbook it cannot subsequently
/// re-read.
const EMBEDDING_PART_MAX_BYTES: usize = 512 * 1024 * 1024;
const EMBEDDING_RELS_CONTENT_TYPE: []const u8 =
    "application/vnd.openxmlformats-package.relationships+xml";

/// A generation the recalc transaction superseded, kept alive until
/// `Workbook.deinit` (§5.7.4, borrow-lifetime preservation).
///
/// `Workbook.sheet()` hands out pointers and `cellByRef()` promises
/// Workbook-lifetime validity for the strings it returns — and those
/// strings borrow **part bytes**, not view arenas (`sheet_xml.zig`'s leaf
/// slices point into the decompressed part). So retaining the typed views
/// alone would dangle: the store has to come with them. That is the whole
/// reason this struct exists rather than a list of stale views.
///
/// Nothing here is ever reclaimed early. Reclaiming would require proving
/// no borrow survives, which is precisely what a Workbook-lifetime promise
/// says cannot be proven — so the reclamation path is `deinit` and reopen,
/// and the pressure valve is `max_retained_generations`, which refuses
/// *before* the swap rather than freeing after it.
pub const RetainedGeneration = struct {
    /// The superseded `PartStore`. Its `SourceBacking` is shared with
    /// every live generation, so retaining it costs an arena, not a file
    /// descriptor (M5b0).
    store: PartStore,
    /// The superseded `xl/workbook.xml` view, when the transaction
    /// replaced it.
    workbook: ?workbook_xml_mod.WorkbookXml = null,
    /// Superseded per-sheet views, parallel to `Workbook.worksheets`.
    /// A slot is non-null only for a sheet whose view the swap replaced.
    /// Empty when no sheet view moved.
    sheets: []?sheet_xml_mod.SheetXml = &.{},
    /// The superseded workbook-scope lazy views. Taken on **every** swap
    /// rather than only when their part changed: deciding they were
    /// untouched means resolving which part backs each one, and being
    /// wrong means a view describing bytes that moved. Handing them to
    /// the retained generation costs a re-parse on next access and cannot
    /// be wrong.
    sst: ?sst_xml_mod.SstXml = null,
    styles: ?styles_xml_mod.StylesXml = null,
    /// What this generation keeps resident, for §5.7.4's byte accounting.
    bytes: u64 = 0,

    pub fn deinit(self: *RetainedGeneration, allocator: Allocator) void {
        if (self.workbook) |*v| {
            var view = v.*;
            view.deinit(allocator);
        }
        for (self.sheets) |*slot| {
            if (slot.*) |*v| {
                var view = v.*;
                view.deinit(allocator);
            }
        }
        if (self.sst) |*v| {
            var view = v.*;
            view.deinit(allocator);
        }
        if (self.styles) |*v| {
            var view = v.*;
            view.deinit(allocator);
        }
        allocator.free(self.sheets);
        self.store.deinit();
        self.* = undefined;
    }
};

pub const Workbook = struct {
    allocator: Allocator,
    store: PartStore,

    /// Parsed `xl/workbook.xml`. Borrows from the PartStore arena
    /// for leaf strings; owns its own arena for spine slices.
    workbook: workbook_xml_mod.WorkbookXml,

    /// Lazy per-sheet typed view. Length == `workbook.sheets.len`.
    /// Each slot is `null` until `sheet(idx)` materialises it.
    worksheets: []Worksheet,

    /// Lazy workbook-scope views. Parsed on first access via
    /// `Workbook.sst()` / `Workbook.styles()`.
    sst_view: ?sst_xml_mod.SstXml = null,
    styles_view: ?styles_xml_mod.StylesXml = null,

    /// B3 iter-wr-2: fresh-emit styles registry. Mirrors the SST plan
    /// pattern — Workbook gains `addStyle` / `addDxf` / `internNumFmt`
    /// pass-throughs so callers can stage styles + dxfs + custom
    /// number formats without going through `xlsx.Writer`. The plan
    /// owns every duped string; `deinit` walks it. Empty-by-default,
    /// so an existing-file workbook that never calls `addStyle`
    /// pays nothing.
    styles_plan: StylesPlan = .{},

    /// Workbook.xml fresh-emit plan (B3 iter-wr-3). Today's only axis
    /// is defined names, registered through `Workbook.addDefinedName`.
    /// On `save`, if at least one entry has been staged the workbook
    /// re-emits `xl/workbook.xml` from scratch via
    /// `workbook_xml_plan_mod.emitWorkbookXml`. The Writer-rebase
    /// path (`xlsx.Writer.save`) consults this same plan.
    workbook_xml_plan: WorkbookXmlPlan = .{},

    /// B3 iter-wr-7: fresh-emit shared-strings registry. The
    /// per-Worksheet `body` builder routes string interns through this
    /// plan; same byte-format as `xlsx.Writer.sst_plan`. Empty for
    /// edit-source workbooks; only populated when callers stage
    /// fresh-emit rows. `Workbook.saveFreshEmit` consumes it directly;
    /// `Workbook.save`'s delta path uses a separately-built plan from
    /// `buildSstExtensionPlan`.
    fresh_sst_plan: SstExtensionPlan = .{},

    /// B3 iter-wr-7: total string-typed cell occurrences across all
    /// sheets. The OOXML `<sst count=>` attribute. Distinct from
    /// `fresh_sst_plan.new_strings.items.len` (uniqueCount).
    fresh_sst_count: u64 = 0,

    /// emb-2: lazy view of `xl/zlsxEmbeddings/*`. `null` until
    /// `Workbook.embeddings()` is first called; cached thereafter.
    /// All XML / binary leaf slices borrow from PartStore arena;
    /// only the three storage handles below are heap-owned.
    embedding_view: ?EmbeddingView = null,
    embedding_index_storage: ?[]embedding_part.Coverage = null,
    embedding_rels_storage: ?[]embedding_part.IndexRelationship = null,
    embedding_coverage_views: ?[]EmbeddingCoverageView = null,

    /// ER: backing storage for a recovered record. Its string slices
    /// point into `recovery_text_storage`, so both live as long as
    /// the Workbook.
    recovery_cov_storage: ?[]recovery_record.RecoveredCoverage = null,
    recovery_text_storage: ?[]u8 = null,
    recovery_opts: RecoveryOptions = .{},

    /// §5.7.4: every generation a recalc superseded, oldest first, held
    /// until `deinit`. Capacity for the incoming entry is reserved during
    /// `prepare`, which is what makes the swap's append infallible.
    retained: std.ArrayListUnmanaged(RetainedGeneration) = .empty,
    /// Sum of `RetainedGeneration.bytes`. Counted rather than documentary
    /// — §5.7.4 gates repeated recalc on it, and a number nobody adds up
    /// is a promise nobody keeps.
    retained_bytes: u64 = 0,

    /// Open an .xlsx file as a typed `Workbook`.
    ///
    /// Errors if `xl/workbook.xml` is absent or malformed; otherwise
    /// every sheet is left lazy. `deinit` is required on success and
    /// on error after `open` returns successfully.
    pub fn open(allocator: Allocator, io: std.Io, path: []const u8) Error!Workbook {
        assert(path.len > 0);

        var store = try PartStore.open(allocator, io, path);
        // `fromStore` takes ownership **including on failure** — it
        // deinits the store itself when the workbook part is missing or
        // malformed — so the errdefer here has to be disarmed before the
        // hand-off. Armed, it double-frees the arena on every failing
        // open, which is a segfault rather than the typed error the
        // caller is expecting.
        var owned = true;
        errdefer if (owned) store.deinit();
        owned = false;
        return try fromStore(allocator, store);
    }

    /// Lazy-open variant. Same shape as `open` for v1 — sheets are
    /// already lazy-materialised on first `Worksheet.ensureParsed()`,
    /// so there's no behavioural difference yet. The split exists so
    /// callers (and the iter-wb-6 RSS gate) can pin to the future-
    /// correct symbol; later iters may add an SST-lazy / drawings-lazy
    /// strategy here without changing call sites.
    pub fn openLazy(allocator: Allocator, io: std.Io, path: []const u8) Error!Workbook {
        assert(path.len > 0);
        return Workbook.open(allocator, io, path);
    }

    /// Open a package that is already in memory (M5c, §5.10).
    ///
    /// **The borrow ends when this returns.** `PartStore.openBuffer`
    /// copies the caller's slice into the backing, so `bytes` may be
    /// freed, reused or poisoned the moment the call comes back — the
    /// same contract `Book.openBuffer` has kept since B-cabi-1
    /// (`xlsx.zig`), and the reason M5b0 made the store dupe rather than
    /// borrow. A borrowing variant would push the archive's lifetime
    /// back onto the caller, and the point of a `SourceBacking` is that
    /// the generations decide when the bytes die.
    ///
    /// This is what lets an orchestrator hand a producer's output
    /// straight to a consumer without a temp file: `Writer` emits into a
    /// buffer, this reads it, and neither touches the filesystem.
    /// Everything downstream — lazy part materialization, the typed
    /// views, `save`, the M5b2 recalc transaction — reaches the same
    /// code a path-opened workbook does, because the only thing that
    /// differs is which arm of the backing answers `readAt`.
    pub fn openBuffer(allocator: Allocator, io: std.Io, bytes: []const u8) Error!Workbook {
        return openBufferControlled(allocator, io, bytes, .none);
    }

    /// §5.10's control-aware consumer (M5d1).
    ///
    /// The mirror of `Writer.saveToOwnedBufferControlled`, and needed for
    /// the same reason: opening a buffer scans the central directory,
    /// eagerly decompresses every structural part and materializes
    /// `xl/workbook.xml`, all *before* a recalc begins. An orchestrator
    /// that promised a deadline has to be able to reach in here, or the
    /// §5.5 bound is only true of the half of the pipeline that comes
    /// after.
    ///
    /// `error.Cancelled` leaves nothing behind: the store is torn down,
    /// the backing released, and the caller's `bytes` — which this only
    /// ever reads — are untouched. Like the producer side, this stage
    /// sits entirely before §5.7.9's commit point.
    pub fn openBufferControlled(
        allocator: Allocator,
        io: std.Io,
        bytes: []const u8,
        ctl: control.Control,
    ) Error!Workbook {
        const watch: control.Watch = .init(io, ctl);
        const poller = watch.poller();
        var store = try PartStore.openBufferControlled(allocator, io, bytes, poller);
        // `fromStore` takes ownership INCLUDING on failure, so the
        // errdefer has to be disarmed before the hand-off. Armed, it
        // double-frees the arena on every failing open — the exact bug
        // `Workbook.open` was fixed for at M4b1, reproduced here the day
        // this function was written by copying it.
        var owned = true;
        errdefer if (owned) store.deinit();
        owned = false;
        return try fromStoreControlled(allocator, store, poller);
    }

    /// Construct a `Workbook` from an already-opened `PartStore`.
    /// Takes ownership of the store; `deinit` will tear it down.
    pub fn fromStore(allocator: Allocator, store: PartStore) Error!Workbook {
        return fromStoreControlled(allocator, store, .none);
    }

    /// `fromStore` with §5.5's poll seam over the one long operation it
    /// performs: materializing (and therefore decompressing)
    /// `xl/workbook.xml`.
    pub fn fromStoreControlled(
        allocator: Allocator,
        store: PartStore,
        poller: control.Poller,
    ) Error!Workbook {
        var s = store;
        errdefer s.deinit();

        const wb_part = try s.partControlled("xl/workbook.xml", poller) orelse
            return Error.MissingWorkbookPart;

        var workbook_view = try workbook_xml_mod.parse(allocator, wb_part.bytes);
        errdefer workbook_view.deinit(allocator);

        const ws_count = workbook_view.sheets.len;
        const slots = try allocator.alloc(Worksheet, ws_count);
        errdefer allocator.free(slots);

        for (slots, 0..) |*slot, i| slot.* = .{
            .workbook = undefined, // patched below; can't take address pre-return
            .sheet_idx = @intCast(i),
            .parsed = null,
            .resolved_part_name = null,
        };

        return .{
            .allocator = allocator,
            .store = s,
            .workbook = workbook_view,
            .worksheets = slots,
        };
    }

    /// Promote an already-opened `zlsx.Book` to a `Workbook`. Caller
    /// passes the path that was originally used to open `book`.
    ///
    /// **v1 contract — re-reads the file.** Today this is a thin
    /// wrapper around `Workbook.open(alloc, io, path)` plus a sanity check
    /// that the resulting sheet count matches `book.sheets.len`. The
    /// "without re-reading the file" promise from the workbook-overlay
    /// plan needs a `PartStore`-from-bytes constructor (or PartStore /
    /// Book sharing the underlying mmap) — out of scope for this iter.
    /// Use `book` for the migration-time consistency check; it is
    /// borrowed and the caller retains ownership.
    ///
    /// Errors `SheetCountMismatch` if `book` and the freshly-opened
    /// Workbook disagree on sheet count — typically a sign of a path
    /// drift bug in the caller (passed the wrong path, file was
    /// renamed, etc.).
    pub fn fromBook(allocator: Allocator, io: std.Io, book: *const zlsx.Book, path: []const u8) Error!Workbook {
        assert(path.len > 0);
        var wb = try Workbook.open(allocator, io, path);
        errdefer wb.deinit();

        if (wb.sheetCount() != book.sheets.len) return error.SheetCountMismatch;
        return wb;
    }

    /// Construct a fresh, empty `Workbook` with no source archive. The
    /// returned workbook holds the OOXML-minimum required parts:
    /// `[Content_Types].xml`, `_rels/.rels`, `xl/workbook.xml` (with
    /// an empty `<sheets/>`), and `xl/_rels/workbook.xml.rels` (with
    /// an empty `<Relationships>` body). Zero worksheets in the typed
    /// view; `addSheet(name)` grows it.
    ///
    /// Used by the upcoming B3 Writer-rebase track: `xlsx.Writer.save`
    /// will call `Workbook.empty(alloc, io)`, populate via `addSheet` +
    /// `setCell` / `appendRows`, then `save(path)`.
    ///
    pub fn empty(allocator: Allocator, io: std.Io) Error!Workbook {
        var store = try PartStore.fresh(allocator, io);
        var owned = true;
        errdefer if (owned) store.deinit();

        // `PartStore.fresh` seeds only `[Content_Types].xml`. Seed
        // the OOXML-minimum remaining parts before handing off to
        // `fromStore`. `addPart` appends the corresponding
        // `<Default>` / `<Override>` to CT.xml automatically.
        try store.addPart(
            "_rels/.rels",
            "application/vnd.openxmlformats-package.relationships+xml",
            "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
                "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">" ++
                "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/>" ++
                "</Relationships>",
        );
        try store.addPart(
            "xl/workbook.xml",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml",
            "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
                "<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">" ++
                "<sheets></sheets>" ++
                "</workbook>",
        );
        try store.addPart(
            "xl/_rels/workbook.xml.rels",
            "application/vnd.openxmlformats-package.relationships+xml",
            "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
                "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">" ++
                "</Relationships>",
        );

        // Ownership moves on failure too — see `open`.
        owned = false;
        return try fromStore(allocator, store);
    }

    pub fn deinit(self: *Workbook) void {
        for (self.worksheets) |*ws| ws.deinit(self.allocator);
        self.allocator.free(self.worksheets);

        if (self.sst_view) |*v| {
            var view = v.*;
            view.deinit(self.allocator);
        }
        if (self.styles_view) |*v| {
            var view = v.*;
            view.deinit(self.allocator);
        }
        self.styles_plan.deinit(self.allocator);
        self.workbook.deinit(self.allocator);
        self.workbook_xml_plan.deinit(self.allocator);
        self.fresh_sst_plan.deinit(self.allocator);
        if (self.embedding_coverage_views) |s| self.allocator.free(s);
        if (self.embedding_rels_storage) |s| self.allocator.free(s);
        if (self.embedding_index_storage) |s| self.allocator.free(s);
        if (self.recovery_cov_storage) |s| self.allocator.free(s);
        if (self.recovery_text_storage) |s| self.allocator.free(s);
        // §5.7.4: the retained generations go last. Every one of them
        // holds a reference to the same `SourceBacking` the live store
        // does, and only the final `release` closes the file — order
        // among them is therefore free, but they must all outlive any
        // view still borrowing their part bytes, which is why nothing
        // above this line reaches into them.
        for (self.retained.items) |*g| g.deinit(self.allocator);
        self.retained.deinit(self.allocator);
        self.store.deinit();
    }

    /// Ask the next consumer to recalculate: set `<calcPr
    /// fullCalcOnLoad="1">` and change nothing else (§5.7.7).
    ///
    /// Honestly named. It does not calculate anything and does not claim
    /// to have: `calcId` is left alone, because the caches in the file are
    /// still the ones its original producer wrote, and `calcId="0"` is how
    /// a zlsx recalc says *it* produced them.
    ///
    /// Runs as a real transaction rather than as a `replacePart` on the
    /// live store — the same prepare/swap, the same retained generation,
    /// the same no-fail swap. A three-line shortcut would have replaced
    /// bytes that the workbook's own typed views still described.
    pub fn markRecalcOnLoad(self: *Workbook) Error!void {
        var result = recalc_txn.markRecalcOnLoad(self, .{}) catch |e| switch (e) {
            // No cancellation token was supplied, so nothing can trigger
            // one. Stated rather than swallowed.
            error.Cancelled => unreachable,
            else => |other| return other,
        };
        switch (result) {
            .refused => |r| {
                // The refusal may own a census since M9a2; this path's
                // synthetic entry is mark-eligible so in practice it
                // arrives empty, but freeing is the contract, not a
                // guess about which arm produced it.
                var refusal = r;
                const e = refusal.toWorkbookError();
                refusal.deinit(self.allocator);
                return e;
            },
            .ok => |*candidate| {
                candidate.swap(self);
                var report = candidate.takeReport();
                report.deinit(self.allocator);
            },
        }
    }

    /// §5.7's in-memory transaction (M5d2): recalculate every formula
    /// cell and swap the result in as the final pipeline operation.
    ///
    /// No file is opened. On refusal, cancellation or allocation failure
    /// the workbook is exactly as it was — the pipeline's three gates all
    /// run before a candidate exists, and the candidate is abandoned
    /// rather than swapped if anything after them says no.
    ///
    /// The report is the caller's and owns its census; `deinit` it with
    /// this workbook's allocator, which is what the transaction that
    /// built it had to use (`recalc_txn.prepare` has no choice — every
    /// other allocation it makes is installed into the workbook by the
    /// swap).
    pub fn recalculate(
        self: *Workbook,
        allocator: Allocator,
        io: std.Io,
        run: recalc_run.RunInputs,
        opts: recalc_run.Options,
    ) Error!recalc_run.Report {
        return recalc_run.recalculate(self, allocator, io, run, opts);
    }

    /// §5.7.9's file transaction (M5d2): recalculate, write, commit,
    /// then swap.
    ///
    /// The ordering is normative and is stated where it is implemented
    /// (`pkg/recalc_run.zig`). What a caller needs from here: any failure
    /// before the rename leaves BOTH the destination's prior bytes and
    /// this workbook's memory untouched (or the destination still absent
    /// if it never existed); a successful rename leaves memory and file
    /// consistent; and a directory fsync that fails afterwards is a
    /// `durability_warning` on the returned report, never an error.
    pub fn saveWithRecalc(
        self: *Workbook,
        allocator: Allocator,
        io: std.Io,
        path: []const u8,
        run: recalc_run.RunInputs,
        opts: recalc_run.Options,
    ) Error!recalc_run.Report {
        return recalc_run.saveWithRecalc(self, allocator, io, path, run, opts);
    }

    /// Register a cell style in the workbook-level styles plan and
    /// return its 1-based `s="…"` index. Dedupes by content. Mirrors
    /// `xlsx.Writer.addStyle` byte-for-byte (both ultimately route
    /// through `StylesPlan.addStyle`). Use this in conjunction with
    /// `Worksheet.setCell` to author styled cells without going
    /// through Writer's fluent-builder API.
    pub fn addStyle(self: *Workbook, style: Style) Error!u32 {
        return self.styles_plan.addStyle(self.allocator, style) catch |e| switch (e) {
            error.OutOfMemory => return error.OutOfMemory,
            error.InvalidFontSize, error.InvalidFontName, error.InvalidNumberFormat => return error.InvalidStyle,
        };
    }

    /// Register a differential format for conditional formatting and
    /// return its 0-based dxfId. Dedupes by content. Mirrors
    /// `xlsx.Writer.addDxf` byte-for-byte.
    pub fn addDxf(self: *Workbook, dxf: Dxf) Error!u32 {
        return self.styles_plan.addDxf(self.allocator, dxf) catch |e| switch (e) {
            error.OutOfMemory => return error.OutOfMemory,
            else => unreachable,
        };
    }

    /// Intern a custom number format string into the workbook's
    /// numFmt pool and return the assigned numFmtId. Subsequent calls
    /// with the same `format_code` return the same id. The first
    /// custom format gets id `styles_plan.NUM_FMT_BASE` (164); each
    /// new format increments the counter.
    pub fn internNumFmt(self: *Workbook, format_code: []const u8) Error!u32 {
        if (format_code.len == 0) return error.InvalidStyle;
        return self.styles_plan.internNumFmt(self.allocator, format_code) catch |e| switch (e) {
            error.OutOfMemory => return error.OutOfMemory,
            else => unreachable,
        };
    }

    pub fn sheetCount(self: *const Workbook) u32 {
        assert(self.worksheets.len == self.workbook.sheets.len);
        return @intCast(self.worksheets.len);
    }

    /// Typed view over `docProps/core.xml` + `docProps/app.xml`, plus a
    /// presence flag for `docProps/custom.xml`.
    ///
    /// All three parts are optional; a workbook without any of them
    /// yields a `DocProps` for which `isEmpty()` is true. Returned
    /// strings borrow from the store's part buffers and stay valid
    /// until `deinit`.
    ///
    /// This is a read of raw parts rather than a cached typed overlay:
    /// document properties are tiny, touched rarely, and re-parsing on
    /// demand keeps them out of the open() hot path.
    pub fn docProps(self: *const Workbook) Error!DocProps {
        const core = try self.store.part(doc_props_mod.core_part_name);
        const app = try self.store.part(doc_props_mod.app_part_name);
        const custom = try self.store.part(doc_props_mod.custom_part_name);
        return doc_props_mod.parse(
            if (core) |p| p.bytes else null,
            if (app) |p| p.bytes else null,
            custom != null,
        );
    }

    /// Rewrite `docProps/core.xml` and `docProps/app.xml` with every
    /// field the mask targets removed, and (when
    /// `mask.custom_properties`) drop `docProps/custom.xml` entirely.
    ///
    /// Everything else is byte-preserved: only the parts that actually
    /// carry masked fields are replaced, and within those only the
    /// matched elements are excised. A workbook with no docProps parts
    /// is a no-op.
    ///
    /// Changes are staged in the PartStore and land on the next `save`.
    pub fn stripDocProps(self: *Workbook, mask: DocPropsMask) Error!void {
        const a = self.allocator;

        if (try self.store.part(doc_props_mod.core_part_name)) |core| {
            const scrubbed = try doc_props_mod.scrubCore(a, core.bytes, mask);
            defer a.free(scrubbed);
            // Skip the write when nothing changed so an untouched part
            // keeps its original compressed bytes in the saved archive.
            if (!std.mem.eql(u8, scrubbed, core.bytes)) {
                try self.store.replacePart(doc_props_mod.core_part_name, scrubbed);
            }
        }

        if (try self.store.part(doc_props_mod.app_part_name)) |app| {
            const scrubbed = try doc_props_mod.scrubApp(a, app.bytes, mask);
            defer a.free(scrubbed);
            if (!std.mem.eql(u8, scrubbed, app.bytes)) {
                try self.store.replacePart(doc_props_mod.app_part_name, scrubbed);
            }
        }

        if (mask.custom_properties) {
            // Custom properties are arbitrary user-defined key/value
            // pairs, so there is nothing to selectively scrub — the
            // part goes wholesale, along with its content-type override
            // and the workbook relationship pointing at it.
            try self.store.removePart(doc_props_mod.custom_part_name);
        }
    }

    /// Borrow a `Worksheet` handle by zero-based index. Materialises
    /// the typed view on first access; subsequent calls hit the cache.
    pub fn sheet(self: *Workbook, idx: u32) Error!*Worksheet {
        if (idx >= self.worksheets.len) return Error.SheetIndexOutOfRange;
        const ws = &self.worksheets[idx];
        // Patch the back-pointer on first observation. Done lazily so
        // the slot table can be allocated before `Workbook` exists.
        ws.workbook = self;
        return ws;
    }

    /// Borrow a `Worksheet` handle by sheet name (case-sensitive,
    /// no Unicode normalisation — match `WorkbookXml.Sheet.name`
    /// exactly). Returns `null` if no sheet with that name.
    pub fn sheetByName(self: *Workbook, name: []const u8) Error!?*Worksheet {
        assert(name.len > 0);
        for (self.workbook.sheets, 0..) |s, i| {
            if (std.mem.eql(u8, s.name, name)) return try self.sheet(@intCast(i));
        }
        return null;
    }

    /// Defined names from `xl/workbook.xml`. Borrowed from the
    /// `WorkbookXml` view; valid for the `Workbook`'s lifetime.
    pub fn definedNames(self: *const Workbook) []const workbook_xml_mod.DefinedName {
        return self.workbook.defined_names;
    }

    /// Defined names with no `localSheetId` attribute — workbook-scope
    /// names visible from every sheet. Allocator-owned (caller frees).
    pub fn definedNamesGlobal(self: *const Workbook, allocator: Allocator) Error![]workbook_xml_mod.DefinedName {
        var out: std.ArrayList(workbook_xml_mod.DefinedName) = .empty;
        errdefer out.deinit(allocator);
        for (self.workbook.defined_names) |dn| {
            if (dn.local_sheet_id == null) try out.append(allocator, dn);
        }
        return try out.toOwnedSlice(allocator);
    }

    /// Defined names scoped to a specific sheet (via `localSheetId`).
    /// Caller frees the returned slice.
    pub fn definedNamesForSheet(self: *const Workbook, allocator: Allocator, sheet_idx: u32) Error![]workbook_xml_mod.DefinedName {
        if (sheet_idx >= self.workbook.sheets.len) return Error.SheetIndexOutOfRange;
        var out: std.ArrayList(workbook_xml_mod.DefinedName) = .empty;
        errdefer out.deinit(allocator);
        for (self.workbook.defined_names) |dn| {
            if (dn.local_sheet_id) |sid| {
                if (sid == sheet_idx) try out.append(allocator, dn);
            }
        }
        return try out.toOwnedSlice(allocator);
    }

    /// Calc properties from `xl/workbook.xml`.
    pub fn calcProperties(self: *const Workbook) workbook_xml_mod.CalcProperties {
        return self.workbook.calc;
    }

    /// S6: every pivot table with its host sheet, output rectangle,
    /// field roles and axes, and every pivot cache with its source —
    /// resolved to the sheet it reads from when the source is local —
    /// its field schema and its records part. Read-only; the parts
    /// stay byte-preserved. Caller owns the result (`deinit`); its raw
    /// slices borrow from this workbook's store, its decoded strings
    /// live in the result and end with its `deinit`.
    ///
    /// Not cached on the workbook: the walk is a handful of small
    /// parts and no accessor on this type mutates a pivot, so there is
    /// no invalidation to get wrong. `MalformedPivotXml` when a pivot
    /// part the graph reaches cannot be read.
    pub fn pivotTables(self: *Workbook) Error!pivots_mod.Pivots {
        return pivots_mod.collect(self.allocator, &self.store, &self.workbook);
    }

    /// **Internal (§5.6f).** Evaluate one formula against this
    /// workbook's *cached* values.
    ///
    /// Cache-based, and that is the whole contract at this row: a
    /// referenced formula cell yields the `<v>` the file already
    /// carries, a formula cell with no cached value reads as blank, and
    /// nothing is recomputed to make either true. Dependency-closure
    /// evaluation — the thing that would make `A1` reflect a `B1` this
    /// run changed — is M5a's, and the two behaviors are tested side by
    /// side so the switch is never silent.
    ///
    /// Not exposed anywhere: §5.6f puts the CLI at M6, the C ABI and
    /// Python at M9a and Spark at M9b, all after closure semantics
    /// exist. A caller reaching this before then would get answers that
    /// change meaning under it.
    ///
    /// **Purity.** Scratch-only. Everything the run produces lives in
    /// the returned arena; the workbook's logical state and its
    /// serialized bytes are identical before and after, on success, on
    /// refusal and on a run that ran out of budget or memory. Gated by
    /// byte-identity tests over all four.
    pub fn evaluate(
        self: *Workbook,
        allocator: Allocator,
        sheet_index: u32,
        formula: []const u8,
        opts: EvaluateOptions,
    ) Error!EvaluateResult {
        if (sheet_index >= self.worksheets.len) return Error.SheetNotFound;

        var model = switch (try WorkbookEnv.build(allocator, self, .{
            .collation = opts.collation,
            .fidelity = opts.fidelity,
            .limits = opts.limits,
        })) {
            .ok => |m| m,
            .refused => |r| return .{ .refused = r },
        };
        defer model.deinit();

        var arena = std.heap.ArenaAllocator.init(allocator);
        var keep = false;
        defer if (!keep) arena.deinit();
        const a = arena.allocator();

        var parsed = try engine.parser.parse(a, formula, .{ .limits = opts.parse_limits });
        const ast = switch (parsed) {
            .ok => |x| x,
            .refused => |r| {
                parsed.deinit(a);
                return .{ .parse_refused = r };
            },
        };

        // Standalone eval draws nothing: no v1 volatile function is
        // reachable from a cache-based read, and a draw source that
        // produced numbers would make the same call answer differently
        // twice. A run that reaches one trips the assertion rather than
        // inventing a value.
        var draws = engine.eval.DrawSource.constant(&unreachable_draw);
        var resolution: engine.NameResolution = .{ .table = &model.symbols, .gpa = allocator };

        var evaluator = engine.eval.Evaluator.init(a, model.evalEnv(), .{
            .current_sheet = engine.env.SheetIndex.fromInt(sheet_index),
            .collation = opts.collation,
            .draws = &draws,
            .fidelity = opts.fidelity,
            .dialect = opts.dialect,
            .site = opts.site,
            .names = resolution.resolver(),
            .array_formula = opts.array_formula,
            .limits = opts.parse_limits,
            // M6: the §5.5 run inputs a standalone caller states. These
            // defaulted here since M5d2 while `evaluateOne` forwarded
            // them, so a caller-set `--now` was echoed but never
            // reached NOW(). The two workbook-derived fields keep the
            // workbook's answer, exactly as the recalc driver does —
            // a caller has nothing true to say about either.
            .now_utc_ms = opts.now_utc_ms,
            .utc_offset_min = opts.utc_offset_min,
            .platform_profile = opts.platform_profile,
            .date_system = model.calc.date_system,
            .text_compat = switch (model.calc.text_compat) {
                .v1 => .cv1,
                .v2 => .cv2,
            },
        });
        defer evaluator.deinit();

        const v = evaluator.evaluate(ast) catch |e| {
            if (e == error.OutOfMemory) return Error.OutOfMemory;
            return .{ .eval_refused = .{
                .plane = engine.eval.planeTwo(e),
                .name = resolution.last_refusal,
                .three_d = evaluator.last_three_d,
            } };
        };
        // Text in the result may still borrow the *model's* arena — a
        // cached `<v>` read straight out of a part — and the model dies
        // at this function's `defer`. Copying is what makes the
        // returned arena the whole lifetime the caller has to track.
        const owned = try cloneEvaluated(a, v);

        keep = true;
        return .{ .ok = .{ .arena = arena, .value = owned } };
    }

    /// **Internal (§5.6f).** Evaluate one formula against this
    /// workbook's *dependency closure*.
    ///
    /// The second of the two behaviours §5.6f names, and the reason it
    /// says "no silent switch": `evaluate` above reads the `<v>` the
    /// file already carries, this one recomputes every formula cell the
    /// target transitively reads, in the graph's order, and then
    /// evaluates the target against those results. Both ship, both are
    /// tested, and a caller picks by which function it calls.
    ///
    /// **Iteration is M5a2's.** A cycle anywhere in the closure is
    /// `FormulaCycle` here (§5.6c's iteration-off rule); the workbook's
    /// `calcPr@iterate` is read but not yet honoured.
    ///
    /// **Dynamic-array placement is M7a's.** A planned cell whose result
    /// is an array contributes its top-left to the computed layer and
    /// spills nothing: this row models the tails as nodes, which is what
    /// makes the order right, and leaves what lands in them to the row
    /// that decides it.
    ///
    /// **Purity.** Identical to `evaluate`'s: scratch-only. The graph,
    /// the plan and every computed value live in the model's arena and
    /// the returned one; the workbook's logical state and its serialized
    /// bytes are byte-identical before and after, on success, on refusal
    /// and under injected allocation failure.
    pub fn evaluateClosure(
        self: *Workbook,
        allocator: Allocator,
        sheet_index: u32,
        formula: []const u8,
        opts: EvaluateOptions,
    ) Error!EvaluateResult {
        if (sheet_index >= self.worksheets.len) return Error.SheetNotFound;

        var model = switch (try WorkbookEnv.build(allocator, self, .{
            .collation = opts.collation,
            .fidelity = opts.fidelity,
            .limits = opts.limits,
        })) {
            .ok => |m| m,
            .refused => |r| return .{ .refused = r },
        };
        defer model.deinit();

        var arena = std.heap.ArenaAllocator.init(allocator);
        var keep = false;
        defer if (!keep) arena.deinit();
        const a = arena.allocator();

        var bridge: GraphBridge = .{ .model = &model, .gpa = allocator };
        const input = try bridge.buildInput(a, a);

        // §9's parse bounds govern the *stored* bodies too: a workbook
        // whose cells a caller's limits cannot parse is a refusal, not a
        // graph with those cells quietly missing.
        var g = switch (try engine.graph.build(allocator, input, bridge.resolver(), .{
            .parse_limits = opts.parse_limits,
            .limits = opts.work_limits,
        })) {
            .ok => |x| x,
            .refused => |r| return .{ .graph_refused = r },
        };
        // Owned here only until `engine.iterate.run` below takes it,
        // error paths included (see that function's header). The flag
        // covers the refusal returns between build and run.
        var g_owned = true;
        defer if (g_owned) g.deinit();

        // The target is parsed once, here, and both refusals it can
        // raise are the ones `evaluate` raises for the same text: the
        // two entry points differ in what they read, never in what they
        // call a refusal.
        var parsed = try engine.parser.parse(a, formula, .{ .limits = opts.parse_limits });
        const target_ast = switch (parsed) {
            .ok => |x| x,
            .refused => |r| {
                parsed.deinit(a);
                return .{ .parse_refused = r };
            },
        };
        if (engine.names.checkThreeD(target_ast, .{ .array_formula = opts.array_formula })) |r| {
            return .{ .eval_refused = .{
                .plane = .FormulaUnsupportedConstruct,
                .three_d = r,
            } };
        }

        const site: ?coords.Cell = if (opts.site) |s| .{ .row = s.row, .col = s.col } else null;
        const roots = try engine.graph.rootsOfAst(allocator, a, input, bridge.resolver(), .{
            .key = .{ .cell = .{
                .sheet = engine.env.SheetIndex.fromInt(sheet_index),
                .row = coords.Row.fromOneBased(1) catch unreachable,
                .col = coords.Col.fromZeroBased(0) catch unreachable,
            } },
            .sheet = engine.env.SheetIndex.fromInt(sheet_index),
            .site = site,
            .array_formula = opts.array_formula,
        }, target_ast);

        var counters: engine.graph.WorkCounters = .{ .limits = opts.work_limits };
        // Planned here as well as inside the engine, and the duplication
        // is deliberate: this call is where a cycle with iteration off
        // becomes a `graph_refused`, which is the answer M5a1 gave and
        // the answer §5.6c still requires. It is also the §9 charge
        // site — the engine re-plans once per §5.6e pass and does not
        // charge, because it charges per evaluation instead.
        switch (try engine.graph.plan(g, allocator, a, .{ .keys = roots }, &counters, .{
            .iterating = model.calc.iterate,
        })) {
            .ok => {},
            .refused => |r| return .{ .graph_refused = r },
        }

        // M5a2: the planned components, through the iteration engine.
        // The engine writes into the model's computed layer — which is
        // scratch, built from the package and thrown away at this
        // function's `defer` — never into the workbook. A cyclic
        // component gets §5.6c's pass counter; an acyclic one evaluates
        // once, which is exactly what the loop here used to do.
        var driver: ClosureDriver = .{
            .wb = self,
            .model = &model,
            .arena = a,
            .opts = opts,
        };
        var schedule: engine.draws.Schedule = .{};
        defer schedule.deinit(allocator);

        g_owned = false;
        const run = try engine.iterate.run(allocator, g, driver.host(), .{
            .limits = opts.work_limits,
            .settings = .{
                .iterate = model.calc.iterate,
                .iterate_count = model.calc.iterate_count,
                .iterate_delta = model.calc.iterate_delta,
            },
            .schedule = &schedule,
            .counters = &counters,
            // The ROOTS, so a §5.6e rebuild re-derives the closure: a
            // dynamic reference reaches cells no static walk found, and
            // the closure that did not contain them before the rebuild
            // has to contain them after it.
            .closure = .{ .roots = .{ .keys = roots }, .iterating = model.calc.iterate },
            .rebuild = .{ .input = input, .resolver = bridge.resolver() },
        });
        switch (run) {
            .ok => |report| {
                var r = report;
                r.deinit(allocator);
            },
            .refused => |r| {
                // A refusal the host raised carries the richer diagnosis
                // the engine's plane cannot; a refusal the engine raised
                // itself is complete as it stands.
                if (driver.refusal) |detail| return detail;
                return .{ .iteration_refused = r };
            },
        }
        if (driver.failure) |e| return e;

        const target = switch (try self.evaluateTarget(a, &model, sheet_index, target_ast, opts)) {
            .ok => |x| x,
            .refused => |r| return r,
        };

        keep = true;
        return .{ .ok = .{ .arena = arena, .value = target } };
    }

    /// M5a2: the package's implementation of §5.6c's evaluation seam.
    ///
    /// Two error channels rather than one, because the engine's is
    /// deliberately narrow: `Host.evaluate` may only fail with
    /// `OutOfMemory`, so a workbook refusal that carries a name or a 3D
    /// diagnosis is parked here and read back after the run. Collapsing
    /// it into the engine's `PlaneTwo` would lose exactly the part of a
    /// refusal a caller can act on.
    const ClosureDriver = struct {
        wb: *Workbook,
        model: *WorkbookEnv,
        arena: Allocator,
        opts: EvaluateOptions,
        /// A plane-2 refusal with its detail intact.
        refusal: ?EvaluateResult = null,
        /// A package-level failure that is not a refusal at all.
        failure: ?Error = null,

        fn host(self: *ClosureDriver) engine.iterate.Host {
            return .{ .ctx = self, .vtable = &host_vtable };
        }

        const host_vtable: engine.iterate.Host.VTable = .{
            .evaluate = vtEvaluate,
            .publish = vtPublish,
            .retract = vtRetract,
        };

        fn of(ctx: *anyopaque) *ClosureDriver {
            return @ptrCast(@alignCast(ctx));
        }

        fn vtEvaluate(
            ctx: *anyopaque,
            cell: engine.env.CellRef,
            key: engine.draws.Key,
        ) error{OutOfMemory}!engine.iterate.Produced {
            const self = of(ctx);
            const text = (self.model.formulaAt(cell) catch |e| switch (e) {
                error.OutOfMemory => return error.OutOfMemory,
                else => {
                    self.failure = Error.SheetNotFound;
                    return .{ .ok = .{ .value = .{ .scalar = .blank } } };
                },
            }) orelse return .{ .ok = .{ .value = .{ .scalar = .blank } } };

            const one = self.wb.evaluateOne(self.arena, self.model, cell, text, self.opts, key) catch |e| switch (e) {
                error.OutOfMemory => return error.OutOfMemory,
                else => {
                    self.failure = e;
                    return .{ .ok = .{ .value = .{ .scalar = .blank } } };
                },
            };
            return switch (one) {
                .refused => |r| blk: {
                    self.refusal = r;
                    break :blk .{ .refused = planeOfRefusal(r) };
                },
                .ok => |x| .{ .ok = .{ .value = x.value, .reads = x.reads } },
            };
        }

        fn vtPublish(
            ctx: *anyopaque,
            cell: engine.env.CellRef,
            v: engine.iterate.Snapshot,
        ) error{OutOfMemory}!void {
            const self = of(ctx);
            // §5.8a (M7a): scalars land in the computed layer, arrays
            // run the decision table and place their tails — or hold
            // `#SPILL!` with the class recorded.
            _ = self.model.publishResult(cell, v) catch |e| switch (e) {
                error.OutOfMemory => return error.OutOfMemory,
                else => blk: {
                    self.failure = Error.SheetNotFound;
                    break :blk engine.value.ScalarValue.blank;
                },
            };
        }

        fn vtRetract(ctx: *anyopaque, cell: engine.env.CellRef) void {
            of(ctx).model.retractResult(cell);
        }
    };

    /// The plane a package refusal reaches the engine as. The engine
    /// only ever stops the run on it; the detail travels separately.
    pub fn planeOfRefusal(r: EvaluateResult) engine.decode.PlaneTwo {
        return switch (r) {
            .parse_refused => .FormulaMalformedInput,
            .eval_refused => |e| e.plane,
            .graph_refused => |g| g.planeTwo(),
            else => .FormulaMalformedInput,
        };
    }

    pub const OneCell = union(enum) {
        ok: struct {
            /// The evaluator's result, WHOLE (M7a): a scalar, or the
            /// matrix a dynamic-array anchor produced. §5.8a's
            /// placement needs the tails and §5.6c's convergence
            /// compares shapes and elements, so narrowing here — as
            /// pre-M7a `scalarOf` did — would hand both of them a
            /// top-left and call it the result.
            value: engine.iterate.Snapshot,
            reads: engine.iterate.Reads,
            /// The result's shape, kept beside the value because the
            /// recalc driver's `published` record wants it after the
            /// snapshot has been consumed — §5.7.3's pre-M7 gate is a
            /// statement about the shape.
            shape: engine.value.Shape = .{ .rows = 1, .cols = 1 },
        },
        refused: EvaluateResult,
    };

    /// Public for M5d2: the recalc driver in `pkg/recalc_run.zig` is the
    /// second `iterate.Host` over this model, and it has to evaluate a
    /// stored cell exactly the way `evaluateClosure` does. Two copies of
    /// this body would be two dialect lookups, two draw-key wirings and
    /// two answers to the same formula.
    pub fn evaluateOne(
        self: *Workbook,
        a: Allocator,
        model: *WorkbookEnv,
        cell: engine.env.CellRef,
        text: []const u8,
        opts: EvaluateOptions,
        key: engine.draws.Key,
    ) Error!OneCell {
        _ = self;
        var parsed = try engine.parser.parse(a, text, .{ .limits = opts.parse_limits });
        const ast = switch (parsed) {
            .ok => |x| x,
            .refused => |r| {
                parsed.deinit(a);
                return .{ .refused = .{ .parse_refused = r } };
            },
        };

        // §5.3b: a *stored* cell's dialect is the workbook's answer, not
        // the caller's. `evaluate` states one because a standalone
        // formula has no cell to ask about.
        const dialect = model.evalEnv().dialectOf(cell) catch |e| switch (e) {
            error.OutOfMemory => return Error.OutOfMemory,
            else => return .{ .refused = .{ .eval_refused = .{
                .plane = .FormulaUnsupportedConstruct,
                .name = null,
            } } },
        };

        var fixed = engine.eval.DrawSource.constant(&unreachable_draw);
        const draws = opts.draws orelse &fixed;
        var resolution: engine.NameResolution = .{ .table = &model.symbols, .gpa = model.allocator };
        var evaluator = engine.eval.Evaluator.init(a, model.evalEnv(), .{
            .current_sheet = cell.sheet,
            .collation = opts.collation,
            .draws = draws,
            .fidelity = opts.fidelity,
            .dialect = dialect,
            .site = .{ .row = cell.row, .col = cell.col },
            .names = resolution.resolver(),
            .limits = opts.parse_limits,
            .now_utc_ms = opts.now_utc_ms,
            .utc_offset_min = opts.utc_offset_min,
            .platform_profile = opts.platform_profile,
            .text_compat = opts.text_compat,
            .date_system = opts.date_system,
            // §5.6d: the invocation path is rooted at the owning cell,
            // and the pass number travels with the key the engine
            // supplied.
            .draw_path = key.path,
        });
        evaluator.opts.draws.key = key;
        defer evaluator.deinit();

        const v = evaluator.evaluate(ast) catch |e| {
            if (e == error.OutOfMemory) return Error.OutOfMemory;
            return .{ .refused = .{ .eval_refused = .{
                .plane = engine.eval.planeTwo(e),
                .name = resolution.last_refusal,
                .three_d = evaluator.last_three_d,
            } } };
        };
        // §5.6e's runtime capture: what the body ACTUALLY read, which is
        // the only place a dynamic reference is visible.
        return .{ .ok = .{
            .value = try snapshotOf(a, v),
            .reads = .{
                .cells = try a.dupe(engine.env.CellRef, evaluator.deps.cells.items),
                .areas = try a.dupe(engine.env.RangeRef, evaluator.deps.areas.items),
            },
            .shape = shapeOf(v),
        } };
    }

    const OneValue = union(enum) {
        ok: engine.eval.Value,
        refused: EvaluateResult,
    };

    fn evaluateTarget(
        self: *Workbook,
        a: Allocator,
        model: *WorkbookEnv,
        sheet_index: u32,
        ast: engine.parser.Ast,
        opts: EvaluateOptions,
    ) Error!OneValue {
        _ = self;
        var draws = engine.eval.DrawSource.constant(&unreachable_draw);
        var resolution: engine.NameResolution = .{ .table = &model.symbols, .gpa = model.allocator };
        var evaluator = engine.eval.Evaluator.init(a, model.evalEnv(), .{
            .current_sheet = engine.env.SheetIndex.fromInt(sheet_index),
            .collation = opts.collation,
            .draws = &draws,
            .fidelity = opts.fidelity,
            .dialect = opts.dialect,
            .site = opts.site,
            .names = resolution.resolver(),
            .array_formula = opts.array_formula,
            .limits = opts.parse_limits,
        });
        defer evaluator.deinit();

        const v = evaluator.evaluate(ast) catch |e| {
            if (e == error.OutOfMemory) return Error.OutOfMemory;
            return .{ .refused = .{ .eval_refused = .{
                .plane = engine.eval.planeTwo(e),
                .name = resolution.last_refusal,
                .three_d = evaluator.last_three_d,
            } } };
        };
        return .{ .ok = try cloneEvaluated(a, v) };
    }

    /// Register a workbook-level defined name (B3 iter-wr-3 fresh-emit
    /// surface). Validates the name shape against Excel's full rule
    /// set (R1C1 reject, A1-shape reject, illegal char reject,
    /// 1..255 length, etc.); rejects empty `refers_to`; rejects
    /// case-insensitive duplicates within the same scope.
    ///
    /// `opts.local_sheet_id` (0-based) makes the name sheet-scoped —
    /// the index is bounds-checked at save / fresh-emit time, not at
    /// `addDefinedName` time, because the sheet count may grow after
    /// the name is registered. `opts.hidden = true` hides the name
    /// from Excel's Name Manager UI (used by `_xlnm.Print_Area` and
    /// similar).
    ///
    /// On success the workbook owns duped copies of `name` and
    /// `refers_to`; the caller can free their staging buffers
    /// immediately.
    pub fn addDefinedName(
        self: *Workbook,
        name: []const u8,
        refers_to: []const u8,
        opts: DefinedNameOptions,
    ) Error!void {
        try self.workbook_xml_plan.addDefinedName(
            self.allocator,
            name,
            refers_to,
            opts,
        );
    }

    /// Convenience: SST entry `idx` as plain text. Errors on rich-run
    /// entries (caller must use `sst()` and walk `RichRun[]` directly).
    /// Returns the raw, undecoded slice — call `sst_xml.decodeText` to
    /// resolve `&amp;` etc.
    pub fn sstText(self: *Workbook, idx: u32) Error!?[]const u8 {
        const view = (try self.sst()) orelse return null;
        if (idx >= view.entries.len) return Error.SstIndexOutOfRange;
        switch (view.entries[idx]) {
            .plain => |s| return s,
            .rich => return Error.SstEntryIsRich,
        }
    }

    /// Lazily-parsed `xl/sharedStrings.xml`. Returns `null` if the
    /// workbook has no SST. Subsequent calls return the cached view.
    pub fn sst(self: *Workbook) Error!?*const sst_xml_mod.SstXml {
        if (self.sst_view != null) return &self.sst_view.?;
        const part = try self.store.part("xl/sharedStrings.xml") orelse return null;
        self.sst_view = try sst_xml_mod.parse(self.allocator, part.bytes);
        return &self.sst_view.?;
    }

    /// Lazily-parsed `xl/styles.xml`. Returns `null` if absent.
    pub fn styles(self: *Workbook) Error!?*const styles_xml_mod.StylesXml {
        if (self.styles_view != null) return &self.styles_view.?;
        const part = try self.store.part("xl/styles.xml") orelse return null;
        self.styles_view = try styles_xml_mod.parse(self.allocator, part.bytes);
        return &self.styles_view.?;
    }

    /// emb-2: lazily-parsed `xl/zlsxEmbeddings/*`. Returns `null` if
    /// the workbook has no embedding index part; cached thereafter.
    ///
    /// All slices in the returned view borrow from PartStore arena
    /// memory and stay valid until `Workbook.deinit`. The three
    /// heap-owned arrays (the parsed-coverage storage backing
    /// `index.coverages`, the parsed-relationship storage, and the
    /// per-coverage view array) are freed by `deinit`.
    ///
    /// Errors:
    /// - `MissingEmbeddingPart` if the index references a vec.bin or
    ///   hashes.bin sub-part by relationship rId but the resolved
    ///   target is not present, OR if the index exists without a
    ///   companion `_rels/index.xml.rels`.
    /// - `embedding_part.Error.CountMismatch` if a coverage's
    ///   declared count diverges from either binary header's count.
    /// - Other `embedding_part.Error` variants from header / XML
    ///   parsing on malformed input.
    pub fn embeddings(self: *Workbook) Error!EmbeddingState {
        if (self.embedding_view) |v| return .{ .present = v };

        const idx_part = (try self.store.part(embedding_part.INDEX_PART_NAME)) orelse {
            // No index. Before reporting nothing, look for the ER
            // recovery record: a consumer that rebuilds the archive
            // drops the index but leaves the record, and the whole
            // contract rests on telling those two cases apart.
            if (try self.recoverEmbeddingRecord()) |rec| return .{ .stripped = rec };
            return .absent;
        };

        // Grow-loop for parseIndex (it requires a caller-provided
        // Coverage buffer; size unknown until we parse). Start at
        // 4 since real workbooks typically have 1-2 coverages.
        var idx_cap: usize = 4;
        var idx_storage: []embedding_part.Coverage = try self.allocator.alloc(
            embedding_part.Coverage,
            idx_cap,
        );
        const idx = while (true) {
            const got = embedding_part.parseIndex(idx_part.bytes, idx_storage) catch |err| switch (err) {
                error.BufferTooSmall => {
                    self.allocator.free(idx_storage);
                    idx_cap = std.math.mul(usize, idx_cap, 2) catch return error.BufferTooSmall;
                    idx_storage = try self.allocator.alloc(embedding_part.Coverage, idx_cap);
                    continue;
                },
                else => |e| {
                    self.allocator.free(idx_storage);
                    return e;
                },
            };
            break got;
        };
        errdefer self.allocator.free(idx_storage);

        // Rels are required once an index is present. Each coverage
        // contributes two rels (vec_rId + hash_rId), so start the
        // grow-loop sized accordingly.
        const rels_part = (try self.store.part(embedding_part.INDEX_RELS_PART_NAME)) orelse
            return error.MissingEmbeddingPart;
        var rels_cap: usize = @max(idx.coverages.len * 2, 4);
        var rels_storage: []embedding_part.IndexRelationship = try self.allocator.alloc(
            embedding_part.IndexRelationship,
            rels_cap,
        );
        const rels = while (true) {
            const got = embedding_part.parseIndexRelationships(rels_part.bytes, rels_storage) catch |err| switch (err) {
                error.BufferTooSmall => {
                    self.allocator.free(rels_storage);
                    rels_cap = std.math.mul(usize, rels_cap, 2) catch return error.BufferTooSmall;
                    rels_storage = try self.allocator.alloc(embedding_part.IndexRelationship, rels_cap);
                    continue;
                },
                else => |e| {
                    self.allocator.free(rels_storage);
                    return e;
                },
            };
            break got;
        };
        errdefer self.allocator.free(rels_storage);

        // Build per-coverage views. Resolves each rId → Target via the
        // relationships, then resolves Target → part bytes via the
        // PartStore (using `EMBEDDINGS_DIR` as the base for the
        // relative Target string).
        const views = try self.allocator.alloc(EmbeddingCoverageView, idx.coverages.len);
        errdefer self.allocator.free(views);

        var path_buf: [256]u8 = undefined;
        for (idx.coverages, 0..) |coverage, i| {
            const vec_target = resolveEmbeddingRelTarget(rels, coverage.vec_rid) orelse
                return error.MissingEmbeddingPart;
            const hash_target = resolveEmbeddingRelTarget(rels, coverage.hash_rid) orelse
                return error.MissingEmbeddingPart;

            const vec_path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ embedding_part.EMBEDDINGS_DIR, vec_target }) catch
                return error.MissingEmbeddingPart;
            const vec_part = (try self.store.part(vec_path)) orelse
                return error.MissingEmbeddingPart;
            const parsed_vec = try embedding_part.parseVecPart(vec_part.bytes);

            const hash_path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ embedding_part.EMBEDDINGS_DIR, hash_target }) catch
                return error.MissingEmbeddingPart;
            const hash_part = (try self.store.part(hash_path)) orelse
                return error.MissingEmbeddingPart;
            const parsed_hash = try embedding_part.parseHashPart(hash_part.bytes);

            try embedding_part.checkCoverageBinary(idx, coverage, parsed_vec.header, parsed_hash.header);

            views[i] = .{
                .coverage = coverage,
                .vec = parsed_vec,
                .hashes = parsed_hash,
            };
        }

        self.embedding_index_storage = idx_storage;
        self.embedding_rels_storage = rels_storage;
        self.embedding_coverage_views = views;
        self.embedding_view = .{
            .index = idx,
            .coverages = views,
        };
        return .{ .present = self.embedding_view.? };
    }

    /// ER read path: reassemble the recovery record from whichever
    /// carrier survived.
    ///
    /// Tries the hidden `<definedName>` chunks first, then
    /// `docProps/custom.xml`. Returns null when neither carries a
    /// record, which is the honest "never had embeddings" answer.
    ///
    /// Storage for the parsed strings is owned by the Workbook and
    /// freed in `deinit`, so the returned record stays valid for the
    /// workbook's lifetime like every other view here.
    fn recoverEmbeddingRecord(self: *Workbook) Error!?recovery_record.RecoveryRecord {
        var joined: std.ArrayListUnmanaged(u8) = .empty;
        defer joined.deinit(self.allocator);

        var carrier: recovery_record.Carrier = .defined_name;
        if (try self.store.part("xl/workbook.xml")) |wbx| {
            var name_buf: [32]u8 = undefined;
            var val_buf: [recovery_record.MAX_CHUNK * 4]u8 = undefined;
            var i: usize = 0;
            while (i < recovery_record.MAX_CHUNKS) : (i += 1) {
                const name = recovery_record.chunkName(&name_buf, i);
                const v = recovery_record.findDefinedNameValue(wbx.bytes, name, &val_buf) orelse break;
                try joined.appendSlice(self.allocator, v);
            }
        }

        if (joined.items.len == 0) {
            if (try self.store.part("docProps/custom.xml")) |dp| {
                var val_buf: [recovery_record.MAX_CHUNK * recovery_record.MAX_CHUNKS]u8 = undefined;
                if (recovery_record.findDocPropValue(dp.bytes, &val_buf)) |v| {
                    try joined.appendSlice(self.allocator, v);
                    carrier = .doc_props;
                }
            }
        }

        // Third: the opt-in cell carrier. Scanned rather than looked up
        // by path, because the payload lands inline in the sheet or in
        // sharedStrings depending on the consumer, and a Numbers export
        // renumbers the sheets besides.
        if (joined.items.len == 0) {
            var names: std.ArrayListUnmanaged([]const u8) = .empty;
            defer names.deinit(self.allocator);
            for (self.store.parts) |p| {
                if (std.mem.startsWith(u8, p.name, "xl/worksheets/") or
                    std.mem.eql(u8, p.name, "xl/sharedStrings.xml"))
                {
                    try names.append(self.allocator, p.name);
                }
            }
            for (names.items) |n| {
                const p = (try self.store.part(n)) orelse continue;
                var val_buf: [recovery_record.MAX_CHUNK * recovery_record.MAX_CHUNKS]u8 = undefined;
                if (recovery_record.findRecordInText(p.bytes, &val_buf)) |v| {
                    try joined.appendSlice(self.allocator, v);
                    carrier = .cell_data;
                    break;
                }
            }
        }
        if (joined.items.len == 0) return null;

        // Grow-loop on both buffers, same contract as parseIndex.
        var cov_cap: usize = 4;
        var scratch_cap: usize = 512;
        while (true) {
            const covs = try self.allocator.alloc(recovery_record.RecoveredCoverage, cov_cap);
            const scratch = try self.allocator.alloc(u8, scratch_cap);
            const rec = recovery_record.decode(joined.items, carrier, covs, scratch) catch |e| {
                self.allocator.free(covs);
                self.allocator.free(scratch);
                switch (e) {
                    error.BufferTooSmall => {
                        cov_cap *= 2;
                        scratch_cap *= 2;
                        if (scratch_cap > 1 << 20) return error.BufferTooSmall;
                        continue;
                    },
                    // A record we cannot parse is reported as absent
                    // rather than fatal: it is provenance, not data,
                    // and a malformed one must not make an otherwise
                    // readable workbook un-openable.
                    else => return null,
                }
            };
            self.recovery_cov_storage = covs;
            self.recovery_text_storage = scratch;
            return rec;
        }
    }

    /// emb-3a: write embedding parts under `xl/zlsxEmbeddings/`.
    ///
    /// `inputs` — one entry per `<coverage>` to register. Caller
    /// owns vector quantization (provide `vec_body` in the on-disk
    /// dtype layout) and hash computation (provide `hashes` of
    /// length `count`).
    ///
    /// Parts written:
    /// - `xl/zlsxEmbeddings/index.xml` — the manifest
    /// - `xl/zlsxEmbeddings/_rels/index.xml.rels` — vec/hash rels
    /// - `xl/zlsxEmbeddings/<id>/vec.bin` per coverage
    /// - `xl/zlsxEmbeddings/<id>/hashes.bin` per coverage
    ///
    /// Content_Types Overrides are added automatically via
    /// `PartStore.addPart`. The workbook → index relationship in
    /// `xl/_rels/workbook.xml.rels` is registered (emb-3b) under
    /// `REL_TYPE_EMBEDDINGS` with target `zlsxEmbeddings/index.xml`
    /// so OPC consumers that prune unreferenced parts on passive
    /// save preserve the embedding part set. A second `setEmbeddings`
    /// call on the same workbook detects existing parts and routes
    /// them through `PartStore.replacePart` rather than surfacing
    /// `PartAlreadyExists`; vec/hash sub-parts for coverage ids that
    /// were present in the prior write but absent from the new one
    /// remain in the archive as orphans (no inbound relationship,
    /// no index reference) — same v1 trade-off as `deleteSheet`.
    ///
    /// Errors:
    /// - `InvalidEmbeddingInput` — `inputs.len == 0`, or per-input
    ///   `vec_body` / `hashes` length mismatch against the range-
    ///   derived count.
    /// - `embedding_part.Error.InvalidRange` — range is not a valid
    ///   A1 form.
    /// - `embedding_part.Error.InvalidCoverageId` — id is empty,
    ///   too long, or has a forbidden character.
    /// - `embedding_part.Error.DuplicateCoverageId` — two inputs
    ///   share the same `id`.
    /// - `embedding_part.Error.CoverageOverlap` — two inputs name
    ///   the same `worksheet_target` and their A1 ranges intersect.
    /// - `EmbeddingExceedsArchiveLimit` — any part would exceed
    ///   PartStore's 512 MiB read cap.
    /// - `embedding_part.Error.BodySizeMismatch` — `vec_body.len`
    ///   does not equal `count * dtype.recordBytes(dim)`.
    /// - `MissingWorkbookRels` — `xl/_rels/workbook.xml.rels` is
    ///   absent. emb-3b registers a workbook→index relationship,
    ///   so the file must exist (every conforming workbook carries
    ///   one; absence indicates malformed input).
    /// - `MalformedWorkbookRels` — the rels file is missing the
    ///   closing `</Relationships>` tag.
    pub fn setEmbeddings(
        self: *Workbook,
        model: []const u8,
        dim: u32,
        dtype: embedding_part.Dtype,
        inputs: []const EmbeddingCoverageInput,
    ) Error!void {
        return self.setEmbeddingsOpts(model, dim, dtype, inputs, .{});
    }

    /// `setEmbeddings` with the durability trade-off exposed.
    ///
    /// The default is what `setEmbeddings` does: the recovery record
    /// rides in carriers no user can see, and Apple Numbers erases it.
    /// `recovery_in_cells` buys Numbers-durability at the cost of a
    /// hidden sheet a user can reveal — the two cannot be had together
    /// (see `RecoveryOptions`).
    pub fn setEmbeddingsOpts(
        self: *Workbook,
        model: []const u8,
        dim: u32,
        dtype: embedding_part.Dtype,
        inputs: []const EmbeddingCoverageInput,
        opts: RecoveryOptions,
    ) Error!void {
        if (inputs.len == 0) return error.InvalidEmbeddingInput;
        if (dim == 0) return error.InvalidEmbeddingInput;
        self.recovery_opts = opts;

        // Pass 1: per-input semantic validation + spec assembly.
        // rId strings are owned (heap-allocated since they don't
        // exist as static lits with the right number).
        var specs = try self.allocator.alloc(embedding_part.CoverageSpec, inputs.len);
        // `spec_freed` tracks how many specs have rIds we still need
        // to free on error. Cleanup loop walks specs[0..spec_freed].
        var spec_freed: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < spec_freed) : (i += 1) {
                self.allocator.free(specs[i].vec_rid);
                self.allocator.free(specs[i].hash_rid);
            }
            self.allocator.free(specs);
        }

        // Parallel array of parsed ranges, used for the overlap
        // check below. Not stored in CoverageSpec since the index-
        // XML encoder consumes the raw A1 string only.
        const parsed_ranges = try self.allocator.alloc(embedding_part.A1Range, inputs.len);
        defer self.allocator.free(parsed_ranges);

        for (inputs, 0..) |inp, i| {
            if (!isValidEmbeddingCoverageId(inp.id))
                return error.InvalidCoverageId;
            const range = try embedding_part.parseA1Range(inp.range);
            const count: u32 = range.last.row - range.first.row + 1;
            const expected_body: usize = @as(usize, count) * dtype.recordBytes(dim);
            if (inp.vec_body.len != expected_body) return error.InvalidEmbeddingInput;
            if (inp.hashes.len != count) return error.InvalidEmbeddingInput;
            parsed_ranges[i] = range;

            // Allocate rIds; +1 to make them 1-based.
            var rid_buf: [24]u8 = undefined;
            const vec_rid = std.fmt.bufPrint(&rid_buf, "rId{d}", .{2 * i + 1}) catch
                return error.WriteFailed;
            const vec_rid_dup = try self.allocator.dupe(u8, vec_rid);
            errdefer self.allocator.free(vec_rid_dup);
            const hash_rid = std.fmt.bufPrint(&rid_buf, "rId{d}", .{2 * i + 2}) catch
                return error.WriteFailed;
            const hash_rid_dup = try self.allocator.dupe(u8, hash_rid);
            errdefer self.allocator.free(hash_rid_dup);

            specs[i] = .{
                .id = inp.id,
                .worksheet_target = inp.worksheet_target,
                .range = inp.range,
                .column = inp.column,
                .count = count,
                .include_formulas = inp.include_formulas,
                .vec_rid = vec_rid_dup,
                .hash_rid = hash_rid_dup,
            };
            spec_freed = i + 1;
        }

        // Pass 2a: duplicate-id rejection.
        for (specs, 0..) |s, i| {
            for (specs[i + 1 ..]) |t| {
                if (std.mem.eql(u8, s.id, t.id)) return error.DuplicateCoverageId;
            }
        }

        // Pass 2b (emb-3b): coverage-overlap rejection. Two coverages
        // overlap when they name the same worksheet_target AND their
        // A1 ranges intersect — mirrors the parse-time check enforced
        // by `embedding_part.parseIndex`, so a setEmbeddings followed
        // by a Workbook.embeddings() roundtrip stays consistent.
        for (specs, 0..) |s, i| {
            for (specs[i + 1 ..], 0..) |t, j_off| {
                const j = i + 1 + j_off;
                if (!std.mem.eql(u8, s.worksheet_target, t.worksheet_target)) continue;
                if (parsed_ranges[i].overlaps(parsed_ranges[j])) return error.CoverageOverlap;
            }
        }

        // Pass 3: encode + upsert per coverage's binaries.
        for (inputs, specs) |inp, s| {
            const vec_part = try embedding_part.encodeVecPart(
                self.allocator,
                .{ .version = embedding_part.WIRE_VERSION, .dim = dim, .count = s.count, .dtype = dtype },
                inp.vec_body,
            );
            defer self.allocator.free(vec_part);
            if (vec_part.len > EMBEDDING_PART_MAX_BYTES)
                return error.EmbeddingExceedsArchiveLimit;

            const hash_part = try embedding_part.encodeHashesPart(self.allocator, inp.hashes);
            defer self.allocator.free(hash_part);
            if (hash_part.len > EMBEDDING_PART_MAX_BYTES)
                return error.EmbeddingExceedsArchiveLimit;

            // `vec_path` and `hash_path` need to outlive the bufPrint
            // scratch since `upsertEmbeddingPart` may use them across
            // an addPart/replacePart branch. Each goes into its own
            // 256-byte stack buffer.
            var vec_path_buf: [256]u8 = undefined;
            const vec_path = std.fmt.bufPrint(
                &vec_path_buf,
                "{s}/{s}/vec.bin",
                .{ embedding_part.EMBEDDINGS_DIR, s.id },
            ) catch return error.WriteFailed;
            try upsertEmbeddingPart(
                &self.store,
                vec_path,
                embedding_part.VEC_CONTENT_TYPE,
                vec_part,
            );

            var hash_path_buf: [256]u8 = undefined;
            const hash_path = std.fmt.bufPrint(
                &hash_path_buf,
                "{s}/{s}/hashes.bin",
                .{ embedding_part.EMBEDDINGS_DIR, s.id },
            ) catch return error.WriteFailed;
            try upsertEmbeddingPart(
                &self.store,
                hash_path,
                embedding_part.HASH_CONTENT_TYPE,
                hash_part,
            );
        }

        // Pass 4: index.xml + index.xml.rels.
        const index_xml = try embedding_part.encodeIndexXml(self.allocator, .{
            .model = model,
            .dim = dim,
            .dtype = dtype,
            .hash_algo = embedding_part.HASH_ALGO_XXH3_64,
            .coverages = specs,
        });
        defer self.allocator.free(index_xml);
        if (index_xml.len > EMBEDDING_PART_MAX_BYTES)
            return error.EmbeddingExceedsArchiveLimit;
        try upsertEmbeddingPart(
            &self.store,
            embedding_part.INDEX_PART_NAME,
            embedding_part.INDEX_CONTENT_TYPE,
            index_xml,
        );

        // Build rels list (2 per coverage). Targets are
        // `<id>/{vec,hashes}.bin` relative to xl/zlsxEmbeddings/.
        var rels = try self.allocator.alloc(embedding_part.RelSpec, 2 * specs.len);
        defer self.allocator.free(rels);
        // Target strings owned per-rel (heap-allocated since each is
        // unique). Free after rels XML is emitted.
        var rel_freed: usize = 0;
        errdefer {
            var i: usize = 0;
            while (i < rel_freed) : (i += 1) self.allocator.free(rels[i].target);
        }
        for (specs, 0..) |s, i| {
            var target_buf: [128]u8 = undefined;
            const vec_target = std.fmt.bufPrint(&target_buf, "{s}/vec.bin", .{s.id}) catch
                return error.WriteFailed;
            const vec_target_dup = try self.allocator.dupe(u8, vec_target);
            rels[2 * i + 0] = .{
                .id = s.vec_rid,
                .type = embedding_part.REL_TYPE_VEC,
                .target = vec_target_dup,
            };
            rel_freed = 2 * i + 1;

            const hash_target = std.fmt.bufPrint(&target_buf, "{s}/hashes.bin", .{s.id}) catch
                return error.WriteFailed;
            const hash_target_dup = try self.allocator.dupe(u8, hash_target);
            rels[2 * i + 1] = .{
                .id = s.hash_rid,
                .type = embedding_part.REL_TYPE_HASH,
                .target = hash_target_dup,
            };
            rel_freed = 2 * i + 2;
        }

        const rels_xml = try embedding_part.encodeIndexRelsXml(self.allocator, rels);
        defer self.allocator.free(rels_xml);
        try upsertEmbeddingPart(
            &self.store,
            embedding_part.INDEX_RELS_PART_NAME,
            EMBEDDING_RELS_CONTENT_TYPE,
            rels_xml,
        );

        // emb-3b: register the workbook → index relationship in
        // `xl/_rels/workbook.xml.rels`. OPC consumers may legitimately
        // strip unknown parts that no parent part references on a
        // passive save; the embeddings rel pins the index so a save
        // through Excel / LibreOffice / Numbers preserves the part
        // set. Idempotent — a prior call leaves the existing rel
        // intact rather than appending a duplicate.
        try self.registerWorkbookEmbeddingsRel();

        // ER: write the recovery record. This is what makes a strip
        // by Numbers or LibreOffice *detectable* — those tools drop
        // every part above, and without the record the result is
        // indistinguishable from a workbook that never had vectors.
        try self.writeRecoveryRecord(model, dim, dtype, specs, inputs);

        // Free the owned target / rId strings now that they're
        // emitted into rels_xml.
        for (rels) |r| self.allocator.free(r.target);
        rel_freed = 0;
        for (specs) |s| {
            self.allocator.free(s.vec_rid);
            self.allocator.free(s.hash_rid);
        }
        spec_freed = 0;
        self.allocator.free(specs);
    }

    /// Remove every embedding artefact — the exact inverse of
    /// `setEmbeddings`, including the recovery record.
    ///
    /// This is the pre-share operation from the design's Caveats: it
    /// removes the vectors *and* the evidence they ever existed, so a
    /// stripped workbook reports `.absent` rather than `.stripped`.
    /// That is deliberately the one place the durability contract's
    /// "never a silent nothing" rule does not apply — the caller asked
    /// for the nothing.
    ///
    /// Idempotent, and safe on a workbook that never had embeddings:
    /// every removal below is a no-op when its part is missing.
    /// Callable on a partially-stripped workbook too (a Numbers export
    /// that kept the recovery record but dropped the vectors), which is
    /// why the recovery carriers are cleaned unconditionally rather
    /// than only when an index was found.
    pub fn stripEmbeddings(self: *Workbook) Error!void {
        // Sweep the whole `xl/zlsxEmbeddings/` directory rather than
        // walking the index's coverage list. The index names the parts
        // *this writer* created; the directory holds whatever is
        // actually in the archive. They diverge exactly when it matters
        // — a truncated or hand-edited index — and leaving vectors
        // behind is the one failure this call exists to prevent.
        //
        // It also means a malformed index needs no special handling: it
        // is just another part under the directory.
        try self.removeEmbeddingDirParts();
        try self.unregisterWorkbookEmbeddingsRel();

        // The recovery record rides in three carriers; all three go.
        self.dropStagedRecoveryNames();
        try self.stripRecoveryNamesFromWorkbookXml();
        try self.removeRecoveryDocProp();
        try self.removeRecoveryCellSheet();

        self.invalidateEmbeddingCache();
    }

    /// Run the redaction sweep: tombstone every slot whose row is no
    /// longer embeddable, and zero the vector that described it.
    ///
    /// This is the `--prune` half of the design's redaction policy
    /// (§Caveats). A row deleted or blanked in plain Excel leaves its
    /// vector behind on disk — recoverable, and describing text the
    /// user believes they removed. The hash column is what detects it:
    /// the stored hash no longer matches anything embeddable at that
    /// row.
    ///
    /// `count` and `@range` do NOT change. The format is dense — slot
    /// `i` is row `first_row + i`, always — so compacting would
    /// silently re-point every later slot at the wrong row. A redacted
    /// slot stays in place as a tombstone.
    ///
    /// Content that merely *drifted* is reported, not redacted; see
    /// `PruneReport.stale`.
    pub fn pruneEmbeddings(self: *Workbook) Error!PruneReport {
        const view = (try self.embeddings()).viewOrNull() orelse return .{};
        const dim = view.index.dim;

        // Resolve rid→target again rather than reaching into the cached
        // view: the write below needs part *names*, which the view does
        // not carry.
        const rels_part = (try self.store.part(embedding_part.INDEX_RELS_PART_NAME)) orelse
            return error.MissingEmbeddingPart;
        var rels_buf: [64]embedding_part.IndexRelationship = undefined;
        const rels = embedding_part.parseIndexRelationships(rels_part.bytes, &rels_buf) catch
            return error.MissingEmbeddingPart;

        var report: PruneReport = .{};
        var scratch: std.ArrayListUnmanaged(u8) = .empty;
        defer scratch.deinit(self.allocator);

        // Patched bytes are staged per coverage and written before
        // moving on, but the cache is only invalidated at the end —
        // `view` borrows into the old part bytes and must stay valid
        // for the whole walk.
        var pending: std.ArrayListUnmanaged(struct { name: []const u8, bytes: []u8 }) = .empty;
        defer {
            for (pending.items) |p| {
                self.allocator.free(p.name);
                self.allocator.free(p.bytes);
            }
            pending.deinit(self.allocator);
        }

        for (view.coverages) |cv| {
            const cov = cv.coverage;
            const ws = (try self.worksheetForTarget(cov.worksheet_target)) orelse continue;

            const vec_name = try self.embeddingPartName(rels, cov.vec_rid);
            defer self.allocator.free(vec_name);
            const hash_name = try self.embeddingPartName(rels, cov.hash_rid);
            defer self.allocator.free(hash_name);

            const vec_src = ((try self.store.part(vec_name)) orelse
                return error.MissingEmbeddingPart).bytes;
            const hash_src = ((try self.store.part(hash_name)) orelse
                return error.MissingEmbeddingPart).bytes;

            // Copied lazily: a coverage with nothing to redact must not
            // rewrite its parts at all, so an unchanged workbook stays
            // byte-identical.
            var new_vec: ?[]u8 = null;
            var new_hash: ?[]u8 = null;
            errdefer {
                if (new_vec) |b| self.allocator.free(b);
                if (new_hash) |b| self.allocator.free(b);
            }

            var slot: u32 = 0;
            while (slot < cov.count) : (slot += 1) {
                const row = cov.parsed_range.first.row + slot;
                const stored = try cv.hashes.value(slot);
                const state = try self.classifySlot(ws, cov, row, stored, &scratch);
                switch (state) {
                    .fresh => report.fresh += 1,
                    .stale => report.stale += 1,
                    .valid_empty => report.valid_empty += 1,
                    .stale_needs_tombstone => {
                        report.redacted += 1;
                        if (new_vec == null) new_vec = try self.allocator.dupe(u8, vec_src);
                        if (new_hash == null) new_hash = try self.allocator.dupe(u8, hash_src);
                        try redactSlot(new_vec.?, new_hash.?, slot, dim, cv.vec.header.dtype);
                    },
                }
            }

            if (new_vec) |b| {
                const owned = try self.allocator.dupe(u8, vec_name);
                errdefer self.allocator.free(owned);
                try pending.append(self.allocator, .{ .name = owned, .bytes = b });
                new_vec = null;
            }
            if (new_hash) |b| {
                const owned = try self.allocator.dupe(u8, hash_name);
                errdefer self.allocator.free(owned);
                try pending.append(self.allocator, .{ .name = owned, .bytes = b });
                new_hash = null;
            }
        }

        for (pending.items) |p| try self.store.replacePart(p.name, p.bytes);
        if (report.redacted > 0) self.invalidateEmbeddingCache();
        return report;
    }

    /// Allocator-owned full part name for a coverage's rId.
    fn embeddingPartName(
        self: *Workbook,
        rels: []const embedding_part.IndexRelationship,
        rid: []const u8,
    ) Error![]const u8 {
        const target = resolveEmbeddingRelTarget(rels, rid) orelse
            return error.MissingEmbeddingPart;
        return std.fmt.allocPrint(self.allocator, "{s}/{s}", .{
            embedding_part.EMBEDDINGS_DIR, target,
        }) catch return error.WriteFailed;
    }

    /// Classify one slot against the live cell at `row`.
    fn classifySlot(
        self: *Workbook,
        ws: *Worksheet,
        cov: embedding_part.Coverage,
        row: u32,
        stored: u64,
        scratch: *std.ArrayListUnmanaged(u8),
    ) Error!SlotState {
        var ref_buf: [16]u8 = undefined;
        const ref = std.fmt.bufPrint(&ref_buf, "{s}{d}", .{ cov.column, row }) catch
            return error.WriteFailed;

        const was_tombstone = stored == embedding_part.TOMBSTONE_HASH;

        // `cellByRef` reads the parsed sheet XML, which does not carry
        // staged `setCell` edits. Without this, `setCell(.blank)` then
        // `prune()` then `save()` would write the blank and keep the
        // vector — the exact orphan this call exists to remove.
        //
        // A staged value is never reported `fresh`: re-deriving its
        // canonical hash would mean reproducing the save-time encoding
        // (SST routing, Ryu number formatting), and guessing wrong
        // would claim freshness that isn't there. Drift is the safe
        // answer, and the caller re-embeds.
        // `column_idx` is 0-based (`embedding_part.parseColumnName`
        // returns `col - 1`); `deltas` is keyed by `parseA1Ref`, which
        // is 1-based. Two conventions, one codebase — the `+ 1` is
        // load-bearing, and without it every lookup silently misses.
        if (ws.deltas.get(.{ .row = row, .col = cov.column_idx + 1 })) |pending| {
            const embeddable = switch (pending) {
                .blank, .deleted => false,
                .string, .shared_string => |s| s.len > 0,
                .formula => cov.include_formulas,
                .number, .boolean => true,
            };
            if (!embeddable) return if (was_tombstone) .valid_empty else .stale_needs_tombstone;
            return .stale;
        }

        const canonical = try self.canonicalCellFor(ws, ref, cov.include_formulas);

        const cell = canonical orelse {
            // Nothing embeddable here now.
            return if (was_tombstone) .valid_empty else .stale_needs_tombstone;
        };

        // Embeddable. A tombstone means the row *became* embeddable
        // since the last embed — stale, but there is nothing to redact.
        if (was_tombstone) return .stale;

        const now = embedding_part.xxh3Canonical(
            self.allocator,
            cov.worksheet_target,
            row,
            cell,
            scratch,
        ) catch return error.WriteFailed;
        return if (now == stored) .fresh else .stale;
    }

    /// Live cell → the canonical form the hash is taken over, or null
    /// when the row is not embeddable (blank, or a formula while
    /// `include_formulas="false"`).
    /// Rows in `column` over `range` that carry embeddable content.
    ///
    /// Non-embeddable rows are **omitted**, not emitted with empty
    /// text. The caller is about to pay one model invocation per row,
    /// and embedding "" burns a call to produce a vector that means
    /// nothing. The gaps are recoverable: any covered row missing from
    /// this list gets `TOMBSTONE_HASH` when the vectors come back,
    /// which is the same state `--prune` would leave it in.
    ///
    /// `text` borrows from the shared-string table or the sheet XML —
    /// valid for as long as the `Workbook` is.
    pub fn embeddableRows(
        self: *Workbook,
        allocator: Allocator,
        worksheet_target: []const u8,
        range: []const u8,
        column: []const u8,
        include_formulas: bool,
    ) Error![]EmbeddableRow {
        const parsed = try embedding_part.parseA1Range(range);
        const col_idx = try embedding_part.parseColumnName(column);
        if (col_idx < parsed.first.col or col_idx > parsed.last.col)
            return error.InvalidRange;

        const ws = (try self.worksheetForTarget(worksheet_target)) orelse
            return error.MissingSheetPart;

        var out: std.ArrayListUnmanaged(EmbeddableRow) = .empty;
        errdefer out.deinit(allocator);
        var scratch: std.ArrayListUnmanaged(u8) = .empty;
        defer scratch.deinit(self.allocator);

        var row = parsed.first.row;
        while (row <= parsed.last.row) : (row += 1) {
            var ref_buf: [16]u8 = undefined;
            const ref = std.fmt.bufPrint(&ref_buf, "{s}{d}", .{ column, row }) catch
                return error.WriteFailed;
            const cell = (try self.canonicalCellFor(ws, ref, include_formulas)) orelse continue;
            const text: []const u8 = switch (cell) {
                .string, .number, .error_value => |s| s,
                .boolean => |b| if (b) "1" else "0",
                .blank => continue,
            };
            const hash = embedding_part.xxh3Canonical(
                self.allocator,
                worksheet_target,
                row,
                cell,
                &scratch,
            ) catch return error.WriteFailed;
            try out.append(allocator, .{ .row = row, .text = text, .hash = hash });
        }
        return out.toOwnedSlice(allocator);
    }

    fn canonicalCellFor(
        self: *Workbook,
        ws: *Worksheet,
        ref: []const u8,
        include_formulas: bool,
    ) Error!?embedding_part.CanonicalCell {
        const cell = (try ws.cellByRef(ref)) orelse return null;
        if (cell.formula != null and !include_formulas) return null;
        const raw = cell.raw_value orelse return null;
        if (raw.len == 0) return null;

        return switch (cell.cell_type) {
            .shared_string => blk: {
                const idx = std.fmt.parseInt(u32, raw, 10) catch return error.UnsupportedCellValue;
                const text = (try self.sstText(idx)) orelse return null;
                break :blk if (text.len == 0) null else .{ .string = text };
            },
            .inline_string, .formula_string => .{ .string = raw },
            .number, .date => .{ .number = raw },
            // Strict per spec: `<v>` is exactly "0" or "1"; anything
            // else is malformed OOXML rather than a value to coerce.
            .boolean => if (std.mem.eql(u8, raw, "1"))
                .{ .boolean = true }
            else if (std.mem.eql(u8, raw, "0"))
                .{ .boolean = false }
            else
                return error.UnsupportedCellValue,
            .error_value => .{ .error_value = raw },
        };
    }

    /// The `Worksheet` a coverage's `@worksheet_target` names, if it is
    /// still in the workbook. Targets are relative to `xl/`.
    fn worksheetForTarget(self: *Workbook, target: []const u8) Error!?*Worksheet {
        var buf: [256]u8 = undefined;
        const want = std.fmt.bufPrint(&buf, "xl/{s}", .{target}) catch return null;
        var i: u32 = 0;
        while (i < self.sheetCount()) : (i += 1) {
            const ws = try self.sheet(i);
            const name = try ws.resolvePartName();
            if (std.mem.eql(u8, name, want)) return ws;
        }
        return null;
    }

    /// Free the lazily-parsed embedding views.
    ///
    /// `embeddings()` assigns these storages unconditionally, so a
    /// re-parse after a mutation would leak the previous allocation if
    /// they were merely nulled.
    fn invalidateEmbeddingCache(self: *Workbook) void {
        if (self.embedding_coverage_views) |s| self.allocator.free(s);
        if (self.embedding_rels_storage) |s| self.allocator.free(s);
        if (self.embedding_index_storage) |s| self.allocator.free(s);
        self.embedding_coverage_views = null;
        self.embedding_rels_storage = null;
        self.embedding_index_storage = null;
        self.embedding_view = null;
    }

    /// Drop every `xl/zlsxEmbeddings/**` part — index, rels, and every
    /// coverage's `vec.bin` / `hashes.bin`.
    ///
    /// Walks the store backwards because `removePart` compacts the
    /// parallel arrays, so forward iteration would skip the entry that
    /// slides into each removed slot.
    ///
    /// Each `removePart` independently drops the removed part's
    /// content-type override and rewrites any `.rels` file pointing at
    /// it, so no ordering between them is required.
    fn removeEmbeddingDirParts(self: *Workbook) Error!void {
        var i: usize = self.store.parts.len;
        while (i > 0) {
            i -= 1;
            const name = self.store.parts[i].name;
            if (!std.mem.startsWith(u8, name, embedding_part.EMBEDDINGS_DIR)) continue;
            // Guard against a same-prefix sibling directory, e.g.
            // `xl/zlsxEmbeddingsBackup/…`, which is not ours to delete.
            if (name.len > embedding_part.EMBEDDINGS_DIR.len and
                name[embedding_part.EMBEDDINGS_DIR.len] != '/') continue;
            try self.store.removePart(name);
        }
    }

    /// Remove the recovery property from `docProps/custom.xml`.
    ///
    /// Removes only our own `<property>`; the part itself goes only if
    /// nothing else is left in it. A workbook can carry custom
    /// properties that predate the embeddings, and a strip has no
    /// business discarding them.
    fn removeRecoveryDocProp(self: *Workbook) Error!void {
        const part = (try self.store.part("docProps/custom.xml")) orelse return;
        const src = part.bytes;
        if (std.mem.indexOf(u8, src, recovery_record.DOC_PROP_NAME) == null) return;

        var out: std.Io.Writer.Allocating = .init(self.allocator);
        defer out.deinit();
        const w = &out.writer;

        // Two cursors, deliberately: `pos` is the start of the region
        // not yet copied out, `scan` is where to look for the next
        // element. A kept property must leave `pos` untouched so it
        // stays inside the region a later copy flushes — advancing both
        // would skip it into the gap and silently drop it.
        var pos: usize = 0;
        var scan: usize = 0;
        var kept_properties: usize = 0;
        while (std.mem.indexOfPos(u8, src, scan, "<property")) |start| {
            // A `<property/>` with no close tag is malformed for this
            // schema (the value is a required child). Stop rather than
            // guess — erring toward keeping bytes we did not write.
            const end_tag = std.mem.indexOfPos(u8, src, start, "</property>") orelse break;
            const after = end_tag + "</property>".len;
            if (std.mem.indexOf(u8, src[start..after], recovery_record.DOC_PROP_NAME) == null) {
                kept_properties += 1;
                scan = after;
                continue;
            }
            w.writeAll(src[pos..start]) catch return error.WriteFailed;
            pos = after;
            scan = after;
        }

        if (kept_properties == 0) {
            try self.store.removePart("docProps/custom.xml");
            return;
        }
        w.writeAll(src[pos..]) catch return error.WriteFailed;
        try self.store.replacePart("docProps/custom.xml", out.written());
    }

    /// Delete the hidden `zlsxRecovery` sheet written by the
    /// `recovery_in_cells` opt-in, if it is present.
    fn removeRecoveryCellSheet(self: *Workbook) Error!void {
        // Names live on the parsed workbook view, not on `Worksheet` —
        // same lookup `sheetByName` does.
        for (self.workbook.sheets, 0..) |s, i| {
            if (!std.mem.eql(u8, s.name, recovery_record.CELL_SHEET_NAME)) continue;
            try self.deleteSheet(@intCast(i));
            return;
        }
    }

    /// Fold every coverage's per-row content hashes into one digest,
    /// in coverage order.
    ///
    /// Recomputable from the *current* cells via the same
    /// canonicalization, which is the point: after a strip, equal
    /// means the covered content has not drifted and a re-embed
    /// reproduces the same vectors; unequal means the content moved
    /// on too.
    fn embeddingDigest(inputs: []const EmbeddingCoverageInput) u64 {
        var h = std.hash.XxHash3.init(embedding_part.HASH_SEED);
        for (inputs) |in| {
            for (in.hashes) |x| {
                var b: [8]u8 = undefined;
                std.mem.writeInt(u64, &b, x, .little);
                h.update(&b);
            }
        }
        return h.final();
    }

    /// ER write path: encode the recovery record and place it in both
    /// carriers — a hidden `<definedName>` (primary) and
    /// `docProps/custom.xml` (secondary).
    ///
    /// Both, because their removal mechanisms are disjoint: Document
    /// Inspector ▸ Document Properties and Personal Information strips
    /// `docProps` and does not touch defined names. ~200 bytes of
    /// redundancy against a vector set measured in megabytes.
    fn writeRecoveryRecord(
        self: *Workbook,
        model: []const u8,
        dim: u32,
        dtype: embedding_part.Dtype,
        specs: []const embedding_part.CoverageSpec,
        inputs: []const EmbeddingCoverageInput,
    ) Error!void {
        var covs = try self.allocator.alloc(recovery_record.RecoveredCoverage, specs.len);
        defer self.allocator.free(covs);
        for (specs, inputs, 0..) |s, in, i| {
            covs[i] = .{
                .id = s.id,
                .worksheet_target = s.worksheet_target,
                .range = s.range,
                .count = @intCast(in.hashes.len),
            };
        }

        const rec = recovery_record.encode(self.allocator, .{
            .model = model,
            .dim = dim,
            .dtype = dtype.string(),
            .hash_algo = embedding_part.HASH_ALGO_XXH3_64,
            .coverages = covs,
            .digest = embeddingDigest(inputs),
        }) catch |e| switch (e) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return error.WriteFailed,
        };
        defer self.allocator.free(rec);

        const n = recovery_record.chunkCount(rec.len);
        if (n > recovery_record.MAX_CHUNKS) return error.EmbeddingExceedsArchiveLimit;

        // Upsert, not append: a second setEmbeddings on the same
        // workbook must replace the record, not accumulate stale
        // copies alongside it. Clear both the staged plan and any
        // names already in the saved bytes before writing.
        self.dropStagedRecoveryNames();
        try self.stripRecoveryNamesFromWorkbookXml();

        var name_buf: [32]u8 = undefined;
        var lit_buf: [recovery_record.MAX_CHUNK + 2]u8 = undefined;
        for (0..n) |i| {
            const name = recovery_record.chunkName(&name_buf, i);
            // A string-literal formula. The payload is percent-encoded
            // ASCII, so it can never contain the quote that would need
            // doubling here.
            const lit = std.fmt.bufPrint(&lit_buf, "\"{s}\"", .{recovery_record.chunk(rec, i)}) catch
                return error.WriteFailed;
            try self.addDefinedName(name, lit, .{ .hidden = true });
        }

        try self.writeRecoveryDocProp(rec);
        if (self.recovery_opts.recovery_in_cells) try self.writeRecoveryCell(rec);
    }

    /// Write the record into a hidden sheet as ordinary cell content.
    ///
    /// Ordinary on purpose: cell data is the only thing Numbers keeps,
    /// precisely because it is part of the document model rather than
    /// package furniture. Anything cleverer would be outside that model
    /// and would not survive.
    ///
    /// Idempotent — a re-embed rewrites the sheet's single cell rather
    /// than adding a second sheet.
    fn writeRecoveryCell(self: *Workbook, rec: []const u8) Error!void {
        if (try self.sheetByName(recovery_record.CELL_SHEET_NAME)) |ws| {
            try ws.setCell("A1", .{ .string = rec });
            return;
        }
        const ws = try self.addSheet(recovery_record.CELL_SHEET_NAME);
        try ws.appendRows(&[_][]const zlsx.Cell{&.{.{ .string = rec }}});
    }

    /// Remove `_zlsxRecovery*` entries from the staged defined-name
    /// plan, freeing their owned strings.
    fn dropStagedRecoveryNames(self: *Workbook) void {
        const list = &self.workbook_xml_plan.defined_names;
        var i: usize = 0;
        while (i < list.items.len) {
            if (std.mem.startsWith(u8, list.items[i].name, recovery_record.NAME_PREFIX)) {
                const removed = list.orderedRemove(i);
                self.allocator.free(removed.name);
                self.allocator.free(removed.refers_to);
                continue;
            }
            i += 1;
        }
    }

    /// Drop `<definedName name="_zlsxRecovery…">…</definedName>`
    /// elements already present in `xl/workbook.xml`.
    ///
    /// Needed because the staged plan splices into the *saved* bytes:
    /// without this, a re-embed after a save would leave the previous
    /// record's chunks beside the new ones, and a reader concatenating
    /// by index would splice two generations together.
    fn stripRecoveryNamesFromWorkbookXml(self: *Workbook) Error!void {
        const part = (try self.store.part("xl/workbook.xml")) orelse return;
        const src = part.bytes;
        if (std.mem.indexOf(u8, src, recovery_record.NAME_PREFIX) == null) return;

        var out: std.ArrayListUnmanaged(u8) = .empty;
        defer out.deinit(self.allocator);

        var i: usize = 0;
        while (i < src.len) {
            const tag_open = std.mem.indexOfPos(u8, src, i, "<definedName") orelse {
                try out.appendSlice(self.allocator, src[i..]);
                break;
            };
            const gt = std.mem.indexOfScalarPos(u8, src, tag_open, '>') orelse {
                try out.appendSlice(self.allocator, src[i..]);
                break;
            };
            const attrs = src[tag_open..gt];
            const is_ours = std.mem.indexOf(u8, attrs, recovery_record.NAME_PREFIX) != null;
            if (!is_ours) {
                try out.appendSlice(self.allocator, src[i .. gt + 1]);
                i = gt + 1;
                continue;
            }
            try out.appendSlice(self.allocator, src[i..tag_open]);
            if (src[gt - 1] == '/') {
                i = gt + 1;
            } else {
                const close = std.mem.indexOfPos(u8, src, gt + 1, "</definedName>") orelse {
                    i = gt + 1;
                    continue;
                };
                i = close + "</definedName>".len;
            }
        }
        try self.store.replacePart("xl/workbook.xml", out.items);
    }

    /// Write the record into `docProps/custom.xml`, creating the part
    /// (and its package relationship) when absent.
    fn writeRecoveryDocProp(self: *Workbook, rec: []const u8) Error!void {
        // An existing part is edited, never overwritten. A workbook can
        // carry custom properties that predate the embeddings, and
        // embedding vectors is no reason to discard someone else's
        // metadata — `removeRecoveryDocProp` is careful to preserve
        // them on the way out, so the way in has to match.
        if ((try self.store.part("docProps/custom.xml")) != null) {
            return self.upsertRecoveryDocProp(rec);
        }

        const xml = std.fmt.allocPrint(self.allocator,
            \\<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
            \\<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/custom-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><property fmtid="{{D5CDD505-2E9C-101B-9397-08002B2CF9AE}}" pid="2" name="{s}"><vt:lpwstr>{s}</vt:lpwstr></property></Properties>
        , .{ recovery_record.DOC_PROP_NAME, rec }) catch return error.WriteFailed;
        defer self.allocator.free(xml);

        try self.store.addPart(
            "docProps/custom.xml",
            "application/vnd.openxmlformats-officedocument.custom-properties+xml",
            xml,
        );
        try self.registerDocPropsCustomRel();
    }

    /// Splice the recovery property into an existing
    /// `docProps/custom.xml`, replacing our own previous entry and
    /// leaving every other property untouched.
    fn upsertRecoveryDocProp(self: *Workbook, rec: []const u8) Error!void {
        const part = (try self.store.part("docProps/custom.xml")) orelse return;
        const src = part.bytes;

        const close = std.mem.lastIndexOf(u8, src, "</Properties>") orelse {
            // Not a custom-properties document at all. Nothing here is
            // meaningful to preserve, so write a well-formed one.
            const xml = std.fmt.allocPrint(self.allocator,
                \\<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
                \\<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/custom-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><property fmtid="{{D5CDD505-2E9C-101B-9397-08002B2CF9AE}}" pid="2" name="{s}"><vt:lpwstr>{s}</vt:lpwstr></property></Properties>
            , .{ recovery_record.DOC_PROP_NAME, rec }) catch return error.WriteFailed;
            defer self.allocator.free(xml);
            return self.store.replacePart("docProps/custom.xml", xml);
        };

        var out: std.Io.Writer.Allocating = .init(self.allocator);
        defer out.deinit();
        const w = &out.writer;

        // Drop our previous entry so a re-embed replaces rather than
        // accumulates. Same two-cursor split as `removeRecoveryDocProp`:
        // `pos` is the uncopied region, `scan` is the search head, and a
        // kept property must leave `pos` alone.
        var pos: usize = 0;
        var scan: usize = 0;
        while (std.mem.indexOfPos(u8, src, scan, "<property")) |start| {
            if (start > close) break;
            const end_tag = std.mem.indexOfPos(u8, src, start, "</property>") orelse break;
            const after = end_tag + "</property>".len;
            if (std.mem.indexOf(u8, src[start..after], recovery_record.DOC_PROP_NAME) == null) {
                scan = after;
                continue;
            }
            w.writeAll(src[pos..start]) catch return error.WriteFailed;
            pos = after;
            scan = after;
        }

        // `pid` must be unique within the part; colliding with a
        // neighbour's would make the document invalid rather than
        // merely odd. Spec floor is 2.
        const next_pid = @max(nextMaxNumericAttr(src, "pid=\"") + 1, 2);

        // Everything up to the closing tag, then our property, then the
        // closing tag — so we land last and disturb no existing offsets.
        const keep_end = @max(pos, @min(close, src.len));
        w.writeAll(src[pos..keep_end]) catch return error.WriteFailed;
        w.print(
            "<property fmtid=\"{{D5CDD505-2E9C-101B-9397-08002B2CF9AE}}\" pid=\"{d}\" name=\"{s}\"><vt:lpwstr>{s}</vt:lpwstr></property>",
            .{ next_pid, recovery_record.DOC_PROP_NAME, rec },
        ) catch return error.WriteFailed;
        w.writeAll(src[close..]) catch return error.WriteFailed;

        try self.store.replacePart("docProps/custom.xml", out.written());
    }

    /// Add the package-level relationship for `docProps/custom.xml`.
    /// Idempotent, same contract as `registerWorkbookEmbeddingsRel`.
    fn registerDocPropsCustomRel(self: *Workbook) Error!void {
        const REL_TYPE = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties";
        const rels_part = (try self.store.part("_rels/.rels")) orelse return;
        if (std.mem.indexOf(u8, rels_part.bytes, REL_TYPE) != null) return;

        const close = "</Relationships>";
        const at = std.mem.lastIndexOf(u8, rels_part.bytes, close) orelse
            return error.MalformedWorkbookRels;
        const out = std.fmt.allocPrint(
            self.allocator,
            "{s}<Relationship Id=\"rIdZlsxRecovery\" Type=\"{s}\" Target=\"docProps/custom.xml\"/>{s}",
            .{ rels_part.bytes[0..at], REL_TYPE, rels_part.bytes[at..] },
        ) catch return error.WriteFailed;
        defer self.allocator.free(out);
        try self.store.replacePart("_rels/.rels", out);
    }

    /// emb-3b: Ensure `xl/_rels/workbook.xml.rels` carries a
    /// `<Relationship Type="…/relationships/embeddings"
    /// Target="zlsxEmbeddings/index.xml"/>` entry. Idempotent: if a
    /// rel with the embeddings type already exists, returns without
    /// mutation (preserves the prior rId). Otherwise picks the next
    /// free rId (one past the largest `rId<N>` in the file) and
    /// splices in a new entry before `</Relationships>`.
    ///
    /// Surfaces `MissingWorkbookRels` if `xl/_rels/workbook.xml.rels`
    /// is absent, and `MalformedWorkbookRels` if the file lacks
    /// a closing `</Relationships>` tag.
    /// Remove the workbook→index relationship.
    ///
    /// `PartStore.removePart` rewrites rels pointing at a removed part,
    /// but it matches on the part's *full* name. This Target is written
    /// relative to the rels file's owner — `zlsxEmbeddings/index.xml`,
    /// not `xl/zlsxEmbeddings/index.xml` — so it survives that sweep and
    /// would be left dangling at a part that no longer exists.
    ///
    /// Matched on Type, the same functional key the add path uses for
    /// its idempotency check, so every Target spelling is covered.
    fn unregisterWorkbookEmbeddingsRel(self: *Workbook) Error!void {
        const rels_part = (try self.store.part("xl/_rels/workbook.xml.rels")) orelse return;
        const src = rels_part.bytes;
        if (std.mem.indexOf(u8, src, embedding_part.REL_TYPE_EMBEDDINGS) == null) return;

        var out: std.Io.Writer.Allocating = .init(self.allocator);
        defer out.deinit();
        const w = &out.writer;

        // Same two-cursor split as `removeRecoveryDocProp`: `pos` is the
        // uncopied region, `scan` is the search head.
        var pos: usize = 0;
        var scan: usize = 0;
        while (std.mem.indexOfPos(u8, src, scan, "<Relationship")) |start| {
            // `<Relationships>` — the root — shares this prefix. Its
            // span would run to the first child's `/>` and could carry
            // our Type inside it, splicing away a sibling. Require a
            // real tag boundary before treating the match as an element.
            const next = start + "<Relationship".len;
            if (next < src.len and src[next] != ' ' and src[next] != '/' and src[next] != '>') {
                scan = next;
                continue;
            }
            const close = std.mem.indexOfPos(u8, src, start, "/>") orelse break;
            const after = close + "/>".len;
            if (std.mem.indexOf(u8, src[start..after], embedding_part.REL_TYPE_EMBEDDINGS) == null) {
                scan = after;
                continue;
            }
            w.writeAll(src[pos..start]) catch return error.WriteFailed;
            pos = after;
            scan = after;
        }
        w.writeAll(src[pos..]) catch return error.WriteFailed;
        try self.store.replacePart("xl/_rels/workbook.xml.rels", out.written());
    }

    fn registerWorkbookEmbeddingsRel(self: *Workbook) Error!void {
        const rels_part = (try self.store.part("xl/_rels/workbook.xml.rels")) orelse
            return error.MissingWorkbookRels;

        // Idempotency: if a rel with our Type attribute is already
        // present, leave it alone. Rationale: a second setEmbeddings
        // call on the same workbook (replace path) should NOT append
        // a duplicate Relationship. ECMA-376 Part 2 §10.1.2 doesn't
        // explicitly forbid duplicates, but OPC consumers treat
        // (Type, Target) as the functional key — extra rels with the
        // same Type are at best confusing, at worst rejected.
        if (std.mem.indexOf(u8, rels_part.bytes, embedding_part.REL_TYPE_EMBEDDINGS) != null) {
            return;
        }

        const next_rid_num = nextMaxNumericAttr(rels_part.bytes, "Id=\"rId") + 1;
        var rid_buf: [32]u8 = undefined;
        const new_rid = std.fmt.bufPrint(&rid_buf, "rId{d}", .{next_rid_num}) catch
            return error.WriteFailed;

        const new_xml = try patchWorkbookRelsAddEmbeddings(
            self.allocator,
            rels_part.bytes,
            new_rid,
        );
        defer self.allocator.free(new_xml);
        try self.store.replacePart("xl/_rels/workbook.xml.rels", new_xml);
    }

    /// Resolve the number-format string a cell of `style_idx` would
    /// render with. Combines the OOXML built-in table (IDs 0..49 well-
    /// known subset; anything else falls through to the custom
    /// `<numFmt>` table in `xl/styles.xml`).
    ///
    /// Returns `null` when:
    ///   - the workbook has no `xl/styles.xml`,
    ///   - `style_idx` is outside `cell_xfs`,
    ///   - the resolved `numFmtId` matches no built-in and no custom
    ///     entry (malformed input — the cell would render as `General`
    ///     in Excel; callers wanting that fallback should treat `null`
    ///     as "General" themselves).
    ///
    /// Lifetime: built-in `code` is a `'static` string literal; custom
    /// `code` borrows from the StylesXml arena (alive as long as the
    /// `Workbook`).
    pub fn numberFormatFor(self: *Workbook, style_idx: u32) Error!?NumberFormatInfo {
        const styles_view = (try self.styles()) orelse return null;
        if (style_idx >= styles_view.cell_xfs.len) return null;
        const xf = styles_view.cell_xfs[style_idx];
        const nfid = xf.num_fmt_id orelse return null;
        if (builtinNumFmtCode(nfid)) |code| {
            return .{ .fmt_id = nfid, .code = code, .is_builtin = true };
        }
        for (styles_view.number_formats) |nf| {
            if (nf.fmt_id == nfid) {
                return .{ .fmt_id = nfid, .code = nf.code, .is_builtin = false };
            }
        }
        return null;
    }

    /// What `formatCellValue` answers. Three of the four arms are
    /// typed conditions the caller picks a spelling for — none of them
    /// is ever a guessed string.
    pub const CellDisplay = union(enum) {
        /// Rendered bytes, owned by the caller's allocator.
        text: []u8,
        /// numfmt_v1 refuses this format code — a park-list row
        /// (locale table, calendar, numeral shaping) or a code outside
        /// the grammar (§5.4b: typed refusal, never an improvisation).
        format_refused: engine.numfmt.Refusal,
        /// The epoch read (`workbookPr@date1904`) refused — malformed
        /// `xl/workbook.xml`.
        calc_refused: engine.calc.Refusal,
        /// The value's serial has no date under the workbook's epoch —
        /// the condition Excel fills a cell with `#` for.
        serial_out_of_range,
    };

    /// M8a's cell-display seam — numfmt_v1's second caller (`TEXT()`
    /// in the registry is the first, and §5.4b pins both to ONE
    /// derivation: neither adds a byte the other would not). Resolves
    /// `style_idx` to its format code (`null` resolves as `General`,
    /// the fallback Excel applies), parses it under the versioned
    /// grammar, and renders `v` under the workbook's own epoch — a
    /// caller-set epoch would silently redate every serial.
    ///
    /// The date-detection heuristic (`src/xlsx.zig`) and its callers
    /// are untouched by this seam; they flip onto the grammar at a
    /// later row, through `Format.describesDate`.
    pub fn formatCellValue(
        self: *Workbook,
        gpa: std.mem.Allocator,
        style_idx: u32,
        v: engine.numfmt.RenderValue,
    ) Error!CellDisplay {
        const info = try self.numberFormatFor(style_idx);
        const code = if (info) |i| i.code else "General";

        const wb_part = (try self.store.part("xl/workbook.xml")) orelse
            return Error.MissingWorkbookPart;
        var calc = switch (try engine.calc.parseCalcState(gpa, wb_part.bytes)) {
            .ok => |c| c,
            .refused => |r| return .{ .calc_refused = r },
        };
        const date_system = calc.date_system;
        calc.deinit(gpa);

        switch (try engine.numfmt.parse(gpa, code)) {
            .refused => |r| return .{ .format_refused = r },
            .ok => |fmt| {
                var f = fmt;
                defer f.deinit(gpa);
                const out = engine.numfmt.render(gpa, &f, v, .{
                    .date_system = date_system,
                }) catch |e| switch (e) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.SerialOutOfRange => return .serial_out_of_range,
                };
                return .{ .text = out };
            },
        }
    }

    /// Persist all pending mutations to `path`. For each Worksheet
    /// with a non-empty delta map: regenerate the sheet's `<sheetData>`
    /// block from the typed view + deltas, splice into the source
    /// XML byte-preserving everything outside `<sheetData>`, push
    /// through PartStore.replacePart, then write the whole archive
    /// via PartStore.save.
    ///
    /// On success: every Worksheet's delta map is empty and any
    /// previously-cached `SheetXml` view is invalidated (next access
    /// re-parses from the new bytes).
    ///
    /// iter-wb-4 m1 limits: numeric / boolean / blank values only.
    /// m2: strings + formulas. m4: shared-string mode (`<c t="s">`).
    pub fn save(self: *Workbook, io: std.Io, path: []const u8) Error!void {
        try self.applySavePlans();
        try self.store.save(io, path);
    }

    /// `save` into caller-owned memory (M9a2, §5.10). The same staged
    /// state the file save writes — deltas, appends, SST extension,
    /// defined names — lands in the store's override map first, so a
    /// later `save` to a path writes byte-identical content. The
    /// returned bytes are the caller's, freed with `allocator`.
    pub fn saveToOwnedBuffer(self: *Workbook, allocator: Allocator) Error![]u8 {
        try self.applySavePlans();
        return self.store.saveToOwnedBuffer(allocator, .none);
    }

    /// Everything `save` does before bytes leave the process: apply the
    /// workbook.xml plan, extend the SST, emit per-sheet XML for staged
    /// deltas / appended rows into `store.replacePart`, and invalidate
    /// the typed views those bytes made stale.
    fn applySavePlans(self: *Workbook) Error!void {
        // Phase 0 (B3 iter-wr-3): apply the workbook.xml fresh-emit
        // plan. Today the only axis is staged defined names — splice
        // them into `xl/workbook.xml` BEFORE the SST + per-sheet
        // phases so the workbook.xml byte image they read is final.
        // The validator at `addDefinedName` time guarantees every
        // staged name is well-formed; only the bounds check on
        // `local_sheet_id` runs at emit (sheet count may have grown
        // since the name was registered).
        if (self.workbook_xml_plan.defined_names.items.len > 0) {
            try self.applyWorkbookXmlPlanDefinedNames();
        }

        // Phase 1: SST extension. Walk every worksheet's deltas for
        // `.shared_string` values and build a single text → index
        // map covering new strings across all sheets. If any are
        // present, regenerate `xl/sharedStrings.xml` BEFORE per-sheet
        // emit (per-sheet emit needs the assigned indices).
        var sst_plan = try buildSstExtensionPlan(self);
        defer sst_plan.deinit(self.allocator);

        if (sst_plan.has_new_strings) {
            try applySstExtensionPlan(self, &sst_plan);
        }

        for (self.worksheets) |*ws| {
            // Per-sheet, deltas and appended_rows are mutually
            // exclusive (refused at staging time). Handle whichever
            // is non-empty; skip clean sheets entirely.
            if (ws.appended_rows.items.len > 0) {
                assert(ws.deltas.count() == 0);
                const part_name = try ws.resolvePartName();
                const new_xml = try ws.emitWithAppendsUsingPlan(self.allocator, &sst_plan);
                defer self.allocator.free(new_xml);
                try self.store.replacePart(part_name, new_xml);
                ws.clearAppendedRows(self.allocator);
                if (ws.parsed) |*p| {
                    var stale = p.*;
                    stale.deinit(self.allocator);
                    ws.parsed = null;
                }
                continue;
            }
            if (ws.deltas.count() == 0) continue;
            _ = try ws.ensureParsed();
            const part_name = ws.resolved_part_name.?;
            const view = &ws.parsed.?;
            const source = blk: {
                const p = try self.store.part(part_name) orelse return error.MissingSheetPart;
                break :blk p.bytes;
            };

            const new_xml = try emitSheetWithDeltas(
                self.allocator,
                source,
                view,
                &ws.deltas,
                &sst_plan,
            );
            defer self.allocator.free(new_xml);
            try self.store.replacePart(part_name, new_xml);

            freeDeltaStrings(self.allocator, &ws.deltas);
            ws.deltas.clearAndFree(self.allocator);
            // Invalidate the parsed view — its leaves borrowed from
            // the prior source bytes, which the caller may still see
            // as live (PartStore arena retains them) but the part's
            // logical content has changed.
            var stale = ws.parsed.?;
            stale.deinit(self.allocator);
            ws.parsed = null;
        }
        // Invalidate cached SST view — its leaves borrowed from the
        // pre-extension SST bytes which `replacePart` swapped out.
        if (sst_plan.has_new_strings) {
            if (self.sst_view) |*v| {
                var view = v.*;
                view.deinit(self.allocator);
                self.sst_view = null;
            }
        }
    }

    /// B3 iter-wr-7: emit a fresh `.xlsx` archive from the workbook's
    /// fresh-emit registries (`fresh_sst_plan`, `fresh_sst_count`,
    /// `styles_plan`, `workbook_xml_plan`) plus per-Worksheet `body` +
    /// `state`. Routes through the shared `pkg/fresh_emit.zig`
    /// substrate, producing byte-identical archives to
    /// `xlsx.Writer.save`. The PartStore is bypassed entirely — this
    /// is a pure producer path. Use `Workbook.empty()` then
    /// `addSheet` + per-Worksheet `add*`/`set*` registrations + this
    /// to author workbooks without a backing source archive.
    ///
    /// Errors flow through verbatim from the substrate: `NoSheets`
    /// when no worksheets are registered; allocation/zip-sentinel
    /// errors on archive build.
    pub fn saveFreshEmit(self: *Workbook, io: std.Io, path: []const u8) !void {
        if (self.worksheets.len == 0) return error.NoSheets;

        const inputs = try self.allocator.alloc(fresh_emit.SheetInput, self.worksheets.len);
        defer self.allocator.free(inputs);
        for (self.worksheets, 0..) |*ws, i| {
            inputs[i] = .{
                .name = ws.name(),
                .body = ws.body.items,
                .state = &ws.sheet_state,
            };
        }

        return fresh_emit.saveArchiveToPath(self.allocator, io, path, .{
            .sheets = inputs,
            .sst_plan = &self.fresh_sst_plan,
            .sst_count = self.fresh_sst_count,
            .styles_plan = &self.styles_plan,
            .workbook_xml_plan = &self.workbook_xml_plan,
        }, freshEmitDeflate, .none);
    }

    /// Stage a plain string into the fresh-emit SST and return the
    /// 0-based index for use in row-emit `<v>{idx}</v>` payloads.
    /// Increments `fresh_sst_count` (the running cell-occurrence
    /// counter that becomes the OOXML `<sst count=>` attribute).
    /// Pair with the `body` payload assembled per-Worksheet.
    pub fn freshSstIntern(self: *Workbook, text: []const u8) Error!u32 {
        const idx = try self.fresh_sst_plan.registerNewPlain(self.allocator, text);
        self.fresh_sst_count += 1;
        return idx;
    }

    /// Apply a structural-edit rewrite to every `<dataValidation>`
    /// formula1/formula2 and every `<cfRule>` formula across every
    /// sheet, persisting the result in-place via `store.replacePart`.
    /// Returns the count of formula *bodies* whose rewrite produced
    /// different bytes (so a DV with both formula1 and formula2
    /// changed counts as 2; an unchanged body — including a no-op
    /// shift — counts 0).
    ///
    /// `target_sheet` scopes the edit the same way as
    /// `RewriteContext.target_sheet`: when non-null, only refs that
    /// resolve to that sheet (bare refs on a matching `on_sheet`, or
    /// sheet-qualified refs naming `target_sheet`) shift. `null`
    /// means "apply everywhere".
    ///
    /// **Persistence model.** This emits patched sheet XML bytes
    /// *immediately* via `PartStore.replacePart`. It does NOT use the
    /// `Workbook.save`-deltas pipeline (DV/CF aren't cell mutations).
    /// Run this BEFORE `Workbook.save` if a save also has pending
    /// `setCell` deltas — `save` re-fetches part bytes per sheet, so
    /// it sees the patched DV/CF blocks and preserves them in its
    /// own splice. The cached `SheetXml` view is invalidated
    /// (`parsed = null`) for any sheet rewritten here, matching the
    /// invalidation contract used by `save`.
    ///
    /// **Splice strategy.** Patches the formula inner text in place,
    /// byte-for-byte, inside each `<formula1>`, `<formula2>`, and
    /// CF `<formula>` element whose body the rewriter changed. Every
    /// surrounding attribute (`errorTitle`, `error`, `prompt`,
    /// `xr:uid`, `dxf_id`, `priority`, `operator`, etc.) is preserved
    /// verbatim — we never regenerate the DV/CF block from the typed
    /// view, which would lose any trivia the parser doesn't expose.
    ///
    /// **Body counting.** Each formula body that produces different
    /// bytes counts once. So a CF `D1+E1` rewritten to `E1+F1` (one
    /// body, two refs shifted) is one rewrite, not two.
    /// Snapshot of the workbook tab order (sheet names, first tab
    /// first) for `RewriteContext.sheet_order` — what lets the
    /// rewriter contract a 3D span (`Sheet1:Sheet3!A1`) when an
    /// endpoint sheet is deleted, and decide mid-span membership.
    ///
    /// Entries are entity-DECODED (`R&amp;D` in workbook.xml becomes
    /// `R&D` here): the whole rewrite boundary operates on decoded
    /// text — formulas decode on the way in, every splice/emit path
    /// re-escapes on the way out (`appendXmlEscaped*`,
    /// `setCell`'s delta emit). Free with `freeSheetOrder`.
    fn sheetOrderSnapshot(self: *Workbook) Error![]const []const u8 {
        const a = self.allocator;
        const order = try a.alloc([]const u8, self.workbook.sheets.len);
        var filled: usize = 0;
        errdefer {
            for (order[0..filled]) |n| a.free(n);
            a.free(order);
        }
        for (self.workbook.sheets) |s| {
            order[filled] = try store_mod.decodeXmlEntities(a, s.name);
            filled += 1;
        }
        return order;
    }

    fn freeSheetOrder(self: *Workbook, order: []const []const u8) void {
        for (order) |n| self.allocator.free(n);
        self.allocator.free(order);
    }

    pub fn rewriteAllValidationsAndConditionalFormats(
        self: *Workbook,
        edit: zlsx.formula_rewriter.RewriteEdit,
        target_sheet: ?[]const u8,
    ) Error!u32 {
        var count: u32 = 0;
        const a = self.allocator;
        const sheet_order = try self.sheetOrderSnapshot();
        defer self.freeSheetOrder(sheet_order);

        var sheet_idx: u32 = 0;
        while (sheet_idx < self.sheetCount()) : (sheet_idx += 1) {
            const ws = try self.sheet(sheet_idx);
            const view = try ws.ensureParsed();
            const ws_name = try store_mod.decodeXmlEntities(a, ws.name());
            defer a.free(ws_name);
            const part_name = ws.resolved_part_name.?;

            // Two phases. Phase A: rewrite each DV/CF formula body
            // against the typed view, building an indexed plan
            // (DV index, CF index) keyed by the *position in the
            // view* — NOT source-byte offsets, since typed view
            // slices borrow from the parser's sanitized buffer, not
            // from `source`. Phase B walks the source XML and re-
            // locates each `<formula1>` / `<formula2>` / `<formula>`
            // body in lockstep with the view, splicing where the plan
            // says so.
            var dv_f1_new: std.AutoHashMapUnmanaged(usize, []u8) = .{};
            var dv_f2_new: std.AutoHashMapUnmanaged(usize, []u8) = .{};
            var cf_f_new: std.AutoHashMapUnmanaged(usize, []u8) = .{};
            defer {
                var it1 = dv_f1_new.iterator();
                while (it1.next()) |e| a.free(e.value_ptr.*);
                dv_f1_new.deinit(a);
                var it2 = dv_f2_new.iterator();
                while (it2.next()) |e| a.free(e.value_ptr.*);
                dv_f2_new.deinit(a);
                var it3 = cf_f_new.iterator();
                while (it3.next()) |e| a.free(e.value_ptr.*);
                cf_f_new.deinit(a);
            }

            for (view.validations, 0..) |dv, i| {
                if (dv.formula1) |f| {
                    if (try maybeRewrite(a, f, ws_name, target_sheet, sheet_order, edit)) |new| {
                        errdefer a.free(new);
                        try dv_f1_new.put(a, i, new);
                    }
                }
                if (dv.formula2) |f| {
                    if (try maybeRewrite(a, f, ws_name, target_sheet, sheet_order, edit)) |new| {
                        errdefer a.free(new);
                        try dv_f2_new.put(a, i, new);
                    }
                }
            }
            for (view.conditional_formats, 0..) |cf, j| {
                if (cf.formula) |f| {
                    if (try maybeRewrite(a, f, ws_name, target_sheet, sheet_order, edit)) |new| {
                        errdefer a.free(new);
                        try cf_f_new.put(a, j, new);
                    }
                }
            }

            const total = dv_f1_new.count() + dv_f2_new.count() + cf_f_new.count();
            if (total == 0) continue;

            // Phase B: walk source XML, build patch list of source-
            // byte spans (start, end, replacement). Then linear-splice.
            const source = blk: {
                const p = try self.store.part(part_name) orelse return error.MissingSheetPart;
                break :blk p.bytes;
            };
            assert(source.len > 0);

            var patches: std.ArrayList(SourcePatch) = .empty;
            defer patches.deinit(a);
            try collectDvCfPatches(a, source, &patches, &dv_f1_new, &dv_f2_new, &cf_f_new);

            // Sanity: every queued rewrite should have located a
            // splice site in the source (typed view and source share
            // document order; a missing site means the source was
            // mutated under us, which is a `replacePart`-ordering bug).
            assert(patches.items.len == total);

            const new_xml = try spliceFormulas(a, source, patches.items);
            defer a.free(new_xml);

            try self.store.replacePart(part_name, new_xml);
            count += @intCast(total);

            // Invalidate the cached parsed view: its leaves borrowed
            // from the old part bytes which `replacePart` swapped.
            // Mirrors the invalidation pattern in `Workbook.save`.
            var stale = ws.parsed.?;
            stale.deinit(self.allocator);
            ws.parsed = null;
        }

        return count;
    }

    /// All-or-nothing gate for the `<xm:f>` sweep: walk every sheet's
    /// `<xm:f>` carriers with `sheet_edit.nextXmFormula` and refuse
    /// (`MalformedExtensionXml`) on the first one that cannot be
    /// rewritten wholly. Pure — reads part bytes, mutates nothing.
    ///
    /// Every structural edit calls this BEFORE its first mutation.
    /// The sweeps below persist part-by-part, so a refusal raised
    /// from inside `rewriteAllExtensionFormulas` would land after the
    /// cell-formula, defined-name, hyperlink and DV/CF sweeps had
    /// already replaced parts — exactly the half-maintained workbook
    /// #140's guard existed to prevent. Running the same scan up front
    /// means the sweep itself can only fail on `OutOfMemory`.
    pub fn preflightExtensionFormulas(self: *Workbook) Error!void {
        var sheet_idx: u32 = 0;
        while (sheet_idx < self.sheetCount()) : (sheet_idx += 1) {
            const ws = try self.sheet(sheet_idx);
            const part_name = try ws.resolvePartName();
            const part = (try self.store.part(part_name)) orelse return error.MissingSheetPart;
            var pos: usize = 0;
            while (try sheet_edit.nextXmFormula(part.bytes, pos)) |f| pos = f.next;
        }
    }

    /// Apply a structural-edit rewrite to every `<extLst>` `<xm:f>`
    /// formula across every sheet, persisting in place via
    /// `store.replacePart`. Returns the count of bodies whose rewrite
    /// produced different bytes.
    ///
    /// This is the S2 lift. `<xm:f>` is the formula leaf of the
    /// `x14:` extensions: a sparkline's data range (`Data!A1:A5`
    /// under `x14:sparkline`) and its group's date axis, an
    /// `x14:cfRule` expression or `x14:cfvo` threshold, an
    /// `x14:formula1` / `x14:formula2` validation body. `<xm:sqref>`
    /// beside it is a plain range and is shifted by the byte
    /// transform in `pkg/sheet_edit.zig`; `<xm:f>` is a formula, so
    /// it needs the rewriter and the sheet-name context that layer
    /// lacks — a sparkline on `Report` pointing at `Data!A1:A5` must
    /// shift when `Data` gains a row and stay put when `Report` does.
    /// Until this sweep existed, any `<xm:f>` refused the edit
    /// (`ExtensionEditUnsafe`, #140).
    ///
    /// Same contract as `rewriteAllValidationsAndConditionalFormats`:
    /// `on_sheet` is the host sheet, `target_sheet` scopes the edit,
    /// bodies decode on the way in and re-escape on the way out
    /// (`spliceFormulas`), no host (relative R1C1 is left alone), and
    /// a no-op rewrite leaves the source bytes — entity spellings
    /// included — untouched. No typed view exists for `<extLst>`, so
    /// the carrier walk is the byte scan itself; a carrier the scan
    /// cannot read is refused by `preflightExtensionFormulas` before
    /// any sweep runs, so an error here is `OutOfMemory` or a
    /// `replacePart`-ordering bug.
    pub fn rewriteAllExtensionFormulas(
        self: *Workbook,
        edit: zlsx.formula_rewriter.RewriteEdit,
        target_sheet: ?[]const u8,
    ) Error!u32 {
        var count: u32 = 0;
        const a = self.allocator;
        const sheet_order = try self.sheetOrderSnapshot();
        defer self.freeSheetOrder(sheet_order);

        var sheet_idx: u32 = 0;
        while (sheet_idx < self.sheetCount()) : (sheet_idx += 1) {
            const ws = try self.sheet(sheet_idx);
            const part_name = try ws.resolvePartName();
            const source = blk: {
                const p = (try self.store.part(part_name)) orelse return error.MissingSheetPart;
                break :blk p.bytes;
            };
            // Cheap exit for the common sheet: no extension formula,
            // nothing to decode.
            if (std.mem.indexOf(u8, source, "<xm:f") == null) continue;
            const ws_name = try store_mod.decodeXmlEntities(a, ws.name());
            defer a.free(ws_name);

            var patches: std.ArrayList(SourcePatch) = .empty;
            defer {
                for (patches.items) |p| a.free(@constCast(p.new));
                patches.deinit(a);
            }

            var pos: usize = 0;
            while (try sheet_edit.nextXmFormula(source, pos)) |f| : (pos = f.next) {
                const body = source[f.body_start..f.body_end];
                if (try maybeRewrite(a, body, ws_name, target_sheet, sheet_order, edit)) |new| {
                    errdefer a.free(new);
                    try patches.append(a, .{ .start = f.body_start, .end = f.body_end, .new = new });
                }
            }
            if (patches.items.len == 0) continue;

            const new_xml = try spliceFormulas(a, source, patches.items);
            defer a.free(new_xml);
            try self.store.replacePart(part_name, new_xml);
            count += @intCast(patches.items.len);

            // The cached parsed view (if any) borrowed from the old
            // part bytes `replacePart` just swapped. Same invalidation
            // as `applySheetEditTransform`.
            if (ws.parsed) |*v| {
                var view = v.*;
                view.deinit(a);
                ws.parsed = null;
            }
        }

        return count;
    }

    /// Apply a structural-edit rewrite to every formula in every
    /// sheet. Walks each worksheet, materializes its SheetXml, runs
    /// `zlsx.formula_rewriter.rewriteFormula` on each cell that has
    /// `formula != null`, then patches the changed `<f>` BODIES in
    /// source-byte space (the DV/CF path's technique): row, cell and
    /// `<f>` attributes plus cached `<v>` values survive
    /// byte-identically. Staging through `setCell` instead would
    /// re-emit whole rows from the typed model and drop everything
    /// the model doesn't carry (Codex #188 r5). Returns the number
    /// of cells rewritten (cells whose rewrite produced
    /// byte-identical output are NOT counted).
    ///
    /// **This rewrites formulas only.** Row/col edits applied here
    /// shift formula references but do NOT structurally move cells —
    /// `Workbook.insertRow` etc. pair this call with the byte-level
    /// sheet transform.
    ///
    /// `target_sheet` plumbs into `RewriteContext.target_sheet`:
    /// the sheet whose grid the row/col edit moved. Bare refs shift
    /// only in formulas ON that sheet; qualified refs shift only
    /// when the qualifier matches it. `null` means "apply
    /// everywhere" per the rewriter's permissive default — the
    /// right value for `rename_sheet`/`delete_sheet` edits, which
    /// match on the edit's own sheet name and ignore bare refs.
    /// `rename_table_column` scoping for BARE structured refs
    /// (`[Old]`, `[@Old]`): they bind to the table whose range
    /// contains the formula's cell, so the walk needs the table's
    /// geometry. The six structural edits pass null.
    ///
    /// The whole rectangle is in scope DELIBERATELY. Excel binds a
    /// bare specifier in any formula inside the table's range —
    /// that is how in-table formulas are written — while the
    /// engine's `vtStructured` binds only producer-owned formulas,
    /// a strict subset. Rewriting a bare ref the engine leaves
    /// unbound changes nothing for the engine (unbound before and
    /// after) and is REQUIRED for Excel, which would otherwise
    /// reopen the workbook with a stale column name.
    pub const TableScope = struct {
        /// Sheet hosting the table (workbook order index).
        sheet_idx: u32,
        /// Declared range, 1-based inclusive.
        tl_row: u32,
        tl_col: u32,
        br_row: u32,
        br_col: u32,
        /// Decoded `displayName` — what `RewriteContext.owning_table`
        /// carries for cells inside the range.
        table: []const u8,
    };

    pub fn rewriteAllFormulas(
        self: *Workbook,
        edit: zlsx.formula_rewriter.RewriteEdit,
        target_sheet: ?[]const u8,
        table_scope: ?TableScope,
    ) Error!u32 {
        var count: u32 = 0;
        const a = self.allocator;
        const sheet_order = try self.sheetOrderSnapshot();
        defer self.freeSheetOrder(sheet_order);
        var sheet_idx: u32 = 0;
        while (sheet_idx < self.sheetCount()) : (sheet_idx += 1) {
            const ws = try self.sheet(sheet_idx);
            const view = try ws.ensureParsed();
            // Decoded boundary: qualifiers inside decoded formulas
            // must scope against a decoded owner name.
            const ws_name = try store_mod.decodeXmlEntities(a, ws.name());
            defer a.free(ws_name);

            // Collect (ref, expected_body, new_text) first; the
            // source-byte walk below needs the parsed view's slices
            // intact. `expected` is the body the rewrite was derived
            // from — the walker refuses to splice a located body
            // that no longer holds those bytes (stale cached view,
            // markup embedded in the body), rather than overwriting
            // whatever sits there now (Codex #188 r8).
            const Pending = struct { ref: []const u8, expected: []const u8, text: []u8 };
            var pending: std.ArrayList(Pending) = .empty;
            defer {
                for (pending.items) |p| a.free(p.text);
                pending.deinit(a);
            }

            for (view.rows) |row| {
                for (row.cells) |c| {
                    const f = c.formula orelse continue;
                    if (f.len == 0) continue;
                    const ctx = zlsx.formula_rewriter.RewriteContext{
                        .on_sheet = ws_name,
                        .target_sheet = target_sheet,
                        .sheet_order = sheet_order,
                        .owning_table = owningTableFor(table_scope, sheet_idx, c.ref),
                        // Relative R1C1 parts respell against the
                        // formula's own cell. For a shared-formula
                        // master this is the master's cell — the only
                        // cell whose `<f>` BODY exists in the source;
                        // follower cells carry no body to patch.
                        .host = hostFromRef(c.ref),
                        .edit = edit,
                    };
                    // Decode-in: view formulas are raw XML bytes
                    // (`&amp;` spelling `&`); the rewriter and the
                    // edit names operate on decoded text, and
                    // `setCell`'s delta emit re-escapes on save.
                    // Rewriting the raw bytes double-escaped every
                    // entity-bearing formula a rewrite touched.
                    const decoded = try store_mod.decodeXmlEntities(a, f);
                    const rewritten = zlsx.formula_rewriter.rewriteFormula(a, decoded, ctx) catch |err| {
                        a.free(decoded);
                        return err;
                    };
                    const unchanged = std.mem.eql(u8, rewritten, decoded);
                    a.free(decoded);
                    if (unchanged) {
                        a.free(rewritten);
                        continue;
                    }
                    errdefer a.free(rewritten);
                    try pending.append(a, .{ .ref = c.ref, .expected = f, .text = rewritten });
                }
            }

            if (pending.items.len == 0) continue;

            // Phase B (mirrors the DV/CF path): patch only the
            // changed `<f>` bodies in the raw part bytes.
            var new_bodies: std.StringHashMapUnmanaged(CellBodySwap) = .empty;
            defer new_bodies.deinit(a);
            for (pending.items) |p| {
                try new_bodies.put(a, p.ref, .{ .expected = p.expected, .text = p.text });
            }

            const part_name = ws.resolved_part_name orelse return error.MissingSheetPart;
            const source = blk: {
                const p = try self.store.part(part_name) orelse return error.MissingSheetPart;
                break :blk p.bytes;
            };
            assert(source.len > 0);

            var patches: std.ArrayList(SourcePatch) = .empty;
            defer patches.deinit(a);
            try collectCellFormulaPatches(a, source, &patches, &new_bodies);
            // Typed view and source share cell refs; a missing splice
            // site means the source was mutated under us, which is a
            // `replacePart`-ordering bug.
            assert(patches.items.len == pending.items.len);

            const new_xml = try spliceFormulas(a, source, patches.items);
            defer a.free(new_xml);
            try self.store.replacePart(part_name, new_xml);
            count += @intCast(pending.items.len);

            // Invalidate the cached parsed view: its leaves borrowed
            // from the old part bytes which `replacePart` swapped.
            var stale = ws.parsed.?;
            stale.deinit(self.allocator);
            ws.parsed = null;
        }
        return count;
    }

    /// Apply `edit` to every `<definedName>` formula in `xl/workbook.xml`.
    /// `target_sheet` plumbs into `RewriteContext.target_sheet`: caller's
    /// statement of which sheet's row/col edit applies. `null` means
    /// "apply everywhere" per the rewriter's permissive default.
    ///
    /// Each defined name's `RewriteContext.on_sheet` is set to:
    ///   - workbook-scope (`local_sheet_id == null`): `null`
    ///   - sheet-scope (`local_sheet_id` set): the name of the sheet
    ///     the `localSheetId` index resolves to
    ///
    /// Returns the number of defined-name formulas whose rewritten
    /// output differs from the input (byte-identical rewrites are not
    /// counted).
    ///
    /// **Splice contract.** Changed formula BODIES are patched in
    /// source-byte space (`collectDefinedNamePatches`); the start
    /// tags — including attributes the typed model doesn't carry
    /// (`workbookParameter`, `function`, `vbProcedure`, comments) —
    /// and every untouched entry survive byte-identically. The
    /// whole-block regeneration lives on only in the fresh-emit plan
    /// path (`applyWorkbookXmlPlanDefinedNames`), which must rebuild
    /// the block to add entries.
    ///
    /// **Bug-fix vs prior iter (PR #37).** The earlier draft re-parsed
    /// `self.workbook` mid-iteration over `defined_names`, leaving the
    /// loop reading freed memory on the sheet-scope branch. This impl
    /// collects ALL rewrites FIRST, then performs the splice +
    /// `replacePart` + re-parse in a single transactional step.
    pub fn rewriteAllDefinedNames(
        self: *Workbook,
        edit: zlsx.formula_rewriter.RewriteEdit,
        target_sheet: ?[]const u8,
    ) Error!u32 {
        const a = self.allocator;

        if (self.workbook.defined_names.len == 0) return 0;

        // Order snapshot borrows nothing from the workbook arena
        // (entries are decoded copies), but every rewrite below still
        // finishes before `refreshWorkbookXmlView` swaps the arena
        // the VIEW slices borrow from.
        const sheet_order = try self.sheetOrderSnapshot();
        defer self.freeSheetOrder(sheet_order);

        // Changed decoded bodies, keyed by the entry's position in
        // the parsed view — the index `collectDefinedNamePatches`
        // reproduces over the raw source.
        var new_bodies: std.AutoHashMapUnmanaged(usize, []u8) = .{};
        defer {
            var it = new_bodies.iterator();
            while (it.next()) |e| a.free(e.value_ptr.*);
            new_bodies.deinit(a);
        }

        for (self.workbook.defined_names, 0..) |dn, dn_idx| {
            // Resolve `on_sheet`: null for workbook-scope, sheet name
            // for sheet-scope (via local_sheet_id index lookup). The
            // decoded order snapshot doubles as the decoded-name
            // source — same indices, same lifetime.
            const on_sheet: ?[]const u8 = blk: {
                if (dn.local_sheet_id) |sid| {
                    if (sid < sheet_order.len) {
                        break :blk sheet_order[sid];
                    }
                    // Out-of-range localSheetId in source XML — treat
                    // as workbook-scope rather than crashing. Tolerant
                    // of malformed input, not a happy path.
                    break :blk null;
                }
                break :blk null;
            };
            const ctx = zlsx.formula_rewriter.RewriteContext{
                .on_sheet = on_sheet,
                .target_sheet = target_sheet,
                .sheet_order = sheet_order,
                .edit = edit,
            };

            // A raw `<` cannot appear in a well-formed formula body
            // (content escapes it as `&lt;`) — its presence means
            // embedded markup: a comment or CDATA block, which also
            // defeats the parser's raw close-tag search, so the
            // recorded span may stop at a decoy `</definedName>`
            // inside a comment. Splicing such a span would expose
            // the decoy as live markup. Conservative: never rewrite
            // a markup-bearing body (Codex #188 r8).
            if (std.mem.indexOfScalar(u8, dn.formula, '<') != null) continue;

            // Decode-in: `dn.formula` is raw XML inner text (still
            // entity-escaped); the rewriter operates on decoded text
            // and `spliceFormulas` re-escapes the patched bodies on
            // emit.
            const decoded = try store_mod.decodeXmlEntities(a, dn.formula);
            const rewritten = zlsx.formula_rewriter.rewriteFormula(a, decoded, ctx) catch |err| {
                a.free(decoded);
                return err;
            };
            const unchanged = std.mem.eql(u8, rewritten, decoded);
            a.free(decoded);
            if (unchanged) {
                a.free(rewritten);
                continue;
            }
            errdefer a.free(rewritten);
            try new_bodies.put(a, dn_idx, rewritten);
        }

        const changed: u32 = @intCast(new_bodies.count());
        if (changed == 0) return 0;

        const part = try self.store.part("xl/workbook.xml") orelse return error.MissingWorkbookPart;
        const source = part.bytes;
        assert(source.len > 0);

        var patches: std.ArrayList(SourcePatch) = .empty;
        defer patches.deinit(a);
        var body_it = new_bodies.iterator();
        while (body_it.next()) |e| {
            // Patch sites come from the PARSER itself — `body_start`/
            // `body_end` are the raw offsets it recorded while
            // building this very view — so the view and the patches
            // cannot disagree on indexing. A second scanner
            // reproducing the parser's walk diverged on legal XML it
            // tolerates: whitespace around `=`, commented-out
            // elements, `>` inside quoted attribute values
            // (Codex #188 r6).
            const dn = self.workbook.defined_names[e.key_ptr.*];
            // The spans were recorded when THIS view was parsed. If
            // the part bytes changed since — a refresh that failed
            // after a prior splice, or a low-level `replacePart` —
            // positional patching would splice into unrelated bytes.
            // Content equality at the recorded offset is precisely
            // "the view still describes these bytes"; refuse loudly
            // otherwise (Codex #188 r7).
            if (dn.body_start > dn.body_end or dn.body_end > source.len or
                !std.mem.eql(u8, source[dn.body_start..dn.body_end], dn.formula))
            {
                return error.MalformedXml;
            }
            try patches.append(a, .{ .start = dn.body_start, .end = dn.body_end, .new = e.value_ptr.* });
        }
        assert(patches.items.len == changed);

        const new_xml = try spliceFormulas(a, source, patches.items);
        defer a.free(new_xml);
        try self.store.replacePart("xl/workbook.xml", new_xml);

        // Re-parse so subsequent reads of `self.workbook.defined_names`
        // see the new bytes. Source slice borrows from the OLD bytes
        // we just replaced; `refresh` swaps both arena and slice.
        try refreshWorkbookXmlView(self);

        return changed;
    }

    /// Apply `edit` to every internal `<hyperlink location="…">` on
    /// every sheet. External hyperlinks (those with `r:id != null`)
    /// are skipped — their target is a relationship, not an A1 ref.
    ///
    /// `target_sheet` plumbs into `RewriteContext.target_sheet`.
    /// `RewriteContext.on_sheet` is the name of the sheet the
    /// hyperlink lives on (so unqualified locations are scoped
    /// correctly during shift).
    ///
    /// Returns the number of hyperlink locations whose rewrite
    /// produced different bytes.
    pub fn rewriteAllHyperlinkLocations(
        self: *Workbook,
        edit: zlsx.formula_rewriter.RewriteEdit,
        target_sheet: ?[]const u8,
    ) Error!u32 {
        const a = self.allocator;
        var total_changed: u32 = 0;
        const sheet_order = try self.sheetOrderSnapshot();
        defer self.freeSheetOrder(sheet_order);

        var sheet_idx: u32 = 0;
        while (sheet_idx < self.sheetCount()) : (sheet_idx += 1) {
            const ws = try self.sheet(sheet_idx);
            const view = try ws.ensureParsed();
            if (view.hyperlinks.len == 0) continue;

            const ws_name = try store_mod.decodeXmlEntities(a, ws.name());
            defer a.free(ws_name);

            // Per-sheet pending list: every hyperlink (preserved
            // verbatim) plus the rewritten location, owned. Empty
            // means nothing to emit — leave the sheet untouched.
            const Pending = struct {
                ref: []u8,
                location: []u8,
                display: ?[]u8,
                tooltip: ?[]u8,
                r_id: ?[]u8,
            };
            var pending: std.ArrayList(Pending) = .empty;
            defer {
                for (pending.items) |p| {
                    a.free(p.ref);
                    a.free(p.location);
                    if (p.display) |s| a.free(s);
                    if (p.tooltip) |s| a.free(s);
                    if (p.r_id) |s| a.free(s);
                }
                pending.deinit(a);
            }

            var sheet_changed: u32 = 0;
            for (view.hyperlinks) |h| {
                // External hyperlinks: r_id present → location is a
                // relationship target, not an A1 ref. Preserve verbatim.
                // Internal-only entries (r_id == null AND location set)
                // are the rewrite candidates.
                const loc_in = h.location orelse {
                    // Hyperlink with neither r_id nor location is
                    // malformed; preserve verbatim so it's not dropped.
                    try appendPendingHyperlink(a, &pending, h, null);
                    continue;
                };
                if (h.r_id != null) {
                    try appendPendingHyperlink(a, &pending, h, null);
                    continue;
                }

                const ctx = zlsx.formula_rewriter.RewriteContext{
                    .on_sheet = ws_name,
                    .target_sheet = target_sheet,
                    .sheet_order = sheet_order,
                    .edit = edit,
                };
                // Decode-in: `location` is a raw attribute value and
                // the block emit re-escapes every attribute.
                const decoded_loc = try store_mod.decodeXmlEntities(a, loc_in);
                const rewritten = zlsx.formula_rewriter.rewriteFormula(a, decoded_loc, ctx) catch |err| {
                    a.free(decoded_loc);
                    return err;
                };
                if (!std.mem.eql(u8, rewritten, decoded_loc)) sheet_changed += 1;
                a.free(decoded_loc);
                errdefer a.free(rewritten);
                try appendPendingHyperlink(a, &pending, h, rewritten);
            }

            // Pair assertion: every parsed hyperlink produced exactly
            // one pending entry.
            assert(pending.items.len == view.hyperlinks.len);

            if (sheet_changed == 0) continue;

            try self.spliceHyperlinksBlock(sheet_idx, pending.items);

            // Invalidate the parsed view: the source bytes for
            // `hyperlinks[].location` borrow from the OLD part bytes
            // that `replacePart` just swapped out.
            if (ws.parsed) |*p| {
                var view_mut = p.*;
                view_mut.deinit(self.allocator);
                ws.parsed = null;
            }

            total_changed += sheet_changed;
        }

        return total_changed;
    }

    /// Helper for `rewriteAllHyperlinkLocations`. Duplicates `h`'s
    /// borrowed slices into pending-list-owned allocations, optionally
    /// substituting `loc_override` for `h.location` (used when the
    /// rewriter produced new bytes). Pending-list type is local to
    /// the caller; mirror its struct shape via anytype to avoid
    /// hoisting a private struct to file scope just for this helper.
    fn appendPendingHyperlink(
        allocator: Allocator,
        pending: anytype,
        h: sheet_xml_mod.Hyperlink,
        loc_override: ?[]u8,
    ) Error!void {
        // Passthrough fields decode on the way in: the parsed view
        // holds raw attribute bytes, and the block emit re-escapes
        // every attribute — duplicating the raw form would
        // double-escape untouched hyperlinks whenever any sibling's
        // location was rewritten.
        const ref_dup = try store_mod.decodeXmlEntities(allocator, h.ref);
        errdefer allocator.free(ref_dup);

        const loc_dup: []u8 = if (loc_override) |lo|
            lo // takes ownership — caller's `errdefer free(rewritten)` is cancelled by successful append
        else
            try store_mod.decodeXmlEntities(allocator, h.location orelse "");
        errdefer if (loc_override == null) allocator.free(loc_dup);

        const display_dup: ?[]u8 = if (h.display) |s| try store_mod.decodeXmlEntities(allocator, s) else null;
        errdefer if (display_dup) |s| allocator.free(s);

        const tooltip_dup: ?[]u8 = if (h.tooltip) |s| try store_mod.decodeXmlEntities(allocator, s) else null;
        errdefer if (tooltip_dup) |s| allocator.free(s);

        const r_id_dup: ?[]u8 = if (h.r_id) |s| try store_mod.decodeXmlEntities(allocator, s) else null;
        errdefer if (r_id_dup) |s| allocator.free(s);

        try pending.append(allocator, .{
            .ref = ref_dup,
            .location = loc_dup,
            .display = display_dup,
            .tooltip = tooltip_dup,
            .r_id = r_id_dup,
        });
    }

    /// B3 iter-wr-3: splice the workbook.xml fresh-emit plan's
    /// staged defined names into `xl/workbook.xml`. Validates every
    /// staged `local_sheet_id` against the current sheet count;
    /// builds the parallel-arrays shape `spliceDefinedNamesBlock`
    /// expects; clears the plan after a successful splice (saves
    /// are idempotent — re-running shouldn't re-add the same
    /// names).
    ///
    /// Mutually exclusive with `rewriteAllDefinedNames` in any single
    /// save: rewrite is "rewrite EVERY name's formula via edit"
    /// while this is "splice the plan's NEW names". The plan is
    /// drained on success, so subsequent rewrites observe the new
    /// names from the re-parsed view.
    fn applyWorkbookXmlPlanDefinedNames(self: *Workbook) Error!void {
        const a = self.allocator;
        const plan = &self.workbook_xml_plan;
        assert(plan.defined_names.items.len > 0);

        // Bounds-check every sheet-scoped name BEFORE building any
        // parallel arrays — atomicity: an out-of-range local_sheet_id
        // bails before we allocate anything.
        for (plan.defined_names.items) |dn| {
            if (dn.local_sheet_id) |sid| {
                if (sid >= self.workbook.sheets.len) {
                    return error.InvalidDefinedNameLocalSheetId;
                }
            }
        }

        // Merge any pre-existing defined names (parsed from the source
        // workbook.xml) with the plan's staged additions. The splice
        // helper rewrites the entire block, so dropping the existing
        // entries would silently delete user-loaded names.
        const existing = self.workbook.defined_names;
        const total = existing.len + plan.defined_names.items.len;

        var owned_names: std.ArrayList([]u8) = .empty;
        defer {
            for (owned_names.items) |s| a.free(s);
            owned_names.deinit(a);
        }
        var owned_formulas: std.ArrayList([]u8) = .empty;
        defer {
            for (owned_formulas.items) |s| a.free(s);
            owned_formulas.deinit(a);
        }
        var local_ids: std.ArrayList(?u32) = .empty;
        defer local_ids.deinit(a);
        var hiddens: std.ArrayList(bool) = .empty;
        defer hiddens.deinit(a);

        try owned_names.ensureTotalCapacity(a, total);
        try owned_formulas.ensureTotalCapacity(a, total);
        try local_ids.ensureTotalCapacity(a, total);
        try hiddens.ensureTotalCapacity(a, total);

        for (existing) |dn| {
            // Existing entries are raw XML bytes and the splice
            // escapes on emit — duplicating the raw form would
            // double-escape entity-bearing names/formulas every time
            // the plan re-emits the block (Codex #188 r3).
            try owned_names.append(a, try store_mod.decodeXmlEntities(a, dn.name));
            try owned_formulas.append(a, try store_mod.decodeXmlEntities(a, dn.formula));
            try local_ids.append(a, dn.local_sheet_id);
            try hiddens.append(a, dn.hidden);
        }
        for (plan.defined_names.items) |dn| {
            try owned_names.append(a, try a.dupe(u8, dn.name));
            try owned_formulas.append(a, try a.dupe(u8, dn.refers_to));
            try local_ids.append(a, dn.local_sheet_id);
            try hiddens.append(a, dn.hidden);
        }

        try self.spliceDefinedNamesBlock(
            owned_names.items,
            owned_formulas.items,
            local_ids.items,
            hiddens.items,
        );

        // Re-parse so subsequent reads of `self.workbook.defined_names`
        // observe the freshly-spliced block. Mirrors the pattern in
        // `rewriteAllDefinedNames`.
        const part = (try self.store.part("xl/workbook.xml")) orelse return error.MissingWorkbookPart;
        var fresh = try workbook_xml_mod.parse(a, part.bytes);
        errdefer fresh.deinit(a);
        self.workbook.deinit(a);
        self.workbook = fresh;

        // Drain the plan so a subsequent save (or the C ABI's
        // save-and-mutate-and-resave loop) doesn't redundantly
        // re-splice the same names.
        plan.deinit(a);
        plan.* = .{};
    }

    /// Re-emit `xl/workbook.xml` with a fresh `<definedNames>` block
    /// built from the parallel arrays (names / formulas / local_ids /
    /// hiddens — same length, same index ↔ same defined name).
    fn spliceDefinedNamesBlock(
        self: *Workbook,
        names: []const []u8,
        formulas: []const []u8,
        local_ids: []const ?u32,
        hiddens: []const bool,
    ) Error!void {
        assert(names.len == formulas.len);
        assert(names.len == local_ids.len);
        assert(names.len == hiddens.len);

        const a = self.allocator;
        const part = try self.store.part("xl/workbook.xml") orelse return error.MissingWorkbookPart;
        const src = part.bytes;
        assert(src.len > 0);

        // Build the new `<definedNames>...</definedNames>` block once
        // — emitted whether the source had a paired block, a self-
        // closing tag, or no block at all. Empty `names` would emit a
        // bare `<definedNames></definedNames>` pair; callers gate on
        // `changed == 0` and skip this path entirely if no rewrite
        // happened, so empty is never emitted.
        var block: std.ArrayList(u8) = .empty;
        defer block.deinit(a);
        try block.appendSlice(a, "<definedNames>");
        for (names, formulas, local_ids, hiddens) |n, f, lid, hid| {
            try block.appendSlice(a, "<definedName name=\"");
            try appendXmlEscaped(a, &block, n);
            try block.appendSlice(a, "\"");
            if (lid) |sid| {
                var buf: [16]u8 = undefined;
                const s = try std.fmt.bufPrint(&buf, "{d}", .{sid});
                try block.appendSlice(a, " localSheetId=\"");
                try block.appendSlice(a, s);
                try block.appendSlice(a, "\"");
            }
            if (hid) try block.appendSlice(a, " hidden=\"1\"");
            try block.appendSlice(a, ">");
            try appendXmlEscapedText(a, &block, f);
            try block.appendSlice(a, "</definedName>");
        }
        try block.appendSlice(a, "</definedNames>");

        // Locate the source `<definedNames` open tag (if any). Decision
        // tree:
        //   present + paired      → splice over the whole block
        //   present + self-close  → splice over the self-close tag
        //   absent                → insert before <calcPr or </workbook>
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(a);
        try out.ensureTotalCapacity(a, src.len + block.items.len + 64);

        if (std.mem.indexOf(u8, src, "<definedNames")) |dn_open| {
            // Boundary check: ensure the tag is real, not a substring
            // of `<definedNamesEx>` or similar (no such Excel tag, but
            // defensive: require the next byte to be space/tab/newline,
            // `>`, or `/`).
            const after_name = dn_open + "<definedNames".len;
            if (after_name >= src.len) return error.MalformedXml;
            const boundary = src[after_name];
            const is_real = switch (boundary) {
                ' ', '\t', '\r', '\n', '>', '/' => true,
                else => false,
            };
            if (!is_real) return error.MalformedXml;

            const open_gt = std.mem.indexOfScalarPos(u8, src, after_name, '>') orelse
                return error.MalformedXml;
            const is_self_closing = open_gt > 0 and src[open_gt - 1] == '/';

            if (is_self_closing) {
                // Replace `<definedNames/>` with the new paired block.
                try out.appendSlice(a, src[0..dn_open]);
                try out.appendSlice(a, block.items);
                try out.appendSlice(a, src[open_gt + 1 ..]);
            } else {
                // Find `</definedNames>` and replace the whole span.
                const close = std.mem.indexOfPos(u8, src, open_gt + 1, "</definedNames>") orelse
                    return error.MalformedXml;
                const close_end = close + "</definedNames>".len;
                try out.appendSlice(a, src[0..dn_open]);
                try out.appendSlice(a, block.items);
                try out.appendSlice(a, src[close_end..]);
            }
        } else {
            // No `<definedNames>` block: insert before `<calcPr`, or
            // before `</workbook>` if calcPr is absent. This places the
            // block at OOXML's expected position in the schema sequence.
            const insert_at: usize = blk: {
                if (std.mem.indexOf(u8, src, "<calcPr")) |i| break :blk i;
                if (std.mem.indexOf(u8, src, "</workbook>")) |i| break :blk i;
                return error.MalformedXml;
            };
            try out.appendSlice(a, src[0..insert_at]);
            try out.appendSlice(a, block.items);
            try out.appendSlice(a, src[insert_at..]);
        }

        try self.store.replacePart("xl/workbook.xml", out.items);
    }

    /// Re-emit the sheet at `sheet_idx`'s XML with a fresh
    /// `<hyperlinks>` block. `pending` contents own their byte slices.
    fn spliceHyperlinksBlock(
        self: *Workbook,
        sheet_idx: u32,
        pending: anytype,
    ) Error!void {
        const a = self.allocator;
        const ws = try self.sheet(sheet_idx);
        // ensureParsed has been called by the time we get here, so
        // resolved_part_name is non-null.
        const part_name = ws.resolved_part_name orelse return error.MissingSheetPart;
        const part = try self.store.part(part_name) orelse return error.MissingSheetPart;
        const src = part.bytes;
        assert(src.len > 0);

        // Build the new block. ALL hyperlinks (including the r_id-
        // bearing ones passed through) are emitted so the splice
        // replaces the entire `<hyperlinks>` block as a unit.
        var block: std.ArrayList(u8) = .empty;
        defer block.deinit(a);
        try block.appendSlice(a, "<hyperlinks>");
        for (pending) |p| {
            try block.appendSlice(a, "<hyperlink ref=\"");
            try appendXmlEscaped(a, &block, p.ref);
            try block.appendSlice(a, "\"");
            if (p.r_id) |rid| {
                try block.appendSlice(a, " r:id=\"");
                try appendXmlEscaped(a, &block, rid);
                try block.appendSlice(a, "\"");
            }
            // Emit `location` only when non-empty AND `r_id` is null;
            // otherwise the relationship target supersedes.
            if (p.r_id == null and p.location.len > 0) {
                try block.appendSlice(a, " location=\"");
                try appendXmlEscaped(a, &block, p.location);
                try block.appendSlice(a, "\"");
            }
            if (p.display) |d| {
                try block.appendSlice(a, " display=\"");
                try appendXmlEscaped(a, &block, d);
                try block.appendSlice(a, "\"");
            }
            if (p.tooltip) |t| {
                try block.appendSlice(a, " tooltip=\"");
                try appendXmlEscaped(a, &block, t);
                try block.appendSlice(a, "\"");
            }
            try block.appendSlice(a, "/>");
        }
        try block.appendSlice(a, "</hyperlinks>");

        // Same three-shape splice as definedNames.
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(a);
        try out.ensureTotalCapacity(a, src.len + block.items.len + 64);

        if (std.mem.indexOf(u8, src, "<hyperlinks")) |hl_open| {
            const after_name = hl_open + "<hyperlinks".len;
            if (after_name >= src.len) return error.MalformedXml;
            const boundary = src[after_name];
            const is_real = switch (boundary) {
                ' ', '\t', '\r', '\n', '>', '/' => true,
                else => false,
            };
            if (!is_real) return error.MalformedXml;

            const open_gt = std.mem.indexOfScalarPos(u8, src, after_name, '>') orelse
                return error.MalformedXml;
            const is_self_closing = open_gt > 0 and src[open_gt - 1] == '/';

            if (is_self_closing) {
                try out.appendSlice(a, src[0..hl_open]);
                try out.appendSlice(a, block.items);
                try out.appendSlice(a, src[open_gt + 1 ..]);
            } else {
                const close = std.mem.indexOfPos(u8, src, open_gt + 1, "</hyperlinks>") orelse
                    return error.MalformedXml;
                const close_end = close + "</hyperlinks>".len;
                try out.appendSlice(a, src[0..hl_open]);
                try out.appendSlice(a, block.items);
                try out.appendSlice(a, src[close_end..]);
            }
        } else {
            // No `<hyperlinks>` in source — unreachable when
            // `pending.len > 0` because pending was built from the
            // parsed view, and the parser only populates hyperlinks
            // when the block exists. Return a clean error rather than
            // silently inserting at a guessed position.
            return error.MalformedXml;
        }

        try self.store.replacePart(part_name, out.items);
    }

    /// Rename sheet at `sheet_idx` to `new_name`. Composes three steps
    /// atomically (in error semantics — partial work is left only on
    /// post-rewrite failures, see below):
    ///
    /// 1. Validate `new_name` per Excel rules (length, forbidden chars,
    ///    "history" reserved, no duplicate of any other sheet name).
    /// 2. Rewrite every formula in every sheet via
    ///    `rewriteAllFormulas(.{ .rename_sheet = ... }, null)`. Cross-sheet
    ///    references targeting `old_name` get retargeted to `new_name`.
    /// 3. Patch `xl/workbook.xml` so the `<sheet name="OLD" .../>`
    ///    element for `sheet_idx` carries the new (XML-escaped) name.
    /// 4. Re-parse the in-memory `WorkbookXml` view from the freshly-
    ///    patched bytes so subsequent `wb.sheet(i).name()` returns the
    ///    new value without a `deinit + open` round-trip.
    ///
    /// **Lifecycle.** Step 2 stages formula deltas; they're persisted
    /// only by `Workbook.save`. The rewritten formulas live in each
    /// Worksheet's `deltas` map, NOT in its cached `parsed` view, so
    /// no `parsed = null` invalidation is required here. Caller still
    /// must call `save` to commit to disk.
    ///
    /// **Length cap.** B3 iter-wr-6 lifted the validator to the
    /// canonical Writer-side `xlsx.validateSheetName` (Unicode-scalar
    /// aware): names cap at 31 SCALARS — Excel's actual rule —
    /// regardless of UTF-8 byte length, additionally rejecting
    /// 0x00..0x1F control bytes and leading/trailing apostrophes.
    /// Pre-iter-wr-6 the cap was a conservative 127-byte fence.
    ///
    /// **Case folding.** Duplicate-name detection still uses ASCII
    /// case-fold (a..z ↔ A..Z); the Writer-side `addSheet` collision
    /// loop uses the Unicode case-fold via
    /// `unicode/casefold.zig`. Workbook's collision check is
    /// per-sheet rather than per-write, so the ASCII compromise is
    /// retained here pending a follow-up iter.
    ///
    /// **Defined names.** Sheet-qualified `<definedName>` formulas
    /// (`Sheet2!$A$1` etc.) are NOT rewritten by this iter — only
    /// per-cell formulas via `rewriteAllFormulas`. Hyperlink targets
    /// pointing at the renamed sheet are likewise unaltered. A future
    /// iter (`m3-defnames-hyperlinks`) covers both.
    pub fn renameSheet(self: *Workbook, sheet_idx: u32, new_name: []const u8) Error!void {
        if (sheet_idx >= self.sheetCount()) return error.SheetIndexOutOfRange;
        try validateSheetName(new_name);
        try self.assertSheetNameAvailable(sheet_idx, new_name);

        // Capture old name into a stack copy: step 4 re-parses the
        // workbook view, freeing the arena that backs `sheets[i].name`.
        // We need the old bytes alive across step 2 (rewriter) and step
        // 3 (XML patch — the patch reads from the source bytes still
        // holding the old name).
        const old_name = self.workbook.sheets[sheet_idx].name;
        if (old_name.len == 0) return error.InternalSheetNameTooLong; // OOXML invariant
        if (old_name.len > 128) return error.InternalSheetNameTooLong;
        var old_buf: [128]u8 = undefined;
        @memcpy(old_buf[0..old_name.len], old_name);
        const old_name_owned = old_buf[0..old_name.len];

        // The view name is raw attribute bytes (`R&amp;D`); the
        // rewriter's decode-in contract wants the decoded form. The
        // raw copy stays alive for the workbook.xml patch below,
        // which edits the source bytes in their own encoding.
        const old_name_decoded = try store_mod.decodeXmlEntities(self.allocator, old_name_owned);
        defer self.allocator.free(old_name_decoded);

        // No-op rename: identical decoded names. Skip rewriter
        // (would error .InvalidEdit on `old == new` is fine, but the
        // cleaner contract is "asking to rename to the current name
        // is a successful no-op").
        if (std.mem.eql(u8, old_name_decoded, new_name)) return;

        const edit: zlsx.formula_rewriter.RewriteEdit = .{
            .rename_sheet = .{ .old = old_name_decoded, .new = new_name },
        };

        // B2 iter-er-5 lift (rename_sheet axis): walk every cross-
        // sheet reference carrier and rewrite the renamed sheet's
        // qualifiers in place. Until iter-er-5, only formula cells
        // were rewritten; defined-name formulas, internal hyperlink
        // locations, and DV/CF formulas all survived as `#REF!`
        // until the next manual save in Excel. Each rewriter is
        // tolerant of "no carriers in the workbook" — they short-
        // circuit on empty workbooks rather than erroring, so
        // calling all five unconditionally is cheap. The `<xm:f>`
        // gate runs first: it is the one sweep with a refusal, and
        // the refusal must land before the first `replacePart`.
        try self.preflightExtensionFormulas();
        _ = try self.rewriteAllFormulas(edit, null, null);
        _ = try self.rewriteAllDefinedNames(edit, null);
        _ = try self.rewriteAllHyperlinkLocations(edit, null);
        _ = try self.rewriteAllValidationsAndConditionalFormats(edit, null);
        _ = try self.rewriteAllExtensionFormulas(edit, null);

        try patchWorkbookXmlSheetName(self, sheet_idx, old_name_owned, new_name);
        try refreshWorkbookXmlView(self);

        // Postcondition: the in-memory view now reports the new name.
        assert(sheet_idx < self.workbook.sheets.len);
        assert(std.mem.eql(u8, self.workbook.sheets[sheet_idx].name, new_name));
    }

    /// Rename a column of the table whose `displayName` matches
    /// `table_name` (the symbol layer's fold rule, like all name
    /// resolution). Composes, in order:
    ///
    /// 1. Locate the table part through each sheet's
    ///    `<tableParts>` rels (first fold-match wins; `displayName`
    ///    is workbook-unique per ECMA-376 §18.5.1.2).
    /// 2. `table_edit.renameTableColumn`: validates the old column
    ///    exists and the new name is free (both fold-rule), then
    ///    rewrites `<tableColumn name>` and every
    ///    `calculatedColumnFormula` / `totalsRowFormula` body in
    ///    the part. All refusals precede any mutation.
    /// 3. Rewrite structured references workbook-wide: cell
    ///    formulas (bare `[Old]` / `[@Old]` specifiers scope to
    ///    cells inside the table's range via `TableScope`), defined
    ///    names, hyperlink locations, and DV/CF formulas.
    /// 4. Replace the table part and stage the header-cell text
    ///    (`setCell` shared-string delta) when the table has a
    ///    header row — Excel repairs a table whose header cell
    ///    disagrees with its column name.
    ///
    /// `table_name` / `old_name` / `new_name` are decoded plain
    /// text. Returns the number of cell formulas rewritten (the
    /// count `rewriteAllFormulas` reports).
    ///
    /// **Failure contract** (same as `renameSheet`'s): every
    /// REFUSAL — table or column not found, name collision or
    /// invalid, malformed part — happens before any mutation, and
    /// the refusals test pins that byte-exactly. Post-validation
    /// failures (OOM mid-sweep, a stale-splice refusal from a part
    /// mutated under us) can leave the workbook partially rewritten,
    /// exactly as a mid-sweep failure in `renameSheet` can; callers
    /// treat any error after open as "discard, reopen". Full
    /// prepare-then-commit transactionality across the four sweeps
    /// is a workbook-wide change deliberately out of this leg's
    /// scope.
    pub fn renameTableColumn(
        self: *Workbook,
        table_name: []const u8,
        old_name: []const u8,
        new_name: []const u8,
    ) Error!u32 {
        if (table_name.len == 0) return error.TableNotFound;

        // Step 1: locate the table part and its host sheet.
        const a = self.allocator;
        var host_sheet_idx: ?u32 = null;
        var table_part_name: []const u8 = "";
        var sheet_idx: u32 = 0;
        outer: while (sheet_idx < self.sheetCount()) : (sheet_idx += 1) {
            const ws = try self.sheet(sheet_idx);
            const sheet_part_name = try ws.resolvePartName();
            const sheet_part = (try self.store.part(sheet_part_name)) orelse continue;
            const rels = self.store.rels(sheet_part_name);
            var rid_iter = TablePartRidIterator.init(sheet_part.bytes);
            while (rid_iter.next()) |rid| {
                const target = relTargetForId(rels, rid) orelse continue;
                const part_name = (try self.store.resolve(sheet_part_name, target)) orelse continue;
                const part = (try self.store.part(part_name)) orelse continue;
                const display_raw = table_edit.tableDisplayNameRaw(part.bytes) orelse continue;
                // STRING-carrier decode (entities + ST_Xstring) —
                // resolution parity with the engine, which reads
                // `displayName="Sales_x0041_"` as SalesA. A part
                // whose attr the codec refuses simply doesn't match.
                const display = engine.decode.decodeAt(a, .table_name, display_raw) catch |err| {
                    if (err == error.OutOfMemory) return error.OutOfMemory;
                    continue;
                };
                defer a.free(display);
                const matches = zlsx.casefold.eqlFolded(a, display, table_name) catch |err| blk: {
                    if (err == error.OutOfMemory) return error.OutOfMemory;
                    break :blk false;
                };
                if (matches) {
                    host_sheet_idx = sheet_idx;
                    table_part_name = part_name;
                    break :outer;
                }
            }
        }
        const host_idx = host_sheet_idx orelse return error.TableNotFound;

        // Step 2: rewrite the table part (validations included —
        // nothing below runs unless the rename is fully legal).
        const table_part = (try self.store.part(table_part_name)) orelse return error.TableNotFound;
        var renamed = try table_edit.renameTableColumn(a, table_part.bytes, old_name, new_name);
        defer renamed.deinit(a);

        // Step 3: workbook-wide structured-ref rewrite. The edit's
        // table spelling is the part's own displayName — `table_name`
        // may be a case variant.
        const edit: zlsx.formula_rewriter.RewriteEdit = .{ .rename_table_column = .{
            .table = renamed.display_name,
            .old = old_name,
            .new = new_name,
        } };
        const scope: TableScope = .{
            .sheet_idx = host_idx,
            .tl_row = renamed.tl_row,
            .tl_col = renamed.tl_col,
            .br_row = renamed.br_row,
            .br_col = renamed.br_col,
            .table = renamed.display_name,
        };
        try self.preflightExtensionFormulas();
        const count = try self.rewriteAllFormulas(edit, null, scope);
        _ = try self.rewriteAllDefinedNames(edit, null);
        _ = try self.rewriteAllHyperlinkLocations(edit, null);
        _ = try self.rewriteAllValidationsAndConditionalFormats(edit, null);
        _ = try self.rewriteAllExtensionFormulas(edit, null);

        // Step 4: commit the part and sync the header cell.
        if (!std.mem.eql(u8, table_part.bytes, renamed.bytes)) {
            try self.store.replacePart(table_part_name, renamed.bytes);
        }
        if (renamed.header_row) |hr| {
            const hc = renamed.header_col.?;
            var ref_buf: [16]u8 = undefined;
            var len: usize = coords.writeColLetters(
                ref_buf[0..3],
                coords.Col.fromOneBased(hc) catch return error.InvalidCellRef,
            );
            len += std.fmt.printInt(ref_buf[len..], hr, 10, .lower, .{});
            const host = try self.sheet(host_idx);
            try host.setCell(ref_buf[0..len], .{ .shared_string = new_name });
        }
        return count;
    }

    /// Add a new empty sheet to the workbook (B2 iter-er-4
    /// structural-edit surface). Allocates a fresh sheet part
    /// (`xl/worksheets/sheetN.xml`), patches `xl/workbook.xml` +
    /// `xl/_rels/workbook.xml.rels` (and `[Content_Types].xml` via
    /// `PartStore.addPart`), then grows the typed-overlay
    /// `worksheets` array. Returns a handle to the newly-added
    /// `Worksheet` view.
    ///
    /// The new sheet's body is the OOXML-minimal empty-sheet
    /// template — `<worksheet>` wrapping `<sheetData/>`. Subsequent
    /// `setCell` / `appendRows` / `addImage` calls operate through
    /// the returned handle.
    ///
    /// **Cap.** Refuses with `error.TooManySheets` if the workbook
    /// already holds `std.math.maxInt(u32)` sheets. Excel itself
    /// has no documented sheet count limit (memory-bounded), but
    /// the typed-overlay's u32 indexing does.
    ///
    /// **Errors:**
    ///   - `error.InvalidSheetName` per `validateSheetName`'s
    ///     contract (length, reserved chars, "history").
    ///   - `error.SheetNameInUse` if the name collides with any
    ///     existing sheet (case-insensitive ASCII).
    ///   - `error.TooManySheets` at the u32 cap.
    ///   - `error.MissingWorkbookPart` / `error.MissingWorkbookRels`
    ///     if the prerequisite parts have been spliced away.
    ///
    /// **Atomicity.** Like `addImage`, the mutation is not perfectly
    /// transactional across the four PartStore writes; ordering
    /// (addPart → rels → workbook.xml → view-refresh) keeps the
    /// workbook consistent right up to the workbook.xml splice.
    /// A failure between addPart and the workbook.xml patch leaves
    /// the part in the store unreferenced; cleanup ships with
    /// `removePart` in a future iter.
    ///
    /// **Pointer lifetime.** The returned `*Worksheet` (and any
    /// `*Worksheet` previously returned by `Workbook.sheet`) is
    /// invalidated by the next structural mutation (`addSheet`,
    /// `deleteSheet`) — those calls reallocate `self.worksheets`.
    /// Re-fetch via `wb.sheet(idx)` after structural edits.
    pub fn addSheet(self: *Workbook, name: []const u8) Error!*Worksheet {
        try validateSheetName(name);
        if (self.worksheets.len >= std.math.maxInt(u32)) return error.TooManySheets;
        // Workbook view stores sheet names as raw attribute bytes —
        // a source name like `R&D` is held as `R&amp;D`. Compare
        // against the entity-decoded form so attribute escaping
        // doesn't bypass the duplicate check. Direct byte-equality
        // first as a fast path; only allocate for entity decoding
        // when the candidate contains an `&`.
        for (self.workbook.sheets) |s| {
            if (try sheetNameMatchesDecoded(self.allocator, s.name, name)) return error.SheetNameInUse;
        }

        const wb_part = (try self.store.part("xl/workbook.xml")) orelse
            return error.MissingWorkbookPart;
        const rels_part = (try self.store.part("xl/_rels/workbook.xml.rels")) orelse
            return error.MissingWorkbookRels;

        // Pick non-colliding identifiers by scanning the source bytes.
        // Each addSheet rescans because previous calls extend the
        // workbook view in-place — nothing else tracks the running
        // high-water marks.
        const next_sheet_id = nextMaxNumericAttr(wb_part.bytes, "sheetId=\"") + 1;
        const next_rid_num = nextMaxNumericAttr(rels_part.bytes, "Id=\"rId") + 1;
        // Path number must avoid orphan worksheet parts too — when
        // a sheet is deleted via `Workbook.deleteSheet`, the part
        // remains in PartStore (orphan-part v1 trade-off). Computing
        // the next slot purely from rels would re-collide on the
        // orphan's path. Walk PartStore instead.
        const next_path_num = (try nextMaxSheetPathNumFromStore(&self.store)) + 1;

        var path_buf: [64]u8 = undefined;
        const new_path = try std.fmt.bufPrint(&path_buf, "xl/worksheets/sheet{d}.xml", .{next_path_num});
        var rid_buf: [32]u8 = undefined;
        const new_rid = try std.fmt.bufPrint(&rid_buf, "rId{d}", .{next_rid_num});

        const empty_body =
            "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
            "<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">" ++
            "<sheetData/></worksheet>";

        try self.store.addPart(
            new_path,
            "application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml",
            empty_body,
        );

        // workbook.xml.rels: add `<Relationship Id="rIdN" Type="…/worksheet" Target="worksheets/sheetN.xml"/>`.
        const new_rels_xml = try patchWorkbookRelsAddSheet(self.allocator, rels_part.bytes, new_rid, new_path);
        defer self.allocator.free(new_rels_xml);
        try self.store.replacePart("xl/_rels/workbook.xml.rels", new_rels_xml);

        // workbook.xml: add `<sheet name="…" sheetId="N" r:id="rIdN"/>`.
        const new_wb_xml = try patchWorkbookXmlAddSheet(self.allocator, wb_part.bytes, name, next_sheet_id, new_rid);
        defer self.allocator.free(new_wb_xml);
        try self.store.replacePart("xl/workbook.xml", new_wb_xml);

        // Re-parse workbook.xml. The patch added one sheet so the
        // fresh view's sheet count must equal the old view's + 1.
        const wb_part2 = (try self.store.part("xl/workbook.xml")) orelse
            return error.MissingWorkbookPart;
        var fresh = try workbook_xml_mod.parse(self.allocator, wb_part2.bytes);
        errdefer fresh.deinit(self.allocator);
        if (fresh.sheets.len != self.workbook.sheets.len + 1) {
            return error.SheetCountMismatch;
        }

        // Grow the worksheets slot table to match the new view.
        const old_count = self.worksheets.len;
        const new_count = old_count + 1;
        const new_slots = try self.allocator.alloc(Worksheet, new_count);
        errdefer self.allocator.free(new_slots);
        @memcpy(new_slots[0..old_count], self.worksheets);
        new_slots[old_count] = .{
            .workbook = self,
            .sheet_idx = @intCast(old_count),
            .parsed = null,
            .resolved_part_name = null,
        };
        // Patch back-pointers — old slots may have moved during
        // the realloc.
        for (new_slots) |*ws| ws.workbook = self;

        // Commit: swap workbook view, free old slots, install new.
        self.workbook.deinit(self.allocator);
        self.workbook = fresh;
        self.allocator.free(self.worksheets);
        self.worksheets = new_slots;

        const new_idx: u32 = @intCast(old_count);
        assert(new_idx < self.worksheets.len);
        return &self.worksheets[new_idx];
    }

    /// Embed `bytes` (PNG/JPEG/GIF, declared via `mime`) as an image
    /// pinned to `cell_anchor` on the sheet at `sheet_idx` — the
    /// `oneCellAnchor` form. The image is emitted at its **native
    /// size**, read from its own header and mapped to EMU at 96 DPI,
    /// and keeps that size when the anchor cell's row or column is
    /// resized.
    ///
    /// `cell_anchor` is 1-based `(col, row)` — col first, matching the
    /// OOXML drawing wire format — and carries optional
    /// `col_off_emu` / `row_off_emu` pixel offsets into that cell,
    /// both defaulting to 0. `drawing_emit.emuFromPixels` converts
    /// from pixels.
    ///
    /// Returns `error.UndecodableImageHeader` when the header is
    /// truncated or carries an unusable size. Use `addImageRange` to
    /// size an image by a cell range instead, or `addImageAnchored`
    /// to pass a deliberate extent.
    pub fn addImage(
        self: *Workbook,
        sheet_idx: u32,
        cell_anchor: drawing_emit.ImageCellAnchor,
        bytes: []const u8,
        mime: drawing_emit.ImageMime,
    ) Error!void {
        // Location errors outrank payload decode errors — the more
        // specific diagnosis wins, the same precedence validateAnchor
        // applies internally — so both are checked before the header
        // parse that deriving the native extent requires.
        if (sheet_idx >= self.sheetCount()) return error.SheetIndexOutOfRange;
        try drawing_emit.validateAnchorCell(cell_anchor);
        const ext = try drawing_emit.nativeExtent(mime, bytes);
        return self.addImageAnchored(
            sheet_idx,
            .{ .one_cell = .{ .at = cell_anchor, .ext = ext } },
            bytes,
            mime,
        );
    }

    /// Embed `bytes` as an image covering the inclusive 1-based cell
    /// range `range` on the sheet at `sheet_idx` — the `twoCellAnchor`
    /// form. `range` reads the way a spreadsheet user writes "B2:D5":
    /// `from` and `to` are both covered, and a 1×1 range (`from` ==
    /// `to`) covers exactly that cell. The image resizes with the rows
    /// and columns it spans.
    ///
    /// Rejects `error.InvalidAnchor` on a 0 row/col and
    /// `error.InvertedAnchorRange` when `to` precedes `from` on either
    /// axis.
    pub fn addImageRange(
        self: *Workbook,
        sheet_idx: u32,
        range: drawing_emit.ImageCellRange,
        bytes: []const u8,
        mime: drawing_emit.ImageMime,
    ) Error!void {
        return self.addImageAnchored(sheet_idx, .{ .two_cell = range }, bytes, mime);
    }

    /// Shared implementation behind `addImage` / `addImageRange`, and
    /// the entry point for callers that already hold an anchor union
    /// — including those that want a `one_cell` extent other than the
    /// image's native size. The remaining v1 limit is the same for
    /// both anchor forms: one image per call.
    ///
    /// Sheets that already carry a `<drawing>` element get the new
    /// image spliced into that existing drawing part as one more
    /// anchor — a fresh `rId` in the drawing's rels, a fresh `cNvPr`
    /// id/name — leaving the sheet XML and sheet rels untouched (see
    /// `appendImageToDrawing`).
    ///
    /// The mutation commits to the in-memory PartStore immediately
    /// (image bytes, drawing part, drawing rels, sheet XML splice,
    /// sheet rels). `Workbook.save` writes the archive to disk.
    pub fn addImageAnchored(
        self: *Workbook,
        sheet_idx: u32,
        anchor_spec: drawing_emit.ImageAnchorSpec,
        bytes: []const u8,
        mime: drawing_emit.ImageMime,
    ) Error!void {
        if (sheet_idx >= self.sheetCount()) return error.SheetIndexOutOfRange;
        try drawing_emit.validateAnchor(anchor_spec);

        // Reject mime/byte mismatch up front. Costs O(8) bytes; saves
        // a "broken image" round-trip in Office.
        try drawing_emit.validateMagic(mime, bytes);

        const ws = try self.sheet(sheet_idx);
        // ensureParsed populates resolved_part_name, needed to derive
        // the sheet rels file path.
        _ = try ws.ensureParsed();
        const sheet_part_name = ws.resolved_part_name.?;
        assert(std.mem.startsWith(u8, sheet_part_name, "xl/worksheets/"));
        assert(std.mem.endsWith(u8, sheet_part_name, ".xml"));

        // Sheets that already carry a LIVE `<drawing>` element take
        // the append path; the detection is name-boundary and
        // comment-aware, so a commented-out drawing element neither
        // diverts a fresh add nor gets spliced into.
        const sheet_part = (try self.store.part(sheet_part_name)) orelse
            return error.MissingSheetPart;
        if (drawing_emit.hasDrawingElement(sheet_part.bytes)) {
            return self.appendImageToDrawing(
                sheet_part_name,
                sheet_part.bytes,
                anchor_spec,
                bytes,
                mime,
            );
        }

        const a = self.allocator;

        // The fresh drawing part and both relationship Types are
        // emitted in the sheet's own conformance dialect, so a Strict
        // workbook doesn't gain a mixed-conformance package.
        const dialect = drawing_emit.detectSheetDialect(sheet_part.bytes);

        // Derive part-name slots. No gap-filling: bumping past the
        // highest seen N keeps the result stable across saves.
        const image_n = try drawing_emit.nextFreeNumber(&self.store, "xl/media/image", "");
        const drawing_n = try drawing_emit.nextFreeNumber(&self.store, "xl/drawings/drawing", ".xml");

        const ext = mime.extension();
        // Compose part names. Free at function-exit; addPart dupes
        // its arguments into PartStore's arena.
        const image_basename = try std.fmt.allocPrint(a, "image{d}.{s}", .{ image_n, ext });
        defer a.free(image_basename);
        const image_part_name = try std.fmt.allocPrint(a, "xl/media/{s}", .{image_basename});
        defer a.free(image_part_name);

        const drawing_basename = try std.fmt.allocPrint(a, "drawing{d}.xml", .{drawing_n});
        defer a.free(drawing_basename);
        const drawing_part_name = try std.fmt.allocPrint(a, "xl/drawings/{s}", .{drawing_basename});
        defer a.free(drawing_part_name);

        const drawing_rels_part_name = try std.fmt.allocPrint(
            a,
            "xl/drawings/_rels/drawing{d}.xml.rels",
            .{drawing_n},
        );
        defer a.free(drawing_rels_part_name);

        // Sheet rels file path = `xl/worksheets/_rels/<basename>.rels`.
        const sheet_basename = sheet_part_name["xl/worksheets/".len..];
        const sheet_rels_part_name = try std.fmt.allocPrint(
            a,
            "xl/worksheets/_rels/{s}.rels",
            .{sheet_basename},
        );
        defer a.free(sheet_rels_part_name);

        // Build the drawing artifacts in the sheet's dialect.
        const drawing_xml = try drawing_emit.buildDrawingXml(a, anchor_spec, dialect);
        defer a.free(drawing_xml);

        const drawing_rels_xml = try drawing_emit.buildDrawingRels(
            a,
            image_basename,
            dialect.imageRelType(),
        );
        defer a.free(drawing_rels_xml);

        // Pick `rId` for the sheet's drawing rel. New rels file → rId1;
        // existing → next free.
        const sheet_rels_existing = self.store.rels(sheet_part_name);
        const rid_n = try drawing_emit.nextFreeRelId(sheet_rels_existing);
        var rid_buf: [16]u8 = undefined;
        const rid = try std.fmt.bufPrint(&rid_buf, "rId{d}", .{rid_n});

        // Build the sheet rels (fresh or appended). Doing this BEFORE
        // any addPart/replacePart so a later addPart failure (OOM, Zip
        // size cap) leaves the store unchanged.
        const sheet_rels_part = try self.store.part(sheet_rels_part_name);
        const new_sheet_rels_xml: []u8 = if (sheet_rels_part) |p|
            try drawing_emit.appendRelationship(
                a,
                p.bytes,
                drawing_basename,
                rid,
                dialect.drawingRelType(),
            )
        else
            try drawing_emit.buildFreshSheetRels(
                a,
                drawing_basename,
                rid,
                dialect.drawingRelType(),
            );
        defer a.free(new_sheet_rels_xml);

        // Build the patched sheet XML (appends `<drawing r:id=...>`).
        const new_sheet_xml = try drawing_emit.appendDrawingElementToSheet(
            a,
            sheet_part.bytes,
            rid,
            dialect.nsR(),
        );
        defer a.free(new_sheet_xml);

        // Mutate the PartStore. Order:
        //   1. addPart image bytes
        //   2. addPart drawing XML
        //   3. addPart drawing rels
        //   4. replace/add sheet rels
        //   5. replacePart sheet XML
        // Not perfectly atomic across these — each call mutates store
        // state — but ordering image+drawing+rels first keeps the
        // workbook consistent right up to step 5: until the sheet XML
        // references the drawing, no consumer sees the partial wiring.
        try self.store.addPart(image_part_name, mime.contentType(), bytes);
        try self.store.addPart(
            drawing_part_name,
            "application/vnd.openxmlformats-officedocument.drawing+xml",
            drawing_xml,
        );
        try self.store.addPart(
            drawing_rels_part_name,
            "application/vnd.openxmlformats-package.relationships+xml",
            drawing_rels_xml,
        );
        if (sheet_rels_part != null) {
            try self.store.replacePart(sheet_rels_part_name, new_sheet_rels_xml);
        } else {
            try self.store.addPart(
                sheet_rels_part_name,
                "application/vnd.openxmlformats-package.relationships+xml",
                new_sheet_rels_xml,
            );
        }
        try self.store.replacePart(sheet_part_name, new_sheet_xml);

        // The cached SheetXml view borrowed from the now-stale source
        // bytes. Invalidate so subsequent reads re-parse from the
        // patched XML.
        if (ws.parsed) |*v| {
            var view = v.*;
            view.deinit(self.allocator);
            ws.parsed = null;
        }
    }

    /// Splice one more image into a sheet's existing drawing part —
    /// the multi-image path behind `addImageAnchored`. Chases the
    /// sheet's `<drawing r:id>` through the sheet rels to the drawing
    /// part, then touches THREE artifacts (image bytes, drawing rels,
    /// drawing XML); the sheet XML and sheet rels already carry their
    /// wiring and stay byte-identical.
    ///
    /// The rels chase parses part BYTES with
    /// `store.parseRelationships` — the same quote-tolerant,
    /// entity-decoding parser that fills `store.rels()`'s cache —
    /// rather than the cache itself: a rels file created by `addPart`
    /// earlier in the same session (the fresh-image path) exists as
    /// bytes but is absent from the cache, which only `replacePart`
    /// refreshes.
    ///
    /// The spliced anchor is emitted in the host drawing's own
    /// conformance dialect (Transitional or Strict, read off its
    /// root's `xmlns:xdr`), with all three prefixes declared inline on
    /// the anchor element so a host that never declares `a:`/`r:`
    /// stays well-formed; the image rel Type follows the same dialect.
    ///
    /// `sheet_xml` is the sheet part's current bytes, already fetched
    /// by the caller to decide this path.
    fn appendImageToDrawing(
        self: *Workbook,
        sheet_part_name: []const u8,
        sheet_xml: []const u8,
        anchor_spec: drawing_emit.ImageAnchorSpec,
        bytes: []const u8,
        mime: drawing_emit.ImageMime,
    ) Error!void {
        const a = self.allocator;

        const drawing_rid = drawing_emit.extractDrawingRelId(sheet_xml) orelse
            return error.DrawingRelationshipNotFound;

        // Sheet rels file path = `xl/worksheets/_rels/<basename>.rels`
        // (the caller asserted the `xl/worksheets/` prefix).
        const sheet_basename = sheet_part_name["xl/worksheets/".len..];
        const sheet_rels_part_name = try std.fmt.allocPrint(
            a,
            "xl/worksheets/_rels/{s}.rels",
            .{sheet_basename},
        );
        defer a.free(sheet_rels_part_name);

        // One scratch arena for both rels parses; parseRelationships
        // allocates every returned slice from it.
        var rels_arena = std.heap.ArenaAllocator.init(a);
        defer rels_arena.deinit();
        const rels_alloc = rels_arena.allocator();

        const sheet_rels_part = (try self.store.part(sheet_rels_part_name)) orelse
            return error.DrawingRelationshipNotFound;
        const sheet_rels = try store_mod.parseRelationships(rels_alloc, sheet_rels_part.bytes);
        // Match on Id AND semantics: the rel must be internal and of a
        // drawing Type. A hand-edited sheet whose `<drawing r:id>`
        // names a hyperlink or external rel must refuse, not chase
        // whatever target that rel happens to carry into a mutation.
        const target = blk: {
            for (sheet_rels) |r| {
                if (!std.mem.eql(u8, r.id, drawing_rid)) continue;
                if (r.target_mode != .internal) return error.DrawingRelationshipNotFound;
                if (!std.mem.eql(u8, r.type, drawing_emit.drawing_rel_type_transitional) and
                    !std.mem.eql(u8, r.type, drawing_emit.drawing_rel_type_strict))
                {
                    return error.DrawingRelationshipNotFound;
                }
                break :blk r.target;
            }
            return error.DrawingRelationshipNotFound;
        };
        // Targets resolve against the OWNER part's directory, not the
        // rels sidecar's (`../drawings/…` from `xl/worksheets/`).
        const drawing_part_name = (try self.store.resolve(sheet_part_name, target)) orelse
            return error.DrawingRelationshipNotFound;

        // The `../media/` image target emitted below assumes the
        // `xl/drawings/<basename>` layout every producer we round-trip
        // uses; a drawing part elsewhere would get a dangling target.
        if (!std.mem.startsWith(u8, drawing_part_name, "xl/drawings/")) {
            return error.UnsupportedDrawingPart;
        }
        const drawing_basename = drawing_part_name["xl/drawings/".len..];
        if (std.mem.indexOfScalar(u8, drawing_basename, '/') != null) {
            return error.UnsupportedDrawingPart;
        }

        const drawing_part = (try self.store.part(drawing_part_name)) orelse
            return error.DrawingRelationshipNotFound;

        // Refuse before any mutation when the host speaks a dialect
        // we can't match — splicing a Transitional anchor into an
        // unknown-namespace wsDr corrupts the part instead.
        const dialect = drawing_emit.detectWsDrDialect(drawing_part.bytes) orelse
            return error.UnsupportedDrawingPart;

        const image_n = try drawing_emit.nextFreeNumber(&self.store, "xl/media/image", "");
        const ext = mime.extension();
        const image_basename = try std.fmt.allocPrint(a, "image{d}.{s}", .{ image_n, ext });
        defer a.free(image_basename);
        const image_part_name = try std.fmt.allocPrint(a, "xl/media/{s}", .{image_basename});
        defer a.free(image_part_name);

        const drawing_rels_part_name = try std.fmt.allocPrint(
            a,
            "xl/drawings/_rels/{s}.rels",
            .{drawing_basename},
        );
        defer a.free(drawing_rels_part_name);

        // Per-image ids within the existing drawing: the next free
        // `rId` in its rels, the next free `cNvPr` id among all its
        // anchors. A shapes-only drawing may have no rels file yet —
        // then the image rel is its first, `rId1`.
        const drawing_rels_part = try self.store.part(drawing_rels_part_name);
        const rid_n: u32 = if (drawing_rels_part) |p|
            try drawing_emit.nextFreeRelId(try store_mod.parseRelationships(rels_alloc, p.bytes))
        else
            1;
        var rid_buf: [16]u8 = undefined;
        const rid = try std.fmt.bufPrint(&rid_buf, "rId{d}", .{rid_n});
        const pic_id = try drawing_emit.nextFreeCnvprId(drawing_part.bytes);

        // Build every artifact BEFORE any store mutation — same
        // discipline as the fresh path: a build failure (malformed
        // rels, OOM) leaves the store unchanged.
        const anchor_xml = try drawing_emit.buildPicAnchorXml(
            a,
            anchor_spec,
            rid,
            pic_id,
            .{ .declare = dialect },
        );
        defer a.free(anchor_xml);

        const new_drawing_xml = try drawing_emit.appendAnchorToDrawing(
            a,
            drawing_part.bytes,
            anchor_xml,
        );
        defer a.free(new_drawing_xml);

        const new_drawing_rels_xml: []u8 = if (drawing_rels_part) |p|
            try drawing_emit.appendImageRelationship(
                a,
                p.bytes,
                image_basename,
                rid,
                dialect.imageRelType(),
            )
        else
            try drawing_emit.buildDrawingRels(a, image_basename, dialect.imageRelType());
        defer a.free(new_drawing_rels_xml);

        // Mutate. Order: image bytes, drawing rels, drawing XML last —
        // until the spliced anchor lands, nothing references the new
        // image, so every intermediate state stays consistent.
        try self.store.addPart(image_part_name, mime.contentType(), bytes);
        if (drawing_rels_part != null) {
            try self.store.replacePart(drawing_rels_part_name, new_drawing_rels_xml);
        } else {
            try self.store.addPart(
                drawing_rels_part_name,
                "application/vnd.openxmlformats-package.relationships+xml",
                new_drawing_rels_xml,
            );
        }
        try self.store.replacePart(drawing_part_name, new_drawing_xml);
    }

    /// Case-insensitive ASCII duplicate check. Skips the slot at
    /// `sheet_idx` itself so renaming a sheet to its own current name
    /// (modulo case) is permitted at this layer; a true no-op (exact
    /// byte match) short-circuits earlier in `renameSheet`.
    fn assertSheetNameAvailable(self: *const Workbook, sheet_idx: u32, new_name: []const u8) Error!void {
        assert(sheet_idx < self.workbook.sheets.len);
        assert(new_name.len > 0);
        for (self.workbook.sheets, 0..) |s, i| {
            if (i == sheet_idx) continue;
            if (asciiCaseInsensitiveEql(s.name, new_name)) return error.SheetNameInUse;
        }
    }

    /// Remove the sheet at `sheet_idx` from the workbook. Patches three
    /// XML parts and refreshes the in-memory view; subsequent
    /// `Workbook.save` writes a workbook whose `<sheets>` list, rels
    /// table, and `[Content_Types].xml` Overrides no longer reference
    /// the removed sheet.
    ///
    /// **Orphan-part trade-off (v1).** `PartStore` has no `removePart`
    /// API today, so the deleted sheet's `xl/worksheets/sheetN.xml`
    /// (and its sidecar `xl/worksheets/_rels/sheetN.xml.rels` when
    /// present) remain physically inside the archive after `save`,
    /// just unreferenced from any rels / Content_Types entries. Excel,
    /// LibreOffice, and openpyxl all tolerate orphan parts (the OPC
    /// reader resolves parts via `[Content_Types].xml` Overrides + rels
    /// graphs; unreferenced parts are dead weight). A true cleanup
    /// requires `PartStore.removePart`; that's a future iter.
    ///
    /// **Cross-references not rewritten (v1).** `<definedName>` slots
    /// with `localSheetId == sheet_idx` (sheet-scoped names), formulas
    /// referencing the deleted sheet, and hyperlink targets pointing at
    /// it remain on the wire and will produce `#REF!` or
    /// `Reference is not valid` in Excel after open. Same scope
    /// boundary as `renameSheet`'s `m3-defnames-hyperlinks` follow-up.
    ///
    /// **Errors:**
    ///   - `SheetIndexOutOfRange` — `sheet_idx >= sheetCount()`.
    ///   - `LastSheetUndeletable` — `sheetCount() == 1`.
    ///   - `MissingWorkbookPart` / `MissingWorkbookRels` — corrupt
    ///     archive lacks the parts to be patched.
    ///   - `SheetElementNotFound` / `RelationshipElementNotFound` —
    ///     the on-wire bytes don't match the parsed view (file
    ///     mutated under us between parse and patch).
    pub fn deleteSheet(self: *Workbook, sheet_idx: u32) Error!void {
        if (sheet_idx >= self.sheetCount()) return error.SheetIndexOutOfRange;
        if (self.sheetCount() == 1) return error.LastSheetUndeletable;
        // Pre-condition: the slot table and the parsed view agree on
        // length (the same invariant `sheetCount` asserts on read).
        assert(self.worksheets.len == self.workbook.sheets.len);
        assert(self.worksheets.len >= 2);

        // Capture r_id BEFORE patches: the post-patch re-parse frees the
        // arena that backs `sheets[idx].r_id`, but the rels patch needs
        // the bytes alive.
        const r_id_src = self.workbook.sheets[sheet_idx].r_id;
        if (r_id_src.len == 0) return error.MissingRelationship;
        if (r_id_src.len > 64) return error.MissingRelationship;
        var r_id_buf: [64]u8 = undefined;
        @memcpy(r_id_buf[0..r_id_src.len], r_id_src);
        const r_id_owned = r_id_buf[0..r_id_src.len];

        // Resolve the part name (e.g. "xl/worksheets/sheet2.xml") via
        // ensureParsed — caches `resolved_part_name` on the Worksheet.
        // Dupe into a stack buffer so the slot deinit below can't free
        // it from under the Content_Types patch.
        const ws = try self.sheet(sheet_idx);
        _ = try ws.ensureParsed();
        const part_name_src = ws.resolved_part_name orelse return error.MissingSheetPart;
        if (part_name_src.len == 0) return error.MissingSheetPart;
        if (part_name_src.len > 256) return error.MissingSheetPart;
        var part_name_buf: [256]u8 = undefined;
        @memcpy(part_name_buf[0..part_name_src.len], part_name_src);
        const part_name_owned = part_name_buf[0..part_name_src.len];

        // B2 iter-er-5 lift (deleteSheet defined-names axis): rewrite
        // every cross-sheet ref to the doomed sheet across the
        // remaining sheets. Cell formulas, defined-name formulas,
        // internal hyperlink locations, and DV / CF formulas all
        // collapse to `#REF!` on the qualifier-matching path. Bare
        // refs are unaffected (the deleted sheet's own formulas
        // are dropped with the sheet, not rewritten).
        const doomed_name_src = self.workbook.sheets[sheet_idx].name;
        // Decoded per the rewrite boundary's decode-in contract —
        // formula qualifiers arrive decoded, so the edit name must
        // match in decoded space.
        const doomed_name_owned = try store_mod.decodeXmlEntities(self.allocator, doomed_name_src);
        defer self.allocator.free(doomed_name_owned);
        const edit: zlsx.formula_rewriter.RewriteEdit = .{ .delete_sheet = doomed_name_owned };
        try self.preflightExtensionFormulas();
        _ = try self.rewriteAllFormulas(edit, null, null);
        _ = try self.rewriteAllDefinedNames(edit, null);
        _ = try self.rewriteAllHyperlinkLocations(edit, null);
        _ = try self.rewriteAllValidationsAndConditionalFormats(edit, null);
        _ = try self.rewriteAllExtensionFormulas(edit, null);

        try patchWorkbookXmlRemoveSheet(self, sheet_idx);
        try patchWorkbookRelsRemoveRelationship(self, r_id_owned);
        // Content_Types Override removal is best-effort — some
        // tooling omits per-sheet Overrides and relies on Default
        // entries instead.
        patchContentTypesRemoveOverride(self, part_name_owned) catch |err| switch (err) {
            error.ContentTypesOverrideNotFound => {},
            else => return err,
        };

        // Re-parse the workbook view in place. Can't use
        // `refreshWorkbookXmlView` here because that helper asserts
        // sheet-count invariance (correct for renameSheet, wrong
        // for delete which expects count - 1).
        {
            const fresh_part = try self.store.part("xl/workbook.xml") orelse
                return error.MissingWorkbookPart;
            var fresh = try workbook_xml_mod.parse(self.allocator, fresh_part.bytes);
            errdefer fresh.deinit(self.allocator);
            if (fresh.sheets.len + 1 != self.workbook.sheets.len) {
                return error.SheetCountMismatch;
            }
            self.workbook.deinit(self.allocator);
            self.workbook = fresh;
        }

        // Shrink the slot table. Order matters:
        //   1. deinit the doomed Worksheet BEFORE copying slots —
        //      copying first then freeing would deinit the wrong slot.
        //   2. allocate the new (n-1)-sized slot array.
        //   3. copy [0..idx] and [idx+1..] across.
        //   4. free the old array.
        const old_slots = self.worksheets;
        const old_len = old_slots.len;
        assert(sheet_idx < old_len);

        old_slots[sheet_idx].deinit(self.allocator);

        const new_slots = try self.allocator.alloc(Worksheet, old_len - 1);
        errdefer self.allocator.free(new_slots);

        var i: u32 = 0;
        var j: u32 = 0;
        while (i < old_len) : (i += 1) {
            if (i == sheet_idx) continue;
            new_slots[j] = old_slots[i];
            // Renumber: surviving Worksheet's `sheet_idx` must line up
            // with its new slot position (the re-parsed view holds
            // sheets in document order).
            new_slots[j].sheet_idx = j;
            j += 1;
        }
        assert(j == old_len - 1);

        self.allocator.free(old_slots);
        self.worksheets = new_slots;

        assert(self.worksheets.len == self.workbook.sheets.len);
        assert(self.worksheets.len == old_len - 1);
    }

    /// Read-only predicate: does the workbook carry any pending
    /// mutation that has not yet been flushed via `save`?
    ///
    /// Returns `true` if EITHER:
    ///   1. any `Worksheet.deltas` map is non-empty (uncommitted
    ///      `setCell` mutations), OR
    ///   2. the underlying `PartStore` has any override (uncommitted
    ///      `replacePart` / `addPart` from e.g. `renameSheet`,
    ///      `rewriteAllFormulas`, the SST extension path).
    ///
    /// Note: `PartStore.save` does NOT clear overrides post-save —
    /// they persist across save calls. So this predicate reflects
    /// "diff vs the original on-disk archive opened by `Workbook.open`",
    /// not "uncommitted-since-last-save". Most callers want the
    /// former (e.g. for "do I need to save before exit?" — the
    /// answer should remain true even after a previous save).
    pub fn hasUnsavedChanges(self: *const Workbook) bool {
        for (self.worksheets) |ws| {
            if (ws.deltas.count() > 0) return true;
        }
        return self.store.hasUnsavedChanges();
    }

    /// Insert a blank row at position `before_row` (1-based) in
    /// sheet `sheet_idx`. Every existing row at or below `before_row`
    /// shifts down by 1.  Mutates the workbook's PartStore in
    /// place: the sheet part is re-emitted with `<row r=>` /
    /// `<c r="…">` / `<mergeCells>` / `<dimension>` shifted by
    /// one row.
    ///
    /// **Refusal contract.** Refuses with
    /// `error.RowEditRequiresCleanSheet` if the sheet has any
    /// staged appendRows or setCell deltas — those deltas index
    /// into the pre-shift refs and would produce stale output.
    ///
    /// **Cross-sheet rewrite.** Cross-sheet formula refs / defined
    /// names / hyperlinks / DV-CF formulas are NOT yet rewritten
    /// for row inserts. Sheets that carry those constructs anywhere
    /// in the workbook are refused at the editor layer
    /// (`Editor.insertRow`); the iter-er-5 row/col-axis lifts
    /// (blocked on this PR's typed surface, plus the
    /// rewriter-call wiring) are tracked in
    /// `docs/plans/refusal-audit.md`.
    pub fn insertRow(self: *Workbook, sheet_idx: u32, before_row: u32) Error!void {
        try self.applySheetEditTransform(sheet_idx, .{ .row = before_row, .kind = .insert });
    }

    /// Delete row `row` (1-based) in sheet `sheet_idx`. Every row
    /// > `row` shifts up by 1; cells in the deleted row are
    /// dropped. Same refusal contract + cross-sheet-rewrite
    /// limitations as `insertRow`.
    pub fn deleteRow(self: *Workbook, sheet_idx: u32, row: u32) Error!void {
        try self.applySheetEditTransform(sheet_idx, .{ .row = row, .kind = .delete });
    }

    /// Insert a blank column at position `before_col` (1-based, A=1)
    /// in sheet `sheet_idx`. Every existing column at or right of
    /// `before_col` shifts right by 1. Same refusal contract as
    /// `insertRow`; cross-sheet rewrite is the same iter-er-5
    /// follow-up.
    pub fn insertColumn(self: *Workbook, sheet_idx: u32, before_col_1based: u32) Error!void {
        try self.applySheetEditTransform(sheet_idx, .{ .col = before_col_1based, .kind = .insert });
    }

    /// Delete column `col_1based` in sheet `sheet_idx`. Every
    /// column > `col_1based` shifts left by 1.
    pub fn deleteColumn(self: *Workbook, sheet_idx: u32, col_1based: u32) Error!void {
        try self.applySheetEditTransform(sheet_idx, .{ .col = col_1based, .kind = .delete });
    }

    const SheetEditSpec = struct {
        row: ?u32 = null,
        col: ?u32 = null,
        kind: sheet_edit.RowEditKind,
    };

    fn applySheetEditTransform(self: *Workbook, sheet_idx: u32, spec: SheetEditSpec) Error!void {
        if (sheet_idx >= self.sheetCount()) return error.SheetIndexOutOfRange;
        const ws = try self.sheet(sheet_idx);
        if (ws.deltas.count() > 0) return error.SheetHasUnsavedMutations;
        if (ws.appended_rows.items.len > 0) return error.SheetHasUnsavedAppends;

        const part_name = try ws.resolvePartName();

        // Preflight the transform on the PRE-sweep bytes, discarding
        // the output (Codex #192 F5): every refusal-class error the
        // transform can raise (ColEditExceedsMaxCol on an occupied
        // last column, RowEditExceedsMaxRow, malformed sheet XML)
        // must fire BEFORE the first mutation — the sweep below
        // replaces parts, and a refusal after it would strand
        // phantom formula rewrites that a later save persists. The
        // sweep only rewrites `<f>` inner text, so a transform that
        // passes preflight cannot newly refuse on the swept bytes;
        // an error there anyway falls under the documented
        // post-validation contract (discard, reopen). The `<xm:f>`
        // gate is the same shape one level up: every sheet's
        // extension formulas must be readable before any sweep
        // replaces a part (all-or-nothing, S2).
        try self.preflightExtensionFormulas();
        {
            const pre = (try self.store.part(part_name)) orelse return error.MissingSheetPart;
            const probe = if (spec.row) |r|
                try sheet_edit.applyRowEditToWorksheet(self.allocator, pre.bytes, r, spec.kind)
            else
                try sheet_edit.applyColEditToWorksheet(self.allocator, pre.bytes, spec.col.?, spec.kind);
            self.allocator.free(probe);
        }

        // The FORMULA sweep runs BEFORE the byte transform (Codex
        // #192 F1): formula text spells PRE-edit positions, and
        // relative R1C1 parts respell against RewriteContext.host —
        // the formula's own cell — which must live in that same
        // pre-edit space. Post-transform, `c.ref` is the shifted
        // coordinate: a `R[-1]C` in B6 under deleteRow(4) re-parsed
        // from B5 would infer target B4 = "deleted" and corrupt to
        // #REF!. The A1 path is order-blind (it maps text positions
        // only), so only this sweep moves; the three host-free
        // sweeps below stay after the transform.
        const target = try store_mod.decodeXmlEntities(self.allocator, self.workbook.sheets[sheet_idx].name);
        defer self.allocator.free(target);
        const edit: zlsx.formula_rewriter.RewriteEdit = if (spec.row) |r|
            switch (spec.kind) {
                .insert => .{ .insert_rows = .{ .at = r, .count = 1 } },
                .delete => .{ .delete_rows = .{ .at = r, .count = 1 } },
            }
        else switch (spec.kind) {
            .insert => .{ .insert_cols = .{ .at = spec.col.?, .count = 1 } },
            .delete => .{ .delete_cols = .{ .at = spec.col.?, .count = 1 } },
        };
        _ = try self.rewriteAllFormulas(edit, target, null);

        // Re-fetch AFTER the sweep: a rewrite replaced the part, and
        // the transform must shift the spliced bytes, not the stale
        // originals.
        const part = (try self.store.part(part_name)) orelse return error.MissingSheetPart;

        const new_xml = if (spec.row) |r|
            try sheet_edit.applyRowEditToWorksheet(self.allocator, part.bytes, r, spec.kind)
        else
            try sheet_edit.applyColEditToWorksheet(self.allocator, part.bytes, spec.col.?, spec.kind);
        defer self.allocator.free(new_xml);
        try self.store.replacePart(part_name, new_xml);

        // dr-1: rewrite modern xdr drawing anchors in the sheet's
        // referenced `xl/drawings/drawingN.xml` part. Sheets without
        // a `<drawing r:id>` element skip silently; no-op rewrites
        // are byte-identical and skip `replacePart` so SHA256
        // passthrough holds.
        try self.applyDrawingEditForSheet(part_name, part.bytes, spec);

        // dr-2: rewrite legacy VML drawing + paired comments part
        // (anchor cell + display rect + paired `<comment ref>`).
        // Sheets without `<legacyDrawing r:id>` skip silently.
        try self.applyVmlDrawingEditForSheet(part_name, part.bytes, spec);

        // tbl: rewrite each `xl/tables/tableN.xml` referenced from
        // the sheet's `<tableParts>` block. Sheets without
        // `<tableParts>` skip silently. The Editor pre-flights
        // unsafe edits (collapse / header-row delete) before we get
        // here, so this call only encounters safe shifts.
        try self.applyTableEditsForSheet(part_name, part.bytes, spec);

        // Invalidate the cached parsed view — the row/col-shifted
        // bytes don't match the previously-parsed structure, and
        // any subsequent ensureParsed must re-tokenize the new
        // body. resolved_part_name stays valid (path didn't change).
        if (ws.parsed) |*v| {
            var view = v.*;
            view.deinit(self.allocator);
            ws.parsed = null;
        }

        // B2 iter-er-5 lift (row/col axes), remaining carriers:
        // defined names, internal hyperlink locations, DV/CF
        // formulas and (S2) `<extLst>` `<xm:f>` formulas. All four
        // splice text in place and carry no host, so they compose
        // with the byte transform in either order; the formula sweep
        // already ran ABOVE the transform (see there for why). The
        // `<xm:f>` sweep and the transform touch the same `<extLst>`
        // — the transform shifts `<xm:sqref>`, the sweep splices
        // `<xm:f>` bodies — on disjoint bytes.
        _ = try self.rewriteAllDefinedNames(edit, target);
        _ = try self.rewriteAllHyperlinkLocations(edit, target);
        _ = try self.rewriteAllValidationsAndConditionalFormats(edit, target);
        _ = try self.rewriteAllExtensionFormulas(edit, target);
    }

    /// dr-1: rewrite the modern xdr drawing part referenced by the
    /// sheet (if any). `<xdr:from>` / `<xdr:to>` `<xdr:col>` /
    /// `<xdr:row>` 0-based coordinates inside `<xdr:twoCellAnchor>`
    /// and `<xdr:oneCellAnchor>` shift in step with the worksheet
    /// row/col edit; full-collapse anchors drop. Sheets without a
    /// `<drawing r:id>` element skip silently.
    fn applyDrawingEditForSheet(
        self: *Workbook,
        sheet_part_name: []const u8,
        sheet_xml: []const u8,
        spec: SheetEditSpec,
    ) Error!void {
        const rid = findWorksheetDrawingRid(sheet_xml) orelse return;
        const rels = self.store.rels(sheet_part_name);
        const target = relTargetForId(rels, rid) orelse return;
        const drawing_part_name = (try self.store.resolve(sheet_part_name, target)) orelse return;
        const drawing_part = (try self.store.part(drawing_part_name)) orelse return;

        const idx_1based = spec.row orelse spec.col.?;
        if (idx_1based == 0) return;
        const axis: drawing_edit.Axis = if (spec.row != null) .row else .col;
        const kind: drawing_edit.EditKind = switch (spec.kind) {
            .insert => .insert,
            .delete => .delete,
        };
        const new_drawing = try drawing_edit.applyEditToDrawing(
            self.allocator,
            drawing_part.bytes,
            axis,
            idx_1based - 1,
            kind,
        );
        defer self.allocator.free(new_drawing);
        if (!std.mem.eql(u8, drawing_part.bytes, new_drawing)) {
            try self.store.replacePart(drawing_part_name, new_drawing);
        }
    }

    /// dr-2: rewrite the legacy VML drawing part referenced by
    /// the sheet (if any), AND the paired comments part. VML
    /// `<x:Anchor>` 8-int payload + the `<x:Row>`/`<x:Column>`
    /// anchor cell shift in step with the edit; shapes whose
    /// anchor cell is on the deleted axis drop. The paired
    /// `<comment ref>` in `xl/commentsN.xml` shifts/drops
    /// alongside (REL-705 — they MUST stay synchronized).
    fn applyVmlDrawingEditForSheet(
        self: *Workbook,
        sheet_part_name: []const u8,
        sheet_xml: []const u8,
        spec: SheetEditSpec,
    ) Error!void {
        const idx_1based = spec.row orelse spec.col.?;
        if (idx_1based == 0) return;
        const axis: vml_edit.Axis = if (spec.row != null) .row else .col;
        const kind: vml_edit.EditKind = switch (spec.kind) {
            .insert => .insert,
            .delete => .delete,
        };
        const rels = self.store.rels(sheet_part_name);

        // VML drawing rewrite (anchor cell + display rect).
        if (findWorksheetLegacyDrawingRid(sheet_xml)) |rid| {
            if (relTargetForId(rels, rid)) |target| {
                if (try self.store.resolve(sheet_part_name, target)) |drawing_part_name| {
                    if (try self.store.part(drawing_part_name)) |drawing_part| {
                        const new_bytes = try vml_edit.applyEditToVmlDrawing(
                            self.allocator,
                            drawing_part.bytes,
                            axis,
                            idx_1based - 1,
                            kind,
                        );
                        defer self.allocator.free(new_bytes);
                        if (!std.mem.eql(u8, drawing_part.bytes, new_bytes)) {
                            try self.store.replacePart(drawing_part_name, new_bytes);
                        }
                    }
                }
            }
        }

        // Comments part rewrite (REL-705): every VML note shape
        // has a paired `<comment ref>` in `xl/commentsN.xml` —
        // they MUST stay synchronized. Drop on delete-match,
        // shift otherwise. Identified by relationship Type
        // (`/relationships/comments` suffix — catches both
        // Transitional and Strict OOXML namespace URIs).
        for (rels) |rel| {
            if (!std.mem.endsWith(u8, rel.type, "/relationships/comments")) continue;
            const comments_part_name = (try self.store.resolve(sheet_part_name, rel.target)) orelse continue;
            const comments_part = (try self.store.part(comments_part_name)) orelse continue;
            const new_bytes = try vml_edit.applyEditToCommentsXml(
                self.allocator,
                comments_part.bytes,
                axis,
                idx_1based,
                kind,
            );
            defer self.allocator.free(new_bytes);
            if (!std.mem.eql(u8, comments_part.bytes, new_bytes)) {
                try self.store.replacePart(comments_part_name, new_bytes);
            }
        }
    }

    /// tbl pre-flight: dry-run `table_edit.applyEditToTable`
    /// against every table part referenced from the sheet's
    /// `<tableParts>` block, freeing the dry-run output. Returns
    /// the first refusal (e.g. `TableCollapseUnsafe`,
    /// `TableHeaderRowDeleteUnsafe`) so the Editor can surface
    /// `RowEditUnsafeForSheet` / `ColEditUnsafeForSheet` BEFORE any
    /// sheet bytes are mutated. Sheets without `<tableParts>` are
    /// no-ops.
    pub fn preflightTableEditsForSheet(
        self: *Workbook,
        sheet_part_name: []const u8,
        axis: table_edit.Axis,
        idx_1based: u32,
        kind: table_edit.EditKind,
    ) Error!void {
        const sheet_part = (try self.store.part(sheet_part_name)) orelse return;
        const rels = self.store.rels(sheet_part_name);
        var rid_iter = TablePartRidIterator.init(sheet_part.bytes);
        while (rid_iter.next()) |rid| {
            const target = relTargetForId(rels, rid) orelse continue;
            const table_part_name = (try self.store.resolve(sheet_part_name, target)) orelse continue;
            const table_part = (try self.store.part(table_part_name)) orelse continue;
            const out = try table_edit.applyEditToTable(
                self.allocator,
                table_part.bytes,
                axis,
                idx_1based,
                kind,
            );
            self.allocator.free(out);
        }
    }

    /// Refuse a row/col edit on a sheet that a pivot table reads from.
    ///
    /// A pivot's `<location ref>` and its cache field ranges live in
    /// `xl/pivotTables/pivotN.xml` and `xl/pivotCache/*`, keyed by a
    /// cross-part reference graph zlsx has no rewriter for. Until it
    /// does, the honest outcome is a typed refusal.
    ///
    /// This closes a **silent-corruption** path, not a feature gap.
    /// `docs/plans/refusal-audit.md` recorded pivots as "refused at
    /// consumer level" — they were not refused anywhere: neither
    /// `pkg/sheet_edit.zig` nor `pkg/editor.zig` contained the string
    /// "pivot". A row insert simply left every pivot coordinate
    /// pointing at the pre-shift grid. Same class as the four
    /// unrewritten elements #125 found, and invisible to the same
    /// audit method for the same reason: you cannot enumerate a guard
    /// that was never written.
    ///
    /// Detection is by relationship type rather than by scanning the
    /// sheet body: a pivot leaves no required marker in the worksheet
    /// XML (`<pivotSelection>` rides in `<sheetView>` but is
    /// optional), while the r:id edge to the pivot part is what makes
    /// the pivot depend on this sheet's coordinates at all.
    pub fn preflightPivotEditsForSheet(
        self: *Workbook,
        sheet_part_name: []const u8,
    ) Error!void {
        for (self.store.rels(sheet_part_name)) |rel| {
            if (isPivotRelType(rel.type)) return error.PivotEditUnsafe;
        }
    }

    /// tbl: walk the sheet's `<tableParts>` block, resolve each
    /// `<tablePart r:id>` through the sheet rels, and run
    /// `table_edit.applyEditToTable` against the referenced
    /// `xl/tables/tableN.xml` part. Sheets without `<tableParts>`
    /// skip silently. Pre-flight refusals (`TableCollapseUnsafe`,
    /// `TableHeaderRowDeleteUnsafe`, `MalformedTableXml`,
    /// `TableCoordinateOverflow`) are caught upstream by the
    /// Editor and remapped to `RowEditUnsafeForSheet` /
    /// `ColEditUnsafeForSheet`; reaching this code with an unsafe
    /// edit propagates the raw table-edit typed error to the caller
    /// (Workbook callers that bypass Editor see the original).
    fn applyTableEditsForSheet(
        self: *Workbook,
        sheet_part_name: []const u8,
        sheet_xml: []const u8,
        spec: SheetEditSpec,
    ) Error!void {
        const idx_1based = spec.row orelse spec.col.?;
        if (idx_1based == 0) return;
        const axis: table_edit.Axis = if (spec.row != null) .row else .col;
        const kind: table_edit.EditKind = switch (spec.kind) {
            .insert => .insert,
            .delete => .delete,
        };
        const rels = self.store.rels(sheet_part_name);

        var rid_iter = TablePartRidIterator.init(sheet_xml);
        while (rid_iter.next()) |rid| {
            const target = relTargetForId(rels, rid) orelse continue;
            const table_part_name = (try self.store.resolve(sheet_part_name, target)) orelse continue;
            const table_part = (try self.store.part(table_part_name)) orelse continue;
            const new_bytes = try table_edit.applyEditToTable(
                self.allocator,
                table_part.bytes,
                axis,
                idx_1based,
                kind,
            );
            defer self.allocator.free(new_bytes);
            if (!std.mem.eql(u8, table_part.bytes, new_bytes)) {
                try self.store.replacePart(table_part_name, new_bytes);
            }
        }
    }
};

/// Iterator over `<tablePart r:id>` elements inside a worksheet's
/// `<tableParts>` block. Yields the rid string for each child.
/// Allocator-free, single-pass.
pub const TablePartRidIterator = struct {
    sheet_xml: []const u8,
    cursor: usize,
    block_end: usize,
    found_block: bool,

    pub fn init(sheet_xml: []const u8) TablePartRidIterator {
        // Locate `<tableParts>` open + matching close. Leave
        // cursor inside the block; on absence, set cursor == end.
        // Comment/CDATA/PI decoys are skipped on both the open and
        // the close search (Codex #190 r1 F5 — the rename lookup
        // widened this scanner's blast radius, so it learned the
        // aware walk for every consumer).
        var i: usize = 0;
        while (i < sheet_xml.len) {
            const lt = std.mem.indexOfScalarPos(u8, sheet_xml, i, '<') orelse break;
            const skip = workbook_xml_mod.skipNonElement(sheet_xml, lt) catch break;
            if (skip != lt) {
                i = skip;
                continue;
            }
            const need = "<tableParts".len;
            if (lt + need >= sheet_xml.len) break;
            if (std.mem.eql(u8, sheet_xml[lt .. lt + need], "<tableParts")) {
                const after_byte = sheet_xml[lt + need];
                if (after_byte == ' ' or after_byte == '\t' or after_byte == '\r' or
                    after_byte == '\n' or after_byte == '/' or after_byte == '>')
                {
                    const open_end = std.mem.indexOfScalarPos(u8, sheet_xml, lt, '>') orelse break;
                    // Self-closing `<tableParts/>` — empty block.
                    if (open_end > 0 and sheet_xml[open_end - 1] == '/') {
                        return .{ .sheet_xml = sheet_xml, .cursor = 0, .block_end = 0, .found_block = false };
                    }
                    const close = (workbook_xml_mod.findClosingTag(sheet_xml, open_end + 1, "</tableParts>") catch break) orelse break;
                    return .{
                        .sheet_xml = sheet_xml,
                        .cursor = open_end + 1,
                        .block_end = close,
                        .found_block = true,
                    };
                }
            }
            i = lt + 1;
        }
        return .{ .sheet_xml = sheet_xml, .cursor = 0, .block_end = 0, .found_block = false };
    }

    pub fn next(self: *TablePartRidIterator) ?[]const u8 {
        if (!self.found_block) return null;
        while (self.cursor < self.block_end) {
            const lt = std.mem.indexOfScalarPos(u8, self.sheet_xml, self.cursor, '<') orelse return null;
            if (lt >= self.block_end) return null;
            const skip = self.skipDecoy(lt) orelse return null;
            if (skip != lt) {
                self.cursor = skip;
                continue;
            }
            const need = "<tablePart".len;
            if (lt + need >= self.sheet_xml.len) return null;
            if (std.mem.eql(u8, self.sheet_xml[lt .. lt + need], "<tablePart")) {
                // Disambiguate `<tablePart` from `<tableParts`.
                const after_byte = self.sheet_xml[lt + need];
                if (after_byte == ' ' or after_byte == '\t' or after_byte == '\r' or
                    after_byte == '\n' or after_byte == '/' or after_byte == '>')
                {
                    const tag_end = std.mem.indexOfScalarPos(u8, self.sheet_xml, lt, '>') orelse return null;
                    // REL-B524: refuse to consume a `<tablePart>` whose
                    // closing `>` lies past the parent `<tableParts>`
                    // block — well-formed XML guarantees this won't
                    // happen, but on adversarial input the iterator
                    // would otherwise leak a rid from outside the
                    // block.
                    if (tag_end >= self.block_end) return null;
                    self.cursor = tag_end + 1;
                    if (findAttrValue(self.sheet_xml[lt .. tag_end + 1], "r:id")) |rid| {
                        return rid;
                    }
                    continue;
                }
            }
            self.cursor = lt + 1;
        }
        return null;
    }

    /// Bounded `skipNonElement`: the index past a comment / CDATA /
    /// PI construct starting at `lt`, `lt` itself for real markup,
    /// or null when the construct is unterminated (the block is
    /// malformed — stop iterating rather than resume mid-comment).
    fn skipDecoy(self: *const TablePartRidIterator, lt: usize) ?usize {
        const skip = workbook_xml_mod.skipNonElement(self.sheet_xml, lt) catch return null;
        return skip;
    }
};

/// Find the value of `r:id` on the worksheet's `<legacyDrawing>`
/// element (always self-closing, at most one per sheet). Returns
/// null when the element isn't present. The xdr-side `<drawing>`
/// element has its own finder; the two are distinct elements and
/// must not match each other.
fn findWorksheetLegacyDrawingRid(sheet_xml: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i < sheet_xml.len) {
        const lt = std.mem.indexOfScalarPos(u8, sheet_xml, i, '<') orelse return null;
        const need = "<legacyDrawing".len;
        if (lt + need >= sheet_xml.len) return null;
        if (std.mem.eql(u8, sheet_xml[lt .. lt + need], "<legacyDrawing")) {
            const after_byte = sheet_xml[lt + need];
            if (after_byte == ' ' or after_byte == '\t' or after_byte == '\r' or
                after_byte == '\n' or after_byte == '/' or after_byte == '>')
            {
                const tag_end = std.mem.indexOfScalarPos(u8, sheet_xml, lt, '>') orelse return null;
                return findAttrValue(sheet_xml[lt .. tag_end + 1], "r:id");
            }
        }
        i = lt + 1;
    }
    return null;
}

/// Find the value of `r:id` on the worksheet's CT_Worksheet
/// `<drawing>` element (always self-closing, at most one per
/// sheet). Disambiguates from `<legacyDrawing>` and namespace-
/// prefixed siblings. Returns null when absent.
fn findWorksheetDrawingRid(sheet_xml: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i < sheet_xml.len) {
        const lt = std.mem.indexOfScalarPos(u8, sheet_xml, i, '<') orelse return null;
        const need = "<drawing".len;
        // `>=`: when sheet_xml ends exactly at `<drawing` we'd
        // otherwise read one byte past the slice. Found by Codex
        // review (REL-601 P2).
        if (lt + need >= sheet_xml.len) return null;
        if (std.mem.eql(u8, sheet_xml[lt .. lt + need], "<drawing")) {
            const after_byte = sheet_xml[lt + need];
            if (after_byte == ' ' or after_byte == '\t' or after_byte == '\r' or
                after_byte == '\n' or after_byte == '/' or after_byte == '>')
            {
                const tag_end = std.mem.indexOfScalarPos(u8, sheet_xml, lt, '>') orelse return null;
                return findAttrValue(sheet_xml[lt .. tag_end + 1], "r:id");
            }
        }
        i = lt + 1;
    }
    return null;
}

/// Look up the `target` of a Relationship by `id`. Returns null
/// if no relationship matches.
fn relTargetForId(rels: []const store_mod.Relationship, id: []const u8) ?[]const u8 {
    for (rels) |r| {
        if (std.mem.eql(u8, r.id, id)) return r.target;
    }
    return null;
}

/// Read the value of `attr_name` (e.g. `r:id`) from a single
/// element's bytes. Tolerates single or double quotes AND
/// XML 1.0 §3.1 `Eq` whitespace on both sides of `=` (per
/// Codex review REL-602 + REL-604). Returns null when absent.
fn findAttrValue(element_bytes: []const u8, attr_name: []const u8) ?[]const u8 {
    var i: usize = 0;
    while (i < element_bytes.len) {
        const eq = std.mem.indexOfScalarPos(u8, element_bytes, i, '=') orelse return null;
        // Walk backward across XML whitespace to find the end of
        // the attribute name (XML allows `name = "value"`).
        var name_end = eq;
        while (name_end > 0) {
            const ch = element_bytes[name_end - 1];
            if (ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r') {
                name_end -= 1;
                continue;
            }
            break;
        }
        if (name_end < attr_name.len) {
            i = eq + 1;
            continue;
        }
        const name_start = name_end - attr_name.len;
        if (std.mem.eql(u8, element_bytes[name_start..name_end], attr_name)) {
            // Confirm the byte before the name is whitespace or
            // `<` (otherwise this is a longer attr like
            // `xr:id`, `customxr:id`, etc.).
            if (name_start == 0 or
                element_bytes[name_start - 1] == ' ' or
                element_bytes[name_start - 1] == '\t' or
                element_bytes[name_start - 1] == '\n' or
                element_bytes[name_start - 1] == '\r' or
                element_bytes[name_start - 1] == '<')
            {
                // Skip XML whitespace between `=` and the quote.
                var quote_pos = eq + 1;
                while (quote_pos < element_bytes.len) {
                    const ch = element_bytes[quote_pos];
                    if (ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r') {
                        quote_pos += 1;
                        continue;
                    }
                    break;
                }
                if (quote_pos >= element_bytes.len) return null;
                const quote = element_bytes[quote_pos];
                if (quote != '"' and quote != '\'') return null;
                const value_start = quote_pos + 1;
                const value_end = std.mem.indexOfScalarPos(u8, element_bytes, value_start, quote) orelse return null;
                return element_bytes[value_start..value_end];
            }
        }
        i = eq + 1;
    }
    return null;
}

/// Validate a candidate sheet name per Excel's rules. B3 iter-wr-6
/// delegates to `zlsx.validateSheetName` (the Writer-side
/// Unicode-scalar-aware validator at `src/writer.zig`):
///   - 1..31 Unicode SCALARS (Excel's actual limit)
///   - no 0x00..0x1F control bytes
///   - none of `: \ / ? * [ ]`
///   - no leading or trailing apostrophe
///   - Unicode case-fold compare not equal to "History"
///
/// Workbook's `Error` surface is unchanged — both validators
/// surface the same `error.InvalidSheetName` token.
fn validateSheetName(name: []const u8) Error!void {
    zlsx.validateSheetName(name) catch return error.InvalidSheetName;
}

/// Lowercase-ASCII byte-equality. Non-ASCII bytes compare verbatim.
/// Documented limitation in `Workbook.renameSheet`.
fn asciiCaseInsensitiveEql(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |x, y| {
        const xl: u8 = if (x >= 'A' and x <= 'Z') x + 32 else x;
        const yl: u8 = if (y >= 'A' and y <= 'Z') y + 32 else y;
        if (xl != yl) return false;
    }
    return true;
}

/// Walk the source `xl/workbook.xml` bytes, find the Nth `<sheet>`
/// element (1-based N == `sheet_idx + 1` since OOXML emits sheets in
/// document order), and rewrite its `name="..."` attribute to the
/// XML-escaped `new_name`. Re-emits the part via `store.replacePart`.
///
/// We match the specific element by index AND verify that its current
/// `name=` attribute equals `expected_old` — this is the pair
/// assertion: independent of whether `xl/workbook.xml` was emitted by
/// an external tool with surprising attribute ordering, we refuse to
/// rewrite an element whose old name doesn't match what we believe it
/// should be (`SheetElementNotFound`).
fn patchWorkbookXmlSheetName(
    self: *Workbook,
    sheet_idx: u32,
    expected_old: []const u8,
    new_name: []const u8,
) Error!void {
    assert(expected_old.len > 0);
    assert(new_name.len > 0);
    assert(sheet_idx < self.workbook.sheets.len);

    const part = try self.store.part("xl/workbook.xml") orelse return error.MissingWorkbookPart;
    const src = part.bytes;
    assert(src.len > 0);

    // Find the Nth `<sheet ` (note the trailing space — distinguishes
    // from `<sheets>`, `<sheetData>`, etc.) Also accept `<sheet/>`-
    // style self-close as a defensive fallback. We require an
    // attribute-bearing form for a name to be present, so primarily
    // match `<sheet ` and `<sheet\t` / `<sheet\n`.
    var search_from: usize = 0;
    var seen: u32 = 0;
    var elem_attrs_start: usize = 0;
    var elem_attrs_end: usize = 0;
    while (true) {
        const open = std.mem.indexOfPos(u8, src, search_from, "<sheet") orelse
            return error.SheetElementNotFound;
        const after = open + "<sheet".len;
        if (after >= src.len) return error.SheetElementNotFound;
        const boundary = src[after];
        // Distinguish `<sheet[ /\t\r\n]` from `<sheets`, `<sheetData`,
        // `<sheetView`, `<sheetFormatPr`, `<sheetPr`, `<sheetCalcPr`,
        // `<sheetProtection` and friends.
        const is_sheet_elem = switch (boundary) {
            ' ', '\t', '\r', '\n', '/' => true,
            else => false,
        };
        if (!is_sheet_elem) {
            search_from = after;
            continue;
        }
        // Find the closing `>` that terminates this open tag. Sheet
        // elements are leaves (`<sheet ... />` or `<sheet ...></sheet>`
        // with empty body); we just need the first `>` past `after`.
        const gt = std.mem.indexOfScalarPos(u8, src, after, '>') orelse
            return error.SheetElementNotFound;
        if (seen == sheet_idx) {
            elem_attrs_start = after;
            elem_attrs_end = if (gt > 0 and src[gt - 1] == '/') gt - 1 else gt;
            break;
        }
        seen += 1;
        search_from = gt + 1;
    }
    assert(elem_attrs_end >= elem_attrs_start);

    // Find `name="..."` (or `name='...'`) inside this element's
    // attribute span. Must be a real attribute, not a substring of
    // another attribute's value: we anchor on a preceding whitespace
    // OR the start of the attribute span.
    const attrs = src[elem_attrs_start..elem_attrs_end];
    const NameAttr = struct { value_start: usize, value_end: usize };
    const found: NameAttr = blk: {
        var i: usize = 0;
        while (i < attrs.len) {
            // Skip leading whitespace.
            while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
                attrs[i] == '\r' or attrs[i] == '\n')) : (i += 1)
            {}
            if (i >= attrs.len) break;
            const key_start = i;
            while (i < attrs.len and attrs[i] != '=' and attrs[i] != ' ' and
                attrs[i] != '\t' and attrs[i] != '\r' and attrs[i] != '\n') : (i += 1)
            {}
            const key_end = i;
            // Skip = and any padding.
            while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
                attrs[i] == '\r' or attrs[i] == '\n')) : (i += 1)
            {}
            if (i >= attrs.len or attrs[i] != '=') return error.SheetElementNotFound;
            i += 1;
            while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
                attrs[i] == '\r' or attrs[i] == '\n')) : (i += 1)
            {}
            if (i >= attrs.len) return error.SheetElementNotFound;
            const quote = attrs[i];
            if (quote != '"' and quote != '\'') return error.SheetElementNotFound;
            i += 1;
            const val_start = i;
            while (i < attrs.len and attrs[i] != quote) : (i += 1) {}
            if (i >= attrs.len) return error.SheetElementNotFound;
            const val_end = i;
            i += 1; // past closing quote

            const key = attrs[key_start..key_end];
            if (std.mem.eql(u8, key, "name")) {
                break :blk .{
                    .value_start = elem_attrs_start + val_start,
                    .value_end = elem_attrs_start + val_end,
                };
            }
        }
        return error.SheetElementNotFound;
    };

    // Pair assertion: the element we found really IS the one we
    // intend to rewrite. The current name (still XML-escaped on the
    // wire — but for unescaped ASCII names like "Sheet1" the byte
    // comparison is correct) must match `expected_old`.
    if (!std.mem.eql(u8, src[found.value_start..found.value_end], expected_old)) {
        // Tolerate XML-escaped equivalents: if a name contains `&` or
        // `<` we'd see entities here; for ASCII-clean names this is
        // straight equality. If the wire form differs, it's not the
        // element we expected to rewrite.
        return error.SheetElementNotFound;
    }

    // Build the patched part: prefix + escaped new name + suffix.
    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(self.allocator);
    try out.ensureTotalCapacity(self.allocator, src.len + new_name.len + 16);
    try out.appendSlice(self.allocator, src[0..found.value_start]);
    try appendXmlEscaped(self.allocator, &out, new_name);
    try out.appendSlice(self.allocator, src[found.value_end..]);

    try self.store.replacePart("xl/workbook.xml", out.items);
}

/// Append `s` to `out`, XML-escaping the five canonical entities
/// (`<`, `>`, `&`, `"`, `'`). Other bytes (including UTF-8
/// continuation bytes for non-ASCII characters) pass through verbatim.
/// B3 iter-wr-6 NOTE: kept local rather than forwarded to
/// `pkg/sheet_plan.zig::appendXmlEscaped`. The plan-side variant
/// rejects XML 1.0 forbidden control bytes with `error.InvalidXmlByte`;
/// Workbook's `Error` set deliberately omits that variant (one-minor
/// API freeze on Workbook's public Error surface), and Workbook's
/// callers pre-validate text via `isXmlSafeText` so a forbidden byte
/// would already be a contract violation. To stay byte-equivalent
/// without widening `Error`, this 5-entity escape stays inline.
/// Producers: sheet-name patch, definedName + sheet-rels emit.
fn appendXmlEscaped(allocator: Allocator, out: *std.ArrayList(u8), s: []const u8) !void {
    for (s) |c| switch (c) {
        '<' => try out.appendSlice(allocator, "&lt;"),
        '>' => try out.appendSlice(allocator, "&gt;"),
        '&' => try out.appendSlice(allocator, "&amp;"),
        '"' => try out.appendSlice(allocator, "&quot;"),
        '\'' => try out.appendSlice(allocator, "&apos;"),
        else => try out.append(allocator, c),
    };
}

/// Re-parse `xl/workbook.xml` from the (now-patched) PartStore bytes
/// and swap the typed view in place. The old view's arena is freed —
/// any external borrows of `wb.workbook.sheets[i].name` from before
/// `renameSheet` are invalidated. The contract says callers don't
/// hold those slices across mutation; this is the enforcement point.
// ─── B2 iter-er-4 addSheet helpers ────────────────────────────────────

/// Case-insensitive ASCII compare with on-the-fly XML entity
/// decoding of `view_name`. Used by `Workbook.addSheet` to detect
/// duplicates where the workbook view holds the encoded form
/// (`R&amp;D`) and the input is the decoded form (`R&D`). Direct
/// byte-equality first as a fast path; only decodes when
/// `view_name` contains an `&`.
fn sheetNameMatchesDecoded(allocator: Allocator, view_name: []const u8, input: []const u8) Error!bool {
    if (asciiCaseInsensitiveEql(view_name, input)) return true;
    if (std.mem.indexOfScalar(u8, view_name, '&') == null) return false;

    var decoded: std.ArrayList(u8) = .empty;
    defer decoded.deinit(allocator);
    try decoded.ensureTotalCapacity(allocator, view_name.len);
    var i: usize = 0;
    while (i < view_name.len) {
        if (view_name[i] != '&') {
            try decoded.append(allocator, view_name[i]);
            i += 1;
            continue;
        }
        const semi = std.mem.indexOfScalarPos(u8, view_name, i, ';') orelse {
            try decoded.append(allocator, view_name[i]);
            i += 1;
            continue;
        };
        const ent = view_name[i + 1 .. semi];
        const replaced: ?u8 =
            if (std.mem.eql(u8, ent, "amp")) @as(u8, '&') else if (std.mem.eql(u8, ent, "lt")) @as(u8, '<') else if (std.mem.eql(u8, ent, "gt")) @as(u8, '>') else if (std.mem.eql(u8, ent, "quot")) @as(u8, '"') else if (std.mem.eql(u8, ent, "apos")) @as(u8, '\'') else null;
        if (replaced) |c| {
            try decoded.append(allocator, c);
            i = semi + 1;
        } else {
            // Unknown entity — pass `&` through and keep scanning.
            try decoded.append(allocator, view_name[i]);
            i += 1;
        }
    }
    return asciiCaseInsensitiveEql(decoded.items, input);
}

/// Scan `xml` for the largest `attr_prefixN"` numeric value (e.g.
/// `sheetId="3"` or `Id="rId7"`). Returns 0 when no match is found.
/// Used by `Workbook.addSheet` to pick non-colliding ids when
/// multiple addSheet calls land before the next save.
fn nextMaxNumericAttr(xml: []const u8, attr_prefix: []const u8) u32 {
    var max_id: u32 = 0;
    var i: usize = 0;
    while (std.mem.indexOfPos(u8, xml, i, attr_prefix)) |pos| {
        const num_start = pos + attr_prefix.len;
        var num_end = num_start;
        while (num_end < xml.len and xml[num_end] >= '0' and xml[num_end] <= '9') : (num_end += 1) {}
        if (num_end > num_start) {
            if (std.fmt.parseInt(u32, xml[num_start..num_end], 10)) |n| {
                if (n > max_id) max_id = n;
            } else |_| {}
        }
        i = num_end + 1;
    }
    return max_id;
}

/// Highest `xl/worksheets/sheetN.xml` part name in the part store
/// (including orphan parts left behind by `Workbook.deleteSheet`).
/// Returns 0 when no such part exists. Used to pick a non-colliding
/// path number for `Workbook.addSheet` even when prior delete +
/// add cycles have already consumed slots.
fn nextMaxSheetPathNumFromStore(store: *const store_mod.PartStore) Error!u32 {
    const names = try store.partNames();
    var max_n: u32 = 0;
    const prefix = "xl/worksheets/sheet";
    const suffix = ".xml";
    for (names) |name| {
        if (!std.mem.startsWith(u8, name, prefix)) continue;
        if (!std.mem.endsWith(u8, name, suffix)) continue;
        const num_str = name[prefix.len .. name.len - suffix.len];
        if (num_str.len == 0) continue;
        if (std.fmt.parseInt(u32, num_str, 10)) |n| {
            if (n > max_n) max_n = n;
        } else |_| {}
    }
    return max_n;
}

/// Highest `worksheets/sheetN.xml` number referenced by a
/// `Target="…"` attribute in the workbook rels XML. Returns 0 when
/// no such target exists. Robust against absolute (`/xl/worksheets/`)
/// and relative (`worksheets/`) prefixes — both decode to the same
/// number. Kept for potential future callers; `Workbook.addSheet`
/// uses `nextMaxSheetPathNumFromStore` instead so orphan parts
/// don't collide.
fn nextMaxSheetPathNumFromRels(xml: []const u8) u32 {
    var max_n: u32 = 0;
    const needle = "sheet";
    var i: usize = 0;
    while (std.mem.indexOfPos(u8, xml, i, needle)) |pos| {
        const num_start = pos + needle.len;
        var num_end = num_start;
        while (num_end < xml.len and xml[num_end] >= '0' and xml[num_end] <= '9') : (num_end += 1) {}
        if (num_end > num_start and num_end + 4 <= xml.len and
            std.mem.eql(u8, xml[num_end .. num_end + 4], ".xml"))
        {
            // Pre-context check: only count when this `sheetN.xml`
            // is preceded by `worksheets/` somewhere in the same
            // attribute span — strips out drawings, comments,
            // pivots, etc.
            const ctx_start = if (pos >= 24) pos - 24 else 0;
            if (std.mem.lastIndexOf(u8, xml[ctx_start..pos], "worksheets/") != null) {
                if (std.fmt.parseInt(u32, xml[num_start..num_end], 10)) |n| {
                    if (n > max_n) max_n = n;
                } else |_| {}
            }
        }
        i = num_end + 1;
    }
    return max_n;
}

/// Splice a new `<Relationship/>` for a worksheet into
/// `xl/_rels/workbook.xml.rels` immediately before `</Relationships>`.
/// Caller frees the returned slice.
fn patchWorkbookRelsAddSheet(
    allocator: Allocator,
    xml: []const u8,
    rid: []const u8,
    full_path: []const u8,
) Error![]u8 {
    const close = std.mem.indexOf(u8, xml, "</Relationships>") orelse return error.MalformedWorkbookRels;
    // Target is relative to xl/_rels/, so strip the "xl/" prefix
    // from `full_path`. e.g. "xl/worksheets/sheet5.xml" →
    // "worksheets/sheet5.xml".
    const target = if (std.mem.startsWith(u8, full_path, "xl/")) full_path[3..] else full_path;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, xml.len + 256);
    try out.appendSlice(allocator, xml[0..close]);
    try out.appendSlice(allocator, "<Relationship Id=\"");
    try out.appendSlice(allocator, rid);
    try out.appendSlice(allocator, "\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"");
    try out.appendSlice(allocator, target);
    try out.appendSlice(allocator, "\"/>");
    try out.appendSlice(allocator, xml[close..]);
    return try out.toOwnedSlice(allocator);
}

/// emb-3b: Splice a `<Relationship/>` for the zlsxEmbeddings index
/// into `xl/_rels/workbook.xml.rels` immediately before
/// `</Relationships>`. Target is `zlsxEmbeddings/index.xml`
/// (relative to `xl/`, the base implied by the rels-file location).
/// Caller frees the returned slice.
fn patchWorkbookRelsAddEmbeddings(
    allocator: Allocator,
    xml: []const u8,
    rid: []const u8,
) Error![]u8 {
    const close = std.mem.indexOf(u8, xml, "</Relationships>") orelse return error.MalformedWorkbookRels;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, xml.len + 256);
    try out.appendSlice(allocator, xml[0..close]);
    try out.appendSlice(allocator, "<Relationship Id=\"");
    try out.appendSlice(allocator, rid);
    try out.appendSlice(allocator, "\" Type=\"");
    try out.appendSlice(allocator, embedding_part.REL_TYPE_EMBEDDINGS);
    try out.appendSlice(allocator, "\" Target=\"zlsxEmbeddings/index.xml\"/>");
    try out.appendSlice(allocator, xml[close..]);
    return try out.toOwnedSlice(allocator);
}

/// Splice a new `<sheet/>` line into `xl/workbook.xml` immediately
/// before `</sheets>`. Caller frees the returned slice. The display
/// name is XML-attribute-escaped; sheet_id and rid are emitted
/// verbatim (caller-controlled identifiers).
fn patchWorkbookXmlAddSheet(
    allocator: Allocator,
    xml: []const u8,
    name: []const u8,
    sheet_id: u32,
    rid: []const u8,
) Error![]u8 {
    const close = std.mem.indexOf(u8, xml, "</sheets>") orelse return error.MalformedXml;
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, xml.len + 256);
    try out.appendSlice(allocator, xml[0..close]);
    try out.appendSlice(allocator, "<sheet name=\"");
    try appendXmlAttrEscapedW(allocator, &out, name);
    var num_buf: [16]u8 = undefined;
    try out.appendSlice(allocator, "\" sheetId=\"");
    try out.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{sheet_id}));
    try out.appendSlice(allocator, "\" r:id=\"");
    try out.appendSlice(allocator, rid);
    try out.appendSlice(allocator, "\"/>");
    try out.appendSlice(allocator, xml[close..]);
    return try out.toOwnedSlice(allocator);
}

/// XML attribute-context escape: `<`, `>`, `&`, `"` → entity refs.
/// Use when emitting into a double-quoted attribute value.
fn appendXmlAttrEscapedW(allocator: Allocator, out: *std.ArrayList(u8), s: []const u8) Error!void {
    for (s) |c| {
        switch (c) {
            '&' => try out.appendSlice(allocator, "&amp;"),
            '<' => try out.appendSlice(allocator, "&lt;"),
            '>' => try out.appendSlice(allocator, "&gt;"),
            '"' => try out.appendSlice(allocator, "&quot;"),
            else => try out.append(allocator, c),
        }
    }
}

fn refreshWorkbookXmlView(self: *Workbook) Error!void {
    const part = try self.store.part("xl/workbook.xml") orelse return error.MissingWorkbookPart;
    var fresh = try workbook_xml_mod.parse(self.allocator, part.bytes);
    errdefer fresh.deinit(self.allocator);

    // Length invariant: re-parse must agree on sheet count, otherwise
    // the slot table (worksheets[]) and the workbook view would drift.
    if (fresh.sheets.len != self.workbook.sheets.len) {
        return error.SheetCountMismatch;
    }

    self.workbook.deinit(self.allocator);
    self.workbook = fresh;
}

// ─── deleteSheet patch helpers ────────────────────────────────────────

/// Walk the source `xl/workbook.xml` bytes, find the Nth `<sheet>`
/// element (1-based N == `sheet_idx + 1`), and splice it out — along
/// with any leading whitespace inside `<sheets>` so the result
/// remains visually stable. Re-emits the part via `replacePart`.
fn patchWorkbookXmlRemoveSheet(self: *Workbook, sheet_idx: u32) Error!void {
    assert(sheet_idx < self.workbook.sheets.len);

    const part = try self.store.part("xl/workbook.xml") orelse return error.MissingWorkbookPart;
    const src = part.bytes;
    assert(src.len > 0);

    var search_from: usize = 0;
    var seen: u32 = 0;
    var elem_open: usize = 0;
    var elem_close: usize = 0;
    while (true) {
        const open = std.mem.indexOfPos(u8, src, search_from, "<sheet") orelse
            return error.SheetElementNotFound;
        const after = open + "<sheet".len;
        if (after >= src.len) return error.SheetElementNotFound;
        const boundary = src[after];
        const is_sheet_elem = switch (boundary) {
            ' ', '\t', '\r', '\n', '/' => true,
            else => false,
        };
        if (!is_sheet_elem) {
            search_from = after;
            continue;
        }
        const gt = std.mem.indexOfScalarPos(u8, src, after, '>') orelse
            return error.SheetElementNotFound;
        if (seen == sheet_idx) {
            elem_open = open;
            // Self-closing form ends at `/>`; otherwise consume the
            // matching `</sheet>`. OOXML emits `<sheet/>` in practice
            // but tolerate the long form.
            if (gt > 0 and src[gt - 1] == '/') {
                elem_close = gt + 1;
            } else {
                const end_tag = std.mem.indexOfPos(u8, src, gt + 1, "</sheet>") orelse
                    return error.SheetElementNotFound;
                elem_close = end_tag + "</sheet>".len;
            }
            break;
        }
        seen += 1;
        search_from = gt + 1;
    }
    assert(elem_close > elem_open);

    var trim_start = elem_open;
    while (trim_start > 0) {
        const c = src[trim_start - 1];
        if (c == ' ' or c == '\t' or c == '\r' or c == '\n') {
            trim_start -= 1;
        } else break;
    }

    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(self.allocator);
    try out.ensureTotalCapacity(self.allocator, src.len);
    try out.appendSlice(self.allocator, src[0..trim_start]);
    try out.appendSlice(self.allocator, src[elem_close..]);

    try self.store.replacePart("xl/workbook.xml", out.items);
}

/// Walk `xl/_rels/workbook.xml.rels` and elide the
/// `<Relationship Id="rIdN" .../>` whose `Id` matches `r_id`.
fn patchWorkbookRelsRemoveRelationship(self: *Workbook, r_id: []const u8) Error!void {
    assert(r_id.len > 0);

    const part = try self.store.part("xl/_rels/workbook.xml.rels") orelse
        return error.MissingWorkbookRels;
    const src = part.bytes;
    assert(src.len > 0);

    var search_from: usize = 0;
    var elem_open: usize = 0;
    var elem_close: usize = 0;
    var found: bool = false;
    while (true) {
        const open = std.mem.indexOfPos(u8, src, search_from, "<Relationship") orelse break;
        const after = open + "<Relationship".len;
        if (after >= src.len) break;
        const boundary = src[after];
        const is_rel_elem = switch (boundary) {
            ' ', '\t', '\r', '\n', '/' => true,
            else => false,
        };
        if (!is_rel_elem) {
            // `<Relationships>` (the wrapper) is the only collision.
            search_from = after;
            continue;
        }
        const gt = std.mem.indexOfScalarPos(u8, src, after, '>') orelse break;
        const this_close = blk: {
            if (gt > 0 and src[gt - 1] == '/') break :blk gt + 1;
            const end_tag = std.mem.indexOfPos(u8, src, gt + 1, "</Relationship>") orelse
                return error.RelationshipElementNotFound;
            break :blk end_tag + "</Relationship>".len;
        };

        const attrs_end = if (gt > 0 and src[gt - 1] == '/') gt - 1 else gt;
        const attrs = src[after..attrs_end];
        if (attrIdEquals(attrs, r_id)) {
            elem_open = open;
            elem_close = this_close;
            found = true;
            break;
        }
        search_from = this_close;
    }
    if (!found) return error.RelationshipElementNotFound;
    assert(elem_close > elem_open);

    var trim_start = elem_open;
    while (trim_start > 0) {
        const c = src[trim_start - 1];
        if (c == ' ' or c == '\t' or c == '\r' or c == '\n') {
            trim_start -= 1;
        } else break;
    }

    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(self.allocator);
    try out.ensureTotalCapacity(self.allocator, src.len);
    try out.appendSlice(self.allocator, src[0..trim_start]);
    try out.appendSlice(self.allocator, src[elem_close..]);

    try self.store.replacePart("xl/_rels/workbook.xml.rels", out.items);
}

/// Walk `[Content_Types].xml` and elide the
/// `<Override PartName="/<part_name>" .../>` whose PartName matches
/// `/<part_name>` (OOXML stores PartNames with a leading slash).
/// Returns `error.ContentTypesOverrideNotFound` when no matching
/// Override exists; the caller (deleteSheet) treats that as soft-OK.
fn patchContentTypesRemoveOverride(self: *Workbook, part_name: []const u8) Error!void {
    assert(part_name.len > 0);

    const part = try self.store.part("[Content_Types].xml") orelse
        return error.ContentTypesOverrideNotFound;
    const src = part.bytes;
    assert(src.len > 0);

    if (part_name.len > 255) return error.ContentTypesOverrideNotFound;
    var pn_buf: [256]u8 = undefined;
    pn_buf[0] = '/';
    @memcpy(pn_buf[1 .. 1 + part_name.len], part_name);
    const target = pn_buf[0 .. 1 + part_name.len];

    var search_from: usize = 0;
    var elem_open: usize = 0;
    var elem_close: usize = 0;
    var found: bool = false;
    while (true) {
        const open = std.mem.indexOfPos(u8, src, search_from, "<Override") orelse break;
        const after = open + "<Override".len;
        if (after >= src.len) break;
        const boundary = src[after];
        const is_override_elem = switch (boundary) {
            ' ', '\t', '\r', '\n', '/' => true,
            else => false,
        };
        if (!is_override_elem) {
            search_from = after;
            continue;
        }
        const gt = std.mem.indexOfScalarPos(u8, src, after, '>') orelse break;
        const this_close = gt + 1;

        const attrs_end = if (gt > 0 and src[gt - 1] == '/') gt - 1 else gt;
        const attrs = src[after..attrs_end];
        if (attrPartNameEquals(attrs, target)) {
            elem_open = open;
            elem_close = this_close;
            found = true;
            break;
        }
        search_from = this_close;
    }
    if (!found) return error.ContentTypesOverrideNotFound;
    assert(elem_close > elem_open);

    var trim_start = elem_open;
    while (trim_start > 0) {
        const c = src[trim_start - 1];
        if (c == ' ' or c == '\t' or c == '\r' or c == '\n') {
            trim_start -= 1;
        } else break;
    }

    var out: std.ArrayList(u8) = .empty;
    defer out.deinit(self.allocator);
    try out.ensureTotalCapacity(self.allocator, src.len);
    try out.appendSlice(self.allocator, src[0..trim_start]);
    try out.appendSlice(self.allocator, src[elem_close..]);

    try self.store.replacePart("[Content_Types].xml", out.items);
}

fn attrIdEquals(attrs: []const u8, value: []const u8) bool {
    return attrEquals(attrs, "Id", value);
}

fn attrPartNameEquals(attrs: []const u8, value: []const u8) bool {
    return attrEquals(attrs, "PartName", value);
}

/// Generic attribute byte-compare. Walks `attrs` token-by-token (same
/// shape as `patchWorkbookXmlSheetName`'s inline parser) and returns
/// `true` iff some attribute named `key` has a quoted value byte-
/// equal to `value`.
fn attrEquals(attrs: []const u8, key: []const u8, value: []const u8) bool {
    var i: usize = 0;
    while (i < attrs.len) {
        while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
            attrs[i] == '\r' or attrs[i] == '\n')) : (i += 1)
        {}
        if (i >= attrs.len) return false;
        const key_start = i;
        while (i < attrs.len and attrs[i] != '=' and attrs[i] != ' ' and
            attrs[i] != '\t' and attrs[i] != '\r' and attrs[i] != '\n') : (i += 1)
        {}
        const key_end = i;
        while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
            attrs[i] == '\r' or attrs[i] == '\n')) : (i += 1)
        {}
        if (i >= attrs.len or attrs[i] != '=') return false;
        i += 1;
        while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
            attrs[i] == '\r' or attrs[i] == '\n')) : (i += 1)
        {}
        if (i >= attrs.len) return false;
        const quote = attrs[i];
        if (quote != '"' and quote != '\'') return false;
        i += 1;
        const val_start = i;
        while (i < attrs.len and attrs[i] != quote) : (i += 1) {}
        if (i >= attrs.len) return false;
        const val_end = i;
        i += 1;

        if (std.mem.eql(u8, attrs[key_start..key_end], key) and
            std.mem.eql(u8, attrs[val_start..val_end], value))
        {
            return true;
        }
    }
    return false;
}

// ─── Emit helpers (iter-wb-4 m1) ─────────────────────────────────────

/// Splice a regenerated `<sheetData>...</sheetData>` block into the
/// source sheet XML. Everything outside `<sheetData>` is copied
/// byte-for-byte. Returns a fresh allocator-owned slice.
fn emitSheetWithDeltas(
    allocator: Allocator,
    source: []const u8,
    view: *const sheet_xml_mod.SheetXml,
    deltas: *const std.AutoHashMapUnmanaged(CellRef, CellValue),
    sst_plan: *const SstExtensionPlan,
) Error![]u8 {
    assert(source.len > 0);

    const sd_idx = std.mem.indexOf(u8, source, "<sheetData") orelse
        return error.NoSheetData;
    const open_gt = std.mem.indexOfScalarPos(u8, source, sd_idx, '>') orelse
        return error.NoSheetData;
    const is_self_closing = open_gt > 0 and source[open_gt - 1] == '/';

    var prefix_end: usize = undefined;
    var suffix_start: usize = undefined;
    if (is_self_closing) {
        prefix_end = sd_idx; // we re-emit `<sheetData>` ourselves
        suffix_start = open_gt + 1;
    } else {
        prefix_end = open_gt + 1;
        suffix_start = std.mem.indexOfPos(u8, source, prefix_end, "</sheetData>") orelse
            return error.NoSheetData;
    }

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, source.len + 1024);

    try out.appendSlice(allocator, source[0..prefix_end]);
    if (is_self_closing) try out.appendSlice(allocator, "<sheetData>");

    try emitSheetData(allocator, &out, view, deltas, sst_plan);

    if (is_self_closing) try out.appendSlice(allocator, "</sheetData>");
    try out.appendSlice(allocator, source[suffix_start..]);

    return try out.toOwnedSlice(allocator);
}

const MergedCell = struct {
    ref: CellRef,
    style_idx: ?u32,
    payload: union(enum) {
        original: struct {
            cell_type: sheet_xml_mod.CellType,
            raw_value: ?[]const u8,
            formula: ?[]const u8,
        },
        delta: CellValue,
    },
};

fn mergedLessThan(_: void, a: MergedCell, b: MergedCell) bool {
    if (a.ref.row != b.ref.row) return a.ref.row < b.ref.row;
    return a.ref.col < b.ref.col;
}

fn emitSheetData(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    view: *const sheet_xml_mod.SheetXml,
    deltas: *const std.AutoHashMapUnmanaged(CellRef, CellValue),
    sst_plan: *const SstExtensionPlan,
) Error!void {
    // 1. Collect existing cells (override with delta if matching).
    var merged: std.ArrayList(MergedCell) = .empty;
    defer merged.deinit(allocator);

    var seen: std.AutoHashMapUnmanaged(CellRef, void) = .{};
    defer seen.deinit(allocator);

    for (view.rows) |row| {
        for (row.cells) |c| {
            const cr = parseA1Ref(c.ref) catch continue;
            const overlay = deltas.get(cr);
            // `.deleted` overrides the original — emit nothing for
            // this ref. Still mark `seen` so the delta-only pass
            // below doesn't re-introduce it.
            if (overlay) |dv| if (dv == .deleted) {
                try seen.put(allocator, cr, {});
                continue;
            };
            const mc: MergedCell = if (overlay) |dv| .{
                .ref = cr,
                .style_idx = c.style_idx,
                .payload = .{ .delta = dv },
            } else .{
                .ref = cr,
                .style_idx = c.style_idx,
                .payload = .{ .original = .{
                    .cell_type = c.cell_type,
                    .raw_value = c.raw_value,
                    .formula = c.formula,
                } },
            };
            try merged.append(allocator, mc);
            try seen.put(allocator, cr, {});
        }
    }

    // 2. Append delta-only cells (not matched to any existing cell).
    // `.deleted` deltas with no matching original are a no-op — there
    // is nothing to elide, so we skip rather than emit a phantom cell.
    var dit = deltas.iterator();
    while (dit.next()) |entry| {
        if (seen.contains(entry.key_ptr.*)) continue;
        if (entry.value_ptr.* == .deleted) continue;
        try merged.append(allocator, .{
            .ref = entry.key_ptr.*,
            .style_idx = null,
            .payload = .{ .delta = entry.value_ptr.* },
        });
    }

    // 3. Sort by (row, col) and group emit.
    std.sort.pdq(MergedCell, merged.items, {}, mergedLessThan);

    var i: usize = 0;
    var num_buf: [32]u8 = undefined;
    while (i < merged.items.len) {
        const row_idx = merged.items[i].ref.row;
        var j = i;
        while (j < merged.items.len and merged.items[j].ref.row == row_idx) : (j += 1) {}

        // <row r="N">
        try out.appendSlice(allocator, "<row r=\"");
        try out.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{row_idx}));
        try out.appendSlice(allocator, "\">");

        for (merged.items[i..j]) |mc| try emitCell(allocator, out, mc, sst_plan);

        try out.appendSlice(allocator, "</row>");
        i = j;
    }
}

fn emitCell(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    mc: MergedCell,
    sst_plan: *const SstExtensionPlan,
) Error!void {
    var ref_buf: [16]u8 = undefined;
    const ref_str = formatA1Ref(&ref_buf, mc.ref);

    try out.appendSlice(allocator, "<c r=\"");
    try out.appendSlice(allocator, ref_str);
    try out.appendSlice(allocator, "\"");

    if (mc.style_idx) |s| {
        var s_buf: [16]u8 = undefined;
        try out.appendSlice(allocator, " s=\"");
        try out.appendSlice(allocator, try std.fmt.bufPrint(&s_buf, "{d}", .{s}));
        try out.appendSlice(allocator, "\"");
    }

    switch (mc.payload) {
        .original => |orig| {
            if (cellTypeAttr(orig.cell_type)) |t_attr| {
                try out.appendSlice(allocator, " t=\"");
                try out.appendSlice(allocator, t_attr);
                try out.appendSlice(allocator, "\"");
            }
            if (orig.raw_value == null and orig.formula == null) {
                try out.appendSlice(allocator, "/>");
                return;
            }
            try out.appendSlice(allocator, ">");
            if (orig.formula) |f| {
                try out.appendSlice(allocator, "<f>");
                try out.appendSlice(allocator, f);
                try out.appendSlice(allocator, "</f>");
            }
            if (orig.raw_value) |v| {
                if (orig.cell_type == .inline_string) {
                    try out.appendSlice(allocator, "<is><t>");
                    try out.appendSlice(allocator, v);
                    try out.appendSlice(allocator, "</t></is>");
                } else {
                    try out.appendSlice(allocator, "<v>");
                    try out.appendSlice(allocator, v);
                    try out.appendSlice(allocator, "</v>");
                }
            }
            try out.appendSlice(allocator, "</c>");
        },
        .delta => |dv| switch (dv) {
            .blank => {
                try out.appendSlice(allocator, "/>");
            },
            .number => |n| {
                try out.appendSlice(allocator, "><v>");
                var nbuf: [64]u8 = undefined;
                try out.appendSlice(allocator, try std.fmt.bufPrint(&nbuf, "{d}", .{n}));
                try out.appendSlice(allocator, "</v></c>");
            },
            .boolean => |b| {
                try out.appendSlice(allocator, " t=\"b\"><v>");
                try out.appendSlice(allocator, if (b) "1" else "0");
                try out.appendSlice(allocator, "</v></c>");
            },
            .string => |s| {
                try out.appendSlice(allocator, " t=\"inlineStr\"><is><t");
                // Preserve leading/trailing whitespace per OOXML.
                if (s.len > 0 and (s[0] == ' ' or s[s.len - 1] == ' ')) {
                    try out.appendSlice(allocator, " xml:space=\"preserve\"");
                }
                try out.appendSlice(allocator, ">");
                try appendXmlEscapedText(allocator, out, s);
                try out.appendSlice(allocator, "</t></is></c>");
            },
            .shared_string => |s| {
                // Resolve the index assigned by the SST extension
                // pass. `getOrUnreachable` is safe here: every
                // `.shared_string` delta was registered into the
                // plan in `buildSstExtensionPlan` (precondition of
                // the save path).
                const idx = sst_plan.indexOf(s) orelse unreachable;
                try out.appendSlice(allocator, " t=\"s\"><v>");
                var ibuf: [16]u8 = undefined;
                try out.appendSlice(allocator, try std.fmt.bufPrint(&ibuf, "{d}", .{idx}));
                try out.appendSlice(allocator, "</v></c>");
            },
            .formula => |f| {
                // No cached value — Excel recalcs on open. The engine
                // exists (M5d/M6: `recalculate` / `saveWithRecalc`
                // stash computed results through the transaction), but
                // THIS path deliberately stays cache-free: a set-cell
                // edit must not imply a recalc the caller didn't ask
                // for.
                try out.appendSlice(allocator, "><f>");
                try appendXmlEscapedText(allocator, out, f);
                try out.appendSlice(allocator, "</f></c>");
            },
            // `.deleted` deltas are filtered out in `emitSheetData`
            // before they ever reach a `MergedCell` — reaching here
            // would mean the filter regressed.
            .deleted => unreachable,
        },
    }
}

// ─── SST extension (iter-wb-4 m4 + iter-wr-1 substrate move) ───────

/// Plan for extending the workbook's shared-string table with new
/// strings collected from `.shared_string` deltas across every
/// worksheet's pending mutations.
///
/// Built upfront in `buildSstExtensionPlan` BEFORE per-sheet emit so
/// each `<c t="s">` knows its target index. `applySstExtensionPlan`
/// commits the plan to the `PartStore` (replacePart on existing SST,
/// addPart + workbook.xml.rels splice when SST is absent).
///
/// De-dup policy:
///   - existing-SST entries: linear scan over decoded text. Linear was
///     chosen over a hashmap because the typical write workload stages
///     a small handful of new strings while the SST may carry
///     thousands of existing entries; building a hashmap of decoded
///     existing entries up front is more work than scanning per-new-
///     string. Stdlib-only + trivially auditable matters more than
///     constant-factor speed at typical SST sizes.
///   - already-staged new strings: O(1) hash via
///     `plan.new_strings_index` (added in iter-wr-1 to keep
///     `xlsx.Writer`'s hot writeRow loop linear in cell count rather
///     than quadratic).
///
/// The plan struct itself lives in `pkg/sst_plan.zig` so `xlsx.Writer`
/// can stage entries through the same shape without forming a module
/// cycle (workbook → zlsx → writer.zig).
const ExistingMatch = sst_plan_mod.ExistingMatch;

/// Compatibility wrapper around `SstExtensionPlan.registerNewRich` so
/// the existing in-tree tests (and any future Workbook-side caller
/// that already has a `*Workbook` in scope) keep their call site
/// unchanged. Pure delegate — see `pkg/sst_plan.zig` for the impl.
fn registerSharedRichString(
    wb: *Workbook,
    plan: *SstExtensionPlan,
    runs: []const RichRun,
) Error!*const RichEntry {
    assert(@intFromPtr(wb) != 0);
    assert(@intFromPtr(wb.allocator.vtable) != 0);
    return try plan.registerNewRich(wb.allocator, runs);
}

/// Walk every worksheet's `.shared_string` deltas, de-dup against
/// the existing SST (when present) and against each other, and stage
/// the resulting unique-new-strings list into a plan. The plan owns
/// duplicates of every staged string; callers free via `plan.deinit`.
/// Register a string `s` into `plan.new_strings` if it matches no
/// existing PLAIN SST entry and isn't already staged. Owns the dupe.
/// Rich entries (`is_rich_existing[i] == true`) are skipped from
/// the match loop — a new string equal to a rich entry's
/// concatenated runs still allocates a fresh `<si><t>` because the
/// reader can't resolve `t="s"` indices that point at rich `<r>`
/// blocks as plain text.
fn registerSharedString(
    wb: *Workbook,
    plan: *SstExtensionPlan,
    s: []const u8,
    decoded_existing: []const []const u8,
    is_rich_existing: []const bool,
) Error!void {
    assert(decoded_existing.len == is_rich_existing.len);
    for (decoded_existing, 0..) |de, i| {
        if (is_rich_existing[i]) continue;
        if (std.mem.eql(u8, de, s)) return;
    }
    if (plan.new_strings_index.contains(s)) return;
    const owned = try wb.allocator.dupe(u8, s);
    errdefer wb.allocator.free(owned);
    const idx: u32 = @intCast(plan.new_strings.items.len);
    try plan.new_strings.append(wb.allocator, owned);
    errdefer _ = plan.new_strings.pop();
    try plan.new_strings_index.put(wb.allocator, owned, idx);
}

/// Append an existing-match record for string `s` if an existing
/// PLAIN SST entry decodes to it and we haven't already recorded
/// it. Owns the dupe. Skips strings staged into `plan.new_strings`
/// (those resolve via the new-strings index, not the side table).
/// Rich entries are skipped — same reasoning as
/// `registerSharedString`.
fn registerExistingMatch(
    wb: *Workbook,
    plan: *SstExtensionPlan,
    s: []const u8,
    decoded_existing: []const []const u8,
    is_rich_existing: []const bool,
) Error!void {
    assert(decoded_existing.len == is_rich_existing.len);
    if (plan.new_strings_index.contains(s)) return;
    for (plan.new_strings.items) |n| {
        if (std.mem.eql(u8, n, s)) return;
    }
    for (plan.existing_matches.items) |em| {
        if (std.mem.eql(u8, em.text, s)) return;
    }
    var found_idx: u32 = std.math.maxInt(u32);
    for (decoded_existing, 0..) |de, i| {
        if (is_rich_existing[i]) continue;
        if (std.mem.eql(u8, de, s)) {
            found_idx = @intCast(i);
            break;
        }
    }
    if (found_idx == std.math.maxInt(u32)) return;
    const owned = try wb.allocator.dupe(u8, s);
    errdefer wb.allocator.free(owned);
    try plan.existing_matches.append(wb.allocator, .{ .text = owned, .index = found_idx });
}

fn buildSstExtensionPlan(wb: *Workbook) Error!SstExtensionPlan {
    assert(@intFromPtr(wb) != 0);
    assert(@intFromPtr(wb.allocator.vtable) != 0);

    var plan: SstExtensionPlan = .{};
    errdefer plan.deinit(wb.allocator);

    // Quick scan: any shared-string payload (delta `.shared_string`
    // OR appended-row `.string`)? Skips any work — and crucially,
    // skips parsing the SST — when the workbook has no string
    // mutations pending across either axis.
    var any: bool = false;
    for (wb.worksheets) |*ws| {
        var it = ws.deltas.valueIterator();
        while (it.next()) |v| switch (v.*) {
            .shared_string => {
                any = true;
                break;
            },
            else => {},
        };
        if (any) break;
        for (ws.appended_rows.items) |row| {
            for (row) |c| switch (c) {
                .string => {
                    any = true;
                    break;
                },
                else => {},
            };
            if (any) break;
        }
        if (any) break;
    }
    if (!any) return plan;

    // Resolve the existing SST's plain-entry count + decoded-text
    // slice for de-dup. Rich entries occupy indices but aren't
    // candidates for de-dup; a new string equal to a rich entry's
    // concatenated runs would still allocate a fresh `<si><t>...`.
    const existing_view = try wb.sst();
    if (existing_view) |view| {
        plan.sst_part_exists = true;
        plan.base_index = @intCast(view.entries.len);
    } else {
        plan.sst_part_exists = false;
        plan.base_index = 0;
    }

    // Pre-decode every existing plain entry once into an arena so
    // each new string compares against decoded text. Rich entries
    // are tracked in a parallel `is_rich_existing` array and SKIPPED
    // from the match loops — a new string can never resolve to a
    // rich entry's index because the OOXML reader treats `<c t="s">`
    // pointing at a rich `<si><r>…</r></si>` differently from a
    // plain one. Without the explicit skip, the previous sentinel
    // (empty slice) silently mis-resolved an empty new string `""`
    // to a rich entry's index.
    var decode_arena = std.heap.ArenaAllocator.init(wb.allocator);
    defer decode_arena.deinit();
    const da = decode_arena.allocator();

    var decoded_existing: [][]const u8 = &.{};
    var is_rich_existing: []bool = &.{};
    if (existing_view) |view| {
        decoded_existing = try da.alloc([]const u8, view.entries.len);
        is_rich_existing = try da.alloc(bool, view.entries.len);
        for (view.entries, 0..) |e, i| {
            switch (e) {
                .plain => |s| {
                    decoded_existing[i] = try sst_xml_mod.decodeText(da, s);
                    is_rich_existing[i] = false;
                },
                .rich => {
                    decoded_existing[i] = "";
                    is_rich_existing[i] = true;
                },
            }
        }
    }

    // Walk strings in worksheet order: first deltas (iteration
    // order), then appended_rows (row-major / col-major). Order is
    // observable to test assertions: "first occurrence across the
    // unified walk wins the lower index". Per-sheet, deltas and
    // appends are mutually exclusive (refused at staging time), but
    // we order deltas-before-appends regardless for determinism.
    for (wb.worksheets) |*ws| {
        var dit = ws.deltas.valueIterator();
        while (dit.next()) |v| {
            const s = switch (v.*) {
                .shared_string => |t| t,
                else => continue,
            };
            try registerSharedString(wb, &plan, s, decoded_existing, is_rich_existing);
        }
        for (ws.appended_rows.items) |row| {
            for (row) |c| switch (c) {
                .string => |s| try registerSharedString(wb, &plan, s, decoded_existing, is_rich_existing),
                else => {},
            };
        }
    }

    // The plan registered at least one new string only when at least
    // one delta failed to match an existing entry. If the user wrote
    // shared-strings that all already existed, has_new_strings stays
    // false and we skip SST regeneration entirely — but we still need
    // indexOf to resolve those existing entries. Patch base_index +
    // pre-load the matched existing entries so `indexOf` works.
    plan.has_new_strings = plan.new_strings.items.len > 0;

    // Whether or not we're regenerating, every `.shared_string` delta
    // must be reachable via plan.indexOf. For deltas that matched an
    // existing entry, register their (raw user) text → existing index
    // mapping by appending the user text under its existing index. We
    // do this by interleaving: re-walk deltas, for each shared_string
    // either it's already in plan.new_strings (just appended) or it
    // matched existing — we need to record the existing index.
    //
    // Simpler implementation: keep a parallel `existing_index_map`.
    // Done below via a second pass that uses the same de-dup logic
    // and populates `existing_match_index_for_each_new_string` which
    // is unused here; instead we extend `indexOf` to scan an
    // existing-match table. Defer that to a follow-up: in the common
    // case where a freshly-staged shared_string matches an existing
    // SST entry, we still want a valid emit path.

    // Build the existing-match side table for any string (delta or
    // appended) whose text equals an existing SST entry. Both fast
    // paths (A: no new strings; B: some new strings) need this so
    // `plan.indexOf(s)` resolves to the existing index, not a fresh
    // one. `registerExistingMatch` skips strings that landed in
    // `plan.new_strings`.
    if (existing_view != null) {
        for (wb.worksheets) |*ws| {
            var it = ws.deltas.valueIterator();
            while (it.next()) |v| {
                const s = switch (v.*) {
                    .shared_string => |t| t,
                    else => continue,
                };
                try registerExistingMatch(wb, &plan, s, decoded_existing, is_rich_existing);
            }
            for (ws.appended_rows.items) |row| {
                for (row) |c| switch (c) {
                    .string => |s| try registerExistingMatch(wb, &plan, s, decoded_existing, is_rich_existing),
                    else => {},
                };
            }
        }
    }

    return plan;
}

/// Persist the SST extension plan to the PartStore. When the source
/// workbook had an existing `xl/sharedStrings.xml`, regenerate the
/// part's bytes (existing entries unchanged, new entries appended)
/// and `replacePart`. When absent, emit a fresh SST + register it via
/// `PartStore.addPart` + splice a `<Relationship>` into
/// `xl/_rels/workbook.xml.rels`.
fn applySstExtensionPlan(wb: *Workbook, plan: *const SstExtensionPlan) Error!void {
    assert(plan.has_new_strings);
    // At least one of the two new-entry axes must be non-empty when
    // `has_new_strings` is true. Plain-only and rich-only and mixed
    // are all valid call shapes.
    assert(plan.new_strings.items.len > 0 or plan.new_rich_strings.items.len > 0);

    if (plan.sst_part_exists) {
        // Re-emit the SST part with the existing entries preserved
        // verbatim and the new entries (plain then rich) appended.
        const existing_part = try wb.store.part("xl/sharedStrings.xml") orelse
            return Error.MissingWorkbookPart; // sst_part_exists invariant violated
        const new_xml = try emitSstXmlForExtension(
            wb.allocator,
            existing_part.bytes,
            plan.new_strings.items,
            plan.new_rich_strings.items,
        );
        defer wb.allocator.free(new_xml);
        try wb.store.replacePart("xl/sharedStrings.xml", new_xml);
        return;
    }

    // Source had no SST. Emit a fresh one containing only the new
    // entries (plain + rich), register it as a new part with the
    // correct content type, then patch the workbook rels file.
    const fresh_xml = try emitFreshSstXml(
        wb.allocator,
        plan.new_strings.items,
        plan.new_rich_strings.items,
    );
    defer wb.allocator.free(fresh_xml);

    try wb.store.addPart(
        "xl/sharedStrings.xml",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml",
        fresh_xml,
    );

    // Splice a `<Relationship>` into `xl/_rels/workbook.xml.rels`.
    const rels_part = try wb.store.part("xl/_rels/workbook.xml.rels") orelse
        return Error.MissingWorkbookRels;
    const new_rels = try injectSstRelationship(wb.allocator, rels_part.bytes);
    defer wb.allocator.free(new_rels);
    try wb.store.replacePart("xl/_rels/workbook.xml.rels", new_rels);
}

/// Produce a regenerated `xl/sharedStrings.xml` with the original
/// entries preserved verbatim and one `<si><t>…</t></si>` per new
/// string appended. The `count` / `uniqueCount` attributes on `<sst>`
/// are rewritten to reflect the new totals; non-attribute markup
/// (xmlns, comments, PIs) is preserved as-is.
fn emitSstXmlForExtension(
    allocator: Allocator,
    src_xml: []const u8,
    new_strings: []const []const u8,
    new_rich: []const RichEntry,
) Error![]u8 {
    assert(src_xml.len > 0);
    assert(new_strings.len > 0 or new_rich.len > 0);

    // Locate `<sst …>` opening tag.
    const sst_open = std.mem.indexOf(u8, src_xml, "<sst") orelse
        return error.MalformedXml;
    const sst_open_gt = std.mem.indexOfScalarPos(u8, src_xml, sst_open, '>') orelse
        return error.MalformedXml;
    const is_self_closing = sst_open_gt > 0 and src_xml[sst_open_gt - 1] == '/';

    // Existing si count: parse uniqueCount attribute when present;
    // otherwise count `<si` opens in the body.
    const existing_si_count: u32 = blk: {
        const attrs = src_xml[sst_open .. sst_open_gt + 1];
        if (extractAttrValue(attrs, "uniqueCount")) |raw| {
            if (std.fmt.parseInt(u32, raw, 10)) |n| break :blk n else |_| {}
        }
        break :blk countSiOpens(src_xml);
    };
    const new_si_count: u32 = @intCast(new_strings.len + new_rich.len);
    const total_si: u32 = existing_si_count + new_si_count;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, src_xml.len + 64 * (new_strings.len + new_rich.len));

    // Copy bytes up to and INCLUDING `<sst`, then rewrite the
    // attribute blob with patched count/uniqueCount, then continue
    // from `>`.
    try out.appendSlice(allocator, src_xml[0 .. sst_open + "<sst".len]);

    // Walk the original attribute blob, replacing count/uniqueCount.
    const attr_start = sst_open + "<sst".len;
    const attr_end = sst_open_gt; // index of `>` (or `/>` slash)
    try writePatchedSstAttrs(
        allocator,
        &out,
        src_xml[attr_start..attr_end],
        total_si,
    );

    // If self-closing, transform into open form so we can append entries.
    if (is_self_closing) {
        try out.appendSlice(allocator, ">");
    } else {
        try out.appendSlice(allocator, ">");
    }

    if (is_self_closing) {
        // Source had `<sst …/>` with no body. Emit only the new entries
        // followed by a fresh `</sst>`. Plain entries first, then
        // rich — `indexOfRich` assumes that order.
        try appendNewSiEntries(allocator, &out, new_strings);
        try appendNewRichSiEntries(allocator, &out, new_rich);
        try out.appendSlice(allocator, "</sst>");
        // Anything past the original `/>` is post-element trailing
        // bytes (rare, but preserve).
        if (sst_open_gt + 1 < src_xml.len) {
            try out.appendSlice(allocator, src_xml[sst_open_gt + 1 ..]);
        }
        return try out.toOwnedSlice(allocator);
    }

    // Normal form: copy body verbatim up to `</sst>`, then append
    // new entries (plain then rich), then `</sst>` + trailing.
    const body_start = sst_open_gt + 1;
    const close = std.mem.indexOfPos(u8, src_xml, body_start, "</sst>") orelse
        return error.MalformedXml;
    try out.appendSlice(allocator, src_xml[body_start..close]);
    try appendNewSiEntries(allocator, &out, new_strings);
    try appendNewRichSiEntries(allocator, &out, new_rich);
    try out.appendSlice(allocator, src_xml[close..]);
    return try out.toOwnedSlice(allocator);
}

/// Build a complete `xl/sharedStrings.xml` from scratch. Used when
/// the source workbook had no SST part.
fn emitFreshSstXml(
    allocator: Allocator,
    new_strings: []const []const u8,
    new_rich: []const RichEntry,
) Error![]u8 {
    assert(new_strings.len > 0 or new_rich.len > 0);
    const total: usize = new_strings.len + new_rich.len;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, 256 + 64 * total);

    try out.appendSlice(allocator, "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>");
    try out.appendSlice(allocator, "<sst xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"");
    var nbuf: [32]u8 = undefined;
    try out.appendSlice(allocator, " count=\"");
    try out.appendSlice(allocator, try std.fmt.bufPrint(&nbuf, "{d}", .{total}));
    try out.appendSlice(allocator, "\" uniqueCount=\"");
    try out.appendSlice(allocator, try std.fmt.bufPrint(&nbuf, "{d}", .{total}));
    try out.appendSlice(allocator, "\">");
    try appendNewSiEntries(allocator, &out, new_strings);
    try appendNewRichSiEntries(allocator, &out, new_rich);
    try out.appendSlice(allocator, "</sst>");
    return try out.toOwnedSlice(allocator);
}

/// Append one `<si><r>…</r>…</si>` per rich entry. Mirrors the
/// emitter shape used by `xlsx.Writer.sstInternRich` so reader
/// round-trips agree on the byte layout. Each run that has at least
/// one typography flag set emits an `<rPr>` block; runs with no
/// flags emit only `<t>`.
fn appendNewRichSiEntries(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    new_rich: []const RichEntry,
) Error!void {
    for (new_rich) |entry| {
        try out.appendSlice(allocator, "<si>");
        for (entry.runs) |r| {
            try out.appendSlice(allocator, "<r>");
            const has_props = r.bold or r.italic or r.underline or r.strike or
                r.font_size != null or r.font_name != null or r.color_argb != null;
            if (has_props) {
                try out.appendSlice(allocator, "<rPr>");
                if (r.bold) try out.appendSlice(allocator, "<b/>");
                if (r.italic) try out.appendSlice(allocator, "<i/>");
                if (r.strike) try out.appendSlice(allocator, "<strike/>");
                if (r.underline) try out.appendSlice(allocator, "<u/>");
                if (r.font_size) |sz| {
                    var szbuf: [32]u8 = undefined;
                    try out.appendSlice(allocator, "<sz val=\"");
                    try out.appendSlice(allocator, try std.fmt.bufPrint(&szbuf, "{d}", .{sz}));
                    try out.appendSlice(allocator, "\"/>");
                }
                if (r.color_argb) |c| {
                    try out.appendSlice(allocator, "<color rgb=\"");
                    try appendXmlEscapedText(allocator, out, c);
                    try out.appendSlice(allocator, "\"/>");
                }
                if (r.font_name) |n| {
                    try out.appendSlice(allocator, "<rFont val=\"");
                    try appendXmlEscapedText(allocator, out, n);
                    try out.appendSlice(allocator, "\"/>");
                }
                try out.appendSlice(allocator, "</rPr>");
            }
            try out.appendSlice(allocator, "<t xml:space=\"preserve\">");
            try appendXmlEscapedText(allocator, out, r.text);
            try out.appendSlice(allocator, "</t></r>");
        }
        try out.appendSlice(allocator, "</si>");
    }
}

/// Append one `<si><t>…</t></si>` per new string to `out`, with
/// `xml:space="preserve"` when the text has leading/trailing
/// whitespace that OOXML would otherwise strip.
fn appendNewSiEntries(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    new_strings: []const []const u8,
) Error!void {
    for (new_strings) |s| {
        try out.appendSlice(allocator, "<si><t");
        if (sstNeedsXmlSpacePreserveLocal(s)) {
            try out.appendSlice(allocator, " xml:space=\"preserve\"");
        }
        try out.appendSlice(allocator, ">");
        try appendXmlEscapedText(allocator, out, s);
        try out.appendSlice(allocator, "</t></si>");
    }
}

/// Mirrors `src/xlsx.zig::sstNeedsXmlSpacePreserve`. Local copy keeps
/// `pkg/workbook.zig` independent of `src/`.
fn sstNeedsXmlSpacePreserveLocal(s: []const u8) bool {
    if (s.len == 0) return false;
    const lead = s[0];
    const trail = s[s.len - 1];
    return lead == ' ' or lead == '\t' or lead == '\n' or lead == '\r' or
        trail == ' ' or trail == '\t' or trail == '\n' or trail == '\r';
}

/// Walk the attribute blob between `<sst` and `>`, emitting it to
/// `out` with `count` and `uniqueCount` rewritten to `new_count`.
/// Attributes other than these two pass through byte-for-byte. If
/// neither attribute is present, both are appended.
fn writePatchedSstAttrs(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    attrs: []const u8,
    new_count: u32,
) Error!void {
    var saw_count: bool = false;
    var saw_unique: bool = false;
    var i: usize = 0;
    while (i < attrs.len) {
        // Skip leading whitespace, but emit it.
        while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
            attrs[i] == '\n' or attrs[i] == '\r'))
        {
            try out.append(allocator, attrs[i]);
            i += 1;
        }
        if (i >= attrs.len) break;
        // Slash (self-closing marker) or any other non-name char: emit + continue.
        if (attrs[i] == '/') {
            try out.append(allocator, attrs[i]);
            i += 1;
            continue;
        }
        // Identify attribute name = run of non-`=`, non-whitespace chars.
        const name_start = i;
        while (i < attrs.len and attrs[i] != '=' and attrs[i] != ' ' and
            attrs[i] != '\t' and attrs[i] != '\n' and attrs[i] != '\r' and
            attrs[i] != '/') : (i += 1)
        {}
        const name = attrs[name_start..i];
        // Skip whitespace before `=`.
        while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
            attrs[i] == '\n' or attrs[i] == '\r')) : (i += 1)
        {}
        if (i >= attrs.len or attrs[i] != '=') {
            // Standalone token (e.g. trailing whitespace before `/>`).
            try out.appendSlice(allocator, name);
            continue;
        }
        i += 1; // past `=`
        // Skip whitespace, find quote.
        while (i < attrs.len and (attrs[i] == ' ' or attrs[i] == '\t' or
            attrs[i] == '\n' or attrs[i] == '\r')) : (i += 1)
        {}
        if (i >= attrs.len or (attrs[i] != '"' and attrs[i] != '\'')) {
            // Malformed attribute — emit verbatim, fall back to scanning to next whitespace.
            try out.appendSlice(allocator, name);
            try out.append(allocator, '=');
            continue;
        }
        const quote = attrs[i];
        const value_start = i + 1;
        const value_end = std.mem.indexOfScalarPos(u8, attrs, value_start, quote) orelse
            return error.MalformedXml;
        const raw_value = attrs[value_start..value_end];

        // Emit the attribute (rewriting count / uniqueCount).
        try out.append(allocator, ' ');
        if (std.mem.eql(u8, name, "count")) {
            saw_count = true;
            try writeCountAttr(allocator, out, "count", new_count);
        } else if (std.mem.eql(u8, name, "uniqueCount")) {
            saw_unique = true;
            try writeCountAttr(allocator, out, "uniqueCount", new_count);
        } else {
            try out.appendSlice(allocator, name);
            try out.append(allocator, '=');
            try out.append(allocator, quote);
            try out.appendSlice(allocator, raw_value);
            try out.append(allocator, quote);
        }
        i = value_end + 1;
    }
    if (!saw_count) try writeCountAttr(allocator, out, " count", new_count);
    if (!saw_unique) try writeCountAttr(allocator, out, " uniqueCount", new_count);
}

fn writeCountAttr(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    name: []const u8,
    n: u32,
) Error!void {
    try out.appendSlice(allocator, name);
    try out.appendSlice(allocator, "=\"");
    var nbuf: [16]u8 = undefined;
    try out.appendSlice(allocator, try std.fmt.bufPrint(&nbuf, "{d}", .{n}));
    try out.append(allocator, '"');
}

/// Extract `name="value"` from an attribute blob (raw value, no
/// entity decoding). Returns null if `name` is absent. Boundary check
/// prevents `count` from matching `uniqueCount`.
fn extractAttrValue(blob: []const u8, name: []const u8) ?[]const u8 {
    assert(name.len > 0);
    var search_from: usize = 0;
    while (true) {
        const pos = std.mem.indexOfPos(u8, blob, search_from, name) orelse return null;
        const left_ok = pos == 0 or blob[pos - 1] == ' ' or blob[pos - 1] == '\t' or
            blob[pos - 1] == '\n' or blob[pos - 1] == '\r' or blob[pos - 1] == '<';
        const after = pos + name.len;
        if (after >= blob.len) return null;
        if (left_ok and blob[after] == '=') {
            const q_pos = after + 1;
            if (q_pos >= blob.len) return null;
            const quote = blob[q_pos];
            if (quote != '"' and quote != '\'') return null;
            const start = q_pos + 1;
            const end = std.mem.indexOfScalarPos(u8, blob, start, quote) orelse return null;
            return blob[start..end];
        }
        search_from = pos + 1;
    }
}

/// Count `<si` opens in `xml`. Used to recover the existing entry
/// count when `<sst>` has no `uniqueCount` attribute. Boundary check
/// keeps `<si` from matching `<silly` (the next char must be a tag
/// boundary).
fn countSiOpens(xml: []const u8) u32 {
    var n: u32 = 0;
    var i: usize = 0;
    while (std.mem.indexOfPos(u8, xml, i, "<si")) |pos| {
        const after = pos + 3;
        if (after >= xml.len) break;
        const c = xml[after];
        if (c == '>' or c == '/' or c == ' ' or c == '\t' or c == '\n' or c == '\r') {
            n += 1;
            i = after;
        } else {
            i = pos + 1;
        }
    }
    return n;
}

/// Splice a `<Relationship>` for `xl/sharedStrings.xml` into
/// `xl/_rels/workbook.xml.rels`. Picks an Id that doesn't collide
/// with existing `rIdN` values. No-op (returns the original bytes
/// duped) if a sharedStrings relationship already exists.
fn injectSstRelationship(allocator: Allocator, xml: []const u8) Error![]u8 {
    if (std.mem.indexOf(u8, xml, "/relationships/sharedStrings") != null) {
        return try allocator.dupe(u8, xml);
    }

    var max_id: u32 = 0;
    var i: usize = 0;
    while (std.mem.indexOfPos(u8, xml, i, "Id=\"rId")) |pos| {
        const num_start = pos + "Id=\"rId".len;
        var num_end = num_start;
        while (num_end < xml.len and xml[num_end] >= '0' and xml[num_end] <= '9') : (num_end += 1) {}
        if (num_end > num_start) {
            if (std.fmt.parseInt(u32, xml[num_start..num_end], 10)) |n| {
                if (n > max_id) max_id = n;
            } else |_| {}
        }
        i = num_end + 1;
    }
    const new_id: u32 = max_id + 1;

    const close = std.mem.indexOf(u8, xml, "</Relationships>") orelse
        return error.MalformedWorkbookRels;

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, xml.len + 256);
    try out.appendSlice(allocator, xml[0..close]);
    try out.appendSlice(allocator, "<Relationship Id=\"rId");
    var nbuf: [16]u8 = undefined;
    try out.appendSlice(allocator, try std.fmt.bufPrint(&nbuf, "{d}", .{new_id}));
    try out.appendSlice(allocator, "\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings\" Target=\"sharedStrings.xml\"/>");
    try out.appendSlice(allocator, xml[close..]);
    return try out.toOwnedSlice(allocator);
}

fn cellTypeAttr(t: sheet_xml_mod.CellType) ?[]const u8 {
    return switch (t) {
        .number => null, // OOXML default; omit attribute
        .shared_string => "s",
        .boolean => "b",
        .formula_string => "str",
        .inline_string => "inlineStr",
        .error_value => "e",
        .date => "d",
    };
}

pub const Worksheet = struct {
    /// Back-pointer set lazily by `Workbook.sheet(idx)` (the slot table
    /// is allocated before the `Workbook` exists, so we patch in on
    /// first observation rather than at construction).
    workbook: *Workbook,
    sheet_idx: u32,

    /// Lazy typed view of the sheet part. `null` until first access.
    parsed: ?sheet_xml_mod.SheetXml,
    /// Cached resolved part name (e.g. "xl/worksheets/sheet1.xml").
    resolved_part_name: ?[]const u8,

    /// Pending mutations (B1 iter-wb-4 m1). Keyed by `CellRef`; the
    /// last `setCell` for a given ref wins. Empty after `Workbook.save`.
    deltas: std.AutoHashMapUnmanaged(CellRef, CellValue) = .{},

    /// B2 iter-er-3 (Phase 3a): pending appended rows. Each entry is
    /// an owned `[]zlsx.Cell` slice with string payloads duped into
    /// the workbook allocator. Cleared by the saver (Editor.save in
    /// iter-er-3, eventually Workbook.save in iter-er-6) after the
    /// substring-spliced sheet XML is emitted.
    ///
    /// **Write contract**: only `Worksheet.appendRows` (and its
    /// editor-side cousin `Editor.appendRows` via the shim) is
    /// allowed to push entries here. Direct field-level writes
    /// bypass the column-cap and integer-precision validation in
    /// `appendRows` and corrupt downstream emit. Reads (size,
    /// has-strings checks) are unrestricted.
    ///
    /// Cannot coexist with non-empty `deltas` on the same Worksheet:
    /// `appendRows` refuses if `deltas.count() > 0` and `setCell`
    /// refuses if `appended_rows.items.len > 0`. Mirrors the legacy
    /// Editor-side guards.
    appended_rows: std.ArrayListUnmanaged([]zlsx.Cell) = .empty,

    /// B3 iter-wr-7: fresh-emit row body. Pre-built `<row>...</row>`
    /// payload (SST indices baked in) appended through the per-sheet
    /// fresh-emit API. Empty for delta-only / source-loaded sheets.
    /// Mutually exclusive with `deltas` and `appended_rows`: a sheet
    /// is either edit-source (deltas / appended_rows) or fresh-emit
    /// (body / state), never both. Today the dispatcher in
    /// `Workbook.saveFreshEmit` is the only consumer; `Workbook.save`
    /// continues to ignore these for the existing delta-on-bytes path.
    body: std.ArrayListUnmanaged(u8) = .empty,

    /// B3 iter-wr-7: fresh-emit per-sheet registries. Owns column
    /// widths, row heights, freeze panes, auto filter, merge cells,
    /// hyperlinks, comments, conditional formats, data validations.
    /// Same shape `xlsx.Writer.SheetWriter.state` carries — the 13
    /// `add*`/`set*` forwarder methods on `Worksheet` route directly
    /// here. Empty-by-default; existing delta-only consumers pay
    /// nothing.
    sheet_state: sheet_plan.SheetState = .{},

    pub fn deinit(self: *Worksheet, allocator: Allocator) void {
        if (self.parsed) |*p| {
            var view = p.*;
            view.deinit(allocator);
        }
        if (self.resolved_part_name) |part_name| allocator.free(part_name);
        freeDeltaStrings(allocator, &self.deltas);
        self.deltas.deinit(allocator);
        for (self.appended_rows.items) |row| {
            for (row) |c| switch (c) {
                .string => |s| allocator.free(s),
                else => {},
            };
            allocator.free(row);
        }
        self.appended_rows.deinit(allocator);
        self.body.deinit(allocator);
        self.sheet_state.deinit(allocator);
    }

    // ─── B3 iter-wr-7: fresh-emit Worksheet methods ─────────────────
    //
    // These 13 forwarders mirror `xlsx.Writer.SheetWriter`'s
    // `add*` / `set*` surface so a `pkg.Workbook` callers can author
    // worksheets without going through the writer's fluent-builder.
    // Each method delegates straight onto `SheetState` — registration,
    // validation, and ownership semantics are identical to the
    // writer-side forwarder set (B3 iter-wr-6).

    pub fn setColumnWidth(self: *Worksheet, col_idx: u32, width: f32) sheet_plan.Error!void {
        try self.sheet_state.setColumnWidth(self.workbook.allocator, col_idx, width);
    }

    pub fn setRowHeight(self: *Worksheet, row_idx: u32, height: f32) sheet_plan.Error!void {
        try self.sheet_state.setRowHeight(self.workbook.allocator, row_idx, height);
    }

    pub fn freezePanes(self: *Worksheet, freeze_rows: u32, freeze_cols: u32) sheet_plan.SheetState.FreezePanesError!void {
        try self.sheet_state.freezePanes(freeze_rows, freeze_cols);
    }

    pub fn setAutoFilter(self: *Worksheet, range: []const u8) sheet_plan.Error!void {
        try self.sheet_state.setAutoFilter(self.workbook.allocator, range);
    }

    pub fn addMergedCell(self: *Worksheet, range: []const u8) sheet_plan.Error!void {
        try self.sheet_state.addMergedCell(self.workbook.allocator, range);
    }

    pub fn addHyperlink(self: *Worksheet, range: []const u8, url: []const u8) sheet_plan.Error!void {
        try self.sheet_state.addHyperlink(self.workbook.allocator, range, url);
    }

    pub fn addInternalHyperlink(self: *Worksheet, range: []const u8, location: []const u8) sheet_plan.Error!void {
        try self.sheet_state.addInternalHyperlink(self.workbook.allocator, range, location);
    }

    pub fn addComment(self: *Worksheet, ref: []const u8, author: []const u8, text: []const u8) sheet_plan.Error!void {
        try self.sheet_state.addComment(self.workbook.allocator, ref, author, text);
    }

    pub fn addDataValidationList(self: *Worksheet, range: []const u8, values: []const []const u8) sheet_plan.Error!void {
        try self.sheet_state.addDataValidationList(self.workbook.allocator, range, values);
    }

    pub fn addDataValidationRange(
        self: *Worksheet,
        range: []const u8,
        kind_name: []const u8,
        op_name: ?[]const u8,
        formula1: []const u8,
        formula2: ?[]const u8,
        needs_two: bool,
    ) sheet_plan.Error!void {
        try self.sheet_state.addDataValidationRange(self.workbook.allocator, range, kind_name, op_name, formula1, formula2, needs_two);
    }

    pub fn addDataValidationCustom(self: *Worksheet, range: []const u8, formula: []const u8) sheet_plan.Error!void {
        try self.sheet_state.addDataValidationCustom(self.workbook.allocator, range, formula);
    }

    pub fn addConditionalFormatCellIs(
        self: *Worksheet,
        range: []const u8,
        operator: sheet_plan.CfOperator,
        formula1: []const u8,
        formula2: ?[]const u8,
        dxf_id: u32,
    ) sheet_plan.Error!void {
        try self.sheet_state.addConditionalFormatCellIs(
            self.workbook.allocator,
            range,
            operator,
            formula1,
            formula2,
            dxf_id,
            self.workbook.styles_plan.dxfs.items.len,
        );
    }

    pub fn addConditionalFormatExpression(
        self: *Worksheet,
        range: []const u8,
        formula: []const u8,
        dxf_id: u32,
    ) sheet_plan.Error!void {
        try self.sheet_state.addConditionalFormatExpression(
            self.workbook.allocator,
            range,
            formula,
            dxf_id,
            self.workbook.styles_plan.dxfs.items.len,
        );
    }

    pub fn addConditionalFormatColorScale(
        self: *Worksheet,
        range: []const u8,
        low_color_argb: u32,
        mid_color_argb: ?u32,
        high_color_argb: u32,
    ) sheet_plan.Error!void {
        try self.sheet_state.addConditionalFormatColorScale(
            self.workbook.allocator,
            range,
            low_color_argb,
            mid_color_argb,
            high_color_argb,
        );
    }

    pub fn addConditionalFormatDataBar(self: *Worksheet, range: []const u8, color_argb: u32) sheet_plan.Error!void {
        try self.sheet_state.addConditionalFormatDataBar(self.workbook.allocator, range, color_argb);
    }

    /// Sheet name from the workbook's sheets list. Borrowed.
    pub fn name(self: *const Worksheet) []const u8 {
        return self.workbook.workbook.sheets[self.sheet_idx].name;
    }

    /// Workbook-assigned sheet ID (NOT the same as sheet_idx).
    pub fn sheetId(self: *const Worksheet) u32 {
        return self.workbook.workbook.sheets[self.sheet_idx].sheet_id;
    }

    pub fn state(self: *const Worksheet) workbook_xml_mod.SheetState {
        return self.workbook.workbook.sheets[self.sheet_idx].state;
    }

    /// Resolve `r_id` → `xl/_rels/workbook.xml.rels` lookup and cache
    /// the sheet's part name (e.g. "xl/worksheets/sheet1.xml")
    /// without parsing the body. Idempotent — second call returns
    /// the cached name.
    ///
    /// Public surface for B2 iter-er-3 fast paths (substring-splice
    /// `emitWithAppendsUsingPlan`) that need the sheet's part name to read
    /// raw XML bytes from the part store WITHOUT walking
    /// `<sheetData>` via `ensureParsed`. On a 100k-row sheet, the
    /// parse step alone runs in the hundreds of milliseconds — too
    /// expensive to pay when the caller will splice a few rows.
    ///
    /// Stability: `r_id` is set once at `Workbook.parse` and is not
    /// re-bound by any current API (`renameSheet` mutates the
    /// display name, not the rels target), so the cached part name
    /// outlives every legal invalidation of `parsed`.
    pub fn resolvePartName(self: *Worksheet) Error![]const u8 {
        if (self.resolved_part_name) |cached| return cached;

        const wb = self.workbook;
        const r_id = wb.workbook.sheets[self.sheet_idx].r_id;
        if (r_id.len == 0) return Error.MissingRelationship;

        const wb_rels = wb.store.rels("xl/workbook.xml");
        var resolved: ?[]const u8 = null;
        for (wb_rels) |rel| {
            if (std.mem.eql(u8, rel.id, r_id)) {
                resolved = try wb.store.resolve("xl/workbook.xml", rel.target);
                break;
            }
        }
        const part_name = resolved orelse return Error.MissingRelationship;
        // Dupe so `resolved_part_name` lifetime is bound to Worksheet,
        // not to PartStore's arena.
        const owned = try wb.allocator.dupe(u8, part_name);
        errdefer wb.allocator.free(owned);
        self.resolved_part_name = owned;
        return owned;
    }

    /// Resolve the part name and parse the sheet XML if not already
    /// cached. Returns a const pointer to the cached view.
    pub fn ensureParsed(self: *Worksheet) Error!*const sheet_xml_mod.SheetXml {
        if (self.parsed != null) return &self.parsed.?;

        const part_name = try self.resolvePartName();
        const wb = self.workbook;
        const part = try wb.store.part(part_name) orelse return Error.MissingSheetPart;
        self.parsed = try sheet_xml_mod.parse(wb.allocator, part.bytes);
        return &self.parsed.?;
    }

    pub fn dimension(self: *Worksheet) Error!?sheet_xml_mod.Dimension {
        const view = try self.ensureParsed();
        return view.dimension;
    }

    pub fn rows(self: *Worksheet) Error![]const sheet_xml_mod.Row {
        const view = try self.ensureParsed();
        return view.rows;
    }

    pub fn merges(self: *Worksheet) Error![]const sheet_xml_mod.MergeRange {
        const view = try self.ensureParsed();
        return view.merges;
    }

    pub fn hyperlinks(self: *Worksheet) Error![]const sheet_xml_mod.Hyperlink {
        const view = try self.ensureParsed();
        return view.hyperlinks;
    }

    pub fn validations(self: *Worksheet) Error![]const sheet_xml_mod.DataValidation {
        const view = try self.ensureParsed();
        return view.validations;
    }

    pub fn conditionalFormats(self: *Worksheet) Error![]const sheet_xml_mod.ConditionalFormat {
        const view = try self.ensureParsed();
        return view.conditional_formats;
    }

    pub fn freezePane(self: *Worksheet) Error!?sheet_xml_mod.FreezePane {
        const view = try self.ensureParsed();
        return view.freeze;
    }

    /// Find a cell by its A1 reference (e.g. "A1", "B7"). Linear scan
    /// over the parsed rows/cells — sufficient for v1 read-only use.
    /// Match is case-insensitive on the column letters; row part is
    /// strict decimal. Returns `null` when no cell matches.
    ///
    /// Matched cells are returned by-value (small struct of borrowed
    /// slices); the underlying SheetXml owns the storage, so the
    /// returned Cell is valid for the Workbook's lifetime.
    pub fn cellByRef(self: *Worksheet, ref: []const u8) Error!?sheet_xml_mod.Cell {
        assert(ref.len > 0);
        const view = try self.ensureParsed();
        for (view.rows) |row| {
            for (row.cells) |c| {
                if (eqlAsciiIgnoreCase(c.ref, ref)) return c;
            }
        }
        return null;
    }

    /// Resolve the cell at `ref` to a composite `ResolvedStyle` view
    /// by walking `SheetXml.Cell.style_idx` → `StylesXml.cell_xfs[idx]`
    /// → the per-attribute fonts/fills/borders/numFmts tables.
    ///
    /// Returns `null` when:
    ///   - the cell does not exist on this sheet,
    ///   - the cell carries no `s="…"` attribute (`style_idx == null`),
    ///   - the workbook has no `xl/styles.xml`, or
    ///   - `style_idx` is out of range for the workbook's `cell_xfs`.
    ///
    /// Per-field semantics: each `apply_*` flag on the matched CellXf
    /// gates whether the corresponding sub-style is surfaced. When the
    /// flag is false, the field is `null` — see `ResolvedStyle` doc-
    /// comment for the v1 cellStyleXfs-inheritance simplification.
    /// Out-of-range sub-ids (font_id ≥ fonts.len, etc.) likewise
    /// surface as `null` rather than erroring; that lets the typed
    /// overlay tolerate workbooks where producers under-count their
    /// `<fonts count="…">` headers.
    ///
    /// `number_format_code` is `null` for built-in numFmt ids (0..163,
    /// ECMA-376 §18.8.30) — those codes are implicit and absent from
    /// `<numFmts>`. Custom ids (≥ 164) resolve via linear scan.
    pub fn cellStyle(self: *Worksheet, ref: []const u8) Error!?ResolvedStyle {
        assert(ref.len > 0);

        const cell = (try self.cellByRef(ref)) orelse return null;
        const sidx = cell.style_idx orelse return null;
        const styles = (try self.workbook.styles()) orelse return null;
        if (sidx >= styles.cell_xfs.len) return null;
        const xf = styles.cell_xfs[sidx];

        const font: ?styles_xml_mod.Font = blk: {
            if (!xf.apply_font) break :blk null;
            const fid = xf.font_id orelse break :blk null;
            if (fid >= styles.fonts.len) break :blk null;
            break :blk styles.fonts[fid];
        };

        const fill: ?styles_xml_mod.Fill = blk: {
            if (!xf.apply_fill) break :blk null;
            const fid = xf.fill_id orelse break :blk null;
            if (fid >= styles.fills.len) break :blk null;
            break :blk styles.fills[fid];
        };

        const border: ?styles_xml_mod.Border = blk: {
            if (!xf.apply_border) break :blk null;
            const bid = xf.border_id orelse break :blk null;
            if (bid >= styles.borders.len) break :blk null;
            break :blk styles.borders[bid];
        };

        const alignment: ?styles_xml_mod.Alignment =
            if (xf.apply_alignment) xf.alignment else null;

        const number_format_code: ?[]const u8 = blk: {
            if (!xf.apply_number_format) break :blk null;
            const nfid = xf.num_fmt_id orelse break :blk null;
            // Built-in codes (0..163) are implicit; not stored in numFmts.
            if (nfid <= 163) break :blk null;
            for (styles.number_formats) |nf| {
                if (nf.fmt_id == nfid) break :blk nf.code;
            }
            break :blk null;
        };

        return ResolvedStyle{
            .font = font,
            .fill = fill,
            .border = border,
            .alignment = alignment,
            .number_format_code = number_format_code,
        };
    }

    /// Stage a mutation for cell at A1 ref `ref`. Persisted by
    /// `Workbook.save`. The last `setCell` call for a given ref wins.
    /// Numeric / boolean / blank values pass through by-value. String
    /// and formula values are duped into the Workbook allocator
    /// (caller can free the input slice as soon as `setCell` returns).
    ///
    /// String + formula inputs are validated against XML 1.0 —
    /// control bytes other than \t, \n, \r are rejected with
    /// `error.MalformedXml` to prevent emitting unparseable XML.
    pub fn setCell(self: *Worksheet, ref: []const u8, value: CellValue) Error!void {
        assert(ref.len > 0);
        // B2 iter-er-3 symmetric guard: setCell + appendRows on the
        // same Worksheet are mutually exclusive (mirrors Editor's
        // legacy SheetHasUnsavedAppends rejection).
        if (self.appended_rows.items.len > 0) return error.SheetHasUnsavedAppends;
        const cr = try parseA1Ref(ref);
        const a = self.workbook.allocator;

        // Free any previous heap allocation for this ref so a
        // string/formula/shared_string overwrite doesn't leak.
        if (self.deltas.get(cr)) |prev| {
            switch (prev) {
                .string => |s| a.free(s),
                .shared_string => |s| a.free(s),
                .formula => |f| a.free(f),
                else => {},
            }
        }

        const stored: CellValue = switch (value) {
            .string => |s| blk: {
                if (!isXmlSafeText(s)) return error.MalformedXml;
                break :blk .{ .string = try a.dupe(u8, s) };
            },
            .shared_string => |s| blk: {
                if (!isXmlSafeText(s)) return error.MalformedXml;
                break :blk .{ .shared_string = try a.dupe(u8, s) };
            },
            .formula => |f| blk: {
                if (!isXmlSafeText(f)) return error.MalformedXml;
                break :blk .{ .formula = try a.dupe(u8, f) };
            },
            else => value,
        };
        errdefer switch (stored) {
            .string => |s| a.free(s),
            .shared_string => |s| a.free(s),
            .formula => |f| a.free(f),
            else => {},
        };

        try self.deltas.put(a, cr, stored);
    }

    /// Stage a deletion for cell `ref`. After `Workbook.save`, the
    /// cell is fully absent from `<sheetData>` (no `<c>` element at
    /// all) and `cellByRef(ref)` returns `null`. Distinct from
    /// `setCell(ref, .blank)`, which keeps the cell present as an
    /// empty `<c r="REF"/>`.
    ///
    /// Staging a deletion against a ref that doesn't exist in the
    /// source sheet is not an error — the delta just elides nothing.
    /// Last `setCell`/`deleteCell` for a given ref wins.
    pub fn deleteCell(self: *Worksheet, ref: []const u8) Error!void {
        assert(ref.len > 0);
        return self.setCell(ref, .deleted);
    }

    /// B2 iter-er-3 (Phase 3a): stage rows to append at the bottom of
    /// the sheet. Each row is an iterable of `xlsx.Cell` variants
    /// (`empty` / `number` / `integer` / `boolean` / `string`).
    /// Strings are duped into the workbook allocator for owned
    /// lifetime.
    ///
    /// **Refusal contract** (mirrors Editor.appendRows):
    ///   - `error.SheetHasUnsavedMutations` if `self.deltas.count() > 0`
    ///   - `error.ColumnIndexOutOfRange` if any row exceeds 16384 cells
    ///   - `error.IntegerExceedsExcelPrecision` if any `.integer`
    ///     value can't round-trip exactly through f64
    ///
    /// **Editor-scope state not visible here**: the editor tracks
    /// `pending_row_inserts` / `pending_row_deletes` / `pending_col_*`
    /// at its own layer. Those edits race with appends at save time
    /// (the editor's row/col substitution runs first, then appends
    /// would splice into the pre-edit XML, silently dropping the
    /// edit). Direct `Worksheet.appendRows` callers must drain those
    /// editor-scope queues themselves; only the editor-side shim
    /// (`Editor.appendRows`) checks `sheetHasPendingRowOrColEdit`.
    ///
    /// **What this method does NOT do**: emit XML, allocate SST
    /// indices, or modify the sheet's parsed view. The actual
    /// substring splice + SST extension happens at save time via
    /// `emitWithAppendsUsingPlan`, driven by `Workbook.save`'s
    /// `SstExtensionPlan` walk.
    pub fn appendRows(
        self: *Worksheet,
        new_rows: []const []const zlsx.Cell,
    ) Error!void {
        if (self.deltas.count() > 0) return error.SheetHasUnsavedMutations;
        if (new_rows.len == 0) return;
        const a = self.workbook.allocator;
        // Validation pass — fail BEFORE any allocation so a bad row
        // doesn't half-stage cells from earlier new_rows in the same call.
        for (new_rows) |row| {
            if (row.len > zlsx.max_col_1based) return error.ColumnIndexOutOfRange;
            for (row) |c| switch (c) {
                .empty, .number, .boolean, .string => {},
                .integer => |n| if (!zlsx.fitsExactlyInF64(n))
                    return error.IntegerExceedsExcelPrecision,
            };
        }
        // Reserve once — keeps the existing-cap path on the hot loop.
        try self.appended_rows.ensureUnusedCapacity(a, new_rows.len);
        for (new_rows) |row| {
            const owned = try a.alloc(zlsx.Cell, row.len);
            errdefer a.free(owned);
            // Track how many cells we've duped so partial-fail
            // cleanup frees only what we allocated.
            var duped: usize = 0;
            errdefer for (owned[0..duped]) |c| switch (c) {
                .string => |s| a.free(s),
                else => {},
            };
            for (row, 0..) |c, i| {
                owned[i] = switch (c) {
                    .string => |s| .{ .string = try a.dupe(u8, s) },
                    else => c,
                };
                duped = i + 1;
            }
            // Capacity reserved above — appendAssumeCapacity is
            // infallible from here.
            self.appended_rows.appendAssumeCapacity(owned);
        }
    }

    /// Regenerate this worksheet's XML with the staged `setCell` /
    /// `deleteCell` deltas applied. Returns allocator-owned bytes —
    /// caller frees. The source `<sheetData>` block is regenerated
    /// from scratch (parsed view + deltas merged in row/col order);
    /// everything outside `<sheetData>` (sheet-level metadata,
    /// `<mergeCells>`, `<dataValidations>`, `<conditionalFormatting>`,
    /// `<hyperlinks>`, `<drawing>`, ...) is copied byte-for-byte from
    /// source. B2 iter-er-2 entry-point: lets `Editor.save` route
    /// modified-sheet emit through the workbook overlay without
    /// invoking the full `Workbook.save` ZIP-rebuild pipeline.
    ///
    /// SST policy: this entry-point uses an EMPTY `SstExtensionPlan`,
    /// so `.shared_string` deltas would resolve to `null` index and
    /// trip the regen's invariant. The Editor pipeline maps every
    /// `Cell.string` to `CellValue.string` (inlineStr — no SST
    /// extension), so this is fine for iter-er-2's call sites.
    /// Future iters that need shared-string emission from Editor
    /// must pass a real plan.
    pub fn emitWithDeltas(self: *Worksheet, allocator: Allocator) Error![]u8 {
        const view = try self.ensureParsed();
        const part_name = self.resolved_part_name orelse return error.MissingSheetPart;
        const part = try self.workbook.store.part(part_name) orelse return error.MissingSheetPart;
        const empty_plan: SstExtensionPlan = .{};
        return emitSheetWithDeltas(allocator, part.bytes, view, &self.deltas, &empty_plan);
    }

    /// B2 iter-er-3 substring-splice fast-path. Used by
    /// `Workbook.save`: every string cell resolves its SST index via
    /// `plan.indexOf(s)` (which already deduplicates against existing
    /// SST entries and across sheets). Caller does NOT receive
    /// `new_strings` — those live in `plan.new_strings`. Returns the
    /// spliced XML only.
    ///
    /// Caller invariants: `appended_rows.items.len > 0`,
    /// `deltas.count() == 0`, every `.string` payload appearing in
    /// `appended_rows` is registered in `plan` (either as a new
    /// string or an existing-match entry).
    pub fn emitWithAppendsUsingPlan(
        self: *Worksheet,
        allocator: Allocator,
        plan: *const SstExtensionPlan,
    ) Error![]u8 {
        assert(self.appended_rows.items.len > 0);
        if (self.deltas.count() > 0) return error.SheetHasUnsavedMutations;

        const part_name = try self.resolvePartName();
        assert(part_name.len > 0);
        const part = try self.workbook.store.part(part_name) orelse return error.MissingSheetPart;
        const src_xml = part.bytes;

        const highest_row = appendXmlFindHighestRow(src_xml);
        const start_row: u32 = highest_row + 1;
        assert(start_row >= 1);
        const final_row64: u64 = @as(u64, start_row) + self.appended_rows.items.len - 1;
        if (final_row64 > zlsx.max_row) return error.RowIndexOutOfRange;
        const final_row: u32 = @intCast(final_row64);
        assert(start_row <= final_row);

        var max_col_1based: u32 = 0;
        for (self.appended_rows.items) |row| {
            if (row.len > max_col_1based) max_col_1based = @intCast(row.len);
        }
        assert(max_col_1based <= zlsx.max_col_1based);

        var rows_buf: std.ArrayList(u8) = .empty;
        defer rows_buf.deinit(allocator);
        try rows_buf.ensureTotalCapacity(allocator, self.appended_rows.items.len * 32);

        for (self.appended_rows.items, 0..) |row, ri| {
            const row_idx: u32 = start_row + @as(u32, @intCast(ri));
            try rows_buf.appendSlice(allocator, "<row r=\"");
            var num_buf: [16]u8 = undefined;
            try rows_buf.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{row_idx}));
            try rows_buf.appendSlice(allocator, "\">");
            for (row, 0..) |cell, ci| {
                const col_1based: u32 = @as(u32, @intCast(ci)) + 1;
                try appendCellXmlForAppendUsingPlan(
                    allocator,
                    &rows_buf,
                    cell,
                    .{ .row = row_idx, .col = col_1based },
                    plan,
                );
            }
            try rows_buf.appendSlice(allocator, "</row>");
        }
        assert(rows_buf.items.len > 0);

        const injected = try appendXmlInjectRows(allocator, src_xml, rows_buf.items);
        errdefer allocator.free(injected);

        const final_xml = blk: {
            const widened = try appendXmlUpdateDimensionBR(
                allocator,
                injected,
                final_row,
                max_col_1based,
            );
            if (widened) |w| {
                allocator.free(injected);
                break :blk w;
            }
            break :blk injected;
        };
        assert(final_xml.len > src_xml.len);
        return final_xml;
    }

    /// Free + reset `appended_rows` after `Workbook.save` (or
    /// `Editor.save` in iter-er-3) has consumed the staged rows.
    /// Pairs with `appendRows` — same allocator semantics.
    pub fn clearAppendedRows(self: *Worksheet, allocator: Allocator) void {
        for (self.appended_rows.items) |row| {
            for (row) |c| switch (c) {
                .string => |s| allocator.free(s),
                else => {},
            };
            allocator.free(row);
        }
        self.appended_rows.clearAndFree(allocator);
    }
};

/// Render a single appended-row cell into `out`. String cells
/// resolve via `plan.indexOf(s)`; the plan owns the string entries
/// (no per-cell dupe needed). Non-string cells render their value
/// verbatim. `.empty` skips emission so trailing empties collapse to
/// nothing — matches the editor's `renderCellOoxml` contract.
fn appendCellXmlForAppendUsingPlan(
    allocator: Allocator,
    out: *std.ArrayList(u8),
    cell: zlsx.Cell,
    ref: CellRef,
    plan: *const SstExtensionPlan,
) Error!void {
    assert(ref.col >= 1 and ref.col <= zlsx.max_col_1based);
    assert(ref.row >= 1 and ref.row <= zlsx.max_row);
    var ref_buf: [16]u8 = undefined;
    const ref_str = formatA1Ref(&ref_buf, ref);
    var num_buf: [64]u8 = undefined;
    switch (cell) {
        .empty => return,
        .integer => |x| {
            try out.appendSlice(allocator, "<c r=\"");
            try out.appendSlice(allocator, ref_str);
            try out.appendSlice(allocator, "\"><v>");
            try out.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{x}));
            try out.appendSlice(allocator, "</v></c>");
        },
        .number => |f| {
            try out.appendSlice(allocator, "<c r=\"");
            try out.appendSlice(allocator, ref_str);
            try out.appendSlice(allocator, "\"><v>");
            try out.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{f}));
            try out.appendSlice(allocator, "</v></c>");
        },
        .boolean => |b| {
            try out.appendSlice(allocator, "<c r=\"");
            try out.appendSlice(allocator, ref_str);
            try out.appendSlice(allocator, "\" t=\"b\"><v>");
            try out.appendSlice(allocator, if (b) "1" else "0");
            try out.appendSlice(allocator, "</v></c>");
        },
        .string => |s| {
            const idx = plan.indexOf(s) orelse return error.SharedStringNotInPlan;
            try out.appendSlice(allocator, "<c r=\"");
            try out.appendSlice(allocator, ref_str);
            try out.appendSlice(allocator, "\" t=\"s\"><v>");
            try out.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{idx}));
            try out.appendSlice(allocator, "</v></c>");
        },
    }
}

/// Find the largest cell-row index in a sheet XML body. Walks both
/// `<row …>` and `<c …>` opening tags inside the `<sheetData>` window
/// and extracts the row component from any `r="…"` attribute (cell
/// refs like `r="A42"` decode to row 42; explicit `<row r="12">`
/// decodes to 12). OOXML doesn't constrain attribute order so the
/// scan is permissive.
///
/// Bounded: scans only `<sheetData>…</sheetData>`. Anything outside
/// that window — `<oddHeader>`, `<tableParts>`, `<extLst>`,
/// `<mergeCell ref="…">`, etc. — is ignored even if its attributes
/// happen to spell `r="A99999"`. XML comments INSIDE the window are
/// not specifically filtered: Excel and every legitimate writer
/// strip them, and adding O(n)-per-tag back-scanning costs ~3% on
/// the 100k-row gate. A `<!-- r="A1048576" -->` inside `<sheetData>`
/// could still inflate `highest_row` — accepted trade-off, fuzz
/// corpus exercises the boundary.
///
/// Parse-free: pure substring walk, suitable for 100k-row sheets
/// where the sheet_xml parse path would dominate the gate.
fn appendXmlFindHighestRow(xml: []const u8) u32 {
    var highest: u32 = 0;

    const window: []const u8 = blk: {
        const open_pos = std.mem.indexOf(u8, xml, "<sheetData") orelse return 0;
        const open_close = std.mem.indexOfScalarPos(u8, xml, open_pos, '>') orelse return 0;
        // Self-closing `<sheetData/>` has no body — empty window.
        if (open_close > 0 and xml[open_close - 1] == '/') break :blk xml[0..0];
        // open_close is a `>` byte found by indexOfScalarPos so it's
        // always within bounds; `open_close + 1 <= xml.len` and
        // indexOfPos accepts start == slice.len.
        assert(open_close + 1 <= xml.len);
        const close_pos = std.mem.indexOfPos(u8, xml, open_close + 1, "</sheetData>") orelse
            return 0;
        break :blk xml[open_close + 1 .. close_pos];
    };

    // Pass 1: `<c …>` tags — extract the row component from r="A1".
    {
        var i: usize = 0;
        while (std.mem.indexOfPos(u8, window, i, "<c")) |tag_start| {
            const after = tag_start + "<c".len;
            if (after >= window.len) break;
            const c = window[after];
            // Filter `<col`, `<conditionalFormatting`, etc.
            if (c != ' ' and c != '\t' and c != '\n' and c != '\r' and c != '/' and c != '>') {
                i = tag_start + 1;
                continue;
            }
            const tag_end = std.mem.indexOfScalarPos(u8, window, tag_start, '>') orelse break;
            if (appendXmlAttrRowFromCellRef(window[tag_start..tag_end])) |n| {
                if (n > highest) highest = n;
            }
            i = tag_end + 1;
        }
    }
    // Pass 2: `<row …>` tags — explicit r="N".
    {
        var i: usize = 0;
        while (std.mem.indexOfPos(u8, window, i, "<row")) |tag_start| {
            const after = tag_start + "<row".len;
            if (after >= window.len) break;
            const c = window[after];
            if (c != ' ' and c != '\t' and c != '\n' and c != '\r' and c != '/' and c != '>') {
                i = tag_start + 1;
                continue;
            }
            const tag_end = std.mem.indexOfScalarPos(u8, window, tag_start, '>') orelse break;
            if (appendXmlAttrRowExplicit(window[tag_start..tag_end])) |n| {
                if (n > highest) highest = n;
            }
            i = tag_end + 1;
        }
    }
    return highest;
}

/// Locate `r="…"` within an opening tag's attribute span and parse
/// the row component of an A1-style cell ref. Returns null on no
/// match or unparseable digits.
fn appendXmlAttrRowFromCellRef(tag: []const u8) ?u32 {
    var search_from: usize = 0;
    while (std.mem.indexOfPos(u8, tag, search_from, "r=\"")) |r_pos| {
        const prev = if (r_pos > 0) tag[r_pos - 1] else 0;
        if (prev == ' ' or prev == '\t' or prev == '\n' or prev == '\r') {
            const ref_start = r_pos + "r=\"".len;
            var col_end = ref_start;
            while (col_end < tag.len and tag[col_end] >= 'A' and tag[col_end] <= 'Z') : (col_end += 1) {}
            var num_end = col_end;
            while (num_end < tag.len and tag[num_end] >= '0' and tag[num_end] <= '9') : (num_end += 1) {}
            if (num_end > col_end) {
                return std.fmt.parseInt(u32, tag[col_end..num_end], 10) catch null;
            }
            return null;
        }
        search_from = r_pos + 1;
    }
    return null;
}

/// Locate `r="N"` within a `<row …>` span and parse N as a u32.
fn appendXmlAttrRowExplicit(tag: []const u8) ?u32 {
    var search_from: usize = 0;
    while (std.mem.indexOfPos(u8, tag, search_from, "r=\"")) |r_pos| {
        const prev = if (r_pos > 0) tag[r_pos - 1] else 0;
        if (prev == ' ' or prev == '\t' or prev == '\n' or prev == '\r') {
            const num_start = r_pos + "r=\"".len;
            var num_end = num_start;
            while (num_end < tag.len and tag[num_end] >= '0' and tag[num_end] <= '9') : (num_end += 1) {}
            if (num_end > num_start) {
                return std.fmt.parseInt(u32, tag[num_start..num_end], 10) catch null;
            }
            return null;
        }
        search_from = r_pos + 1;
    }
    return null;
}

/// Splice a pre-rendered `rendered_rows` block into `src_xml` just
/// before `</sheetData>`. Falls back to the self-closing
/// `<sheetData/>` shape — replaces it with `<sheetData>…</sheetData>`
/// preserving any attributes on the open tag.
fn appendXmlInjectRows(
    allocator: Allocator,
    src_xml: []const u8,
    rendered_rows: []const u8,
) Error![]u8 {
    if (std.mem.indexOf(u8, src_xml, "</sheetData>")) |inject_pos| {
        // indexOf invariant: inject_pos + tag_len <= src_xml.len.
        // Pair-assertion turns a future indexOf-contract regression
        // into a tripwire instead of an out-of-bounds memcpy.
        assert(inject_pos + "</sheetData>".len <= src_xml.len);
        const out_len = src_xml.len + rendered_rows.len;
        const out = try allocator.alloc(u8, out_len);
        errdefer allocator.free(out);
        @memcpy(out[0..inject_pos], src_xml[0..inject_pos]);
        @memcpy(out[inject_pos..][0..rendered_rows.len], rendered_rows);
        @memcpy(out[inject_pos + rendered_rows.len ..], src_xml[inject_pos..]);
        return out;
    }

    const sd_open = std.mem.indexOf(u8, src_xml, "<sheetData") orelse
        return error.NoSheetData;
    const sd_close = std.mem.indexOfScalarPos(u8, src_xml, sd_open, '>') orelse
        return error.NoSheetData;
    if (sd_close == 0 or src_xml[sd_close - 1] != '/') return error.NoSheetData;
    const attrs_end = sd_close - 1;
    const attrs = src_xml[sd_open + "<sheetData".len .. attrs_end];

    var spliced: std.ArrayList(u8) = .empty;
    // `toOwnedSlice` empties the ArrayList on success, so this
    // `errdefer` is a no-op on the happy path — kept so an early
    // `try` failure doesn't leak the partially-built buffer.
    errdefer spliced.deinit(allocator);
    try spliced.ensureTotalCapacity(allocator, src_xml.len + rendered_rows.len + 32);
    try spliced.appendSlice(allocator, src_xml[0..sd_open]);
    try spliced.appendSlice(allocator, "<sheetData");
    try spliced.appendSlice(allocator, attrs);
    try spliced.append(allocator, '>');
    try spliced.appendSlice(allocator, rendered_rows);
    try spliced.appendSlice(allocator, "</sheetData>");
    try spliced.appendSlice(allocator, src_xml[sd_close + 1 ..]);
    return try spliced.toOwnedSlice(allocator);
}

/// Widen the BR corner of a canonical `<dimension ref="TL:BR"/>` so
/// both the row component reaches `new_max_row` and the letter
/// component reaches `new_max_col_1based`. Returns null on no-op,
/// non-canonical shape, or missing `<dimension>` — the spec lets
/// Excel rescan `<sheetData>` and rewrite the dimension on its
/// next save, so staleness on those is tolerable.
fn appendXmlUpdateDimensionBR(
    allocator: Allocator,
    xml: []const u8,
    new_max_row: u32,
    new_max_col_1based: u32,
) Error!?[]u8 {
    const dim_open = "<dimension ref=\"";
    const dim_pos = std.mem.indexOf(u8, xml, dim_open) orelse return null;
    const ref_start = dim_pos + dim_open.len;
    const ref_end = std.mem.indexOfScalarPos(u8, xml, ref_start, '"') orelse return null;
    const ref = xml[ref_start..ref_end];
    const colon = std.mem.indexOfScalar(u8, ref, ':') orelse return null;
    const br = ref[colon + 1 ..];
    if (br.len == 0) return null;

    var digit_start: usize = br.len;
    while (digit_start > 0 and br[digit_start - 1] >= '0' and br[digit_start - 1] <= '9') {
        digit_start -= 1;
    }
    if (digit_start == br.len or digit_start == 0) return null;
    for (br[0..digit_start]) |c| if (c < 'A' or c > 'Z') return null;
    const old_row = std.fmt.parseInt(u32, br[digit_start..], 10) catch return null;
    const old_col_1based = appendXmlParseColLetters(br[0..digit_start]) orelse return null;

    const final_row: u32 = @max(old_row, new_max_row);
    const final_col_1based: u32 = @max(old_col_1based, new_max_col_1based);
    if (final_row == old_row and final_col_1based == old_col_1based) return null;

    const br_abs_start = ref_start + colon + 1;
    const br_abs_end = ref_end;
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(allocator);
    try out.ensureTotalCapacity(allocator, xml.len + 8);
    try out.appendSlice(allocator, xml[0..br_abs_start]);
    var letter_buf: [8]u8 = undefined;
    const letters = appendXmlColLetters(&letter_buf, final_col_1based);
    try out.appendSlice(allocator, letters);
    var num_buf: [16]u8 = undefined;
    try out.appendSlice(allocator, try std.fmt.bufPrint(&num_buf, "{d}", .{final_row}));
    try out.appendSlice(allocator, xml[br_abs_end..]);
    return try out.toOwnedSlice(allocator);
}

/// Parse uppercase A-Z letters as a 1-based Excel column index
/// (A=1, …, XFD=16384). Returns null on empty input or anything
/// past `max_col_1based`.
fn appendXmlParseColLetters(s: []const u8) ?u32 {
    return coords.parseColNumber(s, .{ .case = .upper_only }) catch null;
}

/// Render `col_1based` as A, B, …, Z, AA, … into `buf`. Capacity 8
/// is more than enough (Excel max is XFD = 3 letters).
fn appendXmlColLetters(buf: []u8, col_1based: u32) []u8 {
    assert(buf.len >= 7);
    assert(col_1based >= 1 and col_1based <= zlsx.max_col_1based);
    const n = coords.writeColLetters(buf, coords.Col.fromOneBased(col_1based) catch unreachable);
    return buf[0..n];
}

/// XML 1.0 §2.2: Char ::= #x9 | #xA | #xD | [#x20-#xD7FF] | …
/// Reject ASCII control bytes outside the allowed three. Bytes ≥ 0x80
/// pass through without interpretation — the input must already be
/// well-formed UTF-8.
fn isXmlSafeText(s: []const u8) bool {
    for (s) |b| {
        if (b < 0x20 and b != 0x09 and b != 0x0A and b != 0x0D) return false;
    }
    return true;
}

/// Free any string / formula allocations stashed in `deltas`. Called
/// both before `clearAndFree` (post-save) and `deinit` (Worksheet
/// teardown).
fn freeDeltaStrings(allocator: Allocator, deltas: *std.AutoHashMapUnmanaged(CellRef, CellValue)) void {
    var it = deltas.valueIterator();
    while (it.next()) |v| {
        switch (v.*) {
            .string => |s| allocator.free(s),
            .shared_string => |s| allocator.free(s),
            .formula => |f| allocator.free(f),
            else => {},
        }
    }
}

/// B3 iter-wr-6 NOTE: kept local for the same reason as
/// `appendXmlEscaped` above — `pkg/sheet_plan.zig::appendXmlEscapedText`
/// rejects XML 1.0 forbidden control bytes via `error.InvalidXmlByte`,
/// which is not in Workbook's `Error` set. 3-entity (`<`, `>`, `&`)
/// element-content escape; quotes pass through verbatim per the
/// byte-stable contract.
fn appendXmlEscapedText(allocator: Allocator, out: *std.ArrayList(u8), text: []const u8) Error!void {
    for (text) |b| {
        switch (b) {
            '<' => try out.appendSlice(allocator, "&lt;"),
            '>' => try out.appendSlice(allocator, "&gt;"),
            '&' => try out.appendSlice(allocator, "&amp;"),
            else => try out.append(allocator, b),
        }
    }
}

/// Run the formula rewriter; return the rewritten bytes only when
/// they differ from the original. Caller owns the returned buffer
/// (allocator.free). On byte-identical output we free internally and
/// return null — the splice loop skips it. Helper for
/// `Workbook.rewriteAllValidationsAndConditionalFormats`.
fn maybeRewrite(
    a: Allocator,
    body: []const u8,
    on_sheet: ?[]const u8,
    target_sheet: ?[]const u8,
    sheet_order: ?[]const []const u8,
    edit: zlsx.formula_rewriter.RewriteEdit,
) Error!?[]u8 {
    if (body.len == 0) return null;
    const ctx = zlsx.formula_rewriter.RewriteContext{
        .on_sheet = on_sheet,
        .target_sheet = target_sheet,
        .sheet_order = sheet_order,
        .edit = edit,
    };
    // Decode-in: DV/CF bodies are raw XML inner text and the patch
    // splice re-escapes on emit (`spliceFormulas`). A null return
    // (no-op rewrite) leaves the source bytes — original entity
    // spellings included — untouched.
    const decoded = try store_mod.decodeXmlEntities(a, body);
    const rewritten = zlsx.formula_rewriter.rewriteFormula(a, decoded, ctx) catch |err| {
        a.free(decoded);
        return err;
    };
    const unchanged = std.mem.eql(u8, rewritten, decoded);
    a.free(decoded);
    if (unchanged) {
        a.free(rewritten);
        return null;
    }
    return rewritten;
}

/// The table a cell's BARE structured refs bind to: `scope.table`
/// when the cell sits inside the scoped table's range on its host
/// sheet, null otherwise — the rewriter then leaves bare specifiers
/// alone, matching the engine's owner rule (`vtStructured`).
/// The formula's own cell, for the rewriter's relative-R1C1 parts.
/// A ref the A1 parser cannot read yields null — the rewriter then
/// leaves relative R1C1 untouched rather than guessing. The
/// defined-name and DV/CF sweeps pass no host at all: a defined
/// name's relative R1C1 is anchored to the caller's active cell and
/// a DV/CF formula to its sqref anchor, neither of which this sweep
/// models — absolute R1C1 parts still rewrite there.
fn hostFromRef(ref: []const u8) ?zlsx.formula_rewriter.Host {
    const col = sheet_edit.parseColFromA1(ref) orelse return null;
    const row = sheet_edit.parseRowFromA1(ref) orelse return null;
    return .{ .row = row, .col = col };
}

fn owningTableFor(
    scope: ?Workbook.TableScope,
    sheet_idx: u32,
    ref: []const u8,
) ?[]const u8 {
    const s = scope orelse return null;
    if (s.sheet_idx != sheet_idx) return null;
    const col = sheet_edit.parseColFromA1(ref) orelse return null;
    const row = sheet_edit.parseRowFromA1(ref) orelse return null;
    if (row < s.tl_row or row > s.br_row) return null;
    if (col < s.tl_col or col > s.br_col) return null;
    return s.table;
}

/// Per-formula splice patch in source-byte space. `[start..end]` is
/// the inner-text span of a `<formula1>` / `<formula2>` / `<formula>`
/// element inside the source sheet XML; `new` replaces those bytes.
const SourcePatch = struct { start: usize, end: usize, new: []const u8 };

/// Walk the source sheet XML in document order and locate each
/// formula body whose typed-view counterpart was rewritten. Appends
/// one `SourcePatch` per planned splice. Document order is the
/// invariant linking typed-view indices to source occurrences:
/// `parseValidations` and `parseConditionalFormats` iterate the
/// source linearly without re-ordering, so the Nth `<formula1>`
/// inside `<dataValidations>` corresponds to `view.validations[N]`'s
/// `formula1`, etc.
///
/// Helper used only by
/// `Workbook.rewriteAllValidationsAndConditionalFormats`.
/// Find the next occurrence of a literal closing tag (`</c>`,
/// `</sheetData>`, …) that is REAL markup — comments, CDATA
/// sections, PIs and DOCTYPE blocks are skipped, so a decoy inside
/// `<!-- … -->` can never terminate an element early. Thin wrapper
/// over the workbook scanner's `findClosingTag` that folds its
/// malformed-input error into "not found".
fn findClosingTagAware(source: []const u8, from: usize, close_tag: []const u8) ?usize {
    return workbook_xml_mod.findClosingTag(source, from, close_tag) catch null;
}

/// Collect source-byte patches for rewritten CELL formula bodies:
/// locate each staged `<c r="REF">`'s `<f …>` inner text inside the
/// raw sheet XML and queue the decoded replacement. Only the body
/// bytes are spliced — row attributes (`ht`, `hidden`,
/// `customHeight`, outline levels), cell attributes (`cm`, `vm`,
/// `ph`), `<f>` attributes (`t="shared"`, `si`, `ref`, `t="array"`)
/// and cached `<v>` values all stay byte-identical. Regenerating
/// `sheetData` from the typed view drops everything the model
/// doesn't carry (Codex #188 r5).
///
/// Scanning rides the workbook scanner (`findTagOpen` /
/// `skipNonElement` / `getAttr`): comment/CDATA/PI decoys are
/// skipped and quoted attribute values may contain `>` — a
/// hand-rolled `indexOf` walk patched a decoy `<f>` inside an XML
/// comment while the live formula kept its old bytes
/// (Codex #188 r6).
/// A staged cell-formula replacement: the body bytes the rewrite was
/// derived from, and the decoded rewritten text to splice in.
const CellBodySwap = struct { expected: []const u8, text: []u8 };

fn collectCellFormulaPatches(
    a: Allocator,
    source: []const u8,
    out: *std.ArrayList(SourcePatch),
    new_bodies: *const std.StringHashMapUnmanaged(CellBodySwap),
) Error!void {
    assert(source.len > 0);
    const sd = (workbook_xml_mod.findTagOpen(source, 0, "sheetData") catch
        return error.NoSheetData) orelse return;
    if (sd.self_closing) return;
    const sd_close = findClosingTagAware(source, sd.after_tag_close, "</sheetData>") orelse
        return error.NoSheetData;

    var probe: usize = sd.after_tag_close;
    while (probe < sd_close) {
        const hit = (workbook_xml_mod.findTagOpen(source, probe, "c") catch
            return error.NoSheetData) orelse break;
        if (hit.open_lt >= sd_close) break;
        if (hit.self_closing) {
            // `<c r="…"/>` carries no formula.
            probe = hit.after_tag_close;
            continue;
        }
        const c_close = findClosingTagAware(source, hit.after_tag_close, "</c>") orelse
            return error.NoSheetData;
        const attrs = source[hit.attrs_start..hit.attrs_end];
        if (workbook_xml_mod.getAttr(attrs, "r")) |ref| {
            if (new_bodies.get(ref)) |swap| {
                if (workbook_xml_mod.findTagOpen(source, hit.after_tag_close, "f") catch
                    return error.NoSheetData) |f_hit|
                {
                    if (f_hit.open_lt < c_close and !f_hit.self_closing) {
                        const f_close = findClosingTagAware(source, f_hit.after_tag_close, "</f>") orelse
                            return error.NoSheetData;
                        assert(f_close < c_close);
                        // The located body must still hold the bytes
                        // the rewrite was derived from; a cached view
                        // gone stale (the part was swapped underneath
                        // it) or markup embedded in the body would
                        // otherwise be overwritten with text computed
                        // from something else. Refuse loudly
                        // (Codex #188 r8).
                        if (!std.mem.eql(u8, source[f_hit.after_tag_close..f_close], swap.expected)) {
                            return error.MalformedXml;
                        }
                        try out.append(a, .{
                            .start = f_hit.after_tag_close,
                            .end = f_close,
                            .new = swap.text,
                        });
                    }
                }
            }
        }
        probe = c_close + "</c>".len;
    }
}

fn collectDvCfPatches(
    a: Allocator,
    source: []const u8,
    out: *std.ArrayList(SourcePatch),
    dv_f1_new: *const std.AutoHashMapUnmanaged(usize, []u8),
    dv_f2_new: *const std.AutoHashMapUnmanaged(usize, []u8),
    cf_f_new: *const std.AutoHashMapUnmanaged(usize, []u8),
) Error!void {
    assert(source.len > 0);

    // ─── DV walk ────────────────────────────────────────────────────
    if (dv_f1_new.count() + dv_f2_new.count() > 0) {
        if (std.mem.indexOf(u8, source, "<dataValidations")) |dv_open| {
            const dv_open_gt = std.mem.indexOfScalarPos(u8, source, dv_open, '>') orelse
                return error.NoSheetData;
            const self_closing = dv_open_gt > 0 and source[dv_open_gt - 1] == '/';
            if (!self_closing) {
                const dv_close = std.mem.indexOfPos(u8, source, dv_open_gt, "</dataValidations>") orelse
                    return error.NoSheetData;
                const block_lo = dv_open_gt + 1;
                const block_hi = dv_close;
                var probe: usize = block_lo;
                var dv_idx: usize = 0;
                while (probe < block_hi) {
                    const e_open = std.mem.indexOfPos(u8, source, probe, "<dataValidation") orelse break;
                    if (e_open >= block_hi) break;
                    const after = e_open + "<dataValidation".len;
                    if (after >= source.len) break;
                    const sep = source[after];
                    if (sep != ' ' and sep != '\t' and sep != '\n' and sep != '\r' and sep != '/' and sep != '>') {
                        probe = after;
                        continue;
                    }
                    const e_open_gt = std.mem.indexOfScalarPos(u8, source, e_open, '>') orelse
                        return error.NoSheetData;
                    const e_self_closing = e_open_gt > 0 and source[e_open_gt - 1] == '/';
                    var elem_hi: usize = undefined;
                    if (e_self_closing) {
                        elem_hi = e_open_gt + 1;
                        probe = elem_hi;
                    } else {
                        const e_close = std.mem.indexOfPos(u8, source, e_open_gt, "</dataValidation>") orelse
                            return error.NoSheetData;
                        elem_hi = e_close;
                        probe = e_close + "</dataValidation>".len;

                        const body_lo = e_open_gt + 1;
                        const body_hi = elem_hi;
                        if (dv_f1_new.get(dv_idx)) |new1| {
                            if (findInnerSpan(source, body_lo, body_hi, "<formula1", "</formula1>")) |span| {
                                try out.append(a, .{ .start = span[0], .end = span[1], .new = new1 });
                            }
                        }
                        if (dv_f2_new.get(dv_idx)) |new2| {
                            if (findInnerSpan(source, body_lo, body_hi, "<formula2", "</formula2>")) |span| {
                                try out.append(a, .{ .start = span[0], .end = span[1], .new = new2 });
                            }
                        }
                    }
                    dv_idx += 1;
                }
            }
        }
    }

    // ─── CF walk ────────────────────────────────────────────────────
    if (cf_f_new.count() > 0) {
        var probe: usize = 0;
        var cf_idx: usize = 0;
        while (std.mem.indexOfPos(u8, source, probe, "<conditionalFormatting")) |cf_open| {
            const after = cf_open + "<conditionalFormatting".len;
            if (after >= source.len) break;
            const sep = source[after];
            if (sep != ' ' and sep != '\t' and sep != '\n' and sep != '\r' and sep != '/' and sep != '>') {
                probe = after;
                continue;
            }
            const cf_open_gt = std.mem.indexOfScalarPos(u8, source, cf_open, '>') orelse
                return error.NoSheetData;
            const cf_self_closing = cf_open_gt > 0 and source[cf_open_gt - 1] == '/';
            if (cf_self_closing) {
                probe = cf_open_gt + 1;
                continue;
            }
            const cf_close = std.mem.indexOfPos(u8, source, cf_open_gt, "</conditionalFormatting>") orelse
                return error.NoSheetData;
            const cf_body_lo = cf_open_gt + 1;
            const cf_body_hi = cf_close;
            probe = cf_close + "</conditionalFormatting>".len;

            // Walk each <cfRule> in this group. Each rule advances
            // cf_idx by one, matching parseConditionalFormats's order.
            var r_probe: usize = cf_body_lo;
            while (r_probe < cf_body_hi) {
                const r_open = std.mem.indexOfPos(u8, source, r_probe, "<cfRule") orelse break;
                if (r_open >= cf_body_hi) break;
                const r_after = r_open + "<cfRule".len;
                if (r_after >= source.len) break;
                const r_sep = source[r_after];
                if (r_sep != ' ' and r_sep != '\t' and r_sep != '\n' and r_sep != '\r' and r_sep != '/' and r_sep != '>') {
                    r_probe = r_after;
                    continue;
                }
                const r_open_gt = std.mem.indexOfScalarPos(u8, source, r_open, '>') orelse
                    return error.NoSheetData;
                const r_self_closing = r_open_gt > 0 and source[r_open_gt - 1] == '/';
                if (r_self_closing) {
                    // No body — no formula to splice. Still advance idx.
                    cf_idx += 1;
                    r_probe = r_open_gt + 1;
                    continue;
                }
                const r_close = std.mem.indexOfPos(u8, source, r_open_gt, "</cfRule>") orelse
                    return error.NoSheetData;
                const r_body_lo = r_open_gt + 1;
                const r_body_hi = r_close;
                r_probe = r_close + "</cfRule>".len;

                if (cf_f_new.get(cf_idx)) |new_f| {
                    if (findInnerSpan(source, r_body_lo, r_body_hi, "<formula", "</formula>")) |span| {
                        try out.append(a, .{ .start = span[0], .end = span[1], .new = new_f });
                    }
                }
                cf_idx += 1;
            }
        }
    }
}

/// Locate the inner-text span of `<tag …>BODY</close>` within
/// `source[lo..hi]`. Returns `[body_lo, body_hi]` (the BODY span),
/// or null if either tag is missing in that range. `open_prefix` is
/// the opening-tag prefix without `>` (e.g. "<formula1") so we match
/// both `<formula1>` and `<formula1 attr="…">`. The `<formula` /
/// `<formula1` disambiguation is handled by the caller's choice of
/// `open_prefix` (the search anchors on the literal prefix string).
fn findInnerSpan(
    source: []const u8,
    lo: usize,
    hi: usize,
    open_prefix: []const u8,
    close_tag: []const u8,
) ?[2]usize {
    if (lo >= hi or hi > source.len) return null;
    const slice = source[lo..hi];
    const o_rel = std.mem.indexOf(u8, slice, open_prefix) orelse return null;
    const o_abs = lo + o_rel;
    const o_after = o_abs + open_prefix.len;
    if (o_after >= source.len) return null;
    // `open_prefix` is "<formula" or "<formula1"/"<formula2". The
    // boundary char must be `>`, whitespace, or `/` — otherwise we
    // hit a longer-named element ("<formula1" matched on
    // "<formula12" — guard against this).
    const sep = source[o_after];
    const is_boundary = switch (sep) {
        ' ', '\t', '\r', '\n', '/', '>' => true,
        else => false,
    };
    if (!is_boundary) return null;
    const o_gt = std.mem.indexOfScalarPos(u8, source, o_after, '>') orelse return null;
    if (o_gt >= hi) return null;
    if (o_gt > 0 and source[o_gt - 1] == '/') return null; // self-closing — no body
    const c_rel = std.mem.indexOfPos(u8, source, o_gt + 1, close_tag) orelse return null;
    if (c_rel >= hi) return null;
    return .{ o_gt + 1, c_rel };
}

/// Linear splice of `source` against `patches`. Each patch's
/// `[start..end]` source span is replaced with `new`. Patches arrive
/// in collector-emission order which is NOT guaranteed source-order
/// (OOXML CT_Worksheet places `<conditionalFormatting>` before
/// `<dataValidations>`, but this collector walks DV first). We sort
/// in place by `.start` and assert disjointness.
fn spliceFormulas(
    a: Allocator,
    source: []const u8,
    patches: []SourcePatch,
) Error![]u8 {
    assert(source.len > 0);
    assert(patches.len > 0);

    const lessThan = struct {
        fn lt(_: void, x: SourcePatch, y: SourcePatch) bool {
            return x.start < y.start;
        }
    }.lt;
    std.sort.pdq(SourcePatch, patches, {}, lessThan);

    // Disjointness invariant. A violation implies the collector
    // visited overlapping spans (parser bug or a `formula1`
    // body containing a literal `</formula1>` payload, which OOXML
    // forbids).
    var i: usize = 1;
    while (i < patches.len) : (i += 1) {
        assert(patches[i].start >= patches[i - 1].end);
    }

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(a);
    try out.ensureTotalCapacity(a, source.len + 256);

    var cursor: usize = 0;
    for (patches) |p| {
        assert(p.end <= source.len);
        try out.appendSlice(a, source[cursor..p.start]);
        // The rewriter emits already-formed formula text. It does
        // NOT produce raw `<` / `>` / `&` (the tokenizer prints A1
        // refs and operators only). We still XML-escape on emit so a
        // future rewriter feature that DOES produce one of those
        // bytes can't corrupt the surrounding XML.
        try appendXmlEscapedText(a, &out, p.new);
        cursor = p.end;
    }
    try out.appendSlice(a, source[cursor..]);

    return try out.toOwnedSlice(a);
}

/// ASCII-case-insensitive equality. OOXML cell refs are ASCII letters
/// + decimal digits, so a Unicode-aware fold is unnecessary here.
fn eqlAsciiIgnoreCase(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |ca, cb| {
        if (toAsciiLower(ca) != toAsciiLower(cb)) return false;
    }
    return true;
}

fn toAsciiLower(c: u8) u8 {
    return if (c >= 'A' and c <= 'Z') c + 32 else c;
}

// ─── the EvalEnv adapter (M4b1, goal_engine.md §5.6a) ────────────────
//
// The evaluator reads a workbook through `EvalEnv` and nothing else.
// `src/formula/env.zig` ships the interface and an in-memory fake; this
// is the other implementation, and the only place in the tree where the
// package layer and the engine meet. The direction is fixed: the engine
// never imports `pkg/`, so everything below is the adapter reaching
// down, never the engine reaching up.
//
// What it does, in order:
//
//   1. **Namespace preflight over every part the run will read** —
//      before a byte is decoded and long before anything is mutated. A
//      scanner that literal-matches `<sheetData>` reads a document in an
//      unknown vocabulary as an empty sheet, and recalculating an empty
//      sheet writes zeroes over real data.
//   2. **Decode**, through `engine.decode`: shared strings, then each
//      sheet, carrier class by carrier class.
//   3. **Merge into layers** — stored cells from the part bytes, staged
//      cells from the worksheet's pending deltas, computed cells the run
//      writes back. Precedence is `computed > staged > stored`, exactly
//      as the fake implements it, and the shared test suite is what
//      keeps the two from drifting.

/// A refusal from either half of the boundary. Both halves answer
/// `planeTwo()`, which is what a caller acts on; the payload is kept
/// whole so a diagnostic can say *which* part refused and where.
pub const FormulaRefusal = union(enum) {
    decode: engine.decode.Refusal,
    metadata: engine.metadata.Refusal,
    /// M4b2: the `<f>` attribute inventory, the shared topology, and
    /// the workbook's calc state.
    calc: engine.calc.Refusal,
    /// M4b3: the `CT_DefinedName` and `CT_TableFormula` inventories,
    /// the table producers, and the 3D matrix.
    names: engine.names.Refusal,

    pub fn planeTwo(self: FormulaRefusal) engine.decode.PlaneTwo {
        return switch (self) {
            .decode => |r| r.planeTwo(),
            .metadata => |r| r.planeTwo(),
            .calc => |r| r.planeTwo(),
            .names => |r| r.planeTwo(),
        };
    }
};

// ─── standalone evaluation (§5.6f, M4b3) ─────────────────────────

pub const EvaluateOptions = struct {
    /// §5.4b's fold, injected — the same parameter `FormulaEnvOptions`
    /// takes, for the same reason.
    collation: engine.value.Collation,
    fidelity: engine.value.Fidelity = .excel,
    /// §5.3b. Standalone eval states its dialect; recalc reads each
    /// stored cell's.
    dialect: engine.value.Dialect = .dynamic_array,
    /// Where a site-dependent construct (`@`) is being evaluated.
    /// Absent refuses rather than guessing a row (§5.5).
    site: ?engine.eval.EvalSite = null,
    /// Whether the formula is a declared CSE/DA array formula (§5.6g).
    array_formula: bool = false,
    /// §9's bounds on *modeling the workbook* — cells, parts, depth.
    limits: engine.decode.Limits = .{},
    /// §9's bounds on *the formula* — tokens, nodes, nesting. Two
    /// structs because they bound two different things, and M2 named
    /// the second one before the first existed.
    parse_limits: engine.parser.Limits = .{},
    /// §9's bounds on *work done* — dependency edges, cell evaluations,
    /// closure depth, and M5a2's two iteration ceilings.
    ///
    /// Caller-adjustable in Zig and C only; the CLI and Python fix all
    /// of these at their defaults in v1. The default
    /// `max_scc_iterations` is Excel's own maximum `iterateCount`, so
    /// out of the box this cannot be the bound that fires first — a
    /// caller has to lower it deliberately to make a resource ceiling
    /// beat the workbook's own request (§5.6c).
    work_limits: engine.iterate.WorkLimits = .{},

    // ─── M5d2: the rest of what a run is (§5.5) ──────────────────
    //
    // Five fields and a pointer that a *recalc* has and a standalone
    // cache-based read does not. They default to what `evaluate` and
    // `evaluateClosure` already behaved as, so those two are unchanged;
    // `pkg/recalc_run.zig` is the caller that fills them from a
    // `RunInputs` and from the workbook's own calc state.

    /// The instant `NOW()`/`TODAY()` report. An input, never a clock
    /// read — that is what makes a recalc reproducible from `RunInputs`.
    now_utc_ms: i64 = 0,
    utc_offset_min: i32 = 0,
    /// §5.4b's code page, which `CHAR`/`CODE` resolve through.
    platform_profile: engine.run_inputs.PlatformProfile = .windows_1252,
    /// §5.4d. Workbook-derived: absent compatibility metadata IS CV1.
    text_compat: engine.run_inputs.CompatibilityVersion = .cv1,
    /// §5.4a's epoch. Workbook-derived (`workbookPr@date1904`), never
    /// caller-set in a sense that matters — a caller who changed it
    /// would silently redate every serial in the file.
    date_system: engine.run_inputs.DateSystem = .d1900,
    /// `rng_v1`, seeded from the run, plus §5.6d's memo.
    ///
    /// Null keeps §5.6f's fixed source: a cache-based read must answer
    /// the same call the same way twice, and it has no seed to answer it
    /// from. A recalc does, and volatile determinism is a promise about
    /// that seed rather than about a constant.
    draws: ?*engine.eval.DrawSource = null,
};

/// One evaluation's result, and the arena that owns every byte of it.
pub const Evaluation = struct {
    arena: std.heap.ArenaAllocator,
    value: engine.eval.Value,

    pub fn deinit(self: *Evaluation) void {
        self.arena.deinit();
        self.* = undefined;
    }
};

pub const EvaluateResult = union(enum) {
    ok: Evaluation,
    /// The workbook could not be modeled: a decode, metadata, calc or
    /// name refusal, raised before a byte was evaluated.
    refused: FormulaRefusal,
    /// The formula did not parse (§5.2).
    parse_refused: engine.parser.Refusal,
    /// M5a1: the dependency graph refused. A cycle with iteration off,
    /// a malformed cache seed, a §9 work limit — all statements about
    /// the workbook, raised before a single cell was recomputed.
    graph_refused: engine.graph.Refusal,
    /// M5a2: the iteration engine refused. A caller ceiling that bound
    /// before the workbook's own `iterateCount` (§5.6c), or an outer
    /// loop that never reached a fixpoint (§5.6e). Separate from
    /// `graph_refused` because these are statements about the RUN — the
    /// graph built fine and the schedule is what could not finish — and
    /// because both come with zero mutation, which a caller may want to
    /// rely on by name rather than by plane.
    iteration_refused: engine.iterate.Refusal,
    /// It parsed and the evaluator refused it (§10, plane 2). The two
    /// resolvers' typed reasons ride along, because the plane alone
    /// cannot say *which* name or *which* 3D rule.
    eval_refused: struct {
        plane: engine.decode.PlaneTwo,
        name: ?engine.decode.Refusal = null,
        three_d: ?engine.names.Refusal = null,
    },

    pub fn deinit(self: *EvaluateResult) void {
        switch (self.*) {
            .ok => |*e| e.deinit(),
            else => {},
        }
        self.* = undefined;
    }
};

/// A cache-based read draws nothing that varies. `RAND` is reachable
/// from the registry, so the seam has to answer *something*; answering
/// one fixed number keeps the same call from returning two values in
/// one session, which is the property a cache-based evaluation is for.
/// M5d wires `rng_v1` from `RunInputs`, where a draw has a schedule.
var unreachable_draw: f64 = 0.5;

/// Deep-copy an evaluated value into `a`.
fn cloneEvaluated(a: Allocator, v: engine.eval.Value) Error!engine.eval.Value {
    return switch (v) {
        .scalar => |s| .{ .scalar = try cloneScalar(a, s) },
        .missing_arg => .missing_arg,
        .array => |m| blk: {
            const cells = try a.alloc(engine.value.ScalarValue, m.cells.len);
            for (m.cells, cells) |src, *dst| dst.* = try cloneScalar(a, src);
            break :blk .{ .array = .{ .rows = m.rows, .cols = m.cols, .cells = cells } };
        },
        // `Evaluator.evaluate` dereferences a reference result through
        // §5.3b before returning, so one cannot arrive here.
        .reference => unreachable,
    };
}

/// What a planned cell contributes, WHOLE (M7a): the snapshot §5.8a's
/// placement and §5.6c's convergence both consume. The pre-M7a
/// `scalarOf` narrowed an array to its top-left here, which was the
/// single point every host lost the tails at.
fn snapshotOf(a: Allocator, v: engine.eval.Value) Error!engine.iterate.Snapshot {
    return switch (v) {
        .scalar => |x| .{ .scalar = try cloneScalar(a, x) },
        .missing_arg => .{ .scalar = .blank },
        .array => |m| blk: {
            const out = engine.value.Matrix.init(a, m.rows, m.cols) catch |e| switch (e) {
                error.OutOfMemory => return Error.OutOfMemory,
                // The evaluator built this matrix, so it is non-empty
                // and inside §9's cap by construction.
                error.EmptyMatrix, error.TooManyCells => unreachable,
            };
            for (m.cells, out.cells) |src, *dst| dst.* = try cloneScalar(a, src);
            break :blk .{ .array = out };
        },
        // `Evaluator.evaluate` dereferences a reference result before
        // returning, so one cannot arrive here.
        .reference => unreachable,
    };
}

/// The shape a publication's record keeps (M5d2). §5.7.3's pre-M7 gate
/// refuses a non-1×1 result, and a publication that only carried the
/// top-left would have nothing left to refuse.
fn shapeOf(v: engine.eval.Value) engine.value.Shape {
    return switch (v) {
        .array => |m| m.shape(),
        else => .{ .rows = 1, .cols = 1 },
    };
}

fn cloneScalar(a: Allocator, s: engine.value.ScalarValue) Error!engine.value.ScalarValue {
    return switch (s) {
        .text => |t| .{ .text = try a.dupe(u8, t) },
        else => s,
    };
}

/// `WorkbookEnv` and `SymbolTable`, as the dependency graph sees them.
///
/// The graph module owns no package types by design — `src/formula/`
/// stays free of `pkg/` — so everything it needs about a real workbook
/// arrives through this one struct: plain data for the node set, and a
/// vtable for the three questions a static walk cannot answer from an
/// AST (which sheet a name means, what a spelling binds to, what area a
/// structured reference denotes).
/// Public because M5d2's pipeline lives in `pkg/recalc_run.zig` and needs
/// the same node set `evaluateClosure` builds. A second bridge written
/// there would be a second opinion about which coordinates carry
/// formulas — the recalc would then evaluate a graph the standalone
/// closure disagrees with, and nothing would say so.
pub const GraphBridge = struct {
    model: *WorkbookEnv,
    gpa: Allocator,

    pub fn resolver(self: *GraphBridge) engine.graph.Resolver {
        return .{ .ctx = self, .vtable = &vtable };
    }

    const vtable: engine.graph.Resolver.VTable = .{
        .resolveSheet = vtSheet,
        .resolveName = vtName,
        .resolveStructured = vtStructured,
    };

    fn of(ctx: *anyopaque) *GraphBridge {
        return @ptrCast(@alignCast(ctx));
    }

    /// Every formula-bearing coordinate, every defined name, every table
    /// producer. Allocated into the caller's arena, borrowing the
    /// model's strings — which is why the model has to outlive the
    /// graph, and does.
    /// `records` carries the per-formula-cell array — the run's largest
    /// fixed-size record, sized exactly by a counting pass (M10e). The
    /// recalc path hands it the gpa and frees it with the run; the
    /// evaluate path hands it the same arena as everything else. Either
    /// way the growth ladder the appends used to walk is gone — on an
    /// arena, every doubling's dead buffer stayed resident for the
    /// run's lifetime.
    pub fn buildInput(
        self: *GraphBridge,
        a: Allocator,
        records: Allocator,
    ) Error!engine.graph.Input {
        var cell_count: usize = 0;
        for (self.model.sheets) |sheet| {
            var cur = sheet.start();
            var previous: ?WorkbookEnv.Cell = null;
            while (sheet.at(cur)) |c| : (cur = sheet.next(cur)) {
                const shadowed = if (previous) |p|
                    p.row == c.row and p.col == c.col
                else
                    false;
                previous = c;
                if (shadowed) continue;
                if (c.formula_text == null) continue;
                cell_count += 1;
            }
        }

        const cells = try records.alloc(engine.graph.CellInput, cell_count);
        errdefer records.free(cells);
        var at: usize = 0;
        for (self.model.sheets, 0..) |sheet, i| {
            const idx = engine.env.SheetIndex.fromInt(@intCast(i));
            // Sorted by (row, col, layer descending), so the first entry
            // at a coordinate is the merged one and the rest are shadowed.
            var cur = sheet.start();
            var previous: ?WorkbookEnv.Cell = null;
            while (sheet.at(cur)) |c| : (cur = sheet.next(cur)) {
                const shadowed = if (previous) |p|
                    p.row == c.row and p.col == c.col
                else
                    false;
                previous = c;
                if (shadowed) continue;
                const text = c.formula_text orelse continue;
                // §5.6c (M7a): a dynamic-array cell with NO declared
                // range is a placer whose shape is not file-recoverable
                // — in a cycle it takes the pre-iteration shape pass
                // instead of a scalar seed. A resolver refusal is not
                // decided here: the cell will meet it again at
                // evaluation, where the diagnostic has a home.
                const extra = self.model.extraOf(c);
                const dynamic = extra.array_ref == null and
                    ((self.model.dialectResolver().dialectOf(extra.cm, extra.vm) catch .legacy) == .dynamic_array);
                cells[at] = .{
                    .cell = .{ .sheet = idx, .row = c.row, .col = c.col },
                    .formula = text,
                    .cache = c.cacheState(),
                    .array = extra.array_ref,
                    .dynamic_anchor = dynamic,
                };
                at += 1;
            }
        }
        assert(at == cell_count);

        const names = try a.alloc(engine.graph.NameInput, self.model.symbols.names.len);
        for (self.model.symbols.names, names) |src, *dst| {
            dst.* = .{ .identifier = src.identifier, .body = src.body, .scope = src.scope };
        }

        var producers: std.ArrayList(engine.graph.ProducerInput) = .empty;
        for (self.model.symbols.tables) |t| {
            const geom = geometryOf(t) orelse continue;
            for (t.columns, 0..) |col, i| {
                const sheet_col = coords.Col.fromZeroBased(
                    geom.ref.first.col.zeroBased() + @as(u32, @intCast(i)),
                ) catch continue;
                const both = [_]struct {
                    kind: engine.names.ProducerKind,
                    body: ?[]const u8,
                }{
                    .{ .kind = .calculated_column, .body = col.calculated_formula },
                    .{ .kind = .totals_row, .body = col.totals_formula },
                };
                for (both) |p| {
                    const body = p.body orelse continue;
                    const span = engine.names.producerSpan(
                        p.kind,
                        geom.ref,
                        geom.header_rows,
                        geom.totals_rows,
                        sheet_col,
                    ) orelse continue;
                    try producers.append(a, .{
                        .table = t.name,
                        .column = col.name,
                        .kind = p.kind,
                        .body = body,
                        .span = .{ .sheet = t.sheet, .range = .{
                            .first = .{ .row = span.first_row, .col = span.col },
                            .last = .{ .row = span.last_row, .col = span.col },
                        } },
                    });
                }
            }
        }

        return .{
            .sheet_count = @intCast(self.model.sheets.len),
            .cells = cells,
            .names = names,
            .producers = producers.items,
        };
    }

    /// A table's `ref` is stored raw. A `ref` that will not parse leaves
    /// no geometry to compute against, which is the same answer M4b3's
    /// member check gives it.
    fn geometryOf(t: engine.Table) ?engine.graph.TableGeometry {
        const ref = coords.parseRange(t.ref, .{ .dollar = .accept }) catch return null;
        return .{
            .sheet = t.sheet,
            .ref = ref.normalized(),
            .header_rows = t.header_rows,
            .totals_rows = t.totals_rows,
        };
    }

    fn vtSheet(ctx: *anyopaque, name: []const u8) engine.graph.Error!?engine.env.SheetIndex {
        const self = of(ctx);
        return self.model.symbols.resolveSheet(self.gpa, name);
    }

    fn vtName(
        ctx: *anyopaque,
        from: ?engine.env.SheetIndex,
        spelling: []const u8,
    ) engine.graph.Error!engine.graph.NameBinding {
        const self = of(ctx);
        const table = &self.model.symbols;
        return switch (try table.resolveName(self.gpa, from, spelling)) {
            .name => |ptr| .{ .name = @intCast(ptr - table.names.ptr) },
            // §5.9's table tier. Evaluating one is M7b's; the *edge* is
            // this row's, and the area a bare table name denotes is its
            // data body.
            .table => |t| blk: {
                const geom = geometryOf(t.*) orelse break :blk .unresolved;
                if (t.columns.len == 0) break :blk .unresolved;
                const area = engine.graph.tableArea(
                    geom,
                    .{ .data = true },
                    0,
                    @intCast(t.columns.len - 1),
                    null,
                ) orelse break :blk .unresolved;
                break :blk .{ .area = area };
            },
            // A refused spelling refuses when it is *referenced*; there
            // is no value behind it, so there is nothing to depend on.
            .not_found, .refused => .unresolved,
        };
    }

    fn vtStructured(
        ctx: *anyopaque,
        from: ?engine.env.SheetIndex,
        owner: engine.graph.Owner,
        table: ?[]const u8,
        items: engine.parser.ItemSet,
        columns: engine.parser.ColumnSelector,
    ) engine.graph.Error!?engine.env.RangeRef {
        const self = of(ctx);
        const symbols = &self.model.symbols;

        // The bare `[…]` form names the owner's own table, which only a
        // table producer has.
        const spelling = table orelse switch (owner.key) {
            .producer => |p| p.table,
            else => return null,
        };
        const t = switch (try symbols.resolveName(self.gpa, from, spelling)) {
            .table => |x| x,
            else => return null,
        };
        const geom = geometryOf(t.*) orelse return null;

        const first: u32, const last: u32 = switch (columns) {
            .none => .{ 0, @intCast(t.columns.len -| 1) },
            .one => |raw| blk: {
                const i = (try self.columnIndex(t.*, raw)) orelse return null;
                break :blk .{ i, i };
            },
            .range => |r| blk: {
                const x = (try self.columnIndex(t.*, r.first)) orelse return null;
                const y = (try self.columnIndex(t.*, r.last)) orelse return null;
                break :blk .{ x, y };
            },
        };
        if (t.columns.len == 0) return null;
        return engine.graph.tableArea(
            geom,
            items,
            first,
            last,
            if (owner.site) |c| c.row else null,
        );
    }

    /// A structured reference keeps its column names raw, with the `'`
    /// escapes intact. Decoding then folding is what the symbol layer
    /// matched on when it built the table, so it is what has to happen
    /// here too.
    fn columnIndex(
        self: *GraphBridge,
        t: engine.Table,
        raw: []const u8,
    ) engine.graph.Error!?u32 {
        const decoded = try engine.parser.decodeColumnName(self.gpa, raw);
        defer self.gpa.free(decoded);
        const folded = self.model.symbols.fold(self.gpa, decoded) catch |e| {
            if (e == error.OutOfMemory) return error.OutOfMemory;
            return null;
        };
        defer self.gpa.free(folded);
        return t.columnIndex(folded);
    }
};

pub const FormulaEnvOptions = struct {
    /// §5.4b's fold, injected rather than imported — `value.zig` keeps
    /// the concrete table out of the engine's non-test build, and this
    /// adapter is a caller like any other.
    collation: engine.value.Collation,
    fidelity: engine.value.Fidelity = .excel,
    limits: engine.decode.Limits = .{},
};

pub const WorkbookEnvBuild = union(enum) {
    ok: WorkbookEnv,
    refused: FormulaRefusal,
};

/// One workbook, as the evaluator sees it.
pub const WorkbookEnv = struct {
    allocator: Allocator,
    workbook: *Workbook,
    /// Owns every cell and every decoded string the model kept.
    ///
    /// A `fill.Arena` rather than a bare `ArenaAllocator` so §9.1 M10q's
    /// probe can read the bytes handed *out* of it, not just the chunks
    /// it requested — the two diverge, and for this arena M10p measured
    /// the divergence at 1.57 MB. Costs nothing when no tally is
    /// installed (`pkg/fill.zig`).
    arena: fill_probe.Arena,
    sheets: []Sheet,
    strings: engine.decode.Strings,
    symbols: engine.SymbolTable,
    meta: engine.metadata.Metadata,
    dialects: engine.metadata.CellDialectResolver,
    fidelity: engine.value.Fidelity,
    /// §5.7.6, read from `xl/workbook.xml` before any sheet is scanned
    /// — `date1904` decides what a `t="d"` `<v>` *is*, so it cannot be
    /// discovered halfway through. Every slice in it borrows the part
    /// bytes, which the `PartStore` owns for the workbook's lifetime.
    calc: engine.calc.CalcState,
    /// `<sheetCalcPr>` per worksheet, in workbook order.
    sheet_calc: []engine.calc.SheetCalcPr,
    /// §5.8a (M7a): the per-anchor spill outcomes. What `spillShape`
    /// answers — a blocked anchor has NO extent, so `A1#` against it is
    /// `#REF!` — and what tells the `#SPILL!` classes apart. The map's
    /// storage is the model arena's; rollback empties it entry by entry
    /// through `retractResult`.
    spills: engine.spill.Registry = .{},
    /// Per sheet, the merged ranges the decode boundary produced —
    /// §5.8a's merge row.
    sheet_merges: [][]const coords.Range,
    /// Per sheet, the declared table rectangles — §5.8a's table row.
    sheet_tables: [][]const coords.Range,
    /// Per sheet, the accepted scan's exact list sizes (§9.1 M10l) —
    /// replayed as `decode.Options.size_hints` when staging re-scans
    /// the same bytes, so the re-scan's record lists allocate once
    /// instead of walking the doubling ladder at the peak instant.
    sheet_scan_counts: []engine.decode.SizeHints,
    /// The `Extra` records `Cell.extra` indexes, in the model arena.
    /// Append-only for the model's lifetime: a replaced cell abandons
    /// its entry rather than reclaiming it, which costs nothing an
    /// arena would give back and keeps every live index valid.
    extras: std.ArrayListUnmanaged(Extra) = .empty,

    /// §9.1 M10r: publish by overwriting the formula record's value
    /// instead of laying a second `Cell` over it.
    ///
    /// Off by default, and it must stay off for every host that can
    /// retract. The two records the drive kept at each formula cell were
    /// never both *read*: the computed one shadowed the stored one for
    /// every merged read, and the stored one answered `formulaAt`,
    /// `dialectOf` and `svOccupied` from fields the computed record does
    /// not carry. Overwriting `v` on the record that already holds
    /// `layer`, `formula_text`, `cache` and `extra` gives every one of
    /// those readers the same answer from one record.
    ///
    /// **The cost is retraction, and it is not negotiable.** The
    /// overwritten value is gone; `retractResult` can uncover a lower
    /// layer but cannot restore an overwritten one, and the engine's
    /// journal holds only `CellRef`. So a host that sets this must
    /// discard the whole model on refusal — `iterate.Options.retraction
    /// = .candidate_discard` — which is exactly what `recalc_run`'s
    /// per-run `WorkbookEnv` already does at `defer model.deinit()`.
    /// `retractResult` asserts the pairing rather than trusting it.
    publish_in_place: bool = false,

    /// `Cell.v`'s optional, in band.
    ///
    /// `?ScalarValue` costs 40 bytes to carry 32 of content: the payload
    /// is eight-aligned, so the presence flag cannot share the union's
    /// tag word and opens a new one instead. Absence is a sixth case of
    /// that tag here — the idiom `Target.no_fref` and M10n's `OptSpan`
    /// already use, and it pays for the same reason `Extra` did: `Cell`
    /// is the run's most-multiplied record, so eight bytes is 1.4 MB at
    /// the drive's peak instant (§9.1 M10p).
    ///
    /// **`absent` is not `blank`.** Absent is the coordinate being
    /// *occupied by something with no value* — an uncached formula, a
    /// staged blank, a staged deletion — which shadows lower layers
    /// while contributing nothing to the merged view. `blank` is a
    /// value. This is the same distinction `ScalarValue`'s own doc
    /// comment protects, held one level up.
    pub const OptValue = union(enum) {
        absent,
        number: f64,
        text: []const u8,
        boolean: bool,
        err: engine.value.ErrorValue,
        blank,

        /// The `?ScalarValue` this stands for.
        pub fn get(self: OptValue) ?engine.value.ScalarValue {
            return switch (self) {
                .absent => null,
                .number => |n| .{ .number = n },
                .text => |t| .{ .text = t },
                .boolean => |b| .{ .boolean = b },
                .err => |e| .{ .err = e },
                .blank => .blank,
            };
        }

        /// What the merged view reads: a coordinate holding no value
        /// contributes `blank` to it.
        pub fn orBlank(self: OptValue) engine.value.ScalarValue {
            return self.get() orelse .blank;
        }

        /// The `CacheTag` a record holding this value must carry.
        ///
        /// `.blank` maps to `.absent` for the same reason `dupeValue`
        /// folds it: a blank contributes no cached number to seed from,
        /// and the seed table reads `.absent` as "start from zero".
        pub fn cacheTag(self: OptValue) CacheTag {
            return switch (self) {
                .absent, .blank => .absent,
                .number => .number,
                .text => .text,
                .boolean => .boolean,
                .err => .err,
            };
        }
    };

    /// `graph.CacheState`'s tag, without its `number` payload.
    ///
    /// **The payload is an f64 the record already holds.** `v` and
    /// `cache` are both derived from the same `decode.InputCell` at the
    /// one site that builds a stored cell, so a `.number` cache is
    /// always the `.number` in `v` — the same number, not merely the
    /// same type. Carrying it twice cost 15 of `CacheState`'s 16 bytes
    /// on the run's most-multiplied record (§9.1 M10s).
    ///
    /// **The tag stays, because the tag is not derivable.** `.absent` is
    /// what both a missing `<v>` and a genuine blank read as, and
    /// §5.6c's seed table has to tell those apart from a cached value;
    /// `v` alone cannot say which of them a record came from.
    pub const CacheTag = enum(u8) { number, text, boolean, err, absent, malformed };

    /// One coordinate in one layer. `v` is `.absent` when the coordinate
    /// is *occupied by something with no value*: an uncached formula, a
    /// staged blank, a staged deletion. That is not the same as a blank
    /// value and not the same as an absent cell — it shadows lower
    /// layers while contributing nothing to the merged view.
    pub const Cell = struct {
        row: coords.Row,
        col: coords.Col,
        layer: engine.env.Layer,
        v: OptValue,
        /// Decoded `<f>` body (FORMULA carrier), when the cell has one.
        formula_text: ?[]const u8 = null,
        /// What the `<v>` was, as §5.6c's seed table sees it — the tag
        /// only. `cacheState` puts the number back; see `CacheTag`.
        cache: CacheTag = .absent,
        /// Index into the model's `extras`, or `no_extra`. See `Extra`.
        extra: u32 = no_extra,

        /// Absence, as an index no `extras` entry can occupy — the same
        /// idiom as `Target.no_fref` and `OptSpan`'s `end < start`.
        pub const no_extra: u32 = std.math.maxInt(u32);

        /// The `graph.CacheState` this record stands for.
        ///
        /// `.number`'s payload comes back out of `v`, which is the only
        /// place it was ever stored twice. Two writers keep the pairing
        /// and there are no others: the decode site sets `v` and `cache`
        /// from one `InputCell`, and `putComputed`'s in-place overwrite
        /// re-tags as it writes.
        ///
        /// The `else` arm is unreachable, not a fallback: a wrong seed
        /// is a wrong number, whereas reading `v.number` off a record
        /// holding text is a misread union. The assertion is the real
        /// answer; the arm only decides which of the two a build with
        /// assertions off gets.
        pub fn cacheState(self: Cell) engine.graph.CacheState {
            return switch (self.cache) {
                .number => blk: {
                    assert(self.v == .number);
                    break :blk if (self.v == .number)
                        .{ .number = self.v.number }
                    else
                        .absent;
                },
                .text => .text,
                .boolean => .boolean,
                .err => .err,
                .absent => .absent,
                .malformed => .malformed,
            };
        }
    };

    /// The rare half of a cell.
    ///
    /// `cm`/`vm` are zero and both refs are null on every cell of a
    /// workbook that uses neither cell metadata, nor legacy CSE arrays,
    /// nor spilling — which is most of them, and all of §9's workloads.
    /// Inline they cost 52 bytes on every entry; behind an index they
    /// cost four, and 52 only on the cells that carry one. `Cell` is the
    /// run's most-multiplied record — one per coordinate per layer, and
    /// the drive publishes a second one at every formula cell — so the
    /// per-entry width is what the model's footprint is made of (§9.1
    /// M10o).
    pub const Extra = struct {
        cm: u32 = 0,
        vm: u32 = 0,
        /// A legacy CSE array's declared range (M5a1's spill tails).
        array_ref: ?coords.Range = null,
        /// §5.8a: a `.spill_tail` entry records the anchor that placed
        /// it. Ownership is per cell, not inferred from geometry —
        /// shrink clears exactly the tails carrying this anchor, and a
        /// foreign tail obstructs because this field names someone else.
        spill_anchor: ?engine.env.CellRef = null,
    };

    /// Sorted by (row, col, layer descending), so a merged read is the
    /// first hit of a binary search rather than a scan — the same
    /// invariant `env.Fake` keeps, for the same reason.
    ///
    /// **The order is the contract; the storage is not.** Held as a
    /// directory of bounded chunks rather than one flat array, because a
    /// flat array pays one `memmove` of everything past the insertion
    /// point per published cell — quadratic in the sheet's cell count,
    /// and 42 % of §9.1's M5d3 baseline. A chunk bounds that move to
    /// `chunk_cap` entries no matter how large the sheet is, so
    /// publication is O(1) in the cell count. Every reader still walks
    /// exactly one ascending sequence, and it is the same sequence.
    pub const Sheet = struct {
        /// Non-empty chunks, in key order, addressed by pointer. A split
        /// inserts here too; moving eight bytes per chunk is what keeps
        /// the split from re-introducing the term it exists to remove.
        chunks: std.ArrayListUnmanaged(*Chunk) = .empty,

        /// Insertion moves at most `chunk_cap` entries and, amortised,
        /// `2·len/chunk_cap²` directory slots. The sum is flattest
        /// around 64 at the sizes §9 measures, and 64 keeps a chunk
        /// inside a handful of cache lines besides.
        const chunk_cap = 64;

        pub const Chunk = struct {
            items: [chunk_cap]Cell,
            len: usize,
        };

        /// A position in key order. `chunk == chunks.len` is the end,
        /// and is the only position `at` answers null for: a chunk is
        /// dropped the moment it empties, so `off` always addresses a
        /// live entry.
        pub const Cursor = struct {
            chunk: u32 = 0,
            off: u32 = 0,
        };

        fn start(_: Sheet) Cursor {
            return .{};
        }

        fn end(self: Sheet) Cursor {
            return .{ .chunk = @intCast(self.chunks.items.len), .off = 0 };
        }

        fn at(self: Sheet, c: Cursor) ?Cell {
            if (c.chunk >= self.chunks.items.len) return null;
            const ch = self.chunks.items[c.chunk];
            assert(c.off < ch.len);
            return ch.items[c.off];
        }

        fn next(self: Sheet, c: Cursor) Cursor {
            if (c.chunk >= self.chunks.items.len) return c;
            const ch = self.chunks.items[c.chunk];
            if (c.off + 1 < ch.len) return .{ .chunk = c.chunk, .off = c.off + 1 };
            return .{ .chunk = c.chunk + 1, .off = 0 };
        }

        /// `EvalEnv`'s aligned-iterator cursors are a `[]usize` the
        /// implementation owns the meaning of, so a two-part position
        /// travels through one packed into two halves. `maxInt(usize)`
        /// stays the caller's "not positioned yet" sentinel: it decodes
        /// to a chunk index `max_modeled_cells` cannot reach.
        fn pack(c: Cursor) usize {
            return (@as(usize, c.chunk) << 32) | @as(usize, c.off);
        }

        fn unpack(x: usize) Cursor {
            return .{ .chunk = @intCast(x >> 32), .off = @intCast(x & 0xffff_ffff) };
        }

        /// The first position whose entry is not less than the key.
        fn lowerBound(
            self: Sheet,
            row: coords.Row,
            col: coords.Col,
            layer: engine.env.Layer,
        ) Cursor {
            var lo: usize = 0;
            var hi: usize = self.chunks.items.len;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                const ch = self.chunks.items[mid];
                if (lessThanKey(ch.items[ch.len - 1], row, col, layer)) lo = mid + 1 else hi = mid;
            }
            if (lo >= self.chunks.items.len) return self.end();

            const ch = self.chunks.items[lo];
            var a: usize = 0;
            var b: usize = ch.len;
            while (a < b) {
                const mid = a + (b - a) / 2;
                if (lessThanKey(ch.items[mid], row, col, layer)) a = mid + 1 else b = mid;
            }
            // The chunk was chosen because its last entry is not less
            // than the key, so the position is inside it.
            assert(a < ch.len);
            return .{ .chunk = @intCast(lo), .off = @intCast(a) };
        }

        /// Append an entry that sorts after everything already held —
        /// the decode path's row-major run, which needs no search.
        fn append(self: *Sheet, alloc: Allocator, c: Cell) Allocator.Error!void {
            if (self.chunks.items.len > 0) {
                const last = self.chunks.items[self.chunks.items.len - 1];
                assert(lessThanKey(last.items[last.len - 1], c.row, c.col, c.layer));
                if (last.len < chunk_cap) {
                    last.items[last.len] = c;
                    last.len += 1;
                    return;
                }
            }
            try self.openChunk(alloc, c);
        }

        /// Open a chunk past the end of the directory, holding `c`.
        fn openChunk(self: *Sheet, alloc: Allocator, c: Cell) Allocator.Error!void {
            try self.chunks.ensureUnusedCapacity(alloc, 1);
            const ch = try alloc.create(Chunk);
            ch.* = .{ .items = undefined, .len = 1 };
            ch.items[0] = c;
            self.chunks.appendAssumeCapacity(ch);
        }

        /// Insert or replace one cell in one layer, keeping the ordering
        /// invariant by construction — there is no code path that could
        /// return cells in insertion order, because there is no
        /// insertion order.
        fn insert(self: *Sheet, alloc: Allocator, c: Cell) Allocator.Error!void {
            const cur = self.lowerBound(c.row, c.col, c.layer);
            if (self.at(cur)) |existing| {
                if (existing.row == c.row and existing.col == c.col and existing.layer == c.layer) {
                    self.chunks.items[cur.chunk].items[cur.off] = c;
                    return;
                }
            }

            if (self.chunks.items.len == 0) return self.openChunk(alloc, c);

            // Past the last entry: the tail of the last chunk is the
            // same position in key order, and reusing it keeps an
            // ascending run filling one chunk instead of opening one per
            // entry.
            var ci: usize = cur.chunk;
            var off: usize = cur.off;
            if (ci >= self.chunks.items.len) {
                ci = self.chunks.items.len - 1;
                off = self.chunks.items[ci].len;
            }

            if (self.chunks.items[ci].len == chunk_cap) {
                try self.split(alloc, ci);
                const left = self.chunks.items[ci].len;
                // A position at the boundary belongs to either half; the
                // left one is never full after a split, so take it.
                if (off > left) {
                    off -= left;
                    ci += 1;
                }
            }

            const ch = self.chunks.items[ci];
            assert(ch.len < chunk_cap);
            assert(off <= ch.len);
            std.mem.copyBackwards(Cell, ch.items[off + 1 .. ch.len + 1], ch.items[off..ch.len]);
            ch.items[off] = c;
            ch.len += 1;
        }

        fn split(self: *Sheet, alloc: Allocator, ci: usize) Allocator.Error!void {
            // Capacity first: a directory that could not grow would
            // leave the right half allocated and unreachable, which is
            // the one way a split can lose cells.
            try self.chunks.ensureUnusedCapacity(alloc, 1);
            const left = self.chunks.items[ci];
            const half = left.len / 2;
            assert(half > 0 and half < left.len);
            const right = try alloc.create(Chunk);
            right.* = .{ .items = undefined, .len = left.len - half };
            @memcpy(right.items[0..right.len], left.items[half..left.len]);
            left.len = half;
            self.chunks.insertAssumeCapacity(ci + 1, right);
        }

        fn removeAt(self: *Sheet, cur: Cursor) void {
            const ch = self.chunks.items[cur.chunk];
            assert(cur.off < ch.len);
            std.mem.copyForwards(
                Cell,
                ch.items[cur.off .. ch.len - 1],
                ch.items[cur.off + 1 .. ch.len],
            );
            ch.len -= 1;
            if (ch.len == 0) _ = self.chunks.orderedRemove(cur.chunk);
        }
    };

    pub fn deinit(self: *WorkbookEnv) void {
        self.symbols.deinit();
        self.strings.deinit();
        self.meta.deinit(self.allocator);
        self.calc.deinit(self.allocator);
        self.arena.deinit();
        self.* = undefined;
    }

    /// Build the model. Returns a refusal rather than an error for
    /// anything that is a statement about the workbook; `Error` is
    /// reserved for allocation and for a package that is missing parts
    /// its own manifest promises.
    pub fn build(
        allocator: Allocator,
        wb: *Workbook,
        opts: FormulaEnvOptions,
    ) Error!WorkbookEnvBuild {
        // Phase 1: preflight. Nothing below this line runs against a
        // part whose vocabulary we have not recognized.
        if (try preflightParts(wb, opts.limits)) |r| return .{ .refused = .{ .decode = r } };

        var keep = false;

        var strings = switch (try decodeStrings(allocator, wb, opts)) {
            .ok => |s| s,
            .refused => |r| return .{ .refused = .{ .decode = r } },
        };
        defer if (!keep) strings.deinit();

        var meta = switch (try decodeMetadata(allocator, wb)) {
            .ok => |m| m,
            .refused => |r| return .{ .refused = .{ .metadata = r } },
        };
        defer if (!keep) meta.deinit(allocator);

        // §5.7.6 before §5.7.1: `date1904` decides what a `t="d"`
        // `<v>` means, so the calc state is read before the first sheet
        // rather than alongside them. Its slices borrow the part bytes.
        const wb_part = (try wb.store.part("xl/workbook.xml")) orelse
            return Error.MissingWorkbookPart;
        var calc = switch (try engine.calc.parseCalcState(allocator, wb_part.bytes)) {
            .ok => |c| c,
            .refused => |r| return .{ .refused = .{ .calc = r } },
        };
        defer if (!keep) calc.deinit(allocator);

        var arena: fill_probe.Arena = .init(allocator, .model);
        defer if (!keep) arena.deinit();
        const a = arena.allocator();

        const sheets = try a.alloc(Sheet, wb.worksheets.len);
        for (sheets) |*s| s.* = .{};
        const sheet_calc = try a.alloc(engine.calc.SheetCalcPr, wb.worksheets.len);
        for (sheet_calc) |*s| s.* = .{};
        // §5.8a's geometry (M7a): merges from the decode boundary,
        // table rectangles from the parts the loop below already reads.
        const sheet_merges = try a.alloc([]const coords.Range, wb.worksheets.len);
        for (sheet_merges) |*m| m.* = &.{};
        const sheet_tables = try a.alloc([]const coords.Range, wb.worksheets.len);
        for (sheet_tables) |*t| t.* = &.{};
        const sheet_scan_counts = try a.alloc(engine.decode.SizeHints, wb.worksheets.len);
        for (sheet_scan_counts) |*c| c.* = .{ .cells = 0, .slots = 0, .rows = 0 };
        var extras: std.ArrayListUnmanaged(Extra) = .empty;

        var builder = engine.Builder.init(allocator, opts.collation);
        defer builder.deinit();
        for (wb.workbook.sheets) |s| try builder.addSheet(s.name);

        // M4b3: the names come from the part, not from `definedNames()`.
        // The typed view keeps four fields and drops the attribute
        // region (`workbook_xml.zig:58-68`), and the attribute region is
        // exactly what the `CT_DefinedName` inventory is about — three
        // of the twelve dropped attributes mean the name is a macro
        // entry point rather than a value.
        var defined = switch (try engine.names.scanDefinedNames(allocator, wb_part.bytes)) {
            .ok => |d| d,
            .refused => |r| return .{ .refused = .{ .names = r } },
        };
        defer defined.deinit();
        for (defined.rows) |dn| {
            try builder.addName(dn.raw_identifier, dn.raw_body, .{
                .scope = if (dn.local_sheet_id) |id| engine.env.SheetIndex.fromInt(id) else null,
                .hidden = dn.hidden,
                .attr_refusal = dn.refusal_when_referenced,
            });
        }

        // §9's `max_modeled_cells` bounds the whole model, so each
        // sheet is scanned against what the sheets before it left.
        var cell_budget: u32 = opts.limits.max_modeled_cells;
        for (0..wb.worksheets.len) |i| {
            const idx: u32 = @intCast(i);
            const ws = try wb.sheet(idx);
            const part_name = try ws.resolvePartName();
            const part = (try wb.store.part(part_name)) orelse return Error.MissingSheetPart;

            var sheet_limits = opts.limits;
            sheet_limits.max_modeled_cells = cell_budget;
            var scanned = switch (try engine.decode.scanSheet(allocator, part.bytes, strings.items, .{
                .limits = sheet_limits,
                .fidelity = opts.fidelity,
                .date_system = calc.date_system,
            })) {
                .ok => |s| s,
                .refused => |r| return .{ .refused = .{ .decode = r } },
            };
            defer scanned.deinit();
            cell_budget -= @intCast(scanned.cells.len);
            sheet_merges[idx] = try a.dupe(coords.Range, scanned.merges);
            // Each count fits u32: a slot or row is at least four part
            // bytes and a part is capped at u32 bytes.
            sheet_scan_counts[idx] = .{
                .cells = @intCast(scanned.cells.len),
                .slots = @intCast(scanned.slots.len),
                .rows = @intCast(scanned.rows.len),
            };

            sheet_calc[idx] = switch (engine.calc.parseSheetCalcPr(part.bytes)) {
                .ok => |c| c,
                .refused => |r| return .{ .refused = .{ .calc = r } },
            };

            // §9.1g M10x: what stands beside the list `sharedFormulaText`
            // is about to grow. Recorded here because the scan's blocks
            // are this scope's, not that function's.
            if (engine.calc.census_sink) |c| {
                c.scan_cells_bytes = scanned.cells.len * @sizeOf(engine.decode.SheetCell);
                c.scan_slots_bytes = scanned.slots.len * @sizeOf(engine.decode.CellSlot);
                c.scan_rows_bytes = scanned.rows.len * @sizeOf(engine.decode.RowSlot);
                c.sheet_xml_bytes = part.bytes.len;
            }

            // M4b2: the `<f>` attribute inventory and the shared
            // topology, over the cells the boundary just produced. A
            // slave's formula is its master's, translated — which is why
            // this runs before the cells are copied into the layer and
            // not after.
            const formulas = switch (try sharedFormulaText(
                allocator,
                a,
                scanned.cells,
                scanned.formula_cells,
            )) {
                .ok => |f| f,
                .refused => |r| return .{ .refused = .{ .calc = r } },
            };
            defer allocator.free(formulas);

            // Stored cells arrive row-major already, so appending keeps
            // the ordering invariant without a sort.
            for (scanned.cells, formulas) |c, f| {
                // The common cell carries no metadata and no array
                // range, and pays four bytes for saying so.
                const extra: u32 = if (c.cm == 0 and c.vm == 0 and f.array == null)
                    Cell.no_extra
                else
                    try appendExtra(&extras, a, .{ .cm = c.cm, .vm = c.vm, .array_ref = f.array });
                try sheets[idx].append(a, .{
                    .row = c.row,
                    .col = c.col,
                    .layer = .stored,
                    .v = try dupeValue(a, c.input.scalar(), c.input == .uncached),
                    .formula_text = f.text,
                    .cache = cacheTagOf(c.input),
                    .extra = extra,
                });
            }

            // Tables live in their own parts, reached through the
            // sheet's `<tableParts>` rels.
            var table_ranges: std.ArrayListUnmanaged(coords.Range) = .empty;
            var rids = TablePartRidIterator.init(part.bytes);
            const rels = wb.store.rels(part_name);
            while (rids.next()) |rid| {
                const target = relTargetForId(rels, rid) orelse continue;
                const table_name = (try wb.store.resolve(part_name, target)) orelse continue;
                const table_part = (try wb.store.part(table_name)) orelse continue;
                var table = switch (try engine.decode.scanTable(allocator, table_part.bytes, .{
                    .limits = opts.limits,
                    .fidelity = opts.fidelity,
                })) {
                    .ok => |t| t,
                    .refused => |r| return .{ .refused = .{ .decode = r } },
                };
                defer table.deinit();
                // M4b3: a table's producers, and the members they must
                // have been materialized into. A calculated column that
                // one data cell has no `<f>` for is a column this
                // engine would recalculate as a blank.
                if (try checkTableProducers(table, scanned.cells, formulas)) |r| {
                    return .{ .refused = .{ .names = r } };
                }
                // §5.8a's table row wants the rectangle. The spelling
                // the symbol layer refuses is refused THERE — a range
                // this parse cannot read is simply not a rectangle a
                // spill can meet.
                if (coords.parseRange(table.ref, .{ .dollar = .accept })) |r| {
                    try table_ranges.append(a, r.normalized());
                } else |_| {}
                try builder.addTable(engine.env.SheetIndex.fromInt(idx), table);
            }
            sheet_tables[idx] = try table_ranges.toOwnedSlice(a);

            // Staged deltas are the second layer. `setCell` has already
            // validated the ref, so a delta that will not parse here is
            // a bookkeeping bug, not a workbook statement.
            var it = ws.deltas.iterator();
            while (it.next()) |entry| {
                const ref = entry.key_ptr.*;
                const row = coords.Row.fromOneBased(ref.row) catch continue;
                const col = coords.Col.fromOneBased(ref.col) catch continue;
                const staged = try stagedCell(a, row, col, entry.value_ptr.*);
                try sheets[idx].insert(a, staged);
            }
        }

        var symbols = switch (try builder.finish()) {
            .ok => |t| t,
            .refused => |r| return .{ .refused = .{ .decode = r } },
        };
        defer if (!keep) symbols.deinit();

        keep = true;
        var out: WorkbookEnv = .{
            .allocator = allocator,
            .workbook = wb,
            .arena = arena,
            .sheets = sheets,
            .strings = strings,
            .symbols = symbols,
            .meta = meta,
            .dialects = undefined,
            .fidelity = opts.fidelity,
            .calc = calc,
            .sheet_calc = sheet_calc,
            .sheet_merges = sheet_merges,
            .sheet_tables = sheet_tables,
            .extras = extras,
            .sheet_scan_counts = sheet_scan_counts,
        };
        out.dialects = .{ .part = &out.meta, .role = .input };
        return .{ .ok = out };
    }

    /// Re-seat the interior pointer the dialect resolver holds.
    ///
    /// `build` returns by value, so the `WorkbookEnv` the caller ends up
    /// holding is at a different address than the one that was
    /// constructed — and `CellDialectResolver.part` points *into* it.
    /// Every accessor that needs the resolver calls this first rather
    /// than trusting an address that was correct in another stack frame.
    fn dialectResolver(self: *WorkbookEnv) engine.env.DialectResolver {
        self.dialects.part = &self.meta;
        return self.dialects.resolver();
    }

    /// The refusal a `dialectOf` call turned into `error.MetadataRefused`,
    /// if any. The env interface can only say "the read failed"; the
    /// precise plane travels here (M4a decision 17).
    pub fn lastDialectRefusal(self: *const WorkbookEnv) ?engine.metadata.Refusal {
        return self.dialects.last_refusal;
    }

    /// The decoded `<f>` body at a coordinate, or null when the cell has
    /// no engine. Not part of `EvalEnv` — the evaluator reads *values*
    /// through the interface; formulas are the model builder's business
    /// (M5a) and this is where it will get them.
    /// The formula body at a coordinate, from whichever layer carries
    /// one.
    ///
    /// **Not** the merged read, and the difference is the difference
    /// between a body and a value. A computed layer entry is a value the
    /// run produced; it shadows lower layers for `cellValue` because
    /// that is what "computed > staged > stored" means, and it carries
    /// no `<f>` because a run does not author formulas. Asking the
    /// merged view for a body therefore returns null the moment anything
    /// publishes at that coordinate — which M5a1 could never observe,
    /// since it evaluated each cell exactly once and published after.
    /// M5a2 evaluates the same cell once per pass, and the second pass
    /// would have found no formula to run.
    pub fn formulaAt(self: *WorkbookEnv, cell: engine.env.CellRef) engine.env.Error!?[]const u8 {
        const sheet = try self.sheetConst(cell.sheet);
        var at = sheet.lowerBound(cell.row, cell.col, .computed);
        while (sheet.at(at)) |c| : (at = sheet.next(at)) {
            if (c.row != cell.row or c.col != cell.col) break;
            if (c.formula_text) |t| return t;
        }
        return null;
    }

    /// Whether a coordinate holds a formula cell whose cached value is
    /// absent (§5.6c seeds it, §5.6f reads it as blank).
    pub fn isUncached(self: *WorkbookEnv, cell: engine.env.CellRef) engine.env.Error!bool {
        const sheet = try self.sheetConst(cell.sheet);
        const m = merged(sheet, cell.row, cell.col) orelse return false;
        return m.v == .absent and m.formula_text != null;
    }

    /// The rare fields of one cell. A cell with no `Extra` reads as the
    /// all-default record, so callers never branch on the index.
    pub fn extraOf(self: *const WorkbookEnv, c: Cell) Extra {
        if (c.extra == Cell.no_extra) return .{};
        return self.extras.items[c.extra];
    }

    /// Append one `Extra` and return the index that names it.
    ///
    /// The list holds at most `Cell.no_extra` entries, because the
    /// sentinel *is* an index: the entry that landed on it would be
    /// indistinguishable from "this cell has no extra" and would read
    /// back as the all-default record — a spill anchor or an array
    /// range lost with no diagnostic. Refusing is the only honest
    /// answer, and it costs one compare on a path that runs once per
    /// rare cell.
    fn appendExtra(
        list: *std.ArrayListUnmanaged(Extra),
        a: Allocator,
        e: Extra,
    ) Allocator.Error!u32 {
        if (list.items.len >= Cell.no_extra) return error.OutOfMemory;
        try list.append(a, e);
        return @intCast(list.items.len - 1);
    }

    /// Write a value computed earlier in this run. The `.computed`
    /// layer shadows both others, which is what makes `C1=SUM(A1:B2)`
    /// read a 2×2 this run produced rather than the stale cache.
    pub fn putComputed(
        self: *WorkbookEnv,
        sheet: engine.env.SheetIndex,
        row: coords.Row,
        col: coords.Col,
        v: engine.value.ScalarValue,
    ) engine.env.Error!void {
        const s = try self.sheetMut(sheet);
        const a = self.arena.allocator();
        if (self.publish_in_place and v != .blank) {
            if (inPlaceTarget(s, row, col)) |cur| {
                // `layer` is the identity of the record in key order and
                // moving it would reorder the coordinate; `formula_text`
                // and `extra` are read *after* publication — by
                // `formulaAt` and `dialectOf` — and a computed record
                // never carried them, so preserving them is what makes
                // one record answer for two. Duped first: a failure must
                // not leave the record half-written.
                //
                // `cache` is re-tagged rather than preserved (§9.1
                // M10s). It no longer carries its own f64: `cacheState`
                // reads that out of `v`, so a `cache` left saying
                // `.number` over a `v` this run just made text would
                // describe a record that no longer exists. Nothing reads
                // it between here and the model's death — `buildInput`
                // is its only reader and it has already run — so this
                // costs a byte-store to keep an invariant true rather
                // than to fix an observable bug.
                const dup = try dupeValue(a, v, false);
                const target = &s.chunks.items[cur.chunk].items[cur.off];
                target.v = dup;
                target.cache = dup.cacheTag();
                return;
            }
        }
        try s.insert(a, .{
            .row = row,
            .col = col,
            .layer = .computed,
            .v = try dupeValue(a, v, false),
        });
    }

    /// The record `publish_in_place` may overwrite at a coordinate, or
    /// null when the publication has to lay a `.computed` record instead.
    ///
    /// Only the **topmost** record is a candidate, because only the
    /// topmost record is what a merged read returns — overwriting
    /// anything below it would publish a value nothing can see. Two
    /// exclusions make the rest safe:
    ///
    /// - **Never a spill tail.** A tail's `v` belongs to the anchor that
    ///   placed it, and `retractResult` on the cell that published over
    ///   it must reveal the tail again (the C1-over-B1's-tail fixture).
    ///   A tail carries no `formula_text`, so the formula test below
    ///   already excludes it; it is spelled out anyway, because the
    ///   reason is ownership rather than the absence of a body.
    /// - **A formula record only.** The value being published is that
    ///   formula's own result, so overwriting it restates what the cell
    ///   already means. A stored *value* has no such relationship to the
    ///   run, and a model whose stored values were silently rewritten
    ///   would be a different document, not a recalculated one.
    ///
    /// An existing `.computed` record is left to `Sheet.insert`, which
    /// replaces a same-key entry in place already — the record this
    /// exists to avoid was allocated on some earlier pass and cannot be
    /// un-allocated now.
    ///
    /// The caller adds a third exclusion the cursor cannot see: **a
    /// published `.blank`**. `dupeValue` folds blank to `.absent`, and
    /// `.absent` on a record carrying `formula_text` is this type's
    /// spelling of *uncached* — so writing it in place would say "never
    /// computed" about a cell that just computed, and `isUncached` would
    /// answer the opposite of the truth. A separate `.computed` record
    /// carries no `formula_text`, so it can hold `.absent` without
    /// claiming that; the blank-producing cells keep it.
    fn inPlaceTarget(s: *const Sheet, row: coords.Row, col: coords.Col) ?Sheet.Cursor {
        const cur = s.lowerBound(row, col, .computed);
        const top = s.at(cur) orelse return null;
        if (top.row.oneBased() != row.oneBased()) return null;
        if (top.col.zeroBased() != col.zeroBased()) return null;
        if (top.layer == .computed or top.layer == .spill_tail) return null;
        if (top.formula_text == null) return null;
        return cur;
    }

    /// Remove one coordinate from the computed layer.
    ///
    /// Infallible, because it is what a rolled-back run calls (§5.6c's
    /// "zero mutation"): a rollback that could fail would make the
    /// promise conditional on there being memory to keep it. Lower
    /// layers are untouched, so retracting a computed value uncovers the
    /// stored one — the state a refusal leaves behind is the state it
    /// started from.
    pub fn clearComputed(
        self: *WorkbookEnv,
        sheet: engine.env.SheetIndex,
        row: coords.Row,
        col: coords.Col,
    ) void {
        const s = self.sheetMut(sheet) catch return;
        const at = s.lowerBound(row, col, .computed);
        const cur = s.at(at) orelse return;
        if (cur.row != row or cur.col != col or cur.layer != .computed) return;
        s.removeAt(at);
    }

    // ─── §5.8a: the model half of spill placement (M7a) ────────────

    fn spillHost(self: *WorkbookEnv) engine.spill.Host {
        return .{ .ctx = self, .vtable = &spill_vtable };
    }

    const spill_vtable: engine.spill.Host.VTable = .{
        .occupied = svOccupied,
        .overlapsTable = svOverlapsTable,
        .overlapsMerge = svOverlapsMerge,
        .clearOwnTails = svClearOwnTails,
        .placeTail = svPlaceTail,
    };

    fn svOccupied(ctx: *anyopaque, anchor: engine.env.CellRef, cell: engine.env.CellRef) engine.env.Error!bool {
        const self = selfOf(ctx);
        const s = try self.sheetConst(cell.sheet);
        // Every layer at the coordinate, not the merged view: a stored
        // formula shadowed by a computed value is still a formula, and a
        // spill may not land on it.
        var at = s.lowerBound(cell.row, cell.col, .computed);
        while (s.at(at)) |c| : (at = s.next(at)) {
            if (c.row != cell.row or c.col != cell.col) break;
            if (c.layer == .spill_tail) {
                // A FOREIGN tail is content; the anchor's own tails
                // were cleared before the decision ran.
                const own = self.extraOf(c).spill_anchor;
                if (own == null or !own.?.eql(anchor)) return true;
                continue;
            }
            // A formula is content wherever it is — the racing-anchor
            // rule falls out of this line: the anchor later in calc
            // order meets the earlier one's formula cell or its tails.
            if (c.formula_text != null) return true;
            if (c.v != .absent and c.v != .blank) return true;
            // `v == .absent` with no formula is a staged deletion, and a
            // deleted cell is §5.8a's "empty"; `.blank` is a styled
            // blank, empty the same way.
        }
        return false;
    }

    fn svOverlapsTable(ctx: *anyopaque, area: engine.env.RangeRef) bool {
        const self = selfOf(ctx);
        const i = area.sheet.toInt();
        if (i >= self.sheet_tables.len) return false;
        return engine.spill.overlapsAny(self.sheet_tables[i], area);
    }

    fn svOverlapsMerge(ctx: *anyopaque, area: engine.env.RangeRef) bool {
        const self = selfOf(ctx);
        const i = area.sheet.toInt();
        if (i >= self.sheet_merges.len) return false;
        return engine.spill.overlapsAny(self.sheet_merges[i], area);
    }

    fn svClearOwnTails(ctx: *anyopaque, anchor: engine.env.CellRef) void {
        const self = selfOf(ctx);
        const shape = self.spills.shapeOf(anchor) orelse return;
        self.clearTailsIn(anchor, shape);
    }

    /// Remove `anchor`'s tails inside the extent `shape` names.
    /// Infallible: both the protocol's clear-before-decide and the
    /// rollback path call it, and neither may fail.
    fn clearTailsIn(self: *WorkbookEnv, anchor: engine.env.CellRef, shape: engine.value.Shape) void {
        const area = engine.spill.extent(anchor, shape) orelse return;
        const s = self.sheetMut(anchor.sheet) catch return;
        var off: u64 = 1;
        const n = area.cellCount();
        while (off < n) : (off += 1) {
            const cell = area.cellAtOffset(off);
            var at = s.lowerBound(cell.row, cell.col, .computed);
            while (s.at(at)) |c| : (at = s.next(at)) {
                if (c.row != cell.row or c.col != cell.col) break;
                const own = if (c.layer == .spill_tail) self.extraOf(c).spill_anchor else null;
                if (own != null and own.?.eql(anchor)) {
                    s.removeAt(at);
                    break;
                }
            }
        }
    }

    fn svPlaceTail(ctx: *anyopaque, anchor: engine.env.CellRef, cell: engine.env.CellRef, v: engine.value.ScalarValue) engine.env.Error!void {
        const self = selfOf(ctx);
        const s = try self.sheetMut(cell.sheet);
        const a = self.arena.allocator();
        const extra = try appendExtra(&self.extras, a, .{ .spill_anchor = anchor });
        try s.insert(a, .{
            .row = cell.row,
            .col = cell.col,
            .layer = .spill_tail,
            .v = try dupeValue(a, v, false),
            .extra = extra,
        });
    }

    /// The model half of §5.8a. Scalars land in the computed layer as
    /// before; a DYNAMIC-dialect anchor's array runs the decision table
    /// and either spills — anchor top-left, owned tails — or holds
    /// `#SPILL!` with the class recorded. Both directions clear the
    /// anchor's previous extent first, so a shape change between passes
    /// (grow, shrink, array to scalar) leaves no orphaned tail. Returns
    /// the scalar the anchor's coordinate now reads, for hosts that
    /// track publications.
    ///
    /// A LEGACY cell's array narrows to its top-left, exactly as every
    /// pre-M7a host did: a legacy CSE's tails are its own STORED slave
    /// cells — running the decision table over them would obstruct on
    /// the anchor's own declared range — and §5.6h's declared-range
    /// placement is not this milestone's. The dialect is the stored
    /// cell's (§5.3b); a cell that evaluated at all resolved it already,
    /// so the conservative arm here is unreachable in practice.
    pub fn publishResult(
        self: *WorkbookEnv,
        cell: engine.env.CellRef,
        v: engine.iterate.Snapshot,
    ) engine.env.Error!engine.value.ScalarValue {
        switch (v) {
            .scalar => |s| {
                svClearOwnTails(self, cell);
                self.spills.forget(cell);
                try self.putComputed(cell.sheet, cell.row, cell.col, s);
                return s;
            },
            .array => |m| {
                const dialect = self.evalEnv().dialectOf(cell) catch |e| switch (e) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => engine.value.Dialect.legacy,
                };
                if (dialect == .legacy) {
                    svClearOwnTails(self, cell);
                    self.spills.forget(cell);
                    const top = m.topLeft();
                    try self.putComputed(cell.sheet, cell.row, cell.col, top);
                    return top;
                }
                // A failed publication retracts itself precisely: the
                // journal only names cells that published successfully,
                // so a half-placed spill cannot wait for a rollback that
                // will never reach it. The new extent's tails are
                // cleared by shape — the registry may still hold the
                // OLD outcome at that point.
                //
                // Under `publish_in_place` the third line is weaker —
                // `clearComputed` finds no computed record to remove and
                // the anchor keeps whatever `v` an earlier pass wrote.
                // That is sound only because reaching this `errdefer` at
                // all means the run is failing: the error leaves
                // `publishResult`, `vtPublish` turns it into
                // `driver.failure`, and `prepare` returns before staging.
                // The model is discarded either way; what this block
                // still buys there is a consistent *registry* for the
                // remainder of the unwinding.
                errdefer {
                    self.clearTailsIn(cell, m.shape());
                    self.spills.forget(cell);
                    self.clearComputed(cell.sheet, cell.row, cell.col);
                }
                const outcome = try engine.spill.place(self.spillHost(), cell, m);
                try self.spills.note(self.arena.allocator(), cell, outcome);
                const anchor_value: engine.value.ScalarValue = switch (outcome) {
                    .spilled => m.topLeft(),
                    .blocked => engine.value.ScalarValue.errorOf(.spill),
                };
                try self.putComputed(cell.sheet, cell.row, cell.col, anchor_value);
                return anchor_value;
            },
        }
    }

    /// One publication, undone — tails, outcome record and computed
    /// value together, which is what "tail mutations ride the
    /// transaction" means on the rollback side. Infallible for §5.6c's
    /// zero-mutation promise, like `clearComputed`.
    pub fn retractResult(self: *WorkbookEnv, cell: engine.env.CellRef) void {
        // §9.1 M10r's pairing, checked rather than documented: in-place
        // publication overwrote the record this would have to restore,
        // so a host that reaches here with the flag set has kept a
        // journal it cannot replay. The two are one decision.
        assert(!self.publish_in_place);
        svClearOwnTails(self, cell);
        self.spills.forget(cell);
        self.clearComputed(cell.sheet, cell.row, cell.col);
    }

    /// §5.8a's class record, for fixtures and diagnostics: which
    /// `#SPILL!` row blocked `cell`, or null when it spilled or never
    /// placed.
    pub fn spillClassOf(self: *const WorkbookEnv, cell: engine.env.CellRef) ?engine.spill.Class {
        return self.spills.classOf(cell);
    }

    /// The whole per-anchor outcome, for staging (§5.8b): `stage()`
    /// carries what the model placed into the publication record, and
    /// the patcher consumes it — placement is decided exactly once.
    pub fn spillOutcomeOf(self: *const WorkbookEnv, cell: engine.env.CellRef) ?engine.spill.Outcome {
        return self.spills.map.get(cell);
    }

    pub fn evalEnv(self: *WorkbookEnv) engine.env.EvalEnv {
        return .{ .ctx = self, .vtable = &vtable };
    }

    const vtable: engine.env.EvalEnv.VTable = .{
        .cellValue = vtCellValue,
        .rangeIterator = vtRangeIterator,
        .logicalBlankCount = vtLogicalBlankCount,
        .alignedRangeIterator = vtAlignedRangeIterator,
        .dialectOf = vtDialectOf,
        .spillShape = vtSpillShape,
        .resolveSheet = vtResolveSheet,
    };

    fn selfOf(ctx: *anyopaque) *WorkbookEnv {
        return @ptrCast(@alignCast(ctx));
    }

    fn sheetMut(self: *WorkbookEnv, idx: engine.env.SheetIndex) engine.env.Error!*Sheet {
        const i = idx.toInt();
        if (i >= self.sheets.len) return error.UnknownSheet;
        return &self.sheets[i];
    }

    fn sheetConst(self: *WorkbookEnv, idx: engine.env.SheetIndex) engine.env.Error!*const Sheet {
        const i = idx.toInt();
        if (i >= self.sheets.len) return error.UnknownSheet;
        return &self.sheets[i];
    }

    /// The highest-precedence entry at a coordinate, or null when
    /// nothing occupies it. Every accessor goes through this, which is
    /// why `cellValue` and `rangeIterator` cannot disagree.
    fn merged(s: *const Sheet, row: coords.Row, col: coords.Col) ?Cell {
        const c = s.at(s.lowerBound(row, col, .computed)) orelse return null;
        if (c.row != row or c.col != col) return null;
        return c;
    }

    fn vtCellValue(ctx: *anyopaque, cell: engine.env.CellRef) engine.env.Error!engine.value.ScalarValue {
        const self = selfOf(ctx);
        const s = try self.sheetConst(cell.sheet);
        const m = merged(s, cell.row, cell.col) orelse return .blank;
        return m.v.orBlank();
    }

    fn vtDialectOf(ctx: *anyopaque, cell: engine.env.CellRef) engine.env.Error!engine.value.Dialect {
        const self = selfOf(ctx);
        const s = try self.sheetConst(cell.sheet);
        const r = self.dialectResolver();
        // Dialect is a STORED-cell property (§5.3b), so run-produced
        // layers are skipped: a computed entry carries `cm = 0`, and
        // reading it would flip an iterating dynamic-array anchor to
        // legacy on its second pass (M7a).
        var at = s.lowerBound(cell.row, cell.col, .computed);
        while (s.at(at)) |c| : (at = s.next(at)) {
            if (c.row != cell.row or c.col != cell.col) break;
            if (c.layer == .computed or c.layer == .spill_tail) continue;
            const extra = self.extraOf(c);
            return r.dialectOf(extra.cm, extra.vm);
        }
        // An unoccupied coordinate carries no metadata, which is what
        // `cm = 0` means — the resolver answers it the same way it
        // answers an unmarked stored cell.
        return r.dialectOf(0, 0);
    }

    /// §5.8a's stored spill state (M7a). A cache-based read still
    /// answers null — a spill's extent is not recoverable from cached
    /// `<v>` values — but a run that PLACED a spill this session has
    /// the extent in the registry, and that is what `A1#` resolves
    /// through. A blocked anchor answers null like a non-anchor: `A1#`
    /// against it is `#REF!` (M3a2's spec-pinned row).
    fn vtSpillShape(ctx: *anyopaque, cell: engine.env.CellRef) engine.env.Error!?engine.value.Shape {
        const self = selfOf(ctx);
        _ = try self.sheetConst(cell.sheet);
        return self.spills.shapeOf(cell);
    }

    fn vtResolveSheet(ctx: *anyopaque, name: []const u8) engine.env.Error!?engine.env.SheetIndex {
        const self = selfOf(ctx);
        return self.symbols.resolveSheet(self.allocator, name);
    }

    const RangeState = struct {
        sheet: *const Sheet,
        area: engine.env.RangeRef,
        cur: Sheet.Cursor,
    };

    fn vtRangeIterator(ctx: *anyopaque, area: engine.env.RangeRef) engine.env.Error!engine.env.RangeIterator {
        const self = selfOf(ctx);
        const s = try self.sheetConst(area.sheet);
        const start = s.lowerBound(area.range.first.row, area.range.first.col, .computed);
        return engine.env.RangeIterator.wrap(
            RangeState,
            .{ .sheet = s, .area = area, .cur = start },
            rangeNext,
        );
    }

    fn rangeNext(it: *engine.env.RangeIterator) engine.env.Error!?engine.env.Entry {
        const st = it.stateOf(RangeState);
        const s = st.sheet;
        while (s.at(st.cur)) |c| {
            if (c.row.oneBased() > st.area.range.last.row.oneBased()) return null;
            st.cur = s.next(st.cur);
            const inside = st.area.offsetOf(c.row, c.col) != null;
            // Entries are layer-descending within a coordinate, so the
            // first one seen is the winner and the rest are shadowed.
            while (s.at(st.cur)) |shadowed| {
                if (shadowed.row != c.row or shadowed.col != c.col) break;
                st.cur = s.next(st.cur);
            }
            if (!inside) continue;
            // An occupied coordinate with no value contributes nothing
            // to the merged view — but it still shadowed the layers
            // below it, which is why the skip happens here and not at
            // insert time.
            const v = c.v.get() orelse continue;
            return .{ .row = c.row, .col = c.col, .value = v, .layer = c.layer };
        }
        return null;
    }

    fn vtLogicalBlankCount(
        ctx: *anyopaque,
        area: engine.env.RangeRef,
        class: engine.env.BlankClass,
    ) engine.env.Error!u64 {
        const self = selfOf(ctx);
        var it = try vtRangeIterator(self, area);
        var occupied: u64 = 0;
        while (try it.next()) |e| {
            const counts_as_blank = switch (class) {
                .isblank_class => false,
                .countblank_class => e.value == .text and e.value.text.len == 0,
            };
            if (!counts_as_blank) occupied += 1;
        }
        // Area minus occupancy: no per-coordinate test, so a whole
        // column costs what its stored cells cost.
        return area.cellCount() - occupied;
    }

    const AlignedState = struct {
        env: *WorkbookEnv,
        areas: []const engine.env.RangeRef,
        mode: engine.env.AlignMode,
        dims: engine.value.Shape,
        offset: u64,
        total: u64,
    };

    fn vtAlignedRangeIterator(
        ctx: *anyopaque,
        areas: []const engine.env.RangeRef,
        mode: engine.env.AlignMode,
        cursors: []usize,
        out: []engine.value.ScalarValue,
    ) engine.env.Error!engine.env.AlignedIterator {
        const self = selfOf(ctx);
        assert(areas.len > 0);
        assert(cursors.len == areas.len and out.len == areas.len);
        const dims = areas[0].shape();
        // Validate every area up front: a cursor that discovered a
        // shape mismatch halfway would have already reported rows the
        // caller must now un-count.
        for (areas) |ar| {
            _ = try engine.env.effectiveArea(ar, dims, mode);
            _ = try self.sheetConst(ar.sheet);
        }
        @memset(cursors, std.math.maxInt(usize));
        return engine.env.AlignedIterator.wrap(
            AlignedState,
            .{
                .env = self,
                .areas = areas,
                .mode = mode,
                .dims = dims,
                .offset = 0,
                .total = @as(u64, dims.rows) * @as(u64, dims.cols),
            },
            cursors,
            out,
            alignedNext,
        );
    }

    fn alignedNext(it: *engine.env.AlignedIterator) engine.env.Error!?engine.env.AlignedItem {
        const st = it.stateOf(AlignedState);
        if (st.offset >= st.total) return null;

        var next_occupied: u64 = st.total;
        for (st.areas, it.cursors) |ar, *cursor| {
            const eff = try engine.env.effectiveArea(ar, st.dims, st.mode);
            const s = try st.env.sheetConst(eff.sheet);
            if (cursor.* == std.math.maxInt(usize)) {
                cursor.* = Sheet.pack(s.lowerBound(
                    eff.range.first.row,
                    eff.range.first.col,
                    .computed,
                ));
            }
            const off = advance(s, eff, cursor, st.offset) orelse continue;
            next_occupied = @min(next_occupied, off);
        }

        const cols = st.dims.cols;
        const at = st.offset;
        if (next_occupied > at) {
            const run = next_occupied - at;
            st.offset = next_occupied;
            return .{ .blank_run = .{
                .row_offset = @intCast(at / cols),
                .col_offset = @intCast(at % cols),
                .count = run,
            } };
        }

        for (st.areas, it.out) |ar, *slot| {
            const eff = try engine.env.effectiveArea(ar, st.dims, st.mode);
            const s = try st.env.sheetConst(eff.sheet);
            const cell = eff.cellAtOffset(at);
            slot.* = if (merged(s, cell.row, cell.col)) |m| m.v.orBlank() else .blank;
        }
        st.offset = at + 1;
        return .{ .cells = .{
            .row_offset = @intCast(at / cols),
            .col_offset = @intCast(at % cols),
            .values = it.out,
        } };
    }

    /// Move one area's cursor to the first offset ≥ `from` that holds a
    /// *value*, returning it. Forward-only: offsets within an area
    /// increase with (row, col), which is the order the backing is
    /// sorted in.
    fn advance(
        s: *const Sheet,
        eff: engine.env.RangeRef,
        cursor: *usize,
        from: u64,
    ) ?u64 {
        var cur = Sheet.unpack(cursor.*);
        defer cursor.* = Sheet.pack(cur);
        while (s.at(cur)) |c| {
            if (c.row.oneBased() > eff.range.last.row.oneBased()) return null;
            const off = eff.offsetOf(c.row, c.col) orelse {
                cur = s.next(cur);
                continue;
            };
            if (off < from or (merged(s, c.row, c.col) orelse c).v == .absent) {
                cur = s.next(cur);
                continue;
            }
            return off;
        }
        return null;
    }

    fn lessThanKey(
        c: Cell,
        row: coords.Row,
        col: coords.Col,
        layer: engine.env.Layer,
    ) bool {
        if (c.row.oneBased() != row.oneBased()) return c.row.oneBased() < row.oneBased();
        if (c.col.zeroBased() != col.zeroBased()) return c.col.zeroBased() < col.zeroBased();
        // Layer descending: the highest-precedence entry for a
        // coordinate sorts first, so a merged read is the first hit.
        return c.layer.precedence() > layer.precedence();
    }

    /// Copy a value's text into the model's own arena. A `ScalarValue`
    /// borrows, and the scan arena that produced it is released as soon
    /// as the sheet is decoded.
    fn dupeValue(
        a: Allocator,
        v: engine.value.ScalarValue,
        uncached: bool,
    ) Allocator.Error!WorkbookEnv.OptValue {
        if (uncached) return .absent;
        return switch (v) {
            .blank => .absent,
            .text => |t| .{ .text = try a.dupe(u8, t) },
            .err => |e| switch (e) {
                .known => .{ .err = e },
                .rich => |spelling| .{ .err = .{ .rich = try a.dupe(u8, spelling) } },
            },
            .number => |n| .{ .number = n },
            .boolean => |b| .{ .boolean = b },
        };
    }

    fn stagedCell(
        a: Allocator,
        row: coords.Row,
        col: coords.Col,
        v: CellValue,
    ) Allocator.Error!Cell {
        return switch (v) {
            .number => |n| .{ .row = row, .col = col, .layer = .staged, .v = .{ .number = n } },
            .boolean => |b| .{ .row = row, .col = col, .layer = .staged, .v = .{ .boolean = b } },
            .string, .shared_string => |s| .{
                .row = row,
                .col = col,
                .layer = .staged,
                .v = .{ .text = try a.dupe(u8, s) },
            },
            // A staged formula has no cached value yet — that is what
            // the run is about to compute.
            .formula => |f| .{
                .row = row,
                .col = col,
                .layer = .staged,
                .v = .absent,
                .formula_text = try a.dupe(u8, f),
            },
            // Both shadow whatever the stored layer had, and neither
            // contributes a value.
            .blank, .deleted => .{ .row = row, .col = col, .layer = .staged, .v = .absent },
        };
    }
};

/// Every part the run will read, checked for a vocabulary this engine
/// implements — before decode, and therefore before any mutation.
fn preflightParts(wb: *Workbook, limits: engine.decode.Limits) Error!?engine.decode.Refusal {
    if (try wb.store.part("xl/workbook.xml")) |p| {
        if (engine.decode.preflight(.workbook, p.bytes, limits)) |r| return r;
    } else return Error.MissingWorkbookPart;

    if (try sstPartName(wb)) |name| {
        if (try wb.store.part(name)) |p| {
            if (engine.decode.preflight(.shared_strings, p.bytes, limits)) |r| return r;
        }
    }

    // Through `Workbook.sheet`, never over `worksheets` directly: the
    // back-pointer each slot needs is patched in on first observation
    // (`:6170-6174`), and `resolvePartName` dereferences it.
    for (0..wb.worksheets.len) |i| {
        const ws = try wb.sheet(@intCast(i));
        const part_name = try ws.resolvePartName();
        const part = (try wb.store.part(part_name)) orelse return Error.MissingSheetPart;
        if (engine.decode.preflight(.worksheet, part.bytes, limits)) |r| return r;

        var rids = TablePartRidIterator.init(part.bytes);
        const rels = wb.store.rels(part_name);
        while (rids.next()) |rid| {
            const target = relTargetForId(rels, rid) orelse continue;
            const table_name = (try wb.store.resolve(part_name, target)) orelse continue;
            const table_part = (try wb.store.part(table_name)) orelse continue;
            if (engine.decode.preflight(.table, table_part.bytes, limits)) |r| return r;
        }
    }
    return null;
}

fn sstPartName(wb: *Workbook) Error!?[]const u8 {
    if ((try wb.store.part("xl/sharedStrings.xml")) != null) return "xl/sharedStrings.xml";
    return null;
}

fn decodeStrings(
    allocator: Allocator,
    wb: *Workbook,
    opts: FormulaEnvOptions,
) Error!engine.decode.StringsResult {
    const name = (try sstPartName(wb)) orelse
        return .{ .ok = engine.decode.emptyStrings(allocator) };
    const part = (try wb.store.part(name)) orelse
        return .{ .ok = engine.decode.emptyStrings(allocator) };
    return engine.decode.decodeSharedStrings(allocator, part.bytes, .{
        .limits = opts.limits,
        .fidelity = opts.fidelity,
    });
}

/// What one cell's `<f>` resolved to.
const SharedText = struct {
    /// Null where the cell has no `<f>`.
    text: ?[]const u8 = null,
    /// The declared range of a legacy CSE array (`<f t="array" ref>`).
    /// M5a1 reads it: the graph's spill tails are the cells inside it.
    array: ?coords.Range = null,
};

const SharedTextResult = union(enum) {
    /// One entry per cell, in the order `scanSheet` produced them. The
    /// outer slice is the caller's to free, the strings belong to the
    /// model arena.
    ok: []const SharedText,
    refused: engine.calc.Refusal,
};

/// The effective formula text for every cell on one sheet (M4b2).
///
/// A shared slave's `<f>` is empty or absent in the file; its formula is
/// its master's, translated by the slave's (Δrow, Δcol). Doing that here
/// — between the decode boundary and the layer merge — is what lets
/// `formulaAt` answer the same way for a slave as for any other cell,
/// and it is why `xlsx.zig:2099`'s shape-based reader is not in the
/// path: classification is by attribute.
///
/// Every refusal below is a normal return, so nothing may lean on
/// `errdefer` to release `out` — hence the explicit `keep`.
/// The sheet's cells, as M4b3's producer check asks about them.
///
/// `cells` is row-major and `formulas` is parallel to it (a slave's
/// entry is its master's translated text), so "does this coordinate
/// carry a formula" is a binary search rather than a scan — a
/// calculated column over a 100 000-row table would otherwise be
/// quadratic.
const ProducerCells = struct {
    cells: []const engine.decode.SheetCell,
    formulas: []const SharedText,

    pub fn hasFormula(self: ProducerCells, row: coords.Row, col: coords.Col) bool {
        var lo: usize = 0;
        var hi: usize = self.cells.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const c = self.cells[mid];
            if (c.row.oneBased() < row.oneBased() or
                (c.row == row and c.col.zeroBased() < col.zeroBased()))
            {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= self.cells.len) return false;
        const hit = self.cells[lo];
        if (hit.row != row or hit.col != col) return false;
        return self.formulas[lo].text != null;
    }
};

/// §5.9's table producers, over one table and the sheet it sits on.
///
/// Two questions, in order: does every producer element's attribute
/// region pass the `CT_TableFormula` inventory, and was every member
/// cell the producer covers actually materialized with its own `<f>`.
/// The second is the one that matters — Excel writes the producer into
/// each data cell, so the part and the sheet say the same thing twice,
/// and an engine that writes values back cannot pick a side when they
/// disagree.
fn checkTableProducers(
    table: engine.decode.Table,
    cells: []const engine.decode.SheetCell,
    formulas: []const SharedText,
) Error!?engine.names.Refusal {
    // A table whose `ref` will not parse is not this row's refusal —
    // the geometry is unusable, so there is no member set to check.
    const ref = coords.parseRange(table.ref, .{ .dollar = .accept }) catch return null;
    const members: ProducerCells = .{ .cells = cells, .formulas = formulas };

    for (table.columns, 0..) |column, i| {
        const col_index = ref.first.col.zeroBased() + @as(u32, @intCast(i));
        const col = coords.Col.fromZeroBased(col_index) catch continue;

        if (column.calculated_formula) |text| {
            switch (engine.names.classifyTableFormula(
                .calculated_column,
                column.calculated_attrs,
                text,
                0,
            )) {
                .refused => |r| return r,
                .ok => {},
            }
            if (engine.names.producerSpan(
                .calculated_column,
                ref,
                table.header_rows,
                table.totals_rows,
                col,
            )) |span| {
                if (engine.names.checkProducerMembers(ProducerCells, members, span)) |r| {
                    return r;
                }
            }
        }

        if (column.totals_formula) |text| {
            switch (engine.names.classifyTableFormula(
                .totals_row,
                column.totals_attrs,
                text,
                0,
            )) {
                .refused => |r| return r,
                .ok => {},
            }
            if (engine.names.producerSpan(
                .totals_row,
                ref,
                table.header_rows,
                table.totals_rows,
                col,
            )) |span| {
                if (engine.names.checkProducerMembers(ProducerCells, members, span)) |r| {
                    return r;
                }
            }
        }
    }
    return null;
}

fn sharedFormulaText(
    gpa: Allocator,
    arena: Allocator,
    cells: []const engine.decode.SheetCell,
    /// The scan's own count of the `<f>`-carrying cells in `cells`
    /// (§9.1g M10x). Taken as a parameter rather than re-counted: the
    /// walk that produced these records already knew it.
    formula_cells: u32,
) Error!SharedTextResult {
    var shared = switch (try engine.calc.classifySheet(gpa, cells, .{
        .formula_cells = formula_cells,
    })) {
        .ok => |s| s,
        .refused => |r| return .{ .refused = r },
    };
    defer shared.deinit();

    const out = try gpa.alloc(SharedText, cells.len);
    var keep = false;
    defer if (!keep) gpa.free(out);
    @memset(out, .{});

    // One parse per group, not one per slave.
    var masters = switch (try engine.calc.parseMasters(gpa, shared.groups)) {
        .ok => |m| m,
        .refused => |r| return .{ .refused = r },
    };
    defer masters.deinit();

    // §9.1g M10x: the two terms that arrive after `classifySheet` has
    // handed its list back, so neither of them stands at the maximum.
    if (engine.calc.census_sink) |c| {
        c.out_bytes = out.len * @sizeOf(SharedText);
        var master_bytes: usize = masters.asts.len * @sizeOf(engine.parser.Ast);
        for (masters.asts) |ast| {
            master_bytes += ast.nodes.len * @sizeOf(engine.parser.Node);
            master_bytes += ast.extra.len * @sizeOf(engine.parser.Index);
        }
        c.masters_bytes = master_bytes;
    }

    for (shared.entries) |e| {
        out[e.cell] = .{
            .text = switch (e.role) {
                .slave => |sl| blk: {
                    var t = try masters.translateFor(gpa, sl.group, sl.delta);
                    defer t.deinit();
                    break :blk try arena.dupe(u8, t.text);
                },
                else => try arena.dupe(u8, e.formula.text),
            },
            .array = switch (e.role) {
                .array => |ref| ref.normalized(),
                else => null,
            },
        };
    }

    keep = true;
    return .{ .ok = out };
}

/// §5.6c's seed table reads a *cache state*, not a value: an absent
/// `<v>` and a genuine blank are the same `ScalarValue` and different
/// seeds. `decode.InputCell` already made that distinction, so the
/// translation is a switch rather than an inference.
///
/// `.malformed` never appears here — `decode.classifyCell` refuses a
/// malformed cache before a model exists, which is the pre-mutation
/// half of §5.6c's fourth row. The graph's own row covers a caller that
/// assembles an `Input` by hand.
fn cacheTagOf(input: engine.decode.InputCell) WorkbookEnv.CacheTag {
    return switch (input) {
        .number => .number,
        .text => .text,
        .boolean => .boolean,
        .err => .err,
        .blank, .uncached => .absent,
    };
}

const MetadataResult = union(enum) {
    ok: engine.metadata.Metadata,
    refused: engine.metadata.Refusal,
};

/// A workbook with no `xl/metadata.xml` resolves `.legacy` everywhere,
/// which is the correct reading: without the part there are no
/// dynamic-array marks to find (M4a).
fn decodeMetadata(allocator: Allocator, wb: *Workbook) Error!MetadataResult {
    const part = (try wb.store.part("xl/metadata.xml")) orelse
        return .{ .ok = engine.metadata.Metadata.none };
    return switch (try engine.metadata.parse(allocator, part.bytes, .{})) {
        .ok => |m| .{ .ok = m },
        .refused => |r| .{ .refused = r },
    };
}

// ─── Test helpers ─────────────────────────────────────────────────────

/// Write a minimal SST-less .xlsx to `path` for testing the SST-
/// creation branch. Every part is STORED (compression method = 0)
/// so the file can be assembled without pulling in a deflate
/// dependency. Contents:
///   - `[Content_Types].xml` with no sharedStrings override
///   - `_rels/.rels` pointing to `xl/workbook.xml`
///   - `xl/workbook.xml` declaring a single sheet (rId1)
///   - `xl/_rels/workbook.xml.rels` with the sheet rel only
///   - `xl/worksheets/sheet1.xml` (empty `<sheetData/>`)
fn writeMinimalSstLessXlsx(allocator: Allocator, io: std.Io, path: []const u8) !void {
    const Entry = struct { name: []const u8, body: []const u8 };

    const content_types =
        "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
        "<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">" ++
        "<Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/>" ++
        "<Default Extension=\"xml\" ContentType=\"application/xml\"/>" ++
        "<Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>" ++
        "<Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>" ++
        "</Types>";
    const root_rels =
        "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
        "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">" ++
        "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/>" ++
        "</Relationships>";
    const workbook_xml =
        "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
        "<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\">" ++
        "<sheets><sheet name=\"Sheet1\" sheetId=\"1\" r:id=\"rId1\"/></sheets>" ++
        "</workbook>";
    const workbook_rels =
        "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
        "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">" ++
        "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/>" ++
        "</Relationships>";
    const sheet_xml =
        "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" ++
        "<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\">" ++
        "<sheetData></sheetData>" ++
        "</worksheet>";

    const entries = [_]Entry{
        .{ .name = "[Content_Types].xml", .body = content_types },
        .{ .name = "_rels/.rels", .body = root_rels },
        .{ .name = "xl/workbook.xml", .body = workbook_xml },
        .{ .name = "xl/_rels/workbook.xml.rels", .body = workbook_rels },
        .{ .name = "xl/worksheets/sheet1.xml", .body = sheet_xml },
    };

    var buf: std.ArrayList(u8) = .empty;
    defer buf.deinit(allocator);

    const Lfh = struct { offset: u32, name: []const u8, body: []const u8, crc: u32 };
    var lfhs: std.ArrayList(Lfh) = .empty;
    defer lfhs.deinit(allocator);

    // Phase 1: write LFH + payload for each entry.
    for (entries) |e| {
        const off: u32 = @intCast(buf.items.len);
        const crc = std.hash.Crc32.hash(e.body);
        // LFH = 30 bytes + name + payload.
        var hdr: [30]u8 = undefined;
        std.mem.writeInt(u32, hdr[0..4], 0x04034b50, .little);
        std.mem.writeInt(u16, hdr[4..6], 20, .little); // version
        std.mem.writeInt(u16, hdr[6..8], 0, .little); // flags
        std.mem.writeInt(u16, hdr[8..10], 0, .little); // method = STORED
        std.mem.writeInt(u16, hdr[10..12], 0, .little); // mtime
        std.mem.writeInt(u16, hdr[12..14], 0, .little); // mdate
        std.mem.writeInt(u32, hdr[14..18], crc, .little);
        std.mem.writeInt(u32, hdr[18..22], @intCast(e.body.len), .little);
        std.mem.writeInt(u32, hdr[22..26], @intCast(e.body.len), .little);
        std.mem.writeInt(u16, hdr[26..28], @intCast(e.name.len), .little);
        std.mem.writeInt(u16, hdr[28..30], 0, .little); // extra len
        try buf.appendSlice(allocator, &hdr);
        try buf.appendSlice(allocator, e.name);
        try buf.appendSlice(allocator, e.body);
        try lfhs.append(allocator, .{ .offset = off, .name = e.name, .body = e.body, .crc = crc });
    }

    // Phase 2: central directory.
    const cd_off: u32 = @intCast(buf.items.len);
    for (lfhs.items) |l| {
        var cdfh: [46]u8 = undefined;
        std.mem.writeInt(u32, cdfh[0..4], 0x02014b50, .little);
        std.mem.writeInt(u16, cdfh[4..6], 20, .little);
        std.mem.writeInt(u16, cdfh[6..8], 20, .little);
        std.mem.writeInt(u16, cdfh[8..10], 0, .little);
        std.mem.writeInt(u16, cdfh[10..12], 0, .little);
        std.mem.writeInt(u16, cdfh[12..14], 0, .little);
        std.mem.writeInt(u16, cdfh[14..16], 0, .little);
        std.mem.writeInt(u32, cdfh[16..20], l.crc, .little);
        std.mem.writeInt(u32, cdfh[20..24], @intCast(l.body.len), .little);
        std.mem.writeInt(u32, cdfh[24..28], @intCast(l.body.len), .little);
        std.mem.writeInt(u16, cdfh[28..30], @intCast(l.name.len), .little);
        std.mem.writeInt(u16, cdfh[30..32], 0, .little);
        std.mem.writeInt(u16, cdfh[32..34], 0, .little);
        std.mem.writeInt(u16, cdfh[34..36], 0, .little);
        std.mem.writeInt(u16, cdfh[36..38], 0, .little);
        std.mem.writeInt(u32, cdfh[38..42], 0, .little);
        std.mem.writeInt(u32, cdfh[42..46], l.offset, .little);
        try buf.appendSlice(allocator, &cdfh);
        try buf.appendSlice(allocator, l.name);
    }
    const cd_size: u32 = @intCast(@as(u32, @intCast(buf.items.len)) - cd_off);

    // Phase 3: EOCD.
    var eocd: [22]u8 = undefined;
    std.mem.writeInt(u32, eocd[0..4], 0x06054b50, .little);
    std.mem.writeInt(u16, eocd[4..6], 0, .little);
    std.mem.writeInt(u16, eocd[6..8], 0, .little);
    std.mem.writeInt(u16, eocd[8..10], @intCast(lfhs.items.len), .little);
    std.mem.writeInt(u16, eocd[10..12], @intCast(lfhs.items.len), .little);
    std.mem.writeInt(u32, eocd[12..16], cd_size, .little);
    std.mem.writeInt(u32, eocd[16..20], cd_off, .little);
    std.mem.writeInt(u16, eocd[20..22], 0, .little);
    try buf.appendSlice(allocator, &eocd);

    // Write to disk.
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = buf.items });
}

// ─── Tests ────────────────────────────────────────────────────────────

test "WorkbookEnv.Cell stays at its recorded width (M10s)" {
    // §9.1 M10o: the model holds one `Cell` per coordinate per layer —
    // 100 010 of them on the named workload since M10r stopped the drive
    // publishing a second one, in 64-entry chunks. A byte added here
    // costs 100 KB there, and this is where that trade gets noticed
    // rather than in the next RSS profile. `Extra` is the release valve:
    // a rare field belongs behind the index, not in the record.
    //
    // §9.1 M10p took `v` from `?ScalarValue` to the in-band `OptValue`,
    // 40 bytes to 32. The union below is the guard on that: a payload
    // wider than `ErrorValue`'s would grow every cell, so a new variant
    // is a width decision, not a local one.
    //
    // §9.1 M10s took `cache` from `graph.CacheState` to the 1-byte
    // `CacheTag`, 80 bytes to 64, by reading the payload f64 back out of
    // `v` — where it was already stored. The `CacheTag` guard is the one
    // that matters for the next reader: giving a tag a payload puts the
    // 15 bytes straight back.
    try std.testing.expectEqual(@as(usize, 32), @sizeOf(WorkbookEnv.OptValue));
    try std.testing.expectEqual(@as(usize, 1), @sizeOf(WorkbookEnv.CacheTag));
    try std.testing.expectEqual(@as(usize, 64), @sizeOf(WorkbookEnv.Cell));
    try std.testing.expectEqual(@as(usize, 4104), @sizeOf(WorkbookEnv.Sheet.Chunk));
}

test "WorkbookEnv.Cell.cacheState: the f64 survives the narrowing" {
    // The whole cut rests on one claim — that `cache`'s number and `v`'s
    // number were the same number. This is that claim, stated where a
    // change to either side breaks it.
    const c: WorkbookEnv.Cell = .{
        .row = try coords.Row.fromOneBased(1),
        .col = try coords.Col.fromZeroBased(0),
        .layer = .stored,
        .v = .{ .number = 1.5 },
        .cache = .number,
    };
    try std.testing.expectEqual(
        engine.graph.CacheState{ .number = 1.5 },
        c.cacheState(),
    );

    // The payload-free tags round-trip unchanged, and `.absent` is the
    // one that has to stay distinguishable from a cached zero: a missing
    // `<v>` seeds zero *because the table says so*, not because it holds
    // one.
    const text: WorkbookEnv.Cell = .{
        .row = try coords.Row.fromOneBased(1),
        .col = try coords.Col.fromZeroBased(0),
        .layer = .stored,
        .v = .{ .text = "x" },
        .cache = .text,
    };
    try std.testing.expectEqual(engine.graph.CacheState.text, text.cacheState());

    const uncached: WorkbookEnv.Cell = .{
        .row = try coords.Row.fromOneBased(1),
        .col = try coords.Col.fromZeroBased(0),
        .layer = .stored,
        .v = .absent,
        .cache = .absent,
    };
    try std.testing.expectEqual(engine.graph.CacheState.absent, uncached.cacheState());
}

test "WorkbookEnv.OptValue.cacheTag: every value maps to the tag a record would carry" {
    // `putComputed`'s in-place overwrite re-tags through this, so a new
    // `OptValue` variant that lands here wrong makes `cacheState` read a
    // union field the record does not hold.
    try std.testing.expectEqual(WorkbookEnv.CacheTag.number, (WorkbookEnv.OptValue{ .number = 1 }).cacheTag());
    try std.testing.expectEqual(WorkbookEnv.CacheTag.text, (WorkbookEnv.OptValue{ .text = "x" }).cacheTag());
    try std.testing.expectEqual(WorkbookEnv.CacheTag.boolean, (WorkbookEnv.OptValue{ .boolean = true }).cacheTag());
    try std.testing.expectEqual(WorkbookEnv.CacheTag.err, (WorkbookEnv.OptValue{ .err = .{ .known = .value } }).cacheTag());
    try std.testing.expectEqual(WorkbookEnv.CacheTag.absent, (@as(WorkbookEnv.OptValue, .absent)).cacheTag());
    // Blank folds to `.absent`: it carries no number to resume from.
    try std.testing.expectEqual(WorkbookEnv.CacheTag.absent, (@as(WorkbookEnv.OptValue, .blank)).cacheTag());
}

test "WorkbookEnv.OptValue: absent and blank stay distinct through the seam" {
    // The whole point of the in-band optional is that it loses nothing.
    // `absent` is the coordinate occupied with no value; `blank` is a
    // value. `get` tells them apart and `orBlank` deliberately does not
    // — that collapse is the merged view's rule (§5.6f), not a property
    // of the storage, and it belongs at the read site.
    const absent: WorkbookEnv.OptValue = .absent;
    const blank: WorkbookEnv.OptValue = .blank;
    try std.testing.expect(absent.get() == null);
    try std.testing.expect(blank.get() != null);
    try std.testing.expect(blank.get().? == .blank);
    try std.testing.expect(absent.orBlank() == .blank);
    try std.testing.expect(blank.orBlank() == .blank);

    // Every carrying variant round-trips to the `ScalarValue` it stands
    // for, payload included.
    const cases = [_]WorkbookEnv.OptValue{
        .{ .number = 1.5 },
        .{ .text = "x" },
        .{ .boolean = true },
        .{ .err = .{ .known = .na } },
        .{ .err = .{ .rich = "#GETTING_DATA" } },
        .blank,
    };
    for (cases) |c| {
        const round = c.get() orelse return error.UnexpectedAbsent;
        try std.testing.expect(round.eql(c.orBlank()));
    }
}

test "WorkbookEnv.Extra: the default record is what a cell with no index reads" {
    const c: WorkbookEnv.Cell = .{
        .row = try coords.Row.fromOneBased(1),
        .col = try coords.Col.fromOneBased(1),
        .layer = .stored,
        .v = .absent,
    };
    try std.testing.expectEqual(WorkbookEnv.Cell.no_extra, c.extra);
    // Only `extras` is read on this path, and `no_extra` short-circuits
    // before it — but define it anyway, so the test is asserting the
    // short-circuit rather than relying on undefined memory.
    var env: WorkbookEnv = undefined;
    env.extras = .empty;
    const e = env.extraOf(c);
    try std.testing.expectEqual(@as(u32, 0), e.cm);
    try std.testing.expectEqual(@as(u32, 0), e.vm);
    try std.testing.expect(e.array_ref == null);
    try std.testing.expect(e.spill_anchor == null);
}

