    const tmp_path = try std.fmt.bufPrint(&tmp_buf, ".zig-cache/test-hl-ext-in-{d}.xlsx", .{prng.random().int(u32)});

    // External hyperlink — r:id present, no location. The rewriter
    // must skip it (count == 0), leaving the entry untouched.
    {
