    defer std.Io.Dir.cwd().deleteFile(io, src_path) catch {};

    var wb = try Workbook.open(allocator, io, src_path);
    defer wb.deinit();

    // `to` left of `from`.
    try std.testing.expectError(
        error.InvertedAnchorRange,
        wb.addImageRange(
            0,
            .{ .from = .{ .col = 4, .row = 2 }, .to = .{ .col = 2, .row = 5 } },
            &tiny_png_1x1,
            .png,
        ),
    );
    // `to` above `from`.
    try std.testing.expectError(
        error.InvertedAnchorRange,
        wb.addImageRange(
            0,
