    try wb.stripEmbeddings();

    try std.testing.expectEqual(@as(usize, 0), embeddingDirPartCount(&wb));
    // `.absent`, not `.stripped` — the distinction this call exists for.
    try std.testing.expect((try wb.embeddings()) == .absent);
}

