    defer std.testing.allocator.free(dir);

    const path = try writePruneFile(io, dir, "idem.xlsx", .{ "Alpha", null }, .{
        try pruneHashFor(2, "Alpha"),
        try pruneHashFor(3, "Beta"),
    });
