// ─── M7a: §5.8a in the model — placement, ownership, classes ─────

const m7a_metadata_da =
    "<metadata xmlns=\"" ++ test_ns_main ++ "\" xmlns:xda=\"http://schemas.microsoft.com/office/spreadsheetml/2017/dynamicarray\">" ++
    "<metadataTypes count=\"1\"><metadataType name=\"XLDAPR\" minSupportedVersion=\"120000\" copy=\"1\" pasteAll=\"1\" pasteValues=\"1\" merge=\"1\" splitFirst=\"1\" rowColShift=\"1\" clearFormats=\"1\" clearComments=\"1\" assign=\"1\" coerce=\"1\" cellMeta=\"1\"/></metadataTypes>" ++
    "<futureMetadata name=\"XLDAPR\" count=\"1\"><bk><extLst><ext uri=\"{bdbb8cdc-fa1e-496e-a857-3c3f30c029c3}\">" ++
    "<xda:dynamicArrayProperties fDynamic=\"1\" fCollapsed=\"0\"/></ext></extLst></bk></futureMetadata>" ++
    "<cellMetadata count=\"1\"><bk><rc t=\"1\" v=\"0\"/></bk></cellMetadata></metadata>";

const ct_metadata_part = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheetMetadata+xml";

fn m7aCell(a1: []const u8) engine.env.CellRef {
    const c = coords.parseCell(a1, .{ .dollar = .accept }) catch unreachable;
    return .{ .sheet = engine.env.SheetIndex.fromInt(0), .row = c.row, .col = c.col };
}

fn m7aMatrix(a: Allocator, rows: u32, cols: u32, base: f64) !engine.value.Matrix {
    const m = try engine.value.Matrix.init(a, rows, cols);
    for (m.cells, 0..) |*cell, i| {
        cell.* = engine.value.ScalarValue.fromNumber(base + @as(f64, @floatFromInt(i)));
    }
    return m;
}

test "M7a: §5.8a's decision table over a real workbook, each class recorded" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // Anchors carry `cm="1"` → XLDAPR → dynamic dialect; B6 is the
    // obstruction; D5:E6 is merged; the table sits at G1:H4.
    const sheet =
        "<?xml version=\"1.0\"?><worksheet xmlns=\"" ++ test_ns_main ++ "\"><sheetData>" ++
        "<row r=\"1\"><c r=\"A1\" cm=\"1\"><v>0</v></c><c r=\"B1\" cm=\"1\"><v>0</v></c>" ++
        "<c r=\"F1\" cm=\"1\"><v>0</v></c><c r=\"XFD1\" cm=\"1\"><v>0</v></c></row>" ++
        "<row r=\"5\"><c r=\"B5\" cm=\"1\"><v>0</v></c><c r=\"D5\" cm=\"1\"><v>0</v></c></row>" ++
        "<row r=\"6\"><c r=\"B6\"><v>7</v></c></row>" ++
        "</sheetData>" ++
        "<mergeCells count=\"1\"><mergeCell ref=\"D5:E6\"/></mergeCells>" ++
        "<tableParts count=\"1\"><tablePart r:id=\"rIdT1\"/></tableParts>" ++
        "</worksheet>";
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();
    try wb.store.addPart(
        "xl/tables/table1.xml",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.table+xml",
        "<?xml version=\"1.0\"?><table xmlns=\"" ++ test_ns_main ++
            "\" id=\"1\" name=\"T\" displayName=\"T\" ref=\"G1:H4\"><tableColumns count=\"2\">" ++
            "<tableColumn id=\"1\" name=\"In\"/><tableColumn id=\"2\" name=\"Out\"/>" ++
            "</tableColumns></table>",
    );
    try wb.store.addPart(
        "xl/worksheets/_rels/sheet1.xml.rels",
        "application/vnd.openxmlformats-package.relationships+xml",
        "<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"></Relationships>",
    );
    try wb.store.replacePart(
        "xl/worksheets/_rels/sheet1.xml.rels",
        "<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">" ++
            "<Relationship Id=\"rIdT1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/table\" Target=\"../tables/table1.xml\"/>" ++
            "</Relationships>",
    );
    try wb.store.addPart("xl/metadata.xml", ct_metadata_part, m7a_metadata_da);

    var env = try expectBuilt(try buildEnvOrRefusal(ta, &wb, .{ .collation = test_collation }));
    defer env.deinit();
    var arena = std.heap.ArenaAllocator.init(ta);
    defer arena.deinit();
    const a = arena.allocator();
    const read = env.evalEnv();

    // Row 1 — fits + owned/empty spills: the anchor reads the
    // top-left, every tail is readable through the merged view, and
    // `spillShape` answers the extent.
    const b1 = m7aCell("B1");
    const got = try env.publishResult(b1, .{ .array = try m7aMatrix(a, 2, 2, 1) });
    try std.testing.expectEqual(@as(f64, 1), got.number);
    try std.testing.expect(env.spillClassOf(b1) == null);
    const shape = (try read.spillShape(b1)).?;
    try std.testing.expectEqual(@as(u32, 2), shape.rows);
    try std.testing.expectEqual(@as(u32, 2), shape.cols);
    try std.testing.expectEqual(@as(f64, 4), (try read.cellValue(m7aCell("C2"))).number);

    // Row 2 — foreign non-empty is (obstruction): B5's 2×1 meets B6=7.
    const b5 = m7aCell("B5");
    const blocked = try env.publishResult(b5, .{ .array = try m7aMatrix(a, 2, 1, 1) });
    try std.testing.expectEqual(engine.value.KnownError.spill, blocked.err.known);
    try std.testing.expectEqual(engine.spill.Class.obstruction, env.spillClassOf(b5).?);
    try std.testing.expect((try read.spillShape(b5)) == null);
    // …and the obstruction itself is untouched.
    try std.testing.expectEqual(@as(f64, 7), (try read.cellValue(m7aCell("B6"))).number);

    // Row 3 — the sheet edge: XFD1 has no second column to spill into.
    const xfd1 = m7aCell("XFD1");
    _ = try env.publishResult(xfd1, .{ .array = try m7aMatrix(a, 1, 2, 1) });
    try std.testing.expectEqual(engine.spill.Class.edge, env.spillClassOf(xfd1).?);

    // Row 4 — a declared table blocks: F1's 1×2 reaches G1.
    const f1 = m7aCell("F1");
    _ = try env.publishResult(f1, .{ .array = try m7aMatrix(a, 1, 2, 1) });
    try std.testing.expectEqual(engine.spill.Class.table, env.spillClassOf(f1).?);

    // Row 5 — a merged range blocks: D5's 2×1 sits on D5:E6.
    const d5 = m7aCell("D5");
    _ = try env.publishResult(d5, .{ .array = try m7aMatrix(a, 2, 1, 1) });
    try std.testing.expectEqual(engine.spill.Class.merge, env.spillClassOf(d5).?);

    // Ownership — shrink clears own tails from every subsequent read.
    _ = try env.publishResult(b1, .{ .array = try m7aMatrix(a, 2, 1, 10) });
    try std.testing.expectEqual(@as(f64, 11), (try read.cellValue(m7aCell("B2"))).number);
    try std.testing.expect((try read.cellValue(m7aCell("C1"))) == .blank);
    try std.testing.expect((try read.cellValue(m7aCell("C2"))) == .blank);
    try std.testing.expectEqual(@as(u32, 1), (try read.spillShape(b1)).?.cols);

    // …grow re-places over the freed cells.
    _ = try env.publishResult(b1, .{ .array = try m7aMatrix(a, 1, 3, 20) });
    try std.testing.expectEqual(@as(f64, 22), (try read.cellValue(m7aCell("D1"))).number);
    try std.testing.expect((try read.cellValue(m7aCell("B2"))) == .blank);

    // Racing anchors resolve in calc order: A1's 1×3 now meets B1 —
    // an anchor's own coordinate is content — and blocks without
    // touching B1's spill.
    const a1 = m7aCell("A1");
    _ = try env.publishResult(a1, .{ .array = try m7aMatrix(a, 1, 3, 1) });
    try std.testing.expectEqual(engine.spill.Class.obstruction, env.spillClassOf(a1).?);
    try std.testing.expectEqual(@as(u32, 3), (try read.spillShape(b1)).?.cols);

    // An OVERWRITTEN TAIL obstructs the next placement: a foreign
    // publication lands where B1's tail sits, and B1's re-place meets
    // it — after clearing its own previous tails, so the obstruction it
    // finds is genuinely the newcomer.
    _ = try env.publishResult(m7aCell("C1"), .{ .scalar = engine.value.ScalarValue.fromNumber(99) });
    _ = try env.publishResult(b1, .{ .array = try m7aMatrix(a, 1, 3, 30) });
    try std.testing.expectEqual(engine.spill.Class.obstruction, env.spillClassOf(b1).?);
    try std.testing.expect((try read.spillShape(b1)) == null);
    try std.testing.expectEqual(@as(f64, 99), (try read.cellValue(m7aCell("C1"))).number);
    // The newcomer retracted, the same rectangle spills again.
    env.retractResult(m7aCell("C1"));
    _ = try env.publishResult(b1, .{ .array = try m7aMatrix(a, 1, 3, 20) });
    try std.testing.expectEqual(@as(u32, 3), (try read.spillShape(b1)).?.cols);

    // ANCHOR-ERROR: an anchor whose next result is an error scalar
    // stops owning anything — the error rides the same clear-first path
    // as any scalar, and the freed cells read blank again.
    _ = try env.publishResult(b1, .{ .scalar = engine.value.ScalarValue.errorOf(.ref) });
    try std.testing.expect((try read.spillShape(b1)) == null);
    try std.testing.expect(env.spillClassOf(b1) == null);
    try std.testing.expectEqual(engine.value.KnownError.ref, (try read.cellValue(b1)).err.known);
    try std.testing.expect((try read.cellValue(m7aCell("C1"))) == .blank);
    try std.testing.expect((try read.cellValue(m7aCell("D1"))) == .blank);

    // Retract undoes the whole publication — tails, record, value.
    env.retractResult(b5);
    try std.testing.expect(env.spillClassOf(b5) == null);
    try std.testing.expect((try read.cellValue(b5)) == .blank or (try read.cellValue(b5)) == .number);
}

// ─── §9.1 M10r: in-place publication ─────────────────────────────

/// Every record a coordinate carries, and the topmost one. The count is
/// what M10r is *about* — one record where the drive used to keep two —
/// so a fixture that only compared read-back values could not see the
/// row at all.
const CoordRecords = struct { count: usize, top: WorkbookEnv.Cell };

fn recordsAt(s: *const WorkbookEnv.Sheet, row: coords.Row, col: coords.Col) CoordRecords {
    var cur = s.lowerBound(row, col, .computed);
    var out: CoordRecords = .{ .count = 0, .top = undefined };
    while (s.at(cur)) |c| : (cur = s.next(cur)) {
        if (c.row.oneBased() != row.oneBased()) break;
        if (c.col.zeroBased() != col.zeroBased()) break;
        if (out.count == 0) out.top = c;
        out.count += 1;
    }
    return out;
}

test "M10r: in-place publication overwrites `v` and preserves the rest of the record" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const sheet = try testSheetXml(
        ta,
        "<row r=\"1\"><c r=\"A1\"><v>5</v></c><c r=\"B1\"><f>A1+1</f><v>6</v></c></row>",
    );
    defer ta.free(sheet);
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    var env = try expectBuilt(try buildEnvOrRefusal(ta, &wb, .{ .collation = test_collation }));
    defer env.deinit();
    const e = env.evalEnv();
    const s0 = engine.env.SheetIndex.fromInt(0);
    const row1 = try coords.Row.fromOneBased(1);
    const col_b = try coords.Col.fromZeroBased(1);
    const b1: engine.env.CellRef = .{ .sheet = s0, .row = row1, .col = col_b };

    const before = recordsAt(&env.sheets[0], row1, col_b);
    try std.testing.expectEqual(@as(usize, 1), before.count);

    env.publish_in_place = true;
    try env.putComputed(s0, row1, col_b, engine.value.ScalarValue.fromNumber(42));

    // The row itself: one record, where the drive used to leave two.
    const after = recordsAt(&env.sheets[0], row1, col_b);
    try std.testing.expectEqual(@as(usize, 1), after.count);
    // …and it is the SAME record, with one field moved. `layer` is its
    // position in key order, `cache` is what §5.6c seeded from, `extra`
    // names its metadata — a publication that disturbed any of them
    // would have answered a later reader with a different cell.
    try std.testing.expectEqual(engine.env.Layer.stored, after.top.layer);
    try std.testing.expectEqualStrings("A1+1", after.top.formula_text.?);
    try std.testing.expectEqual(before.top.cache, after.top.cache);
    try std.testing.expectEqual(before.top.extra, after.top.extra);
    try std.testing.expectEqual(@as(f64, 42), after.top.v.number);

    // Every reader answers as it did when a second record carried the
    // value — which is the whole claim.
    try std.testing.expectEqual(@as(f64, 42), (try e.cellValue(b1)).number);
    try std.testing.expectEqualStrings("A1+1", (try env.formulaAt(b1)).?);
    try std.testing.expectEqual(engine.value.Dialect.legacy, try e.dialectOf(b1));
    try std.testing.expect(!try env.isUncached(b1));
}

test "M10r: a published blank keeps its own record, so `isUncached` stays honest" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // `<f>` with no `<v>`: the record's `v` is already `.absent`, which
    // on a formula record is this type's spelling of *uncached*.
    const sheet = try testSheetXml(ta, "<row r=\"1\"><c r=\"A1\"><f>B1</f></c></row>");
    defer ta.free(sheet);
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    var env = try expectBuilt(try buildEnvOrRefusal(ta, &wb, .{ .collation = test_collation }));
    defer env.deinit();
    const s0 = engine.env.SheetIndex.fromInt(0);
    const row1 = try coords.Row.fromOneBased(1);
    const col_a = try coords.Col.fromZeroBased(0);
    const a1: engine.env.CellRef = .{ .sheet = s0, .row = row1, .col = col_a };
    try std.testing.expect(try env.isUncached(a1));

    // Publishing blank folds to `.absent` (`dupeValue`). Written onto
    // the formula record it would say "never computed" about a cell that
    // just computed, so this one publication declines the saving and
    // lays a `.computed` record — which carries no `formula_text` and
    // therefore cannot make that claim.
    env.publish_in_place = true;
    try env.putComputed(s0, row1, col_a, engine.value.ScalarValue.blank);

    const at = recordsAt(&env.sheets[0], row1, col_a);
    try std.testing.expectEqual(@as(usize, 2), at.count);
    try std.testing.expectEqual(engine.env.Layer.computed, at.top.layer);
    try std.testing.expect(!try env.isUncached(a1));
    try std.testing.expectEqual(
        engine.value.ScalarValue.blank,
        try env.evalEnv().cellValue(a1),
    );
}

test "M10r: in-place publication never overwrites a foreign spill tail" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const sheet = try testSheetXml(ta, "<row r=\"1\"><c r=\"B1\" cm=\"1\"><v>0</v></c></row>");
    defer ta.free(sheet);
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();
    try wb.store.addPart("xl/metadata.xml", ct_metadata_part, m7a_metadata_da);

    var env = try expectBuilt(try buildEnvOrRefusal(ta, &wb, .{ .collation = test_collation }));
    defer env.deinit();
    var arena = std.heap.ArenaAllocator.init(ta);
    defer arena.deinit();
    const read = env.evalEnv();

    const b1 = m7aCell("B1");
    const c1 = m7aCell("C1");
    _ = try env.publishResult(b1, .{ .array = try m7aMatrix(arena.allocator(), 1, 3, 10) });
    try std.testing.expectEqual(@as(f64, 11), (try read.cellValue(c1)).number);

    // C1 now holds a tail whose value belongs to B1. A publication
    // landing on it must shadow it, never absorb it — the tail carries
    // no formula of its own, and the value being published is not the
    // one it was placed with.
    env.publish_in_place = true;
    _ = try env.publishResult(c1, .{ .scalar = engine.value.ScalarValue.fromNumber(99) });
    const at = recordsAt(&env.sheets[0], c1.row, c1.col);
    try std.testing.expectEqual(@as(usize, 2), at.count);
    try std.testing.expectEqual(engine.env.Layer.computed, at.top.layer);
    try std.testing.expectEqual(@as(f64, 99), (try read.cellValue(c1)).number);

    // The proof that the tail survived intact: uncover it. (A host that
    // publishes in place does not retract — that is M10r's other half —
    // so the flag comes off first, exactly as the assertion in
    // `retractResult` requires.)
    env.publish_in_place = false;
    env.retractResult(c1);
    try std.testing.expectEqual(@as(f64, 11), (try read.cellValue(c1)).number);
}

test "M7a: A1# resolves the owner's current extent, against stored cells" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const sheet =
        "<?xml version=\"1.0\"?><worksheet xmlns=\"" ++ test_ns_main ++ "\"><sheetData>" ++
        "<row r=\"1\"><c r=\"A1\" cm=\"1\"><f>SEQUENCE(3)</f><v>0</v></c></row>" ++
        "</sheetData></worksheet>";
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();
    try wb.store.addPart("xl/metadata.xml", ct_metadata_part, m7a_metadata_da);

    // The anchor spills A1:A3 in the closure; `A1#` names that extent.
    var summed = try wb.evaluateClosure(ta, 0, "SUM(A1#)", .{ .collation = test_collation });
    defer summed.deinit();
    try std.testing.expectEqual(@as(f64, 6), summed.ok.value.scalar.number);

    // Bare `A1#` dereferences to the whole rectangle.
    var whole = try wb.evaluateClosure(ta, 0, "A1#", .{ .collation = test_collation });
    defer whole.deinit();
    try std.testing.expectEqual(@as(u32, 3), whole.ok.value.array.rows);
    try std.testing.expectEqual(@as(f64, 3), whole.ok.value.array.at(2, 0).number);

    // A range dependent sees the tails the same run placed — §5.6a's
    // same-run spill-grow visibility.
    var range = try wb.evaluateClosure(ta, 0, "SUM(A1:A9)", .{ .collation = test_collation });
    defer range.deinit();
    try std.testing.expectEqual(@as(f64, 6), range.ok.value.scalar.number);

    // `A1#` against a NON-anchor is `#REF!` (M3a2's spec-pinned row).
    var not_anchor = try wb.evaluateClosure(ta, 0, "SUM(B9#)", .{ .collation = test_collation });
    defer not_anchor.deinit();
    try std.testing.expectEqual(engine.value.KnownError.ref, not_anchor.ok.value.scalar.err.known);
}

test "M7a: the spill extent follows the data, and an obstructed anchor answers #SPILL!" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // A1's extent is B1's number: the same formula, two workbooks, two
    // extents — what "the owner's CURRENT spill extent" means.
    inline for (.{ .{ "2", 3.0 }, .{ "4", 10.0 } }) |case| {
        const sheet =
            "<?xml version=\"1.0\"?><worksheet xmlns=\"" ++ test_ns_main ++ "\"><sheetData>" ++
            "<row r=\"1\"><c r=\"A1\" cm=\"1\"><f>SEQUENCE(B1)</f><v>0</v></c>" ++
            "<c r=\"B1\"><v>" ++ case[0] ++ "</v></c></row>" ++
            "</sheetData></worksheet>";
        var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
        defer wb.deinit();
        try wb.store.addPart("xl/metadata.xml", ct_metadata_part, m7a_metadata_da);

        var r = try wb.evaluateClosure(ta, 0, "SUM(A1:A9)", .{ .collation = test_collation });
        defer r.deinit();
        try std.testing.expectEqual(@as(f64, case[1]), r.ok.value.scalar.number);
    }

    // An anchor whose rectangle meets a stored value answers `#SPILL!`
    // end to end.
    const blocked_sheet =
        "<?xml version=\"1.0\"?><worksheet xmlns=\"" ++ test_ns_main ++ "\"><sheetData>" ++
        "<row r=\"1\"><c r=\"A1\" cm=\"1\"><f>SEQUENCE(3)</f><v>0</v></c></row>" ++
        "<row r=\"2\"><c r=\"A2\"><v>5</v></c></row>" ++
        "</sheetData></worksheet>";
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = blocked_sheet }}, null);
    defer wb.deinit();
    try wb.store.addPart("xl/metadata.xml", ct_metadata_part, m7a_metadata_da);

    var r = try wb.evaluateClosure(ta, 0, "A1", .{ .collation = test_collation });
    defer r.deinit();
    try std.testing.expectEqual(engine.value.KnownError.spill, r.ok.value.scalar.err.known);
    // The obstruction itself still reads its stored value.
    var kept = try wb.evaluateClosure(ta, 0, "A2", .{ .collation = test_collation });
    defer kept.deinit();
    try std.testing.expectEqual(@as(f64, 5), kept.ok.value.scalar.number);
}

test "M7a: a legacy cell's array still narrows — placement is the dynamic dialect's" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // No metadata part: every cell is legacy, which is what a workbook
    // without the part actually is. The same SEQUENCE narrows to its
    // top-left exactly as every pre-M7a host behaved.
    const sheet =
        "<?xml version=\"1.0\"?><worksheet xmlns=\"" ++ test_ns_main ++ "\"><sheetData>" ++
        "<row r=\"1\"><c r=\"A1\"><f>SEQUENCE(3)</f><v>0</v></c></row>" ++
        "</sheetData></worksheet>";
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    var top = try wb.evaluateClosure(ta, 0, "A1", .{ .collation = test_collation });
    defer top.deinit();
    try std.testing.expectEqual(@as(f64, 1), top.ok.value.scalar.number);

    var range = try wb.evaluateClosure(ta, 0, "SUM(A1:A3)", .{ .collation = test_collation });
    defer range.deinit();
    try std.testing.expectEqual(@as(f64, 1), range.ok.value.scalar.number);

    // A legacy anchor owns no extent: `A1#` is `#REF!`.
    var spill_ref = try wb.evaluateClosure(ta, 0, "SUM(A1#)", .{ .collation = test_collation });
    defer spill_ref.deinit();
    try std.testing.expectEqual(engine.value.KnownError.ref, spill_ref.ok.value.scalar.err.known);
}

test "M7a: @ applies §5.3b's implicit intersection against stored cells" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const sheet =
        "<?xml version=\"1.0\"?><worksheet xmlns=\"" ++ test_ns_main ++ "\"><sheetData>" ++
        "<row r=\"1\"><c r=\"B1\"><v>10</v></c></row>" ++
        "<row r=\"2\"><c r=\"B2\"><v>20</v></c></row>" ++
        "<row r=\"3\"><c r=\"B3\"><v>30</v></c></row>" ++
        "</sheetData></worksheet>";
    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    const site2 = m7aCell("D2");
    // A column vector intersects the evaluation ROW.
    var v = try wb.evaluate(ta, 0, "@B1:B3", .{
        .collation = test_collation,
        .site = .{ .row = site2.row, .col = site2.col },
    });
    defer v.deinit();
    try std.testing.expectEqual(@as(f64, 20), v.ok.value.scalar.number);

    // The single-cell exception precedes intersection: `@B1` is B1
    // whatever the site's row.
    var single = try wb.evaluate(ta, 0, "@B1", .{
        .collation = test_collation,
        .site = .{ .row = site2.row, .col = site2.col },
    });
    defer single.deinit();
    try std.testing.expectEqual(@as(f64, 10), single.ok.value.scalar.number);

    // No shared axis is `#VALUE!`.
    const site9 = m7aCell("D9");
    var off = try wb.evaluate(ta, 0, "@B1:B3", .{
        .collation = test_collation,
        .site = .{ .row = site9.row, .col = site9.col },
    });
    defer off.deinit();
    try std.testing.expectEqual(engine.value.KnownError.value, off.ok.value.scalar.err.known);
}

test "checkAllAllocationFailures: evaluate leaks nothing, and still mutates nothing" {
    const H = struct {
        fn run(allocator: Allocator) !void {
            var threaded: std.Io.Threaded = .init(allocator, .{});
            defer threaded.deinit();
            const io = threaded.io();

            const sheet = try m4b3Sheet(
                allocator,
                "<row r=\"1\"><c r=\"A1\"><v>2</v></c>" ++
                    "<c r=\"B1\"><f>A1*10</f><v>20</v></c></row>",
            );
            defer allocator.free(sheet);
            var wb = try testWorkbookFromPartsWithNames(
                allocator,
                io,
                &.{.{ .name = "S", .body = sheet }},
                null,
                "<definedNames><definedName name=\"R\">S!$A$1</definedName></definedNames>",
            );
            defer wb.deinit();

            var r = try wb.evaluate(allocator, 0, "R+B1", .{ .collation = test_collation });
            defer r.deinit();
            if (r != .ok) return error.WrongOutcome;
            if (r.ok.value.scalar.number != 22) return error.WrongValue;

            // An injected failure must not have left a value behind
            // either: the parts are still what they were.
            const part = (try wb.store.part("xl/worksheets/sheet1.xml")) orelse
                return error.MissingPart;
            if (std.mem.indexOf(u8, part.bytes, "<v>22</v>") != null) return error.Mutated;
        }
    };
    try std.testing.checkAllAllocationFailures(std.testing.allocator, H.run, .{});
}

// ─── M5a1: closure evaluation (§5.6f) ─────────────────────────────

test "M5a1: closure evaluation recomputes what cache-based evaluation reads" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // B1's cached value disagrees with its own formula, and C1 has no
    // cache at all. That disagreement is the instrument: it is exactly
    // what tells the two behaviours apart.
    const body =
        "<row r=\"1\">" ++
        "<c r=\"A1\"><v>2</v></c>" ++
        "<c r=\"B1\"><f>A1*10</f><v>999</v></c>" ++
        "<c r=\"C1\"><f>B1+1</f></c>" ++
        "</row>";
    const sheet = try m4b3Sheet(ta, body);
    defer ta.free(sheet);

    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    // Cache-based (M4b3): the file's own 999.
    var cached = try wb.evaluate(ta, 0, "B1", .{ .collation = test_collation });
    defer cached.deinit();
    try std.testing.expectEqual(@as(f64, 999), cached.ok.value.scalar.number);

    // Closure (M5a1): `A1*10` recomputed to 20.
    var closed = try wb.evaluateClosure(ta, 0, "B1", .{ .collation = test_collation });
    defer closed.deinit();
    try std.testing.expectEqual(@as(f64, 20), closed.ok.value.scalar.number);

    // Two hops: C1 = B1+1 = 21, from a cell that had no cache at all.
    var deep = try wb.evaluateClosure(ta, 0, "C1", .{ .collation = test_collation });
    defer deep.deinit();
    try std.testing.expectEqual(@as(f64, 21), deep.ok.value.scalar.number);

    // …and the cache-based reading of the same cell is still blank, so
    // §5.6f's "both behaviours, no silent switch" is observable rather
    // than asserted.
    var deep_cached = try wb.evaluate(ta, 0, "SUM(C1,100)", .{ .collation = test_collation });
    defer deep_cached.deinit();
    try std.testing.expectEqual(@as(f64, 100), deep_cached.ok.value.scalar.number);
}

test "M5a1: closure evaluation reads a range through the computed layer" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const body =
        "<row r=\"1\">" ++
        "<c r=\"A1\"><v>1</v></c>" ++
        "<c r=\"B1\"><f>A1*2</f><v>0</v></c>" ++
        "</row>" ++
        "<row r=\"2\">" ++
        "<c r=\"A2\"><v>3</v></c>" ++
        "<c r=\"B2\"><f>A2*2</f><v>0</v></c>" ++
        "</row>";
    const sheet = try m4b3Sheet(ta, body);
    defer ta.free(sheet);

    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    // Both caches say 0. Recomputed: 2 + 6.
    var r = try wb.evaluateClosure(ta, 0, "SUM(B1:B2)", .{ .collation = test_collation });
    defer r.deinit();
    try std.testing.expectEqual(@as(f64, 8), r.ok.value.scalar.number);
}

test "M5a1: a cycle in the closure refuses while iteration is off" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const sheet = try m4b3Sheet(
        ta,
        "<row r=\"1\"><c r=\"A1\"><f>B1+1</f><v>0</v></c>" ++
            "<c r=\"B1\"><f>A1+1</f><v>0</v></c></row>",
    );
    defer ta.free(sheet);

    var wb = try testWorkbookFromParts(ta, io, &.{.{ .name = "S", .body = sheet }}, null);
    defer wb.deinit();

    const before = try partSnapshot(ta, &wb);
    defer freeSnapshot(ta, before);

    var r = try wb.evaluateClosure(ta, 0, "A1", .{ .collation = test_collation });
    defer r.deinit();
    try std.testing.expectEqual(engine.graph.Refusal.Reason.cycle, r.graph_refused.reason);
    try expectSnapshotUnchanged(ta, &wb, before);
    try std.testing.expectEqual(
        engine.decode.PlaneTwo.FormulaCycle,
        r.graph_refused.planeTwo(),
    );

    // The same workbook is still readable cache-first: the two
    // behaviours disagree about cycles, and only one of them refuses.
    var cached = try wb.evaluate(ta, 0, "A1", .{ .collation = test_collation });
    defer cached.deinit();
    try std.testing.expectEqual(@as(f64, 0), cached.ok.value.scalar.number);
}

test "M5a1: closure evaluation mutates neither logical state nor serialized bytes" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const sheet = try m4b3Sheet(
        ta,
        "<row r=\"1\"><c r=\"A1\"><v>2</v></c>" ++
            "<c r=\"B1\"><f>A1*10</f><v>999</v></c></row>",
    );
    defer ta.free(sheet);
    var wb = try testWorkbookFromPartsWithNames(
        ta,
        io,
        &.{.{ .name = "S", .body = sheet }},
        null,
        "<definedNames><definedName name=\"R\">S!$A$1</definedName></definedNames>",
    );
    defer wb.deinit();

    const before = try partSnapshot(ta, &wb);
    defer freeSnapshot(ta, before);

    // 1. Success — and the recomputed 20 does NOT reach the part.
    var ok = try wb.evaluateClosure(ta, 0, "B1+R", .{ .collation = test_collation });
    defer ok.deinit();
    try std.testing.expectEqual(@as(f64, 22), ok.ok.value.scalar.number);
    try expectSnapshotUnchanged(ta, &wb, before);
    const part = (try wb.store.part("xl/worksheets/sheet1.xml")) orelse return error.MissingPart;
    try std.testing.expect(std.mem.indexOf(u8, part.bytes, "<v>20</v>") == null);

    // 2. Refusal, raised after the closure had already been planned and
    //    every cell in it recomputed. `IMDIV` is the canonical
    //    out-of-inventory name since M9d retired the canonical-
    //    unregistered pin — every frozen name now resolves.
    var refused = try wb.evaluateClosure(ta, 0, "IMDIV(A1)", .{ .collation = test_collation });
    defer refused.deinit();
    try std.testing.expectEqual(
        engine.decode.PlaneTwo.FormulaUnsupportedFunction,
        refused.eval_refused.plane,
    );
    try expectSnapshotUnchanged(ta, &wb, before);

    // 3. A parse refusal, which never reaches the graph at all — and
    //    the same outcome `evaluate` gives for the same text.
    var parse_refused = try wb.evaluateClosure(ta, 0, "((((", .{ .collation = test_collation });
    defer parse_refused.deinit();
    try std.testing.expect(parse_refused == .parse_refused);
    try expectSnapshotUnchanged(ta, &wb, before);

    // 4. A graph refusal, raised while the graph was still being built.
    //    `B1` is one token and parses; the *stored* body `A1*10` is
    //    three and does not, so the run refuses before a single cell was
    //    recomputed — which is what makes "pre-mutation" a claim about
    //    the whole run rather than about one function's return.
    var starved = try wb.evaluateClosure(ta, 0, "B1", .{
        .collation = test_collation,
        .parse_limits = .{ .max_tokens = 2 },
    });
    defer starved.deinit();
    try std.testing.expectEqual(
        engine.graph.Refusal.Reason.formula_parse_failed,
        starved.graph_refused.reason,
    );
    try expectSnapshotUnchanged(ta, &wb, before);
}

