}

// ─── M5a2: the iteration engine, through the package ─────────────

/// A workbook whose `<calcPr>` says what §5.6c needs it to say. The
/// helper takes the element where defined names go, and the schema puts
/// `<calcPr>` after them — one string covers both.
fn m5a2CalcPr(iterate: bool, count: u32, delta: []const u8) [128]u8 {
    var buf: [128]u8 = @splat(0);
    _ = std.fmt.bufPrint(
        &buf,
        "<calcPr iterate=\"{s}\" iterateCount=\"{d}\" iterateDelta=\"{s}\"/>",
        .{ if (iterate) "true" else "false", count, delta },
    ) catch unreachable;
    return buf;
}

fn m5a2Workbook(
    allocator: Allocator,
    io: std.Io,
    body: []const u8,
    calc_pr: []const u8,
) !Workbook {
    const sheet = try m4b3Sheet(allocator, body);
    defer allocator.free(sheet);
    return testWorkbookFromPartsWithNames(
        allocator,
        io,
        &.{.{ .name = "S", .body = sheet }},
        null,
        calc_pr,
    );
}

test "M5a2: a cycle a workbook asks to iterate is scheduled, not refused" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // §5.6c's parity formula, uncached: the seed table's zero, then ten
    // passes, then a value within `iterateDelta` of where the eleventh
    // would land.
    const pr = m5a2CalcPr(true, 100, "0.001");
    var wb = try m5a2Workbook(
        ta,
        io,
        "<row r=\"1\"><c r=\"A1\"><f>(A1+1)/2</f></c></row>",
        std.mem.sliceTo(&pr, 0),
    );
    defer wb.deinit();

    var r = try wb.evaluateClosure(ta, 0, "A1", .{ .collation = test_collation });
    defer r.deinit();
    try std.testing.expectApproxEqAbs(
        1 - std.math.pow(f64, 2, -10),
        r.ok.value.scalar.number,
        1e-12,
    );

    // The same workbook with iteration OFF is M5a1's answer, unchanged.
    const off = m5a2CalcPr(false, 100, "0.001");
    var wb_off = try m5a2Workbook(
        ta,
        io,
        "<row r=\"1\"><c r=\"A1\"><f>(A1+1)/2</f></c></row>",
        std.mem.sliceTo(&off, 0),
    );
    defer wb_off.deinit();
    var refused = try wb_off.evaluateClosure(ta, 0, "A1", .{ .collation = test_collation });
    defer refused.deinit();
    try std.testing.expectEqual(engine.graph.Refusal.Reason.cycle, refused.graph_refused.reason);
}

test "M5a2: a caller ceiling below the workbook's iterateCount refuses the run" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const pr = m5a2CalcPr(true, 50, "0.001");
    var wb = try m5a2Workbook(
        ta,
        io,
        "<row r=\"1\"><c r=\"A1\"><f>A1+1</f></c></row>",
        std.mem.sliceTo(&pr, 0),
    );
    defer wb.deinit();

    // Above and equal are the workbook's bound: success, non-converged.
    for ([_]u64{ 50, 80 }) |ceiling| {
        var ok = try wb.evaluateClosure(ta, 0, "A1", .{
            .collation = test_collation,
            .work_limits = .{ .max_scc_iterations = ceiling },
        });
        defer ok.deinit();
        try std.testing.expectEqual(@as(f64, 50), ok.ok.value.scalar.number);
    }

    // Below is the caller's, and §9's limits are plane-2 refusals at
    // every layer.
    var refused = try wb.evaluateClosure(ta, 0, "A1", .{
        .collation = test_collation,
        .work_limits = .{ .max_scc_iterations = 5 },
    });
    defer refused.deinit();
    try std.testing.expectEqual(
        engine.iterate.Refusal.Reason.scc_iteration_ceiling,
        refused.iteration_refused.reason,
    );
    try std.testing.expectEqual(
        engine.decode.PlaneTwo.FormulaLimitExceeded,
        refused.iteration_refused.planeTwo(),
    );
}

test "M5a2: the iteration engine mutates neither logical state nor serialized bytes" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // A cache of 999 that no outcome may overwrite, beside a cycle whose
    // behaviour each leg below changes with nothing but its options.
    const body =
        "<row r=\"1\">" ++
        "<c r=\"A1\"><f>A1+1</f><v>999</v></c>" ++
        "<c r=\"B1\"><f>A1*2</f><v>888</v></c>" ++
        "</row>";
    const pr = m5a2CalcPr(true, 4, "0.001");
    var wb = try m5a2Workbook(ta, io, body, std.mem.sliceTo(&pr, 0));
    defer wb.deinit();

    const before = try partSnapshot(ta, &wb);
    defer freeSnapshot(ta, before);

    // 1. Non-convergence. A success, and the workbook's own bound
    //    decided it: 999 seeded, four passes, 1003.
    {
        var r = try wb.evaluateClosure(ta, 0, "B1", .{ .collation = test_collation });
        defer r.deinit();
        try std.testing.expectEqual(@as(f64, 2006), r.ok.value.scalar.number);
        try expectSnapshotUnchanged(ta, &wb, before);
    }

    // 2. Convergence. Same workbook, a tolerance nothing can miss.
    {
        var r = try wb.evaluateClosure(ta, 0, "B1", .{
            .collation = test_collation,
            .work_limits = .{ .max_scc_iterations = 32_767 },
        });
        defer r.deinit();
        try expectSnapshotUnchanged(ta, &wb, before);
    }

    // 3. Refusal, raised after four passes had already published.
    {
        var r = try wb.evaluateClosure(ta, 0, "B1", .{
            .collation = test_collation,
            .work_limits = .{ .max_scc_iterations = 2 },
        });
        defer r.deinit();
        try std.testing.expect(r == .iteration_refused);
        try expectSnapshotUnchanged(ta, &wb, before);
    }

    // 4. Injected allocation failure, at every step a run can reach one.
    //    The parts are bytes the store owns and the engine never touches
    //    — which is the point: purity here is structural, and this is
    //    what proves the structure holds when the run dies partway.
    {
        var i: usize = 0;
        while (i < 400) : (i += 1) {
            var failing = std.testing.FailingAllocator.init(ta, .{ .fail_index = i });
            var r = wb.evaluateClosure(failing.allocator(), 0, "B1", .{
                .collation = test_collation,
            }) catch |e| {
                try std.testing.expectEqual(error.OutOfMemory, e);
                try expectSnapshotUnchanged(ta, &wb, before);
                continue;
            };
            r.deinit();
            try expectSnapshotUnchanged(ta, &wb, before);
        }
    }

    // …and the caches the workbook shipped with are still the caches it
    // shipped with, read through the cache-first entry point.
    var cached = try wb.evaluate(ta, 0, "A1", .{ .collation = test_collation });
    defer cached.deinit();
    try std.testing.expectEqual(@as(f64, 999), cached.ok.value.scalar.number);
}

test "M5a2: a dynamic reference is ordered by the outer loop, through the package" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // `A1` reads `C1` through text no walk over the body could resolve,
    // and `C1` sorts after it — so the static order evaluates `A1`
    // first, reads a stale `C1`, and only the rebuild fixes it.
    const body =
        "<row r=\"1\">" ++
        "<c r=\"A1\"><f>INDIRECT(\"C1\")*2</f></c>" ++
        "<c r=\"C1\"><f>21</f></c>" ++
        "</row>";
    const pr = m5a2CalcPr(false, 100, "0.001");
    var wb = try m5a2Workbook(ta, io, body, std.mem.sliceTo(&pr, 0));
    defer wb.deinit();

    const before = try partSnapshot(ta, &wb);
    defer freeSnapshot(ta, before);

    var r = try wb.evaluateClosure(ta, 0, "A1", .{ .collation = test_collation });
    defer r.deinit();
    try std.testing.expectEqual(@as(f64, 42), r.ok.value.scalar.number);
    try expectSnapshotUnchanged(ta, &wb, before);
}

test "M5a2: one SCC hitting the ceiling refuses the whole run, on the bytes" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    // `A1` converges on pass 10 (§5.6c's parity formula); `C1` never
    // converges. Both cycles are under one `iterateCount`, and the
    // ceiling sits between what one needs and what the other would.
    const body =
        "<row r=\"1\">" ++
        "<c r=\"A1\"><f>(A1+1)/2</f></c>" ++
        "<c r=\"C1\"><f>C1+1</f></c>" ++
        "<c r=\"E1\"><f>A1+C1</f></c>" ++
        "</row>";
    const pr = m5a2CalcPr(true, 100, "0.001");
    var wb = try m5a2Workbook(ta, io, body, std.mem.sliceTo(&pr, 0));
    defer wb.deinit();

    const before = try partSnapshot(ta, &wb);
    defer freeSnapshot(ta, before);

    // A ceiling of 20 is above what `A1` needs and below what the
    // workbook asked for, so `A1` converges and `C1` is the component
    // that trips it.
    var refused = try wb.evaluateClosure(ta, 0, "E1", .{
        .collation = test_collation,
        .work_limits = .{ .max_scc_iterations = 20 },
    });
    defer refused.deinit();
    try std.testing.expectEqual(
        engine.iterate.Refusal.Reason.scc_iteration_ceiling,
        refused.iteration_refused.reason,
    );
    // The component that tripped, named — and it is not the one that
    // reached its answer.
    try std.testing.expect(refused.iteration_refused.at.?.eql(.{ .cell = .{
        .sheet = engine.env.SheetIndex.fromInt(0),
        .row = try coords.Row.fromOneBased(1),
        .col = try coords.Col.fromZeroBased(2),
    } }));
    // The whole run rolled back, `A1`'s converged value with it.
    try expectSnapshotUnchanged(ta, &wb, before);

    // …and a ceiling above what the workbook asked for is a success, so
    // the refusal above was the ceiling and not the workbook.
    var ok = try wb.evaluateClosure(ta, 0, "E1", .{
        .collation = test_collation,
        .work_limits = .{ .max_scc_iterations = 32_767 },
    });
    defer ok.deinit();
    try std.testing.expectApproxEqAbs(
        (1 - std.math.pow(f64, 2, -10)) + 100,
        ok.ok.value.scalar.number,
        1e-9,
    );
    try expectSnapshotUnchanged(ta, &wb, before);
}

// ─── M5c: Workbook.openBuffer ────────────────────────────────────

/// Everything a buffer-opened workbook has to agree with a path-opened
/// one about, asserted through the public accessors rather than by
/// comparing internals: the two stores differ in exactly one thing, and
/// no reader above the backing is supposed to be able to tell.
fn expectWorkbooksEquivalent(a: *Workbook, b: *Workbook) !void {
    try std.testing.expectEqual(a.sheetCount(), b.sheetCount());

    var i: u32 = 0;
    while (i < a.sheetCount()) : (i += 1) {
        const wa = try a.sheet(i);
        const wb2 = try b.sheet(i);
        try std.testing.expectEqualStrings(wa.name(), wb2.name());
        try std.testing.expectEqualStrings(
            try wa.resolvePartName(),
            try wb2.resolvePartName(),
        );
        const va = try wa.ensureParsed();
        const vb = try wb2.ensureParsed();
        try std.testing.expectEqual(va.rows.len, vb.rows.len);
        for (va.rows, vb.rows) |ra, rb| {
            try std.testing.expectEqual(ra.cells.len, rb.cells.len);
            for (ra.cells, rb.cells) |ca, cb| {
                try std.testing.expectEqualStrings(ca.ref, cb.ref);
                try std.testing.expectEqualStrings(
                    ca.raw_value orelse "",
                    cb.raw_value orelse "",
                );
            }
        }
    }

    // Parts, content types, and rels — the three things `PartStore`
    // resolves at open, and therefore the three a different source arm
    // could plausibly get wrong.
    const names_a = try a.store.partNames();
    const names_b = try b.store.partNames();
    try std.testing.expectEqual(names_a.len, names_b.len);
    for (names_a, names_b) |na, nb| {
        try std.testing.expectEqualStrings(na, nb);
        const pa = (try a.store.part(na)) orelse return error.MissingPart;
        const pb = (try b.store.part(nb)) orelse return error.MissingPart;
        try std.testing.expectEqualSlices(u8, pa.bytes, pb.bytes);
        try std.testing.expectEqualStrings(pa.content_type orelse "", pb.content_type orelse "");
        try std.testing.expectEqual(pa.compression_method, pb.compression_method);

        const ra = a.store.rels(na);
        const rb = b.store.rels(nb);
        try std.testing.expectEqual(ra.len, rb.len);
        for (ra, rb) |x, y| {
            try std.testing.expectEqualStrings(x.id, y.id);
            try std.testing.expectEqualStrings(x.type, y.type);
            try std.testing.expectEqualStrings(x.target, y.target);
            try std.testing.expectEqual(x.target_mode, y.target_mode);
        }
    }
}

// ─── M5d1: the control-aware consumer (§5.10) ────────────────────────

test "M5d1: openBufferControlled under a null control equals openBuffer" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const fixture = "tests/corpus/frictionless_2sheets.xlsx";
    std.Io.Dir.cwd().access(io, fixture, .{}) catch return error.SkipZigTest;
    const raw = try std.Io.Dir.cwd().readFileAlloc(io, fixture, ta, .limited(1 << 24));
    defer ta.free(raw);

    var plain = try Workbook.openBuffer(ta, io, raw);
    defer plain.deinit();
    var controlled = try Workbook.openBufferControlled(ta, io, raw, .none);
    defer controlled.deinit();

    try expectWorkbooksEquivalent(&plain, &controlled);
}

test "M5d1: cancel mid-buffer-open mutates nothing and leaks nothing" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const base = threaded.io();
    const ta = std.testing.allocator;

    const fixture = "tests/corpus/frictionless_2sheets.xlsx";
    std.Io.Dir.cwd().access(base, fixture, .{}) catch return error.SkipZigTest;
    const raw = try std.Io.Dir.cwd().readFileAlloc(base, fixture, ta, .limited(1 << 24));
    defer ta.free(raw);

    // Trip a few polls in: past the entry-point check, inside the eager
    // structural-part pass. The deadline makes every poll read the
    // injected clock, which is what makes "a few polls in" exact.
    var flag: u8 = 0;
    const io = control.inject.wrap(base, .{ .trip_at = 3, .trip_flag = &flag });
    try std.testing.expectError(error.Cancelled, Workbook.openBufferControlled(ta, io, raw, .{
        .cancel = .{ .flag = &flag },
        .deadline = .{ .nanoseconds = std.math.maxInt(i64) },
    }));

    // The caller's bytes are read-only input and survive verbatim — this
    // is the "mutates nothing" half — and the testing allocator's leak
    // check at teardown is the other: a cancelled open released the
    // backing and tore down the arena.
    var again = try Workbook.openBuffer(ta, base, raw);
    defer again.deinit();
    try std.testing.expect(again.sheetCount() > 0);
}

test "M5d1: a deadline expires mid-buffer-open" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const base = threaded.io();
    const ta = std.testing.allocator;

    const fixture = "tests/corpus/frictionless_2sheets.xlsx";
    std.Io.Dir.cwd().access(base, fixture, .{}) catch return error.SkipZigTest;
    const raw = try std.Io.Dir.cwd().readFileAlloc(base, fixture, ta, .limited(1 << 24));
    defer ta.free(raw);

    const io = control.inject.wrap(base, .{ .step_ns = std.time.ns_per_ms });
    try std.testing.expectError(error.Cancelled, Workbook.openBufferControlled(ta, io, raw, .{
        .deadline = .{ .nanoseconds = 3 * std.time.ns_per_ms },
    }));
}

test "M5c: openBuffer and open reach the same workbook, and the borrow ends at return" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const fixture = "tests/corpus/frictionless_2sheets.xlsx";
    std.Io.Dir.cwd().access(io, fixture, .{}) catch return error.SkipZigTest;

    var from_path = try Workbook.open(ta, io, fixture);
    defer from_path.deinit();

    var from_buffer = blk: {
        const raw = try std.Io.Dir.cwd().readFileAlloc(io, fixture, ta, .limited(1 << 24));
        defer ta.free(raw);
        const wb = try Workbook.openBuffer(ta, io, raw);
        // Poison the caller's slice before a single part is read. If the
        // store had borrowed rather than copied, everything below would
        // fail as *content* — not as luck, and not as a crash a later
        // reader would blame on something else.
        @memset(raw, 0xAA);
        break :blk wb;
    };
    defer from_buffer.deinit();

    try expectWorkbooksEquivalent(&from_path, &from_buffer);
}

test "M5c: a buffer-opened workbook saves the bytes a path-opened one does" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const fixture = "tests/corpus/frictionless_2sheets.xlsx";
    std.Io.Dir.cwd().access(io, fixture, .{}) catch return error.SkipZigTest;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const dir = try tmp.dir.realPathFileAlloc(io, ".", ta);
    defer ta.free(dir);

    const out_path = try std.fs.path.join(ta, &.{ dir, "from_path.xlsx" });
    defer ta.free(out_path);
    const out_buf = try std.fs.path.join(ta, &.{ dir, "from_buffer.xlsx" });
    defer ta.free(out_buf);

    {
        var wb = try Workbook.open(ta, io, fixture);
        defer wb.deinit();
        try wb.store.save(io, out_path);
    }
    {
        const raw = try std.Io.Dir.cwd().readFileAlloc(io, fixture, ta, .limited(1 << 24));
        defer ta.free(raw);
        var wb = try Workbook.openBuffer(ta, io, raw);
        defer wb.deinit();
        @memset(raw, 0xAA);
        try wb.store.save(io, out_buf);
    }

    const a_bytes = try std.Io.Dir.cwd().readFileAlloc(io, out_path, ta, .limited(1 << 24));
    defer ta.free(a_bytes);
    const b_bytes = try std.Io.Dir.cwd().readFileAlloc(io, out_buf, ta, .limited(1 << 24));
    defer ta.free(b_bytes);

    // Byte-identical: both are untouched-LFH + untouched-CDFH copies
    // through one call, with only the source arm differing. Anything
    // less would mean the buffer path re-emitted a part.
    try std.testing.expectEqualSlices(u8, a_bytes, b_bytes);
}

test "M5c: openBuffer refuses garbage the way open does, and leaks nothing" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    try std.testing.expectError(error.NotPkzip, Workbook.openBuffer(ta, io, "not a zip"));
    try std.testing.expectError(error.NotPkzip, Workbook.openBuffer(ta, io, &.{}));

    // A well-formed archive with no `xl/workbook.xml` — the failure that
    // happens INSIDE `fromStore`, after it has taken ownership. The
    // errdefer disarm is what keeps this a typed error instead of a
    // double free, and only a test that reaches this branch says so.
    const bytes = blk: {
        var store = try PartStore.fresh(ta, io);
        defer store.deinit();
        try store.addPart("docProps/core.xml", "application/xml", "<x/>");
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();
        const dir = try tmp.dir.realPathFileAlloc(io, ".", ta);
        defer ta.free(dir);
        const path = try std.fs.path.join(ta, &.{ dir, "nowb.xlsx" });
        defer ta.free(path);
        try store.save(io, path);
        break :blk try std.Io.Dir.cwd().readFileAlloc(io, path, ta, .limited(1 << 20));
    };
    defer ta.free(bytes);
    try std.testing.expectError(error.MissingWorkbookPart, Workbook.openBuffer(ta, io, bytes));
}

test "M5c: openBuffer leaves nothing allocated under any failure" {
    var threaded: std.Io.Threaded = .init(std.testing.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const ta = std.testing.allocator;

    const fixture = "tests/corpus/frictionless_2sheets.xlsx";
    std.Io.Dir.cwd().access(io, fixture, .{}) catch return error.SkipZigTest;
    const raw = try std.Io.Dir.cwd().readFileAlloc(io, fixture, ta, .limited(1 << 24));
    defer ta.free(raw);

    try std.testing.checkAllAllocationFailures(ta, struct {
        fn run(alloc: Allocator, the_io: std.Io, bytes: []const u8) !void {
            var wb = try Workbook.openBuffer(alloc, the_io, bytes);
            defer wb.deinit();
            const ws = try wb.sheet(0);
            _ = try ws.ensureParsed();
        }
    }.run, .{ io, raw });
}
